/* hi-IN-only expansion: 1,600 authored records, 4+ lines each, across 16 regional categories. */
window.JESTBOX_JOKES["hi-IN"].push(
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—खजाने में कमी कैसे पकड़ोगे।\nअकबर ने पूछा, \"खजाने में कमी कैसे पकड़ोगे?\"\nबीरबल ने उत्तर दिया, \"पहले हिसाब की किताब देखूँगा,\nफिर उन हाथों को जो उसे छूते हैं।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—अगर दो मुहरें एक जैसी हों तो असली कौन-सी।\nअकबर ने पूछा, \"अगर दो मुहरें एक जैसी हों तो असली कौन-सी?\"\nबीरबल ने उत्तर दिया, \"जिससे काम पूरा हो,\nवही असली; बाकी सिर्फ़ दिखावा हैं।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—खर्च घटाने का सबसे आसान उपाय क्या है।\nअकबर ने पूछा, \"खर्च घटाने का सबसे आसान उपाय क्या है?\"\nबीरबल ने उत्तर दिया, \"जो चीज़ दरबार में काम न आए,\nउसका खर्च दरबार से बाहर रखिए।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—सोने का सही मूल्य कैसे जानें।\nअकबर ने पूछा, \"सोने का सही मूल्य कैसे जानें?\"\nबीरबल ने उत्तर दिया, \"उसे बेचने वाले की बात नहीं,\nतौलने वाले का बाट देखिए।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—खाली संदूक किस बात का प्रमाण है।\nअकबर ने पूछा, \"खाली संदूक किस बात का प्रमाण है?\"\nबीरबल ने उत्तर दिया, \"कि किसी ने उसे खाली करने,\nमें पूरी मेहनत की है।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—किताब में गलती हो तो दोष किसका।\nअकबर ने पूछा, \"किताब में गलती हो तो दोष किसका?\"\nबीरबल ने उत्तर दिया, \"कलम का नहीं,\nउस हाथ का जिसने बिना जाँचे हस्ताक्षर किए।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—कौन-सा हिसाब सबसे कठिन है।\nअकबर ने पूछा, \"कौन-सा हिसाब सबसे कठिन है?\"\nबीरबल ने उत्तर दिया, \"वह जिसमें जोड़ने वाला भी,\nअपना हिस्सा जोड़ता रहे।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—धन बचाने का राज़ क्या है।\nअकबर ने पूछा, \"धन बचाने का राज़ क्या है?\"\nबीरबल ने उत्तर दिया, \"पहले यह तय करें कि धन जनता का है,\nकिसी की जेब का नहीं।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—खजाने की रखवाली कौन करे।\nअकबर ने पूछा, \"खजाने की रखवाली कौन करे?\"\nबीरबल ने उत्तर दिया, \"वह जिसे चाबी से,\nज़्यादा जवाबदेही प्यारी हो।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—सिक्के की आवाज़ क्या बताती है।\nअकबर ने पूछा, \"सिक्के की आवाज़ क्या बताती है?\"\nबीरबल ने उत्तर दिया, \"कि वह गिरा है;\nकिसकी जेब से आया, यह जाँच बताएगी।\""],
  ["akbar-birbal", "दरबार में अकबर ने बीरबल से पूछा, \"सबसे तेज़ खबर किस रास्ते आती है?\"\nबीरबल बोले, \"जहाँ पहरेदार सोता हो, वहाँ अफ़वाह सबसे पहले पहुँचती है।\"\nअकबर ने पहरेदार को देखा; वह तुरंत जाग गया।\nबीरबल मुस्कराए, \"हुज़ूर, अब खबर भी जागकर आएगी।\""],
  ["akbar-birbal", "अकबर ने पूछा, \"मेरे राज्य में सबसे ईमानदार व्यापारी कौन है?\"\nबीरबल ने कहा, \"जो अपना बाट ग्राहक के सामने रखता है।\"\nव्यापारी बोला, \"मैं तो हमेशा सही तौलता हूँ।\"\nबीरबल ने जवाब दिया, \"तभी तो बाट छिपाने की ज़रूरत नहीं पड़ती।\""],
  ["akbar-birbal", "राजा ने बीरबल से कहा, \"ऐसा सवाल पूछो जिसका जवाब कोई न दे सके।\"\nबीरबल ने पूछा, \"हुज़ूर, आज दरबार में किसने सबसे कम बात की?\"\nसबने एक-दूसरे की ओर देखा और चुप हो गए।\nअकबर बोले, \"आज पहली बार तुम्हारा सवाल पूरे दरबार ने मिलकर हल किया।\""],
  ["akbar-birbal", "अकबर ने पूछा, \"दरबार में सबसे कठिन काम क्या है?\"\nबीरबल बोले, \"हुज़ूर, सबकी बात सुनकर सही बात चुनना।\"\nअकबर ने कहा, \"यह तो मैं रोज़ करता हूँ।\"\nबीरबल मुस्कराए, \"इसीलिए तो दरबार रोज़ चलता है।\""],
  ["akbar-birbal", "एक दरबारी ने दावा किया कि वह बिना देखे सब पहचान सकता है।\nबीरबल ने उसे बंद आँखों से सिक्का पहचानने को कहा।\nदरबारी ने सिक्का चखा और बोला, \"चाँदी का है।\"\nबीरबल बोले, \"पहचान ठीक है; तरीका शाही वैद्य को मत बताना।\""],
  ["akbar-birbal", "अकबर ने पूछा, \"राज्य में सबसे कीमती चीज़ क्या है?\"\nदरबारी सोना, घोड़ा और महल गिनाने लगे।\nबीरबल बोले, \"समय, क्योंकि खोया हुआ समय खजाने से नहीं लौटता।\"\nअकबर ने उसी दिन दरबार की लंबी बहस छोटी कर दी।"],
  [ "akbar-birbal", "अकबर ने दरबार में पूछा, “सबसे भरोसेमंद खबर कौन-सी होती है?”\nदरबारी बोले, “जो सबसे पहले पहुँचे।”\nबीरबल ने कहा, “नहीं जहाँपनाह, जो जाँच के बाद पहुँचे।”\nअकबर ने फरमान दिया कि अफ़वाहों को अब घोड़े नहीं, सबूत दौड़ाएँगे।" ],
  [ "akbar-birbal", "एक व्यापारी ने दावा किया कि उसका तराज़ू कभी गलत नहीं होता।\nबीरबल ने उससे खाली बाट तौलने को कहा।\nव्यापारी बोला, “खाली चीज़ का वज़न कैसे?”\nबीरबल मुस्कराए, “ईमानदारी भी खाली दावा हो तो उसका वज़न यही होता है।”" ],
  [ "akbar-birbal", "अकबर ने पूछा, “राज्य में सबसे तेज़ कौन दौड़ता है?”\nसिपाही घोड़े का नाम लेने लगे।\nबीरबल बोले, “कर वसूलने की खबर सुनकर प्रजा की बचत।”\nराजा हँसे और बोले, “आज खजाने को भी थोड़ा आराम दो।”" ],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—किसे पुरस्कार दें।\nअकबर ने पूछा, \"किसे पुरस्कार दें?\"\nबीरबल ने उत्तर दिया, \"उस व्यापारी को जो ग्राहक को,\nलौटते समय भी पूरा नाप दे।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—बारिश का पानी किसका है।\nअकबर ने पूछा, \"बारिश का पानी किसका है?\"\nबीरबल ने उत्तर दिया, \"बादल का नहीं,\nउस किसान का भी है जिसने खेत सँभाला।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—सूखा पड़ने पर सबसे पहले क्या बचाएँ।\nअकबर ने पूछा, \"सूखा पड़ने पर सबसे पहले क्या बचाएँ?\"\nबीरबल ने उत्तर दिया, \"बीज और उम्मीद;\nअगली फसल दोनों से उगती है।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—किसान की मेहनत कैसे मापें।\nअकबर ने पूछा, \"किसान की मेहनत कैसे मापें?\"\nबीरबल ने उत्तर दिया, \"उसके हाथों की लकीरों से नहीं,\nखेत की उपज और उसके हिस्से से।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—नहर का पानी सब तक कैसे पहुँचे।\nअकबर ने पूछा, \"नहर का पानी सब तक कैसे पहुँचे?\"\nबीरबल ने उत्तर दिया, \"ऊपर बैठे आदमी की प्यास से नहीं,\nनीचे के खेत की ज़रूरत से।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—फसल कम हो तो कर कितना लें।\nअकबर ने पूछा, \"फसल कम हो तो कर कितना लें?\"\nबीरबल ने उत्तर दिया, \"उतना ही जितना किसान अगली,\nबुवाई के लिए बचा सके।\""],
  [ "akbar-birbal", "अकबर ने पूछा, “सबसे कठिन काम क्या है?”\nबीरबल बोले, “अपनी गलती मानना।”\nअकबर ने कहा, “मैं तो मान लेता हूँ।”\nबीरबल मुस्कराए, “परीक्षा तब होगी जब गलती होगी, जहाँपनाह।”" ],
  [ "akbar-birbal", "एक कवि ने दावा किया कि उसकी कविता सबको समझ आती है।\nअकबर ने बीरबल से राय पूछी।\nबीरबल ने कवि से वही कविता उलटी सुनाने को कहा।\nकवि अटक गया; बीरबल बोले, “दावा बड़ा था, अभ्यास छोटा।”" ],
  [ "akbar-birbal", "अकबर ने पूछा, “सबसे अच्छी सलाह कहाँ मिलती है?”\nदरबारी अपने पद गिनाने लगे।\nबीरबल बोले, “उस व्यक्ति से, जो निर्णय का परिणाम भुगतता है।”\nअकबर ने जनता की बात पहले सुनने का आदेश दिया." ],
  ["akbar-birbal", "एक दिन अकबर ने बीरबल से पूछा, “मेरे दरबार में सबसे तेज़ दिमाग किसका है?”\nबीरबल ने पास बैठे मुंशी की कलम उठा ली और बोले, “हुज़ूर, इसका।”\nअकबर चौंके, “कलम का?”\nबीरबल मुस्कराए, “जी, यह बिना बोले आपकी हर बात लिख लेती है—और गलती हो तो आपके हस्ताक्षर भी माँगती है।”"],
  ["akbar-birbal", "अकबर ने बीरबल को एक खाली थाली देकर कहा, “ऐसा भोजन लाओ जो सबको पसंद आए।”\nबीरबल थाली लेकर रसोई पहुँचे और उसे साफ़ करके लौटा दिए।\nअकबर बोले, “यह क्या?”\nबीरबल ने कहा, “खाली थाली पर किसी को नमक कम या मिर्च ज़्यादा होने की शिकायत नहीं होगी।”"],
  ["akbar-birbal", "दरबार में दो व्यापारी एक ही घोड़े को अपना बता रहे थे।\nअकबर ने बीरबल से फैसला करने को कहा।\nबीरबल ने घोड़े के सामने दोनों से चारा रखने को कहा; घोड़ा तीसरे सिपाही के पास चला गया।\nबीरबल बोले, “मालिकाना हक़ का दावा दोनों का है, भरोसा घोड़े का किसी और पर।”"],
  ["akbar-birbal", "अकबर ने पूछा, “बीरबल, सबसे महँगी चीज़ क्या है?”\nबीरबल ने कहा, “गलत समय पर दिया गया वचन।”\nअकबर ने कारण पूछा।\nबीरबल बोले, “उसे निभाने में धन भी जाता है और न निभाने पर मान भी।”"],
  ["akbar-birbal", "एक दरबारी हर बात में अपनी तारीफ़ जोड़ देता था।\nअकबर ने बीरबल से पूछा, “इसे कैसे समझाएँ?”\nबीरबल ने दरबारी को आईना भेंट किया और कहा, “इसे रोज़ देखिए।”\nदरबारी खुश हुआ; बीरबल ने जोड़ा, “ताकि सभा में दूसरों को भी बोलने की जगह मिले।”"],
  ["akbar-birbal", "अकबर ने बाग़ में सूखे पौधे देखकर माली को डाँटा।\nबीरबल ने पूछा, “हुज़ूर, इसे आख़िरी बार पानी कब मिला था?”\nअकबर को याद नहीं आया।\nबीरबल बोले, “दोष माली का तय करने से पहले हुक्मों की सिंचाई भी देखिए।”"],
  ["akbar-birbal", "दरबार में एक कवि ने दावा किया कि उसकी कविता हर भाषा में समझी जाती है।\nबीरबल ने उससे कविता सुनाने को कहा।\nकवि ने लंबी रचना पढ़ी; सब चुप रहे।\nबीरबल बोले, “वाह! अर्थ इतना गहरा है कि कवि के अलावा किसी तक पहुँचा ही नहीं।”"],
  ["akbar-birbal", "अकबर ने पूछा, “राज्य में सबसे बड़ा पहरेदार कौन है?”\nबीरबल ने कहा, “जनता की याददाश्त।”\nअकबर हँसे, “वह कैसे?”\nबीरबल बोले, “सिपाही महल की रखवाली करते हैं; जनता आपके वादों का हिसाब रखती है।”"],
  ["akbar-birbal", "एक दरबारी ने कहा कि वह बिना सोचे कभी निर्णय नहीं लेता।\nअकबर ने बीरबल से उसकी परीक्षा लेने को कहा।\nबीरबल ने पूछा, “क्या आप अभी बोल रहे हैं?” दरबारी बोला, “जी हाँ।”\nबीरबल ने कहा, “तो आज पहली बार आपने सोचकर उत्तर दिया होगा—कल फिर कोशिश कीजिए।”"],
  ["akbar-birbal", "अकबर ने बीरबल से पूछा, “कौन-सा सलाहकार सबसे उपयोगी है?”\nबीरबल ने कहा, “जो आपकी बात से असहमत होने का साहस रखे।”\nअकबर ने भौंहें चढ़ाईं।\nबीरबल ने जोड़ा, “और जो असहमति के बाद भी काम पूरा करे—वह अनमोल है।”"],
  ["akbar-birbal", "एक व्यापारी ने शिकायत की कि बाज़ार में उसका तराज़ू सही रहता है, फिर भी ग्राहक शक करते हैं।\nबीरबल ने तराज़ू के पलड़े से छिपा सिक्का निकाल लिया।\nव्यापारी घबरा गया।\nबीरबल बोले, “अब तराज़ू सही है; भरोसा लौटाने के लिए थोड़ा समय भी तौलना पड़ेगा।”"],
  ["akbar-birbal", "अकबर ने दरबारियों से पूछा कि सबसे तेज़ कौन पहुँचता है—घोड़ा या संदेशवाहक।\nसबने घोड़े का नाम लिया।\nबीरबल ने कहा, “अफ़वाह।” अकबर ने पूछा, “वह कैसे?”\nबीरबल बोले, “घोड़ा रास्ता पूछता है; अफ़वाह बिना रास्ते और बिना सच के पहुँच जाती है।”"],
  ["akbar-birbal", "एक दरबारी ने अकबर को सलाह दी कि खज़ाने का ताला और भारी कर दिया जाए।\nबीरबल ने पूछा, “खज़ाना किससे बचाना है?”\nदरबारी बोला, “चोरों से।”\nबीरबल ने कहा, “तो चाबी संभालने वालों की ईमानदारी का भी पहरा रखिए।”"],
  ["akbar-birbal", "अकबर ने बीरबल को दो दीपक दिखाए—एक बड़ा, एक छोटा।\n“कौन अधिक प्रकाश देगा?” उन्होंने पूछा।\nबीरबल ने दोनों जलाकर छोटे दीपक को हवा से बचाया।\n“आकार नहीं, देखभाल तय करती है कि उजाला कितना टिकेगा।”"],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—झूठ बोलने वाला क्यों घबराता है।\nअकबर ने पूछा, \"झूठ बोलने वाला क्यों घबराता है?\"\nबीरबल ने उत्तर दिया, \"उसे हर सुबह अपनी पिछली,\nकहानी याद करनी पड़ती है।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—सच्चाई को गवाह चाहिए।\nअकबर ने पूछा, \"सच्चाई को गवाह चाहिए?\"\nबीरबल ने उत्तर दिया, \"कभी-कभी सबूत चाहिए,\nपर सच को सजावट नहीं चाहिए।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—कौन-सा वादा सबसे पक्का है।\nअकबर ने पूछा, \"कौन-सा वादा सबसे पक्का है?\"\nबीरबल ने उत्तर दिया, \"जो लिखने से पहले,\nनिभाने की तैयारी हो।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—दरबारी ने कहा मैं कभी झूठ नहीं बोलता।\nअकबर ने पूछा, \"दरबारी ने कहा मैं कभी झूठ नहीं बोलता।\"\nबीरबल ने उत्तर दिया, \"बीरबल बोले,\nअच्छा है, आज पहली बार सच बोलने का अभ्यास कर लीजिए।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—ईमानदार कर्मचारी को कैसे पहचानें।\nअकबर ने पूछा, \"ईमानदार कर्मचारी को कैसे पहचानें?\"\nबीरबल ने उत्तर दिया, \"जो गलती मिलने पर फ़ाइल नहीं,\nसमाधान लेकर आए।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—सबसे साफ़ आईना कौन-सा।\nअकबर ने पूछा, \"सबसे साफ़ आईना कौन-सा?\"\nबीरबल ने उत्तर दिया, \"वह जिसमें आदमी अपना चेहरा नहीं,\nअपना काम देखे।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—विश्वास टूटे तो क्या करें।\nअकबर ने पूछा, \"विश्वास टूटे तो क्या करें?\"\nबीरबल ने उत्तर दिया, \"उसे भाषण से नहीं,\nलगातार सही काम से जोड़ें।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—सच बोलने का सही समय।\nअकबर ने पूछा, \"सच बोलने का सही समय?\"\nबीरबल ने उत्तर दिया, \"जब चुप्पी किसी निर्दोष को,\nदोषी बना रही हो।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—रसोई का खर्च कैसे घटे।\nअकबर ने पूछा, \"रसोई का खर्च कैसे घटे?\"\nबीरबल ने उत्तर दिया, \"पहले थाली का सम्मान बढ़ाइए,\nफिर बर्बादी घटेगी।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—सबसे स्वादिष्ट भोजन कौन-सा।\nअकबर ने पूछा, \"सबसे स्वादिष्ट भोजन कौन-सा?\"\nबीरबल ने उत्तर दिया, \"जो भूखे तक पहुँचे और,\nमेहनत का अपमान न करे।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—रसोइया कहता है नमक कम है, क्या करें।\nअकबर ने पूछा, \"रसोइया कहता है नमक कम है, क्या करें?\"\nबीरबल ने उत्तर दिया, \"पहले स्वाद चखें;\nशिकायत सुनकर ही नमक मत उड़ेलें।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—दावत में भोजन बच जाए तो।\nअकबर ने पूछा, \"दावत में भोजन बच जाए तो?\"\nबीरबल ने उत्तर दिया, \"अगली दावत का बजट नहीं,\nआज की भूख याद रखिए।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—महँगी मिठाई बेहतर होती है।\nअकबर ने पूछा, \"महँगी मिठाई बेहतर होती है?\"\nबीरबल ने उत्तर दिया, \"मीठा स्वाद से होता है,\nदाम से नहीं।\""],
  ["akbar-birbal", "अकबर के दरबार में आज यह सवाल गूँजा—रसोई में सबसे बड़ा चोर कौन।\nअकबर ने पूछा, \"रसोई में सबसे बड़ा चोर कौन?\"\nबीरबल ने उत्तर दिया, \"वह जो बची हुई,\nरोटी को कूड़ा समझे।\""],
  ["akbar-birbal", "अकबर ने बीरबल से पूछा, “दरबार में सबसे भरोसेमंद गवाह कौन है?”\nबीरबल ने कहा, “वह सिपाही जो घटना के समय वहाँ मौजूद हो।”\nअकबर बोले, “और अगर वह सो रहा हो?”\nबीरबल ने उत्तर दिया, “तो उसकी नींद का बयान भी दर्ज कर लीजिए, हुज़ूर।”"],
  ["akbar-birbal", "एक व्यापारी ने अकबर से शिकायत की कि बाज़ार में ग्राहक बहुत मोलभाव करते हैं।\nअकबर ने बीरबल से उपाय पूछा।\nबीरबल ने व्यापारी से कहा, “दाम उचित रखिए और तौल साफ़।”\nव्यापारी बोला, “फिर मोलभाव कौन करेगा?” बीरबल ने कहा, “आपका हिसाब।”"],
  ["akbar-birbal", "अकबर ने दरबार में पूछा, “सबसे अच्छा नक्शा कौन बनाता है?”\nएक चित्रकार ने अपना सुंदर नक्शा दिखाया।\nबीरबल ने पूछा, “इसमें कुआँ कहाँ है?”\nचित्रकार चुप रहा; बीरबल बोले, “सुंदर नक्शा रास्ता दिखाए, प्यास नहीं बढ़ाए।”"],
  ["akbar-birbal", "एक मंत्री ने दावा किया कि महल का हर दरवाज़ा सुरक्षित है।\nबीरबल ने पूछा, “फिर शिकायतें बाहर कैसे निकलती हैं?”\nमंत्री ने कहा, “शिकायतें तो लोग करते हैं।”\nबीरबल बोले, “तो पहले सुनने का दरवाज़ा खोलिए, पहरा बाद में बढ़ाइए।”"],
  ["akbar-birbal", "अकबर ने बीरबल को एक भारी संदूक उठाने को कहा।\nबीरबल ने दो मज़दूर बुलाए और संदूक आराम से रखवा दिया।\nअकबर ने पूछा, “तुमने स्वयं क्यों नहीं उठाया?”\nबीरबल बोले, “हुज़ूर, समझदारी का काम ताकत दिखाना नहीं, सही ताकत लगाना है।”"],
  ["akbar-birbal", "दरबार में एक ज्योतिषी ने कहा कि कल वर्षा अवश्य होगी।\nअकबर ने बीरबल से पूछा कि क्या तैयारी की जाए।\nबीरबल ने छाते मँगवाए और किसानों को खेत देखने भेजा।\n“भविष्यवाणी छाता दे सकती है,” वे बोले, “फसल की देखभाल नहीं।”"],
  ["akbar-birbal", "अकबर ने पूछा, “किसी अधिकारी की योग्यता कैसे परखें?”\nबीरबल ने एक छोटी अर्ज़ी उसके सामने रखी।\nअधिकारी ने उसे पढ़े बिना मुहर लगा दी।\nबीरबल बोले, “हुज़ूर, परीक्षा पूरी हुई—इन्हें पढ़ने का अभ्यास चाहिए।”"],
  ["akbar-birbal", "एक दरबारी ने कहा कि उसके पास हर प्रश्न का उत्तर है।\nबीरबल ने पूछा, “तो क्या आप यह भी जानते हैं कि आपको क्या नहीं पता?”\nदरबारी ने तुरंत हाँ कहा।\nबीरबल मुस्कराए, “अब हमें पता चल गया कि एक प्रश्न का उत्तर आपको नहीं आता।”"],
  ["akbar-birbal", "अकबर ने बाग़ में लगे आमों की गिनती पूछी।\nमाली ने अनुमान बताया और दरबारियों ने अलग-अलग संख्या कही।\nबीरबल ने टोकरी मँगवाई और आम तुड़वाकर गिने।\n“अनुमान सभा को व्यस्त रखता है,” वे बोले, “गिनती काम पूरा करती है।”"],
  ["akbar-birbal", "एक सैनिक ने कहा कि महल की दीवारें इतनी ऊँची हैं कि कोई भीतर नहीं आ सकता।\nबीरबल ने पूछा, “और जो भीतर से लापरवाही करे?”\nसैनिक ने सिर झुका लिया।\nबीरबल बोले, “दीवार बाहर वालों को रोकती है; चौकसी भीतर वालों की ज़िम्मेदारी है।”"],
  ["akbar-birbal", "अकबर ने पूछा, “न्याय में सबसे ज़रूरी क्या है—तेज़ी या सावधानी?”\nबीरबल ने कहा, “दोनों का संतुलन।”\nअकबर ने उदाहरण माँगा।\nबीरबल बोले, “जल्दी में गलत फैसला अन्याय है; देर से मिला सही फैसला भी अधूरा न्याय है।”"],
  ["akbar-birbal", "दरबार में एक लेखक ने अपनी लिखावट की प्रशंसा की।\nबीरबल ने उससे आदेश पढ़ने को कहा।\nलेखक स्वयं अपनी लिखी पंक्ति न पढ़ सका।\nबीरबल बोले, “अच्छी लिखावट वह है जिसे लिखने वाला ही नहीं, पाने वाला भी समझे।”"],
  ["akbar-birbal", "अकबर ने पूछा, “राज्य की सड़कें कब अच्छी मानी जाएँगी?”\nमंत्री ने कहा, “जब उनका उद्घाटन भव्य हो।”\nबीरबल बोले, “जब बरसात के बाद भी उन पर चल सकें।”\nअकबर ने उसी दिन मरम्मत का हिसाब मँगवाया।"],
  ["akbar-birbal", "एक दरबारी ने कहा कि वह हर दिन बहुत काम करता है।\nबीरबल ने पूछा, “कौन-सा काम पूरा हुआ?”\nदरबारी ने अपनी व्यस्तता की सूची पढ़नी शुरू कर दी।\nबीरबल बोले, “सूची लंबी है; अब उसमें परिणाम का एक पन्ना जोड़िए।”"],
  ["akbar-birbal", "अकबर ने बीरबल से पूछा, “सबसे कठिन वादा कौन-सा है?”\nबीरबल ने कहा, “वह जो दूसरों के लिए किया जाए।”\nअकबर ने कारण पूछा।\n“क्योंकि उसमें अपनी सुविधा नहीं, दूसरे की ज़रूरत पहले रखनी पड़ती है।”"],
  ["akbar-birbal", "एक व्यापारी ने कहा कि उसके गोदाम में अनाज कभी खराब नहीं होता।\nबीरबल ने देखा कि बोरे ज़मीन पर रखे थे और छत टपक रही थी।\nउन्होंने व्यापारी से पूछा, “फिर यह गीली बोरियाँ किसकी हैं?”\nव्यापारी बोला, “पुराना माल।” बीरबल ने कहा, “बहाना भी अब भीग चुका है।”"],
  ["akbar-birbal", "अकबर ने दरबारियों से पूछा कि खाली समय का सबसे अच्छा उपयोग क्या है।\nकिसी ने संगीत कहा, किसी ने शिकार।\nबीरबल ने कहा, “लंबित अर्ज़ियाँ पढ़ना।”\nअकबर हँसे, “तुम्हें तो खाली समय भी काम से भरना है।”"],
  ["akbar-birbal", "एक दरबारी ने दावा किया कि वह बिना देखे भी सही निर्णय कर सकता है।\nबीरबल ने उसके सामने दो समान मुहरें रखीं और एक चुनने को कहा।\nदरबारी ने आँखें बंद कर एक उठा ली।\nबीरबल बोले, “मुहर सही निकली; अब आँखें खोलकर काग़ज़ भी पढ़िए।”"],
  ["akbar-birbal", "अकबर ने पूछा, “किसे बड़ा मानें—धनवान को या दानी को?”\nबीरबल ने एक भरा घड़ा और एक प्याला सामने रखा।\nउन्होंने घड़े से प्याले में पानी डालकर प्यासे सिपाही को दिया।\n“भरा होना संपत्ति है,” वे बोले, “बाँटना उसका सदुपयोग।”"],
  ["akbar-birbal", "दरबार में एक कवि ने कहा कि उसकी कविता सुनकर पत्थर भी पिघल जाएँ।\nबीरबल ने उसे महल के पत्थर के फर्श पर कविता सुनाने को कहा।\nकविता पूरी हुई, फर्श वैसा ही रहा।\nबीरबल बोले, “कविता अच्छी हो सकती है; अब इसे सुनकर सफ़ाई करने वाले को छुट्टी दिलाइए।”"],
  ["akbar-birbal", "अकबर ने बीरबल से पूछा, \"राज्य में सबसे तेज़ खबर कौन फैलाता है?\"\nबीरबल ने कहा, \"शाही ढोल नहीं, हुज़ूर—बाज़ार की अफ़वाह।\"\nअकबर ने पूछा, \"उसे रोकें कैसे?\"\nबीरबल बोले, \"पहले सच बता दीजिए; अफ़वाह को काम ही नहीं मिलेगा।\""],
  ["akbar-birbal", "एक व्यापारी ने दरबार में शिकायत की कि उसका तराज़ू हमेशा सही बताता है।\nबीरबल ने पूछा, \"फिर ग्राहक नाराज़ क्यों हैं?\"\nव्यापारी बोला, \"वे कम तौल चाहते हैं।\"\nबीरबल ने कहा, \"तो तराज़ू नहीं, आपकी नीयत ठीक करवाइए।\""],
  ["akbar-birbal", "अकबर ने पूछा, \"बीरबल, अच्छा मंत्री किसे कहेंगे?\"\nबीरबल बोले, \"जो राजा को प्रसन्न करने से पहले राज्य की परेशानी सुने।\"\nअकबर मुस्कराए, \"और जो हर बात में मेरी हाँ में हाँ मिलाए?\"\nबीरबल ने कहा, \"वह मंत्री नहीं, दरबार का प्रतिध्वनि-कक्ष है।\""],
  ["akbar-birbal", "दरबार में एक कवि ने दावा किया कि उसकी कविता सबको समझ आती है।\nअकबर ने बीरबल से राय माँगी।\nबीरबल ने कवि से कविता का अर्थ पूछा; वह स्वयं उलझ गया।\nबीरबल बोले, \"हुज़ूर, कविता कठिन नहीं—कवि का परिचय अभी अधूरा है।\""],
  ["akbar-birbal", "अकबर ने सैनिकों की चौकसी जाँचने का उपाय पूछा।\nबीरबल ने रात में महल के फाटक पर एक खाली संदूक रखवा दिया।\nसुबह पहरेदार ने संदूक सुरक्षित होने की सूचना दी।\nबीरबल बोले, \"चौकसी अच्छी है; अब यह भी पूछिए कि खाली संदूक आया कहाँ से।\""],
  ["akbar-birbal", "एक दरबारी ने कहा कि वह बिना मेहनत के बड़ा काम कर सकता है।\nअकबर ने उसे राज्य का कुआँ साफ़ करने भेजा।\nवह बोला, \"यह तो बहुत कठिन है!\"\nबीरबल मुस्कराए, \"आपने काम बड़ा माँगा था, मेहनत छोटी नहीं।\""],
  ["akbar-birbal", "अकबर ने पूछा, \"सच्चा मित्र संकट में कैसे पहचाना जाता है?\"\nबीरबल ने दो दरबारियों को बुलाकर एक भारी संदूक उठाने को कहा।\nएक ने बहाना बनाया, दूसरे ने साथ दिया।\nबीरबल बोले, \"मित्र वही नहीं जो संदूक उठाए; जो बहाना छोड़कर आए, वही मित्र है।\""],
  ["akbar-birbal", "एक ज्योतिषी ने दावा किया कि वह भविष्य की हर घटना जानता है।\nअकबर ने पूछा, \"कल दरबार में कौन देर से आएगा?\"\nज्योतिषी चुप हो गया।\nबीरबल बोले, \"हुज़ूर, भविष्य बताने से पहले इन्हें आज का समय तो मालूम हो।\""],
  ["akbar-birbal", "अकबर ने पूछा, \"राजकोष में बचत कैसे बढ़े?\"\nबीरबल ने कहा, \"पहले उन खर्चों की सूची बनाइए जिनका लाभ किसी ने देखा ही नहीं।\"\nखजांची ने लंबी सूची रख दी।\nअकबर बोले, \"यह सूची इतनी लंबी है कि बचत शुरू होने से पहले ही खज़ाना थक गया।\""],
  ["akbar-birbal", "एक दरबारी ने कहा कि वह हर प्रश्न का उत्तर जानता है।\nबीरबल ने पूछा, \"तो बताइए, मौन का रंग क्या होता है?\"\nदरबारी ने तुरंत उत्तर देना चाहा, फिर रुक गया।\nबीरबल बोले, \"आज आपने पहली बार सही उत्तर दिया—मौन को मौन रहने दिया।\""],
  ["akbar-birbal", "अकबर ने बीरबल से पूछा, \"न्याय में सबसे बड़ी बाधा क्या है?\"\nबीरबल बोले, \"जब फैसला सुनने से पहले ही पक्ष चुन लिया जाए।\"\nअकबर ने कहा, \"और उपाय?\"\n\"दोनों पक्षों को बराबर समय दीजिए; फिर अपने मन को भी गवाही देने से रोकिए।\""],
  ["akbar-birbal", "एक किसान ने शिकायत की कि पड़ोसी उसकी छाया भी अपने खेत में नहीं आने देता।\nअकबर ने मामला बीरबल को सौंपा।\nबीरबल ने दोनों को दोपहर में खेत पर बुलाया।\nउन्होंने कहा, \"छाया सूरज की है; झगड़ा बाँटने से पहले पेड़ लगाना सीखिए।\""],
  ["akbar-birbal", "अकबर ने पूछा, \"सबसे कठिन पहेली कौन-सी है?\"\nबीरबल बोले, \"वह जिसमें उत्तर सामने हो, पर पूछने वाला सुनना न चाहे।\"\nअकबर ने हँसकर कहा, \"क्या यह मेरे लिए है?\"\nबीरबल बोले, \"हुज़ूर, आपने ही तो उत्तर पूछ लिया।\""],
  ["akbar-birbal", "एक दरबारी ने अपनी वफ़ादारी का प्रमाण माँगा।\nबीरबल ने उसे राज्य की गलती गिनाने को कहा।\nवह बोला, \"मुझसे ऐसी गुस्ताख़ी नहीं होगी।\"\nबीरबल ने कहा, \"जो गलती बताए ही नहीं, उसकी वफ़ादारी राज्य को अँधा कर देती है।\""],
  ["akbar-birbal", "अकबर ने पूछा, \"समय की कीमत कैसे समझें?\"\nबीरबल ने दरबार की घड़ी कुछ देर के लिए रोक दी।\nदरबारी बेचैन हो उठे और काम रुक गया।\nबीरबल बोले, \"घड़ी रुकी थी, हुज़ूर—आप सबका समय फिर भी खर्च होता रहा।\""],
  ["akbar-birbal", "एक सुनार ने दावा किया कि उसका सोना कभी कम नहीं पड़ता।\nबीरबल ने उससे सोने की शुद्धता पूछी।\nसुनार बोला, \"मेरी बात पर भरोसा कीजिए।\"\nबीरबल ने कहा, \"धातु की जाँच अग्नि करती है; आदमी की जाँच सवाल।\""],
  ["akbar-birbal", "अकबर ने पूछा, \"राजा को कब बोलना चाहिए?\"\nबीरबल ने उत्तर दिया, \"जब बोलने से उलझन सुलझे।\"\n\"और कब चुप रहना चाहिए?\"\n\"जब प्रजा अपनी बात कह रही हो—दरबार कोई एकल प्रस्तुति नहीं है।\""],
  ["akbar-birbal", "एक दूत ने संदेश पहुँचाने में तीन दिन लगा दिए।\nउसने रास्ते की कठिनाइयों का लंबा वर्णन किया।\nबीरबल ने पूछा, \"संदेश सुरक्षित है?\"\nदूत बोला, \"जी।\"\nबीरबल ने कहा, \"अच्छा; अब अगली बार संदेश के साथ समय भी बचाकर लाइए।\""],
  ["akbar-birbal", "अकबर ने पूछा, \"बुद्धिमान और चतुर में क्या अंतर है?\"\nबीरबल बोले, \"चतुर रास्ता निकालता है; बुद्धिमान देखता है कि जाना भी चाहिए या नहीं।\"\nअकबर ने कहा, \"तो आज दरबार जल्दी समाप्त करें?\"\nबीरबल बोले, \"हुज़ूर, आज आपने दोनों गुण दिखा दिए।\""],
  ["akbar-birbal", "एक दरबारी ने कहा कि महल की हर समस्या का समाधान उसके पास है।\nबीरबल ने पूछा, \"तो यह टूटी सीढ़ी क्यों नहीं सुधरी?\"\nदरबारी बोला, \"मुझे आदेश नहीं मिला।\"\nबीरबल ने कहा, \"समस्या सीढ़ी में थी; रुकावट आपके आदेश की प्रतीक्षा में।\""],
  ["akbar-birbal", "अकबर ने पूछा, \"प्रजा का भरोसा कैसे जीता जाए?\"\nबीरबल बोले, \"वादा कम कीजिए, पूरा अधिक।\"\nएक मंत्री ने कहा, \"यह सुनने में बहुत सरल है।\"\nबीरबल ने उत्तर दिया, \"इसीलिए कठिन है—इसमें बहाने की जगह नहीं।\""],
  ["akbar-birbal", "एक व्यापारी ने कहा कि उसके हिसाब में एक भी गलती नहीं।\nबीरबल ने बहीखाता देखा; कुल जोड़ सही था, पर एक पन्ना गायब था।\nव्यापारी बोला, \"वह पन्ना अलग रख दिया।\"\nबीरबल ने कहा, \"हिसाब में जोड़ सही हो सकता है; सच में घटाव नहीं।\""],
  ["akbar-birbal", "अकबर ने पूछा, \"दरबार में सबसे उपयोगी सलाह कौन देता है?\"\nबीरबल बोले, \"वह जो असहमति जताने का साहस रखे।\"\nमंत्री ने कहा, \"ऐसे व्यक्ति से राजा नाराज़ हो सकता है।\"\nबीरबल बोले, \"इसीलिए उसकी सलाह की कीमत और बढ़ जाती है।\""],
  ["akbar-birbal", "एक पहरेदार ने दावा किया कि उसने रात भर आँख नहीं झपकाई।\nअकबर ने पूछा, \"तो सुबह फाटक खुला कैसे रह गया?\"\nपहरेदार घबरा गया।\nबीरबल बोले, \"जागते रहने का दावा आसान है; जागरूक रहने का हिसाब दीजिए।\""],
  ["corruption", "अकबर ने पूछा, \"राज्य की सबसे मज़बूत दीवार कौन-सी है?\"\nबीरबल ने कहा, \"न्याय पर जनता का भरोसा।\"\nअकबर ने पत्थर की दीवारों की ओर देखा।\nबीरबल बोले, \"पत्थर टूटे तो मरम्मत होगी; भरोसा टूटे तो नींव हिलती है।\""],
  ["corruption", "नगर निगम के दफ़्तर में नागरिक ने पूछा, \"नाली की सफ़ाई का भुगतान हो गया, नाली अब भी भरी क्यों है?\"\nकर्मचारी ने फ़ाइल पलटकर कहा, \"कागज़ों में सफ़ाई पूरी है।\"\nनागरिक बोला, \"तो फ़ाइल को ही नाली में बहा दीजिए।\"\nकर्मचारी ने तुरंत कहा, \"सरकारी संपत्ति को नुकसान पहुँचाना मना है।\""],
  ["corruption", "एक ठेकेदार ने पुल का उद्घाटन समय से पहले कर दिया।\nपत्रकार ने पूछा, \"काम पूरा कैसे हुआ?\"\nठेकेदार बोला, \"फीता काटने का काम सबसे पहले पूरा होता है।\"\nपास खड़े मज़दूर ने कहा, \"बाक़ी पुल अभी मेहनत कर रहा है।\""],
  ["corruption", "कार्यालय में अधिकारी ने पारदर्शिता पर भाषण दिया।\nनागरिक ने पूछा, \"खर्च का पूरा विवरण कहाँ मिलेगा?\"\nअधिकारी ने पर्दा हटाकर दीवार पर लगा नया नारा दिखाया।\nनागरिक बोला, \"पर्दा तो हट गया, हिसाब अब भी ढका है।\""],
  ["corruption", "एक विभाग ने शिकायतों के समाधान का नया पोर्टल शुरू किया।\nपहले दिन नागरिक ने टूटी सड़क की शिकायत दर्ज की।\nपोर्टल ने उत्तर दिया, \"आपकी समस्या हमारे लिए महत्वपूर्ण है।\"\nदूसरे दिन सड़क पर गड्ढा और पोर्टल पर वही उत्तर था।"],
  ["corruption", "निरीक्षण से पहले सड़क पर जल्दी-जल्दी रंगीन पट्टी बनाई गई।\nअधिकारी ने तस्वीर देखकर कहा, \"काम शानदार दिख रहा है।\"\nस्थानीय निवासी ने पूछा, \"बारिश में भी ऐसा ही दिखेगा?\"\nमज़दूर बोला, \"बारिश को निरीक्षण की तारीख़ बता दीजिए।\""],
  ["corruption", "एक दफ़्तर में फाइलें गायब होने की जाँच बैठी।\nजाँच अधिकारी ने पूछा, \"आख़िरी बार फाइल किसने देखी थी?\"\nसबने एक-दूसरे की ओर देखा।\nचपरासी बोला, \"साहब, फाइल तो सबने देखी; पढ़ी किसी ने नहीं।\""],
  ["corruption", "नगरपालिका ने पार्क के लिए नया बजट घोषित किया।\nबच्चों ने पूछा, \"झूले कब लगेंगे?\"\nअधिकारी ने कहा, \"पहले योजना बनेगी, फिर समिति बैठेगी।\"\nएक बच्चे ने कहा, \"तब तक हम बजट की स्लाइड पर झूल लें?\""],
  ["corruption", "एक नागरिक ने सूचना माँगी कि सड़क की मरम्मत कितनी बार हुई।\nकार्यालय ने मरम्मत की तारीख़ों की लंबी सूची भेजी।\nनागरिक ने पूछा, \"सड़क की हालत का रिकॉर्ड?\"\nजवाब आया, \"वह अलग विभाग में है; शायद सड़क वहीं चली गई।\""],
  ["corruption", "ठेके की बोली में सबसे कम कीमत वाली कंपनी चुनी गई।\nअगले महीने काम की गुणवत्ता पर सवाल उठा।\nअधिकारी ने कहा, \"हमने पैसे बचाए हैं।\"\nनिवासी बोला, \"जी, अब मरम्मत के लिए फिर से पैसे बचाइए।\""],
  ["corruption", "जनता ने पूछा कि सार्वजनिक शौचालय का ताला क्यों बंद है।\nकर्मचारी ने कहा, \"उद्घाटन हो चुका है, उपयोग की अनुमति लंबित है।\"\nएक बुज़ुर्ग ने पूछा, \"अनुमति किससे मिलेगी?\"\nकर्मचारी बोला, \"जिसे ज़रूरत नहीं, वही समिति में है।\""],
  ["corruption", "एक परियोजना की प्रगति रिपोर्ट में लिखा था—काम लगभग पूरा।\nनागरिक ने स्थल पर जाकर देखा, वहाँ सिर्फ़ बोर्ड लगा था।\nउसने पूछा, \"लगभग का मतलब क्या है?\"\nमज़दूर बोला, \"बोर्ड पूरा है; परियोजना अभी कल्पना में है।\""],
  ["corruption", "दफ़्तर ने शिकायतों के निपटारे का रिकॉर्ड दिखाया।\nअधिकारी ने गर्व से कहा, \"सभी मामलों पर कार्रवाई हुई है।\"\nनागरिक ने पूछा, \"नतीजा कहाँ है?\"\nअधिकारी बोला, \"कार्रवाई फ़ाइल में है; नतीजे की फ़ाइल बन रही है।\""],
  ["corruption", "एक ठेकेदार ने कहा कि निर्माण में कोई कमी नहीं है।\nइंजीनियर ने दीवार पर हल्की दरार दिखा दी।\nठेकेदार बोला, \"यह दरार नहीं, हवा आने का इंतज़ाम है।\"\nइंजीनियर ने कहा, \"तो अगली बार छत में भी खिड़की बना देना।\""],
  ["corruption", "गाँव की सड़क के लिए धन स्वीकृत हुआ।\nग्रामसभा ने पूछा, \"काम कब शुरू होगा?\"\nअधिकारी ने कहा, \"प्रक्रिया चल रही है।\"\nएक किसान बोला, \"साहब, बैलगाड़ी भी प्रक्रिया से तेज़ चलती है।\""],
  ["corruption", "एक कार्यालय ने दावा किया कि अब हर सेवा ऑनलाइन है।\nनागरिक ने प्रमाणपत्र डाउनलोड करना चाहा।\nवेबसाइट ने कहा, \"कृपया कार्यालय में उपस्थित होकर ऑनलाइन आवेदन करें।\"\nनागरिक बोला, \"इंटरनेट आया है या सिर्फ़ नया चक्कर?\""],
  ["corruption", "पानी की टंकी का उद्घाटन हुआ, लेकिन नल सूखे रहे।\nअधिकारी ने कहा, \"आपूर्ति शीघ्र शुरू होगी।\"\nबच्चे ने पूछा, \"फिर पानी के बिना रिबन क्यों काटा?\"\nअधिकारी बोला, \"क्योंकि रिबन को पानी नहीं चाहिए।\""],
  ["corruption", "एक पार्षद ने कहा कि इलाके में हर समस्या का समाधान हो चुका है।\nनिवासी ने सड़क का गड्ढा दिखाया।\nपार्षद बोले, \"यह गड्ढा नहीं, वर्षा जल संचयन का अवसर है।\"\nनिवासी ने कहा, \"तो इसमें आपका वादा भी जमा कर दूँ?\""],
  ["corruption", "दफ़्तर में खर्च का ऑडिट चल रहा था।\nलेखाकार ने कहा, \"हर बिल के साथ प्रमाण लगा है।\"\nऑडिटर ने पूछा, \"काम का प्रमाण कहाँ है?\"\nलेखाकार बोला, \"वह अगली फाइल में है—और फाइल अभी रास्ते में है।\""],
  ["corruption", "एक विभाग ने स्वच्छता अभियान की तस्वीरें साझा कीं।\nनागरिक ने पूछा, \"कूड़ा उठाने की तारीख़ क्या है?\"\nअधिकारी ने कहा, \"तस्वीरें आज की हैं।\"\nनागरिक बोला, \"कूड़ा पुराना है; शायद उसे भी फोटो खिंचवाने का अनुभव है।\""],
  ["corruption", "नगर निगम ने फुटपाथ पर अतिक्रमण हटाने की घोषणा की।\nटीम पहुँची तो रास्ता फिर से सामान से भरा था।\nअधिकारी ने कहा, \"कार्रवाई जारी रहेगी।\"\nदुकानदार बोला, \"जी, सामान भी रोज़ वापस आने का अभ्यास करता है।\""],
  ["corruption", "एक नागरिक ने पूछा कि सड़क की गारंटी कितने साल की है।\nअधिकारी ने कहा, \"कागज़ पर पाँच साल।\"\nनागरिक ने सामने उखड़ी सड़क दिखाई।\nअधिकारी बोला, \"यह कागज़ से बाहर की स्थिति है।\""],
  ["corruption", "कार्यालय ने नई हेल्पलाइन शुरू की।\nनागरिक ने फोन करके पानी की समस्या बताई।\nरिकॉर्डेड आवाज़ बोली, \"आपका कॉल हमारे लिए मूल्यवान है।\"\nनागरिक ने कहा, \"तो कृपया इसे पानी की टंकी तक पहुँचा दीजिए।\""],
  ["corruption", "एक योजना के बोर्ड पर लिखा था—लाभार्थियों की सूची शीघ्र।\nगाँव वालों ने पूछा, \"सूची कहाँ देख सकते हैं?\"\nकर्मचारी बोला, \"सूची तैयार है, बस सार्वजनिक होना बाकी है।\"\nएक बुज़ुर्ग ने कहा, \"फिर तो लाभ भी तैयार होगा, बस मिलना बाकी है।\""],
  ["corruption", "निरीक्षण दल ने स्कूल की नई इमारत देखी।\nप्रधानाचार्य ने बताया कि कक्षाएँ अभी पुराने कमरे में चलती हैं।\nअधिकारी ने पूछा, \"नई इमारत खाली क्यों है?\"\nप्रधानाचार्य बोले, \"उद्घाटन के बाद से वह सिर्फ़ मेहमानों का स्वागत करती है।\""],
  ["corruption", "एक नागरिक ने पूछा कि नाले की सफ़ाई का ठेका किसे मिला।\nअधिकारी ने कहा, \"सब कुछ नियम से हुआ है।\"\nनागरिक ने नाले की तस्वीर दिखाई।\nअधिकारी बोला, \"तस्वीर में तारीख़ नहीं है।\"\nनागरिक ने जवाब दिया, \"बदबू रोज़ की है; उसे तारीख़ की ज़रूरत नहीं।\""],
  ["corruption", "दफ़्तर में अधिकारी ने कहा कि अब भ्रष्टाचार के लिए कोई जगह नहीं बची।\nनागरिक ने पूछा, \"तो शिकायत कहाँ दर्ज कराएँ?\"\nअधिकारी ने मुस्कराकर कहा, \"शिकायत कक्ष में।\"\nनागरिक बोला, \"अच्छा, जगह तो बची है—बस नाम बदल गया।\""],
  ["corruption", "एक परियोजना का उद्घाटन तीसरी बार तय हुआ।\nपत्रकार ने पूछा, \"पहले दो उद्घाटन किस बात के थे?\"\nअधिकारी ने कहा, \"पहले योजना का, फिर घोषणा का।\"\nमज़दूर बोला, \"अब शायद काम का भी दिन आ जाए।\""],
  ["corruption", "सरकारी गोदाम में अनाज की जाँच हुई।\nअधिकारी ने रिकॉर्ड देखकर कहा, \"कागज़ पर सब सुरक्षित है।\"\nकिसान ने खाली बोरी उठाकर दिखाई।\nवह बोला, \"साहब, अनाज भी शायद कागज़ पढ़कर बाहर चला गया।\""],
  ["corruption", "एक कार्यालय ने समय पर सेवा देने का वादा किया।\nनागरिक सुबह से कतार में खड़ा रहा।\nदोपहर को खिड़की पर पर्ची लगी—आज समय समाप्त।\nनागरिक बोला, \"सेवा समय पर समाप्त हुई; वादा भी निभ गया।\""],
  ["corruption", "गाँव में स्ट्रीट लाइट लगाने का बिल पास हो गया।\nरात को पूरा रास्ता अँधेरे में था।\nअधिकारी ने कहा, \"लाइटें लग चुकी हैं।\"\nगाँव वाले ने पूछा, \"तो रोशनी किस विभाग में जमा है?\""],
  ["corruption", "नगर के स्वास्थ्य केंद्र में दवा का स्टॉक रजिस्टर भरा हुआ था।\nमरीज ने खिड़की पर पूछा, \"दवा कहाँ मिलेगी?\"\nकर्मचारी ने रजिस्टर दिखाकर कहा, \"यहाँ तो पूरी उपलब्ध है।\"\nमरीज बोला, \"फिर इलाज रजिस्टर को ही कर दीजिए।\""],
  ["corruption", "सड़क निर्माण की जाँच में अधिकारी ने नई परत देखकर तारीफ़ की।\nस्थानीय दुकानदार ने पूछा, \"पुरानी सड़क कहाँ गई?\"\nठेकेदार बोला, \"उसे नई सड़क के नीचे सम्मानपूर्वक रखा है।\"\nदुकानदार ने कहा, \"तो अगली बारिश में पुरानी यादें फिर बाहर आएँगी।\""],
  ["corruption", "गाँव में पेयजल योजना का बोर्ड लगा, पर नल सूखे रहे।\nअधिकारी ने कहा, \"काम कागज़ पर पूरा हो चुका है।\"\nएक किसान बोला, \"कागज़ से पानी निकालने की मशीन भी लगवा दीजिए।\"\nअधिकारी ने फ़ाइल बंद की और बोला, \"उसका प्रस्ताव अगली योजना में जाएगा।\""],
  ["corruption", "एक नागरिक ने पूछा कि स्ट्रीट लाइट लगाने का भुगतान किसे हुआ।\nकर्मचारी ने कहा, \"ठेकेदार को पूरा भुगतान हो गया।\"\nनागरिक बोला, \"रात में अँधेरा किसे भुगतान कर रहे हैं?\"\nकर्मचारी ने उत्तर दिया, \"वह तो बिजली विभाग का विषय है।\""],
  ["corruption", "नगर कार्यालय ने कूड़ा उठाने की नई समय-सारणी जारी की।\nनिवासी सुबह से गाड़ी का इंतज़ार करते रहे।\nदोपहर में संदेश आया कि सेवा सफलतापूर्वक पूरी हुई।\nएक बच्चे ने पूछा, \"कूड़ा गया या सिर्फ़ संदेश पहुँच गया?\""],
  ["corruption", "एक पुल की मरम्मत का उद्घाटन फिर से तय हुआ।\nपत्रकार ने पूछा, \"पिछली बार मरम्मत कब हुई थी?\"\nअधिकारी बोले, \"तारीख़ रिकॉर्ड में है।\"\nमज़दूर ने कहा, \"पुल को तारीख़ नहीं, थोड़ी मज़बूती याद है।\""],
  ["corruption", "विद्यालय में नई प्रयोगशाला का बजट स्वीकृत हुआ।\nप्रधानाचार्य ने पूछा, \"उपकरण कब आएँगे?\"\nअधिकारी ने कहा, \"पहले खरीद की प्रक्रिया पूरी होगी।\"\nएक छात्र बोला, \"तब तक हम प्रयोग बजट पर ही कर लें?\""],
  ["corruption", "एक अस्पताल में मरीज ने पूछा कि एक्स-रे मशीन कब चलेगी।\nकर्मचारी ने कहा, \"मशीन की मरम्मत का बिल पास हो गया है।\"\nमरीज बोला, \"मुझे बिल नहीं, जाँच चाहिए।\"\nकर्मचारी ने जवाब दिया, \"जाँच के लिए पहले मरम्मत की जाँच होगी।\""],
  ["corruption", "नगर निगम ने पार्क में पौधे लगाने का अभियान चलाया।\nनागरिक ने पूछा, \"पौधे कहाँ लगाए गए?\"\nअधिकारी ने तस्वीरों का एल्बम दिखाया।\nबच्चे ने कहा, \"तस्वीर में तो पेड़ हैं; हमारे पार्क में अभी भी पोस्टर उग रहे हैं।\""],
  ["corruption", "एक राशन दुकान पर लाभार्थी ने अपना नाम सूची में खोजा।\nदुकानदार ने कहा, \"सूची में नाम है, पर माल अभी नहीं आया।\"\nलाभार्थी बोला, \"तो सूची से ही दो किलो अनाज तौल दीजिए।\"\nदुकानदार ने कहा, \"सूची डिजिटल है; उसमें छेद नहीं कर सकते।\""],
  ["corruption", "ठेकेदार ने नाली निर्माण पूरा होने की रिपोर्ट जमा की।\nइंजीनियर ने स्थल पर जाकर देखा कि नाली का रास्ता दीवार पर खत्म था।\nठेकेदार बोला, \"आगे की दिशा अगली परियोजना में है।\"\nइंजीनियर ने कहा, \"पानी को भी अब अगली किस्त का इंतज़ार करना पड़ेगा।\""],
  ["corruption", "एक नागरिक ने कार्यालय से सड़क की मरम्मत का खर्च पूछा।\nअधिकारी ने कुल राशि बता दी।\nनागरिक ने पूछा, \"कितने गड्ढे भरे गए?\"\nअधिकारी बोले, \"उसका हिसाब गड्ढों से ही लेना पड़ेगा।\""],
  ["corruption", "सरकारी बस अड्डे पर शौचालय का नया बोर्ड लगा था।\nयात्री ने पूछा, \"सुविधा किस तरफ़ है?\"\nकर्मचारी ने बंद दरवाज़े की ओर इशारा किया।\nयात्री बोला, \"बोर्ड खुला है, दरवाज़ा छुट्टी पर क्यों है?\""],
  ["corruption", "एक विभाग ने दावा किया कि शिकायतों का निपटारा चौबीस घंटे में होता है।\nनागरिक ने पुरानी शिकायत का नंबर दिखाया।\nअधिकारी ने कहा, \"आपकी शिकायत प्रक्रिया में है।\"\nनागरिक बोला, \"लगता है प्रक्रिया को ही चौबीस घंटे से ज़्यादा लग गए।\""],
  ["corruption", "गाँव की सड़क के लिए बजट आया और स्वागत समारोह भी हुआ।\nकिसान ने पूछा, \"मिट्टी कब हटेगी?\"\nअधिकारी ने कहा, \"पहले शिलान्यास होगा।\"\nकिसान बोला, \"हम तो रोज़ कीचड़ में चलकर पहले ही नींव रख चुके हैं।\""],
  ["corruption", "एक कार्यालय ने ऑनलाइन प्रमाणपत्र सेवा शुरू की।\nआवेदक ने वेबसाइट पर आवेदन भरा।\nअंतिम चरण में संदेश आया—मूल दस्तावेज़ लेकर काउंटर पर आएँ।\nआवेदक बोला, \"ऑनलाइन यात्रा पूरी हुई; अब ऑफलाइन दर्शन बाकी हैं।\""],
  ["corruption", "नगर के नाले की सफ़ाई का निरीक्षण हुआ।\nअधिकारी ने पूछा, \"काम संतोषजनक है?\"\nनिवासी ने कहा, \"आप खिड़की बंद करके देखिए।\"\nअधिकारी ने पूछा, \"क्यों?\"\nनिवासी बोला, \"तब आपको रिपोर्ट की खुशबू समझ आएगी।\""],
  ["corruption", "एक सार्वजनिक नल पर पानी नहीं आ रहा था।\nकर्मचारी ने कहा, \"लाइन में दबाव कम है।\"\nनागरिक ने पूछा, \"कब बढ़ेगा?\"\nकर्मचारी बोला, \"जब शिकायतों का दबाव ऊपर तक पहुँचेगा।\""],
  ["corruption", "नगर निगम ने फुटपाथ चौड़ा करने का काम शुरू किया।\nदुकानदारों ने पूछा कि पैदल चलने की जगह कहाँ होगी।\nअधिकारी ने कहा, \"योजना में सबके लिए जगह है।\"\nएक राहगीर बोला, \"बस नक्शे से बाहर निकलकर दिखा दीजिए।\""],
  ["corruption", "एक ठेकेदार ने स्कूल की छत की मरम्मत का बिल दिया।\nप्रधानाचार्य ने पूछा, \"बारिश में पानी फिर क्यों टपका?\"\nठेकेदार बोला, \"बिल में छत सूखी दिखाई गई है।\"\nप्रधानाचार्य ने कहा, \"बच्चों की कॉपियाँ भी बिल देखकर सूख जाएँगी क्या?\""],
  ["corruption", "अस्पताल के बाहर दवाओं की उपलब्धता का बोर्ड लगा था।\nमरीज ने दवा माँगी तो कर्मचारी ने कहा, \"स्टॉक खत्म है।\"\nमरीज ने बोर्ड की ओर इशारा किया।\nकर्मचारी बोला, \"बोर्ड पुराना है; उसकी तबीयत अच्छी है।\""],
  ["corruption", "एक नागरिक ने पूछा कि सार्वजनिक पार्क की बेंचें कहाँ गईं।\nअधिकारी ने कहा, \"सुरक्षा कारणों से हटाई गई हैं।\"\nबुज़ुर्ग ने पूछा, \"अब बैठें कहाँ?\"\nअधिकारी बोले, \"आप शिकायत दर्ज कर सकते हैं—खड़े होकर।\""],
  ["corruption", "जल विभाग ने पाइपलाइन बदलने का काम पूरा बताया।\nपहली ही सुबह सड़क पर पानी बहने लगा।\nअधिकारी ने कहा, \"नई लाइन का परीक्षण चल रहा है।\"\nनिवासी बोला, \"पानी घर तक नहीं पहुँचा, पर सड़क को नई सुविधा मिल गई।\""],
  ["corruption", "एक सरकारी गोदाम में अनाज की बोरियों का मिलान हुआ।\nरजिस्टर में संख्या पूरी थी, फर्श पर जगह खाली।\nअधिकारी ने कहा, \"शायद बोरियाँ दूसरे कमरे में होंगी।\"\nमज़दूर बोला, \"कमरा भी रिकॉर्ड में ही होगा, साहब।\""],
  ["corruption", "नगर कार्यालय ने आवारा पशुओं के लिए आश्रय बनाने की घोषणा की।\nनागरिक ने पूछा, \"निर्माण कहाँ होगा?\"\nअधिकारी ने कहा, \"स्थान चयन समिति देख रही है।\"\nपास खड़ी गाय ने सड़क पर बैठकर कहा मानो, \"मैंने तो जगह चुन ली।\""],
  ["corruption", "एक पुल पर सुरक्षा रेलिंग लगाने का बजट पास हुआ।\nस्थानीय लोगों ने पूछा कि काम कब शुरू होगा।\nअधिकारी बोले, \"टेंडर की प्रक्रिया अंतिम चरण में है।\"\nएक राहगीर ने कहा, \"तब तक हम नदी से दूरी बनाकर ही चलेंगे।\""],
  ["corruption", "शहर में बारिश से पहले नालों की सफ़ाई का आदेश जारी हुआ।\nनिवासी ने पूछा, \"मशीनें कब आएँगी?\"\nकर्मचारी ने कहा, \"आदेश आज ही निकला है।\"\nनिवासी बोला, \"बारिश को भी आदेश की प्रति भेज दीजिए।\""],
  ["corruption", "एक विभाग ने महिला शौचालय की मरम्मत पूरी होने की सूचना दी।\nमहिला ने जाकर देखा तो ताला अब भी लगा था।\nकर्मचारी ने कहा, \"मरम्मत पूरी है, चाबी खोजी जा रही है।\"\nमहिला बोली, \"सुविधा तैयार है; बस उपयोगकर्ता को अनुमति नहीं।\""],
  ["corruption", "नगर के पुस्तकालय के लिए नई किताबें खरीदी गईं।\nपाठक ने पूछा, \"किताबें कहाँ रखी हैं?\"\nकर्मचारी ने कहा, \"अभी सूची बनाने के लिए कार्यालय में हैं।\"\nपाठक बोला, \"ज्ञान भी पहले फ़ाइल पढ़ेगा क्या?\""],
  ["corruption", "नगर निगम की बैठक में सड़क की मरम्मत का बजट पढ़ा गया।\nअधिकारी ने कहा, \"राशि पूरी स्वीकृत है।\"\nनागरिक ने गड्ढे की फोटो दिखाकर पूछा, \"तो सड़क ने पैसा किस खाते में जमा किया?\"\nबैठक ने फोटो को अगली बैठक के एजेंडे में रख दिया।"],
  ["corruption", "एक स्कूल के बाहर नए शौचालय का उद्घाटन हुआ।\nपट्टिका पर लिखा था, \"जनता को समर्पित।\"\nपहला नागरिक लौटा और बोला, \"समर्पण अच्छा है, चाबी भी जनता को दे देते।\"\nफीता काटने वाले ने तुरंत चाबी खोजने की समिति बना दी।"],
  ["corruption", "पंचायत में पानी की टंकी की ऊँचाई पर चर्चा हुई।\nठेकेदार बोला, \"काम नक्शे के अनुसार हुआ है।\"\nगाँव वाले ने पूछा, \"नक्शे में नल भी था या सिर्फ़ टंकी की तस्वीर?\"\nइंजीनियर ने नक्शा उलटकर देखा, शायद नल पीछे छपा हो।"],
  ["corruption", "कार्यालय में नागरिक ने अपनी पेंशन की फ़ाइल पूछी।\nकर्मचारी बोला, \"फ़ाइल आगे बढ़ रही है।\"\nनागरिक ने पूछा, \"किस दिशा में?\"\nकर्मचारी ने कहा, \"दिशा गोपनीय है, पर फ़ाइल को रास्ते में चाय मिलती रहती है।\""],
  ["corruption", "एक ठेकेदार ने पुल का उद्घाटन समय से पहले करने का दावा किया।\nपत्रकार ने पूछा, \"मज़बूती की जाँच कब हुई?\"\nठेकेदार बोला, \"उद्घाटन के बाद करेंगे, अभी रिबन सुंदर लग रहा है।\"\nपास खड़े इंजीनियर ने रिबन से पहले पुल की जाँच माँग ली।"],
  ["corruption", "राशन दुकान पर मशीन ने अंगूठा पहचानने से मना कर दिया।\nदुकानदार बोला, \"सिस्टम में आपका नाम नहीं दिख रहा।\"\nबुज़ुर्ग ने कहा, \"नाम सूची में है, अनाज शायद डिजिटल हो गया।\"\nलाइन में खड़े लोगों ने मशीन से उसका राशन कार्ड माँग लिया।"],
  ["corruption", "सरकारी दफ़्तर में शिकायत पेटी पर नया ताला लगाया गया।\nनागरिक ने पूछा, \"चाबी किसके पास है?\"\nकर्मचारी बोला, \"शिकायत गोपनीय रहती है।\"\nनागरिक ने कहा, \"ताला भी गोपनीय है, तभी तो खुलता नहीं।\""],
  ["corruption", "गाँव में स्ट्रीट लाइट लगाने का काम पूरा बताया गया।\nरात को सरपंच ने पूछा, \"किसी ने रोशनी देखी?\"\nएक निवासी बोला, \"बिल में तो पूरा गाँव चमक रहा है।\"\nअगली सुबह निरीक्षण दल दिन के उजाले में आया और संतुष्ट लौट गया।"],
  ["corruption", "नगरपालिका ने कूड़ा उठाने का नया कैलेंडर जारी किया।\nनिवासी ने पूछा, \"गाड़ी किस दिन आएगी?\"\nअधिकारी बोला, \"कैलेंडर में सभी दिन उपलब्ध हैं।\"\nनिवासी ने कहा, \"तो कूड़ा भी रोज़ छुट्टी मनाता होगा।\"\nकैलेंडर ने अगली तारीख़ पर शिकायत दर्ज कर ली।"],
  ["corruption", "एक कार्यालय में उपस्थिति रजिस्टर बहुत साफ़ रखा जाता था।\nकर्मचारी ने पूछा, \"काम का रजिस्टर कहाँ है?\"\nअधिकारी बोला, \"पहले उपस्थिति पूरी हो जाए।\"\nकर्मचारी ने कहा, \"काम दिखेगा तो उपस्थिति पर भरोसा भी बढ़ेगा।\"\nकमरे में पहली बार काम की बात पर सन्नाटा हुआ।"],
  ["corruption", "सार्वजनिक पार्क के लिए झूले खरीदे गए।\nबच्चों ने पूछा, \"झूले कब लगेंगे?\"\nअधिकारी ने कहा, \"खरीद की प्रक्रिया पूरी हो गई।\"\nबच्चे बोले, \"हम झूले पर बैठेंगे या प्रक्रिया पर?\"\nफाइल ने बच्चों की बात सुनकर पहली बार तेज़ी दिखाई।"],
  ["corruption", "एक सड़क पर मरम्मत का बोर्ड महीनों से लगा था।\nराहगीर ने पूछा, \"काम कब शुरू होगा?\"\nमज़दूर बोला, \"बोर्ड पहले आया है, काम को रास्ता याद करना है।\"\nराहगीर ने कहा, \"तब तक गड्ढों से ही रास्ता पूछ लेते हैं।\"\nबोर्ड ने हवा में सिर हिलाया।"],
  ["corruption", "स्वास्थ्य केंद्र में दवा की सूची दीवार पर टँगी थी।\nमरीज़ ने पूछा, \"इनमें से कौन-सी दवा उपलब्ध है?\"\nकर्मचारी बोला, \"सूची पूरी है।\"\nमरीज़ ने कहा, \"मुझे सूची नहीं, दवा चाहिए।\"\nदीवार ने इलाज की ज़िम्मेदारी लेने से इनकार कर दिया।"],
  ["corruption", "नगर परिषद ने नाली की सफ़ाई का निरीक्षण किया।\nअधिकारी ने कहा, \"रिकॉर्ड में सफ़ाई पूरी है।\"\nनिवासी ने नाली की ओर इशारा किया, \"रिकॉर्ड को यहाँ बुलाइए।\"\nअधिकारी बोला, \"रिकॉर्ड बाहर नहीं निकलता, वह संवेदनशील है।\""],
  ["corruption", "सरकारी बस अड्डे पर नया प्रतीक्षालय बना।\nयात्री ने पूछा, \"बस कहाँ से मिलेगी?\"\nकर्मचारी बोला, \"प्रतीक्षालय में बैठकर प्रतीक्षा कीजिए।\"\nयात्री ने कहा, \"नाम के हिसाब से सुविधा पूरी है, अब बस भी भेज दीजिए।\"\nघोषणा मशीन ने पहली बार माफ़ी माँगी।"],
  ["corruption", "एक गाँव में सौर लाइट लगाने का बिल आया।\nग्रामीण ने पूछा, \"रात में रोशनी क्यों नहीं?\"\nअधिकारी बोला, \"सूरज से ऊर्जा मिलती है।\"\nग्रामीण ने कहा, \"सूरज दिन में आता है, रात में आपकी योजना कहाँ जाती है?\"\nबैठक ने बैटरी का नाम पहली बार सुना।"],
  ["corruption", "कार्यालय ने शिकायतों के निपटारे का प्रमाणपत्र जारी किया।\nनागरिक ने पूछा, \"मेरी शिकायत का क्या हुआ?\"\nकर्मचारी बोला, \"निपटारा हो चुका है।\"\nनागरिक ने कहा, \"मुझे तो जवाब भी नहीं मिला।\"\nकर्मचारी बोला, \"इसीलिए तो शिकायत अब शांत है।\""],
  ["corruption", "विद्यालय की छत की मरम्मत का बजट स्वीकृत हुआ।\nअभिभावक ने पूछा, \"बारिश में कक्षा क्यों टपकती है?\"\nअधिकारी बोला, \"मरम्मत कागज़ पर पूरी है।\"\nबच्चे ने बाल्टी रखते हुए कहा, \"तो परीक्षा भी कागज़ पर ले लीजिए।\"\nप्रधानाचार्य ने छत की जाँच के लिए छुट्टी घोषित कर दी।"],
  ["corruption", "एक ठेकेदार ने नल योजना की सफलता बताई।\nगाँव की महिला ने पूछा, \"नल में पानी कब आएगा?\"\nठेकेदार बोला, \"कनेक्शन हर घर तक पहुँच गया।\"\nमहिला ने कहा, \"पानी को भी घर का पता दे दीजिए।\"\nपास खड़ा बच्चा खाली बाल्टी बजाकर ताल देने लगा।"],
  ["corruption", "नगर निगम ने फुटपाथ से अतिक्रमण हटाने का अभियान चलाया।\nदुकानदार ने पूछा, \"अब पैदल चलने वाले कहाँ चलेंगे?\"\nअधिकारी बोला, \"फुटपाथ खाली कराया जाएगा।\"\nपैदल यात्री ने कहा, \"पहले फुटपाथ ढूँढ़िए, वह दुकानों के नीचे छिपा है।\"\nअभियान की टीम ने नक्शा माँगा।"],
  ["corruption", "भर्ती बोर्ड ने परिणाम की तारीख़ घोषित की।\nउम्मीदवार ने पूछा, \"मेरिट सूची कब दिखेगी?\"\nअधिकारी बोला, \"पहले प्रेस विज्ञप्ति आएगी।\"\nउम्मीदवार ने कहा, \"मेहनत मेरी थी, नतीजे की पहली खबर भी मुझे ही मिलनी चाहिए।\""],
  ["corruption", "एक नागरिक ने नगर कार्यालय में भुगतान की रसीद माँगी।\nक्लर्क बोला, \"रसीद बाद में मिल जाएगी।\"\nनागरिक ने पूछा, \"भुगतान अभी क्यों लिया?\"\nक्लर्क ने कहा, \"व्यवस्था समय से आगे चलती है, रसीद पीछे आती है।\""],
  ["corruption", "सरकारी गोदाम में अनाज के स्टॉक का निरीक्षण हुआ।\nअधिकारी ने रजिस्टर दिखाकर कहा, \"सब कुछ पूरा है।\"\nनिरीक्षक ने खाली शेल्फ़ देखी और पूछा, \"फिर बोरी कहाँ गई?\"\nजवाब मिला, \"कागज़ पर सुरक्षित है, शायद वहीं रखी हो।\""],
  ["corruption", "एक नागरिक ने ठेके की निविदा की शर्तें पढ़ीं।\nउसने पूछा, \"सबको बराबर मौका मिलेगा?\"\nकर्मचारी बोला, \"नियम तो यही कहते हैं।\"\nनागरिक ने कहा, \"तो बैठक की तारीख़ और दस्तावेज़ भी सबको बराबर समय पर भेजिए।\""],
  ["corruption", "कार्यालय में एक ही काम के लिए दो अलग शुल्क बताए गए।\nनागरिक ने पूछा, \"सही शुल्क कौन-सा है?\"\nकर्मचारी बोला, \"काउंटर के हिसाब से बदलता है।\"\nनागरिक ने कहा, \"फिर बोर्ड पर दरें नहीं, काउंटरों का मूड लिख दीजिए।\""],
  ["corruption", "एक अस्पताल में उपकरण खरीदने का बिल स्वीकृत हुआ।\nडॉक्टर ने पूछा, \"मशीन कब पहुँचेगी?\"\nअधिकारी बोला, \"आपूर्ति का आदेश जारी हो गया है।\"\nडॉक्टर ने कहा, \"मरीज़ आदेश से जाँच नहीं करा सकते।\""],
  ["corruption", "पंचायत ने तालाब की सफ़ाई का प्रमाणपत्र जारी किया।\nगाँव के बच्चे वहाँ मछली पकड़ने गए और सूखी मिट्टी मिली।\nएक बच्चे ने पूछा, \"मछली कहाँ है?\"\nबुज़ुर्ग बोले, \"शायद प्रमाणपत्र में तैर रही होगी।\""],
  ["corruption", "एक नागरिक ने सरकारी वेबसाइट पर शिकायत दर्ज की।\nस्क्रीन पर लिखा आया, \"आपकी प्रतिक्रिया हमारे लिए महत्वपूर्ण है।\"\nउसने पूछा, \"जवाब कब आएगा?\"\nवेबसाइट ने फिर वही संदेश दिखाया—कम से कम प्रतिक्रिया लगातार मिल रही थी।"],
  ["corruption", "कार्यालय में कर्मचारी ने कहा कि फ़ाइल पर हस्ताक्षर हो चुके हैं।\nनागरिक ने पूछा, \"अब आदेश कब मिलेगा?\"\nकर्मचारी बोला, \"हस्ताक्षर तो हो गए, अब हस्ताक्षर की पुष्टि होगी।\"\nनागरिक ने कहा, \"स्याही को भी सत्यापन चाहिए क्या?\""],
  ["corruption", "एक सार्वजनिक परियोजना की लागत बढ़ती गई।\nअधिकारी ने कहा, \"महँगाई का असर है।\"\nनागरिक ने पूछा, \"काम की प्रगति पर भी महँगाई लागू है?\"\nअधिकारी ने जवाब दिया, \"प्रगति का बजट अलग से विचाराधीन है।\""],
  ["corruption", "परीक्षा केंद्र पर अभ्यर्थियों को समय से पहले बुलाया गया।\nप्रवेश द्वार देर से खुला और कोई सूचना नहीं मिली।\nएक छात्र बोला, \"समयपालन का पाठ हमसे लिया जा रहा है या हमसे छिपाया जा रहा है?\"\nनिरीक्षक ने घड़ी देखी और दरवाज़ा खोल दिया।"],
  ["corruption", "नगर निगम ने पार्क की बेंचों की मरम्मत का भुगतान किया।\nसुबह बुज़ुर्ग बैठे तो एक बेंच बीच से हिलने लगी।\nउन्होंने कहा, \"बिल मज़बूत है, बेंच को भी थोड़ा सहारा दे दीजिए।\"\nमाली ने मरम्मत दल को बुलाया।"],
  ["corruption", "एक दफ़्तर ने नागरिक सेवा का समय बढ़ाने की घोषणा की।\nनागरिक पहुँचा तो काउंटर बंद था।\nउसने पूछा, \"समय बढ़ा है या सिर्फ़ बोर्ड?\"\nचौकीदार बोला, \"बोर्ड रोज़ ड्यूटी पर है, काउंटर का रोस्टर अलग है।\""],
  ["corruption", "एक गाँव में पुलिया की मरम्मत का काम दिखाया गया।\nग्रामीण ने पूछा, \"भारी वाहन कब निकल सकेंगे?\"\nअधिकारी बोला, \"काम पूरा घोषित हो गया है।\"\nग्रामीण ने कहा, \"घोषणा पार कर सकती है, ट्रैक्टर अभी नहीं।\""],
  ["corruption", "खरीद समिति ने कार्यालय के लिए पंखे मँगवाए।\nकर्मचारी ने पूछा, \"गर्मी में कब लगेंगे?\"\nअधिकारी बोला, \"पहले स्टॉक का मिलान होगा।\"\nकर्मचारी ने कहा, \"तब तक हवा भी सूची में ही घूमेगी।\""],
  ["corruption", "एक नागरिक ने सार्वजनिक सूचना बोर्ड पर पुराना आदेश देखा।\nउसने पूछा, \"नया आदेश कहाँ मिलेगा?\"\nकर्मचारी बोला, \"वेबसाइट पर होगा।\"\nनागरिक ने कहा, \"वेबसाइट पर पुराना लिंक है।\"\nकर्मचारी ने उत्तर दिया, \"तो बोर्ड और वेबसाइट दोनों इतिहास पढ़ा रहे हैं।\""],
  ["corruption", "एक ठेकेदार ने काम की गुणवत्ता को उत्कृष्ट बताया।\nस्थानीय निवासी ने टूटे किनारे की तस्वीर दिखाई।\nठेकेदार बोला, \"यह छोटा हिस्सा है।\"\nनिवासी ने कहा, \"छोटा हिस्सा ही रोज़ सबसे पहले मिलता है।\""],
  ["corruption", "सरकारी स्कूल में खेल सामग्री का बजट आया।\nशिक्षक ने पूछा, \"बच्चों को गेंद कब मिलेगी?\"\nकार्यालय बोला, \"खरीद की स्वीकृति मिल गई है।\"\nबच्चे ने कहा, \"तब तक हम स्वीकृति से क्रिकेट खेलें?\""],
  ["corruption", "नगर के जल विभाग ने आपूर्ति का समय तय किया।\nनल पर पानी नहीं आया, लेकिन संदेश आया कि आपूर्ति सामान्य है।\nनिवासी ने जवाब भेजा, \"संदेश की धारा तेज़ है, नल की कब होगी?\"\nविभाग ने शिकायत संख्या भेज दी।"],
  ["corruption", "एक नागरिक ने सार्वजनिक सुनवाई में बोलने का समय माँगा।\nअध्यक्ष ने कहा, \"हर व्यक्ति को समान अवसर मिलेगा।\"\nमाइक अगले वक्ता तक पहुँचते-पहुँचते बंद हो गया।\nनागरिक बोला, \"कम से कम माइक ने पक्षपात नहीं किया—सबको चुप कराया।\""],
  ["bhojpuri", "गाँव के हाट में एगो आदमी नया चश्मा खरीदलस।\nदुकानदार पूछलस, “अब साफ-साफ देखात बा?”\nआदमी बोलल, “हाँ, बाकिर उधारी वाला रजिस्टर अब अउरी साफ दिखत बा।”\nदुकानदार हँसल, “त चश्मा के पैसा आजे दे दऽ, हिसाब मत पढ़ऽ।”"],
  ["bhojpuri", "नाव पर चढ़े से पहिले रामधनी टिकट पूछलस।\nमल्लाह कहलस, “पार जाए के दस रुपइया।”\nरामधनी पूछलस, “लौटे के?”\nमल्लाह मुस्कियाइल, “ऊ नदी के मूड आ तोहरे हिम्मत पर निर्भर बा।”"],
  ["bhojpuri", "गाँव के डाकघर में चिट्ठी देवे गइल बबलू।\nकर्मचारी पूछलस, “पता पूरा लिखले बाड़ऽ?”\nबबलू कहलक, “हाँ, घर के आगे पीयर गाय बँधल रहेला।”\nकर्मचारी बोलल, “गाय छुट्टी पर निकल गइल त चिट्ठी कहाँ जाई?”"],
  ["bhojpuri", "माई बबुआ से पूछली, “आज स्कूल में का सीखलऽ?”\nबबुआ कहलक, “मास्टर जी कहले कि सवाल पूछल जरूरी बा।”\nमाई खुश होके पूछली, “त कवन सवाल पूछलऽ?”\nबबुआ बोलल, “छुट्टी के घंटी में देरी काहे होला?”"],
  ["bhojpuri", "खेत में किसान नया मोबाइल से फोटो खींचत रहे।\nदोस्त पूछलस, “का भेजबऽ शहर वाला बेटा के?”\nकिसान कहलक, “धान के फोटो।”\nदोस्त हँसल, “बढ़िया, अब बेटा वीडियो कॉल पर खाद के लिंक भेजी।”"],
  ["bhojpuri", "चाय दुकान पर दू गो दोस्त मौसम पर बहस करत रहलें।\nपहिला कहलक, “आज बरखा जरूर होई, चींटी ऊपर चढ़तिया।”\nदूसरा आसमान देख के बोलल, “बादर त नइखे।”\nचायवाला जोड़लस, “तू दुनो बहस करऽ, हम छाता किराया पर देतानी।”"],
  ["bhojpuri", "पंचायत में लाउडस्पीकर के आवाज जाँचल जात रहे।\nमुखिया पूछले, “पीछे तक सुनात बा?”\nएक बुजुर्ग बोलले, “आवाज त पूरा टोला में पहुँच गइल।”\nमुखिया खुश भइले, बुजुर्ग जोड़ले, “बस बात अबहियों समझ में नइखे आइल।”"],
  ["bhojpuri", "छठ के तैयारी में छोटकी टोकरी सजावत रहे।\nभइया पूछलस, “एतना ध्यान से काहे सजा रहल बाड़ू?”\nछोटकी बोलली, “सूरज देव देखिहें नू।”\nदादी हँसली, “त पहिले घर के लोग देख ले, ऊ लोग रोज देखेला।”"],
  ["bhojpuri", "गाँव के पुस्तकालय में नया किताब आइल।\nलाइब्रेरियन पूछलस, “कवन किताब चाहीं?”\nलल्लन कहलक, “अइसन किताब जे जल्दी खत्म हो जाए।”\nलाइब्रेरियन बोललस, “त कैलेंडर उठा लऽ, परीक्षा के तारीख नजदीक बा।”"],
  ["bhojpuri", "साइकिल के दुकान पर पप्पू हवा भरवावे गइल।\nमिस्त्री पूछलस, “टायर में कतना हवा रखीं?”\nपप्पू बोलल, “एतना कि चढ़ाई पर खुदे चढ़ जाए।”\nमिस्त्री हँसल, “त साइकिल ना, पहाड़ी बकरा खोजऽ।”"],
  ["bhojpuri", "मेला में जादूगर टोपी से कबूतर निकाललस।\nछोटका पूछलस, “ई कबूतर कहाँ छुपल रहे?”\nजादूगर कहलक, “ई जादू के राज बा।”\nछोटका बोलल, “हमरा टोपी में होमवर्क छुपा दीं, मास्टर जी ना खोज पइहें।”"],
  ["bhojpuri", "गाँव में नया सिलाई मशीन आइल।\nचाची कहली, “अब कपड़ा जल्दी सिली।”\nपड़ोसिन पूछली, “त फुर्सत मिली?”\nचाची बोलली, “ना, अब सबके कपड़ा जल्दी जमा होई।”"],
  ["bhojpuri", "नहर किनारे दू किसान पानी के बारी देखत रहलें।\nपहिला कहलक, “आज पानी समय से आ गइल।”\nदूसरा बोलल, “हाँ, अब खेत के चिंता कम होई।”\nपासे खड़ा बतख बोला, “हमरा से पूछीं, पानी पहिले से हमरे नाम बा।”"],
  ["bhojpuri", "बस अड्डा पर कंडक्टर आवाज लगवलस, “शहर चले वाला बैठीं!”\nएक बुजुर्ग पूछले, “बस सीधे जाई?”\nकंडक्टर कहलक, “रास्ता सीधा बा, बाकिर मोड़ पर बस के आपन राय बा।”\nबुजुर्ग बोलले, “त खिड़की के सीट दे, सलाह सुनत जइब।”"],
  ["bhojpuri", "गाँव के नाई नया शीशा लगववलस।\nग्राहक बाल कटवाके पूछलस, “अब हम जवान लागतानी?”\nनाई कहलक, “शीशा नया बा, चेहरा त पुरनके बा।”\nग्राहक हँसल, “त दाम में पुरान ग्राहक वाला छूट दे दऽ।”"],
  ["bhojpuri", "मास्टर जी पूछले, “नदी आ नहर में का अंतर बा?”\nगोलू कहलक, “नदी अपने मन से बहेले।”\nमास्टर जी पूछले, “नहर?”\nगोलू बोलल, “ओकरा हर मोड़ पर सरकारी कागज चाहीं।”"],
  ["bhojpuri", "गाँव के रेडियो पर खेती के कार्यक्रम चलत रहे।\nकिसान आवाज बढ़ा के सुनत रहलें।\nपोता पूछलस, “दादा, ई सलाह काम आई?”\nदादा बोलले, “जरूर, बाकिर पहिले रेडियो से कहऽ कि खेत में आके देखे।”"],
  ["bhojpuri", "कुम्हार के चाक घूमत रहे आ ग्राहक घड़ा देखत रहे।\nग्राहक पूछलस, “ई घड़ा पानी ठंडा रखी?”\nकुम्हार कहलक, “रखी, बस ओकरा फ्रिज समझ के बर्फ मत माँगिहऽ।”\nग्राहक बोलल, “त दाम में बिजली बिल बचत के छूट चाहीं।”"],
  ["bhojpuri", "गाँव के चौक पर नाटक के रिहर्सल होत रहे।\nनिर्देशक कहले, “संवाद जोर से बोलऽ।”\nकलाकार धीरे से बोलल, “हमरा आवाज कम बा।”\nनिर्देशक कहले, “त माइक पकड़ऽ, कहानी के गला मत दबा।”"],
  ["bhojpuri", "एक किसान मंडी में नया तराजू देखे गइल।\nदुकानदार कहलक, “ई डिजिटल बा, पूरा सही तौलेला।”\nकिसान पूछलस, “भाव भी डिजिटल बा कि अबहियों पुरानहीं?”\nदुकानदार चुप भइल, किसान मुस्किया के आगे बढ़ गइल।"],
  ["bhojpuri", "बरखा रुकते बच्चा लोग पोखरा में कागज के नाव छोड़लस।\nएक नाव किनारे अटक गइल।\nचिंटू कहलक, “ई नाव आगे काहे नइखे जात?”\nदोस्त बोलल, “कप्तान घर से अनुमति लेवे गइल बा।”"],
  ["bhojpuri", "गाँव के स्वास्थ्य शिविर में डॉक्टर वजन नापत रहलें।\nरामू मशीन पर चढ़ल आ नंबर देख के चौंकल।\nडॉक्टर पूछले, “का भइल?”\nरामू कहलक, “मशीन हमसे जादे सच्चाई बोलतिया, एकरा चुप कराईं।”"],
  ["bhojpuri", "पंचायत भवन में नया घड़ी टँगल।\nसचिव कहले, “अब बैठक समय पर शुरू होई।”\nएक किसान पूछलस, “घड़ी सही समय बतावेला?”\nसचिव बोलले, “घड़ी त सही बा, लोग के मनावे के जिम्मा अबहियों हमरे बा।”"],
  ["bhojpuri", "दू गो भाई आम के पेड़ नीचे हिसाब करत रहलें।\nबड़का कहलक, “आधा आम तोहरा, आधा हमरा।”\nछोटका पूछलस, “गुठली केकरा मिली?”\nबड़का बोलल, “जे पहिले रोपी, अगिला साल ओकरा पूरा पेड़ के सपना मिली।”"],
  ["bhojpuri", "गाँव के मोबाइल दुकान पर नेटवर्क के शिकायत आइल।\nग्राहक कहलक, “फोन में सिग्नल गायब बा।”\nदुकानदार छत पर चढ़ के फोन उठवलस।\nग्राहक बोलल, “अब सिग्नल आ गइल; दुकान के किराया भी ऊपर से लागी का?”"],
  ["bhojpuri", "माई बाजार से नया प्रेशर कुकर खरीदली।\nबेटी पूछली, “ई सीटी कब देई?”\nमाई बोलली, “दाल तैयार होई त।”\nदादी जोड़ली, “घर में त बिना दाल के भी सबके सीटी बजेला।”"],
  ["bhojpuri", "गाँव के खेल मैदान में क्रिकेट मैच चलत रहे।\nअंपायर के फैसला पर सब बहस करे लगल।\nकप्तान कहलक, “फैसला साफ बा।”\nअंपायर बोलल, “हाँ, बाकिर तोहरा लोग के चश्मा अलग-अलग नंबर के बा।”"],
  ["bhojpuri", "मेला में खिलौना वाला बोलल, “ई पवनचक्की हवा से चलेला।”\nबच्चा पूछलस, “हवा ना रहे त?”\nदुकानदार कहलक, “त तू फूँक मारिहऽ।”\nबच्चा बोलल, “त दाम आधा करऽ, आधा काम हम करब।”"],
  ["bhojpuri", "डाकिया गाँव में पार्सल लेके आइल।\nघर पर ताला देख के ऊ पड़ोसी से पूछलस।\nपड़ोसी कहलक, “घरवाला खेत गइल बा।”\nडाकिया हँसल, “ठीक बा, पार्सल के भी खेत में छुट्टी मनावे भेज देतानी।”"],
  ["bhojpuri", "चौपाल पर बुजुर्ग लोग पुरान दिन याद करत रहलें।\nएक जवान पूछलस, “तब मोबाइल ना रहे त खबर कइसे मिलत रहे?”\nकाका कहले, “लोग एक-दूसरा से मिलत रहे।”\nजवान बोलल, “ई त बहुत महँग सुविधा रहे—समय लागे वाला।”"],
  ["bhojpuri", "भोर में दूध लेवे गइल रघु के बछिया रस्सी छुड़ा के भाग गइल।\nऊ पीछे-पीछे दौड़ल, त पड़ोसी पूछलस, “एतना तेज कहाँ?”\nरघु हाँफ के बोलल, “दूध के दाम बढ़ल बा, अब गाय के भी फिटनेस जरूरी बा।”\nपड़ोसी कहलक, “पहिले अपना साँस बचा, दूध त बाद में दुहाइ।”"],
  ["bhojpuri", "गाँव के मेले में कठपुतली वाला राजा के कहानी सुनावत रहे।\nछोटका पूछलस, “राजा हर बात पर मंत्री से सलाह काहे लेत रहे?”\nबाबूजी बोलले, “काहे कि अकेले फैसला करे में गलती हो सकेला।”\nछोटका कहलक, “त घर में माई के सलाह पहिले काहे ना मानेलऽ?”"],
  ["bhojpuri", "नदी पार करे खातिर पप्पू नाव पर चढ़ल।\nमल्लाह पूछलस, “तैरल आवेला?”\nपप्पू कहलक, “ना, बाकिर मोबाइल में स्विमिंग वाला वीडियो देखले बानी।”\nमल्लाह हँसल, “वीडियो किनारे रखऽ, लाइफ जैकेट पहिनऽ।”"],
  ["bhojpuri", "खेत में नीलगाय घुस गइल त किसान लाठी लेके पहुँचल।\nपोता पूछलस, “दादा, ई फसल काहे खा रहल बा?”\nदादा बोलले, “एकरा मेन्यू में हमार मेहनत मुफ्त लिखल बा।”\nपोता कहलक, “त खेत के चारदीवारी के बिल भेज दीं।”"],
  ["bhojpuri", "चौपाल पर काका पुरान हारमोनियम निकाललन।\nपोता पूछलस, “ई अबहियों बाजी?”\nकाका कहले, “बाजी, बस पहिले हवा भरल जाव।”\nपोता बोलल, “त दादा, ई हारमोनियम बा कि साइकिल के टायर?”"],
  ["bhojpuri", "गाँव के स्कूल में विज्ञान मेला लागल।\nगुड्डू पवनचक्की बनवले रहे, बाकिर हवा ना चलत रहे।\nमास्टर जी पूछले, “अब का करबऽ?”\nगुड्डू बोलल, “पहिले भाषण देब, भीड़ से हवा अपने आप बन जाई।”"],
  ["bhojpuri", "पान दुकान पर काका नया चश्मा लगाके अखबार पढ़त रहलें।\nदोस्त पूछलस, “खबर साफ दिखतिया?”\nकाका कहले, “खबर त साफ बा, बस दाम पढ़ते आँख फिर धुँधला जाला।”\nदुकानदार बोलल, “त चश्मा के साथ बजट भी बदलवाईं।”"],
  ["bhojpuri", "पोखरा में बतख के बच्चा कतार बना के तैरत रहलें।\nचिंटू पूछलस, “सब एके लाइन में काहे बा?”\nदादी कहली, “माई के पीछे-पीछे चलत बा।”\nचिंटू बोलल, “हमरो स्कूल में अइसन नियम होखे त छुट्टी में भी लाइन ना टूटे।”"],
  ["bhojpuri", "किसान सहकारी समिति में नया रजिस्टर खुलल।\nकर्मचारी पूछलस, “नाम साफ-साफ लिखाईं।”\nबुजुर्ग बोले, “नाम लिख दीं, बाकिर हमार अंगूठा के हस्ताक्षर मत बिगाड़ीं।”\nकर्मचारी हँसल, “ई त सबसे पुरान डिजिटल पहचान बा।”"],
  ["bhojpuri", "गाँव में पहली बेर सौर लाइट लागल।\nरात में काका बोले, “अब बिजली जाए त अँधेरा ना होई।”\nपोता कहलक, “दादा, बादर छा गइल त?”\nकाका मुस्कियइले, “त बादर से कहब, बिल समय पर जमा करे।”"],
  ["bhojpuri", "मछरी बाजार में छोटका एगो मछरी चुनलस।\nमाई पूछली, “एतने छोट काहे?”\nछोटका कहलक, “ई हमरा से आँख मिला के देखत रहे।”\nमछरी वाला बोलल, “त जल्दी ले जा, अब ई तोहरा परिवार के सदस्य हो गइल।”"],
  ["bhojpuri", "गाँव के नाटक में रामू के पेड़ के किरदार मिलल।\nऊ मंच पर चुपचाप खड़ा रहल।\nनिर्देशक पूछले, “संवाद काहे ना बोललऽ?”\nरामू कहलक, “पेड़ के किरदार बा, हवा चले त पत्ता बोले।”"],
  ["bhojpuri", "चाचा नया रेडियो खरीद के खेत ले गइलें।\nपोता पूछलस, “एतना दूर रेडियो काहे?”\nचाचा कहले, “काम करत घड़ी गीत सुनब।”\nपोता बोलल, “त बैटरी भी रखीं, ना त गीत बीच में उपवास कर ली।”"],
  ["bhojpuri", "बरखा में कच्चा रास्ता कीचड़ से भर गइल।\nडाकिया साइकिल उतार के पैदल चले लागल।\nकाका पूछले, “आज साइकिल काहे ना चलावताड़ऽ?”\nडाकिया बोलल, “चिट्ठी पहुँचावे निकसल बानी, नाव चलावे ना।”"],
  ["bhojpuri", "गाँव के दर्जी से पप्पू नया कुर्ता सिलवावे गइल।\nदर्जी नाप लेके पूछलस, “ढीला रखीं कि फिट?”\nपप्पू बोलल, “अइसन रखीं कि भोज में खइला के बादो इज्जत बचल रहे।”\nदर्जी कहलक, “त कपड़ा से जादे पेट के नाप बतावऽ।”"],
  ["bhojpuri", "आँगन में दादी अचार के मर्तबान धूप में रखली।\nपोती पूछली, “एतना धूप काहे जरूरी बा?”\nदादी कहली, “अचार के स्वाद धीरज से बनेला।”\nपोती बोलली, “त हमार होमवर्को धूप में रख दीं, शायद जल्दी तैयार हो जाए।”"],
  ["bhojpuri", "गाँव के खेल में रस्साकशी शुरू भइल।\nएक टीम रस्सी खींचे से पहिले रणनीति बनावे लागल।\nदूसरा टीम चुपचाप खींच के जीत गइल।\nहारल कप्तान बोलल, “अगिला बेर मीटिंग बाद में, ताकत पहिले।”"],
  ["bhojpuri", "नया पंचायत भवन में पंखा लगल, बाकिर स्विच ना मिलल।\nसब लोग दीवार पर खोजे लागल।\nबिजली मिस्त्री हँस के बोलल, “स्विच बाहर बा।”\nमुखिया पूछले, “बाहर काहे?” मिस्त्री कहलक, “भीतर बहस बहुत गरम रहे।”"],
  ["bhojpuri", "पोता दादा से पूछलस, “पहिले गाँव में खबर कइसे फैलत रहे?”\nदादा कहले, “किसी के आँगन में बतकही शुरू हो जाव।”\nपोता बोलल, “अब त फोन पर फैलतिया।”\nदादा हँसलें, “फर्क बस एतने बा कि अब बतकही के स्क्रीनशॉटो रहेला।”"],
  ["bhojpuri", "धान रोपनी के दिन सब खेत में जुटल रहे।\nशहर से आइल भतीजा जूता पहिन के कीचड़ में उतर गइल।\nकाका पूछले, “ई जूता नया बा?”\nभतीजा बोलल, “हाँ।” काका कहले, “अब ई गाँव के यादगार बन गइल।”"],
  ["bhojpuri", "गाँव के मंदिर के घंटी नया लगावल गइल।\nछोटका पूछलस, “ई पुरान घंटी से तेज बा?”\nपुजारी कहले, “आवाज दूर तक जाई।”\nछोटका बोलल, “त माई के घर से बोलाईं, ऊ रोज हमरा उठावे में हार जाली।”"],
  ["bhojpuri", "किसान मंडी में अपना उपज के फोटो खींचत रहे।\nबेटा फोन पर पूछलस, “पापा, फोटो साफ आइल?”\nकिसान कहलक, “फसल साफ बा, भाव धुँधला बा।”\nबेटा बोलल, “त फोटो के साथ रसीद भी भेजीं।”"],
  ["bhojpuri", "चौपाल पर एगो बुजुर्ग मोबाइल में भजन खोजत रहलें।\nपोता कहलक, “दादा, आवाज बोल के खोजीं।”\nदादा फोन से बोलले, “हे भगवान, भजन चला दऽ।”\nफोन चुप रहल; पोता कहलक, “पहिले इंटरनेट के आशीर्वाद चाहीं।”"],
  ["bhojpuri", "गाँव के कुम्हार नया डिजाइन के सुराही बनवलें।\nग्राहक पूछलस, “ई पानी ठंडा रखी?”\nकुम्हार कहलक, “माटी के सुराही अपना काम करी।”\nग्राहक बोलल, “त फोटो खींच के फ्रिज में रखे के जरूरत नइखे।”"],
  ["bhojpuri", "बाजार में लिट्टी के ठेला पर भीड़ लागल रहे।\nग्राहक पूछलस, “चोखा तीखा बा?”\nठेले वाला कहलक, “स्वाद पूछीं, डर काहे?”\nग्राहक एक कौर खाके बोलल, “अब पानी के गिलासो प्लेट में जोड़ दीं।”"],
  ["bhojpuri", "गाँव के पुल पर बकरी बीच रास्ता में रुक गइल।\nसाइकिल वाला घंटी बजवलस, बाकिर बकरी ना हटल।\nकाका कहले, “धीरे जा, ई रोज के रास्ता बा।”\nसाइकिल वाला बोलल, “त पहिले एकरा से टोल टैक्स पूछीं।”"],
  ["bhojpuri", "स्कूल के मैदान में पतंग उड़ावे के मुकाबला भइल।\nगुड्डू के पतंग पेड़ में अटक गइल।\nदोस्त पूछलस, “अब का करबऽ?”\nगुड्डू कहलक, “पेड़ पर चढ़े वाला के इनाम देब, पतंग के नौकरी लग गइल।”"],
  ["bhojpuri", "गाँव के स्वास्थ्य केंद्र में डॉक्टर दवाई समझावत रहलें।\nकाका पूछले, “ई गोली कब खाए के बा?”\nडॉक्टर कहले, “खाना के बाद।”\nकाका बोलले, “त पहिले खाना के इंतजाम लिख दीं, दवाई बाद में लेब।”"],
  ["bhojpuri", "छोटका रेडियो पर क्रिकेट सुनत रहे।\nटीम के विकेट गिरल त ऊ माथा पकड़ लिहलस।\nदादी पूछली, “का भइल?”\nछोटका कहलक, “हमार टीम हारतिया।” दादी बोलली, “त रेडियो बंद कर, कम-से-कम घर के मनोबल बची।”"],
  ["bhojpuri", "गाँव के मेले में झूला वाला टिकट काटत रहे।\nकाका पूछले, “झूला तेज घूमी?”\nवाला कहलक, “जेतना टिकट, ओतने मजा।”\nकाका बोलले, “त हम दू टिकट लेतानी, बाकिर नीचे उतरे के गारंटी लिख दीं।”"],
  ["bhojpuri", "गाँव के चौक पर आज ई बतकही छिड़ल—मास्टर जी होमवर्क काहे देले।\nगाँव में एक ने पूछा, \"मास्टर जी होमवर्क काहे देले?\"\nदूसरे ने हँसकर कहा, \"कहले घर पर पढ़ऽ,\nस्कूल में त हमहूँ पढ़ावत-पढ़ावत थक जानी।\""],
  ["bhojpuri", "गाँव के चौक पर आज ई बतकही छिड़ल—बच्चा सवाल पूछलस कि छुट्टी कब होई।\nगाँव में एक ने पूछा, \"बच्चा सवाल पूछलस कि छुट्टी कब होई?\"\nदूसरे ने हँसकर कहा, \"मास्टर जी कहले जब घंटी बजे;\nबच्चा कहले घंटी के भी पढ़ाई कराईं।\""],
  ["bhojpuri", "गाँव के चौक पर आज ई बतकही छिड़ल—कापी खाली काहे बा।\nगाँव में एक ने पूछा, \"कापी खाली काहे बा?\"\nदूसरे ने हँसकर कहा, \"बच्चा कहता ज्ञान दिमाग में बा;\nकापी कहती हमहूँ देखीं।\""],
  ["bhojpuri", "गाँव के चौक पर आज ई बतकही छिड़ल—परीक्षा में सबसे कठिन सवाल का रहे।\nगाँव में एक ने पूछा, \"परीक्षा में सबसे कठिन सवाल का रहे?\"\nदूसरे ने हँसकर कहा, \"समय कम बा,\nआ उत्तर लंबा बा।\""],
  ["bhojpuri", "गाँव के चौक पर आज ई बतकही छिड़ल—मास्टर जी तारीफ कइले।\nगाँव में एक ने पूछा, \"मास्टर जी तारीफ कइले?\"\nदूसरे ने हँसकर कहा, \"कहले मेहनत बढ़िया बा;\nबस उत्तर सवाल से मिल जाए त कमाल होई।\""],
  ["bhojpuri", "गाँव के चौक पर आज ई बतकही छिड़ल—स्कूल के घंटी काहे खुश बा।\nगाँव में एक ने पूछा, \"स्कूल के घंटी काहे खुश बा?\"\nदूसरे ने हँसकर कहा, \"ऊ रोज सबके छुट्टी,\nके खबर सुनावेला।\""],
  ["bhojpuri", "गाँव के चौक पर आज ई बतकही छिड़ल—बच्चा किताब खोललस।\nगाँव में एक ने पूछा, \"बच्चा किताब खोललस?\"\nदूसरे ने हँसकर कहा, \"हाँ, किताब खुलते नींद के,\nअध्याय शुरू हो गइल।\""],
  ["bhojpuri", "गाँव के चौक पर आज ई बतकही छिड़ल—गणित से दोस्ती कइसे होई।\nगाँव में एक ने पूछा, \"गणित से दोस्ती कइसे होई?\"\nदूसरे ने हँसकर कहा, \"पहिले सवाल से डर हटाईं,\nफेर जोड़-घटाव खुद बतियाई।\""],
  ["bhojpuri", "गाँव के चौक पर आज ई बतकही छिड़ल—मास्टर जी पूछलें पढ़ाई कइसन चलत बा।\nगाँव में एक ने पूछा, \"मास्टर जी पूछलें पढ़ाई कइसन चलत बा?\"\nदूसरे ने हँसकर कहा, \"बच्चा कहले किताब आगे बा,\nहम ओकरा पीछे-पीछे चलत बानी।\""],
  ["bhojpuri", "गाँव के चौक पर आज ई बतकही छिड़ल—सबसे बढ़िया छात्र के।\nगाँव में एक ने पूछा, \"सबसे बढ़िया छात्र के?\"\nदूसरे ने हँसकर कहा, \"जे गलती से सीखे आ,\nदोस्त के भी समझावे।\""],
  ["bhojpuri", "भोजपुर के गाँव में नयका मोबाइल टावर लागल।\nमुखिया पूछले, “अब नेटवर्क ठीक मिली नू?”\nयुवक कहलक, “हाँ, अब आवाज साफ आई।”\nबुजुर्ग बोलले, “त पहिले घर में धीरे बोलऽ, नेटवर्क से पहिले दीवार सुनतिया।”"],
  ["bhojpuri", "चाय के दुकान पर भोला अपना नया जूता देखावत रहे।\nदोस्त पूछलस, “कइसन बा, आरामदायक?”\nभोला कहलक, “बहुते बढ़िया, बस रास्ता देख के चले के पड़ेला।”\nचायवाला बोलल, “जूता नया बा, जमीन त पुरनके बा।”"],
  ["bhojpuri", "खेत में पंपसेट बंद पड़ गइल।\nकिसान बेटा के फोन कइलस, “मशीन काहे ना चलतिया?”\nबेटा कहलक, “पापा, प्लग देखीं।”\nकिसान बोलल, “प्लग त ठीक बा, अब बिजली विभाग के मन देखे के बा।”"],
  ["bhojpuri", "गाँव के स्कूल में बच्चा भोजपुरी कविता सुनवलस।\nमास्टर जी पूछले, “कविता के भाव का बा?”\nबच्चा कहलक, “माटी से जुड़ल रहऽ।”\nमास्टर जी खुश भइले, बच्चा जोड़लस, “एहसे जूता बाहर उतार के आइल बानी।”"],
  ["bhojpuri", "हाट में सब्जी वाला तराजू पर टमाटर रखलस।\nग्राहक पूछलस, “ताजा बा नू?”\nविक्रेता कहलक, “आजु भोरहीं खेत से आइल बा।”\nग्राहक बोलल, “त भावो भोर वाला लगाईं, शहर वाला ना।”"],
  ["bhojpuri", "बरखा के बाद गाँव के पोखरा भर गइल।\nछोटका कागज के नाव छोड़लस।\nनाव घूम के ओही किनारे आ गइल।\nछोटका कहलक, “ई नावो घर के रास्ता जानेला, हमरा से तेज बा।”"],
  ["bhojpuri", "दादी पोता के भोजपुरी कहावत सिखावत रहली।\nपोता हर कहावत के अर्थ पूछत रहे।\nदादी कहली, “पहिले सुन, फेर समझ।”\nपोता बोलल, “त मोबाइलो के पास बैठीं, ऊ रोज बिना पूछले समझावेला।”"],
  ["bhojpuri", "गाँव के बिजली मिस्त्री नया पंखा लगावत रहे।\nमालिक पूछलस, “हवा तेज चली?”\nमिस्त्री कहलक, “तीन स्पीड बा।”\nमालिक बोलल, “घर में बहस चार स्पीड पर चलेला, ओकरा से तेज चाहीं।”"],
  ["bhojpuri", "रेलवे फाटक पर गाड़ी रुकल रहे।\nयात्री घड़ी देख के बेचैन भइल।\nपासे के किसान कहलक, “फाटक बंद बा, ट्रेन के रास्ता बा।”\nयात्री बोलल, “हमरा जल्दी बा।” किसान कहलक, “ट्रेनो के जल्दी होई, बाकिर ऊ नियम मानतिया।”"],
  ["bhojpuri", "छठ घाट पर बेटा सजावट में मदद करत रहे।\nपिता पूछले, “सब सामान आ गइल?”\nबेटा सूची देख के कहलक, “हाँ, बस धीरज बाकी बा।”\nपिता हँसलें, “ऊ त हर साल नया से खरीदल जाला।”"],
  ["bhojpuri", "कुम्हार के दुकान पर ग्राहक सुराही देखे आइल।\nऊ पूछलस, “ई फ्रिज से बढ़िया ठंडा करी?”\nकुम्हार कहलक, “माटी के स्वाद अलग बा।”\nग्राहक बोलल, “त पानी के साथ परंपरा भी भर दीं।”"],
  ["bhojpuri", "गाँव के नाई दुकान पर रेडियो पर खबर चलत रहे।\nग्राहक पूछलस, “देश में का नया भइल?”\nनाई कहलक, “खबर त रोज नया बा।”\nग्राहक बोलल, “त बाल पुरान स्टाइल में काटीं, कम-से-कम कुछ स्थिर रहे।”"],
  ["bhojpuri", "भोजपुरी नाटक के रिहर्सल में कलाकार संवाद भूल गइल।\nनिर्देशक पूछले, “लाइन कहाँ गइल?”\nकलाकार कहलक, “भावना याद बा, शब्द भाग गइल।”\nपीछे से ढोलकिया बोलल, “त ताल दे दीं, कहानी अपने चल पड़ी।”"],
  ["bhojpuri", "गाँव के किसान मंडी में नया ऐप देखत रहे।\nबेटा समझवलस कि भाव मोबाइल पर देख सकत बानी।\nकिसान पूछलस, “ऐप खरीददारो से बात कराई?”\nबेटा कहलक, “ना।” किसान बोलल, “त आधा काम अबहियों हमरा करे के बा।”"],
  ["bhojpuri", "बकरी के बच्चा आँगन में रस्सी खींचत रहे।\nपोती पूछली, “ई कहाँ जाए चाहत बा?”\nदादी कहली, “जहाँ हरियर पत्ता दिखे।”\nपोती बोलली, “हमरो मन स्कूल के छुट्टी में ओही दिशा देखेला।”"],
  ["bhojpuri", "गाँव के पुस्तकालय में नया पंखा लगल।\nलाइब्रेरियन कहले, “अब आराम से पढ़ीं।”\nएक पाठक बोलल, “हवा बढ़िया बा।”\nलाइब्रेरियन पूछले, “किताबो बढ़िया लागल?” ऊ कहलक, “पहिले पन्ना उड़ल बंद होखे दीं।”"],
  ["bhojpuri", "खेत में किसान आ ओकर पोता बीज छाँटत रहलें।\nपोता पूछलस, “सबसे बढ़िया बीज कवन?”\nदादा कहले, “जे मेहनत आ मौसम दुनो सह सके।”\nपोता बोलल, “त हमरो परीक्षा में अइसने बीज बोईं।”"],
  ["bhojpuri", "गाँव के बस अड्डा पर कंडक्टर टिकट काटत रहे।\nयात्री पूछलस, “ई बस शहर कब पहुँची?”\nकंडक्टर कहलक, “रास्ता साफ रहे त जल्दी।”\nयात्री बोलल, “त रास्ता से पहिले ओकरा से पूछ लीं।”"],
  ["bhojpuri", "माई नया सिलबट्टा खरीदली।\nबेटी पूछली, “मिक्सर छोड़ देब?”\nमाई कहली, “ना, दुनो के काम अलग बा।”\nदादी जोड़ली, “जइसे मोबाइल आ पड़ोसिन—दुनो से खबर मिलेला।”"],
  ["bhojpuri", "गाँव में खेल प्रतियोगिता के उद्घाटन होखे वाला रहे।\nमुखिया माइक पर बोलले, “सब खिलाड़ी तैयार?”\nएक बच्चा पूछलस, “इनाम का मिली?”\nमुखिया कहले, “पहिले खेलऽ।” बच्चा बोलल, “त भाषण के भी टाइम लिमिट रखीं।”"],
  ["bhojpuri", "गाँव के हाट में भोला नया छाता बेचत रहे।\nग्राहक पूछलस, “बरखा में टिके वाला बा नू?”\nभोला कहलक, “एकदम मजबूत बा, हवा में भी साथ ना छोड़े।”\nबगल के दुकानदार बोलल, “बस छाता खोल के देखिहऽ, हवा खुद फैसला कर दी।”"],
  ["bhojpuri", "खलिहान में किसान अनाज के बोरा गिनत रहे।\nमजदूर पूछलस, “आज गिनती पूरा होई का?”\nकिसान कहलक, “बोरा त पूरा बा, बस हिसाब वाला कागज घर पर रह गइल।”\nमजदूर हँसल, “त आज अनाज से पहिले याददाश्त तौल लीं।”"],
  ["bhojpuri", "पंचायत के नल पर औरत लोग पानी भरे जुटल रहे।\nएक पूछलस, “आज पानी समय से आई?”\nदूसरी कहलक, “घोषणा त भइल बा, अब नल के मन भी मान जाए।”\nतीसरी बोलल, “बाल्टी लगा के रखऽ, भरोसा खाली खबर पर मत करऽ।”"],
  ["bhojpuri", "बरात में ढोलक वाला नया ताल आजमावत रहे।\nनाचत युवक पूछलस, “ई धुन पहिले काहे ना बजवलऽ?”\nवादक कहलक, “पहिले सबके पैर एक ताल पर आवे दीं।”\nबुजुर्ग हँसलें, “हमरा पैर त पुरनके ताल पर खुश बा।”"],
  ["bhojpuri", "गाँव के स्कूल में मास्टरजी पूछनी, “होमवर्क काहे ना कइलऽ?”\nछात्र कहलक, “सर, बिजली रात भर ना रहल।”\nमास्टरजी पूछनी, “दिन में कर सकत रहलऽ।”\nछात्र बोलल, “दिन में त बिजली विभाग के दफ्तर खुलल रहे, शिकायत करे गइल रहीं।”"],
  ["bhojpuri", "नयका दुकान खुलल त मालिक बोर्ड लगवले—“उधार बंद बा।”\nपुरान ग्राहक पूछलस, “हमरा खातिर कुछ छूट?”\nमालिक कहलक, “तोहरा खातिर त अलग नियम बा।”\nग्राहक खुश हो गइल। मालिक जोड़लस, “तोहरा से नकद पहिले लेब।”"],
  ["bhojpuri", "पंचायत में सड़क के गड्ढा पर चर्चा चलत रहे।\nमुखिया कहले, “मरम्मत के प्रस्ताव भेज देहनी।”\nयुवक पूछलस, “काम कब शुरू होई?”\nमुखिया बोलले, “पहिले प्रस्ताव के फोटो खिंचाई, तबे फाइल आगे बढ़ी।”"],
  ["bhojpuri", "रेलवे फाटक पर लोग ट्रेन के इंतजार करत रहे।\nएक बुजुर्ग पूछले, “कितना देर लागी?”\nयुवक कहलक, “घड़ी से पूछीं, हम त रोजे इहाँ धैर्य सीखे आवतानी।”\nबुजुर्ग मुस्कुरा के बोलले, “त फीस टिकट में शामिल बा का?”"],
  ["bhojpuri", "भोला बाजार से नया तराजू खरीद के लवलस।\nदुकानदार पूछलस, “अब त सही तौल होई?”\nभोला कहलक, “हाँ, अब गलती के बहाना ना रही।”\nदोस्त बोललस, “त अब ग्राहक से माफी भी सही नाप के माँगिहऽ।”"],
  ["bhojpuri", "गाँव में इंटरनेट कैफे खुलल।\nपहिला ग्राहक पूछलस, “ऑनलाइन फॉर्म भर दीहीं?”\nमालिक कहलक, “भर देब, बस कागज पर लिखल नाम साफ-साफ पढ़ाई।”\nग्राहक बोललस, “नाम त साफ बा, बाबूजी के हस्ताक्षर में पूरा खानदान बा।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आपको सबसे ज़्यादा थकान कब होती है?”\nमरीज बोला, “जब कोई कहता है कि बस पाँच मिनट का काम है।”\nडॉक्टर ने कहा, “तो पाँच मिनट से सावधान रहिए।”\nडॉक्टर ने कहा, “पहले दिनचर्या सुधारिए, फिर बहाने की जाँच करेंगे।”"],
  ["doctor-patient", "मरीज ने कहा, “डॉक्टर साहब, सुबह उठते ही आलस आता है।”\nडॉक्टर बोले, “रात को जल्दी सोया कीजिए।”\nमरीज बोला, “कोशिश करता हूँ, पर मोबाइल को मेरी चिंता रहती है।”\nडॉक्टर बोले, “मोबाइल को रात में चार्ज पर लगाइए, खुद को भी आराम दीजिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आप रोज़ कितनी देर चलते हैं?”\nमरीज बोला, “ऑफिस में मीटिंग रूम बदलने जितना।”\nडॉक्टर ने कहा, “कम से कम रास्ता लंबा चुनिए।”\nडॉक्टर ने सलाह दी, “रोज़ थोड़ा अतिरिक्त चलना भी शुरुआत है।”"],
  ["doctor-patient", "मरीज बोला, “मुझे काम के बीच सिर भारी लगता है।”\nडॉक्टर ने पूछा, “ब्रेक लेते हैं?”\nमरीज बोला, “जी, ब्रेक का संदेश पढ़कर फिर काम शुरू कर देता हूँ।”\nडॉक्टर ने कहा, “काम के बीच छोटा विराम भी ज़रूरी है।”"],
  ["doctor-patient", "डॉक्टर ने कहा, “रात को स्क्रीन कम देखिए।”\nमरीज बोला, “ठीक है, टीवी बंद कर दूँगा।”\nडॉक्टर ने पूछा, “फोन?” मरीज बोला, “वह तो स्क्रीन नहीं, साथी है।”\nडॉक्टर बोले, “साथी अच्छा है, पर नींद उससे भी ज़रूरी है।”"],
  ["doctor-patient", "मरीज ने पूछा, “क्या तनाव से भूख बढ़ती है?”\nडॉक्टर बोले, “कुछ लोगों में ऐसा हो सकता है।”\nमरीज बोला, “तभी मेरी चिंता हर बार नाश्ते के समय आती है।”\nडॉक्टर ने कहा, “तनाव की जगह नाश्ते को समय पर बुलाइए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आपको आराम कब मिलता है?”\nमरीज बोला, “जब घर में सब सो जाते हैं।”\nडॉक्टर ने कहा, “फिर आप?” मरीज बोला, “तब ऑनलाइन सामान की सूची बनती है।”\nडॉक्टर बोले, “अपने लिए भी कैलेंडर में जगह रखिए।”"],
  ["doctor-patient", "मरीज बोला, “मेरी याददाश्त कमजोर हो रही है।”\nडॉक्टर ने पूछा, “कोई उदाहरण?”\nमरीज बोला, “आपने अभी पूछा था... सवाल अच्छा था।”\nडॉक्टर ने कहा, “अगली बार सवाल के साथ जवाब भी याद रखिएगा।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आप चाय कितनी पीते हैं?”\nमरीज बोला, “मौके के हिसाब से।”\nडॉक्टर ने कहा, “कितने मौके?” मरीज बोला, “घर में हर बातचीत एक मौका है।”\nडॉक्टर बोले, “चाय के साथ पानी का भी हिसाब रखिए।”"],
  ["doctor-patient", "मरीज ने कहा, “सीढ़ियाँ चढ़ते ही साँस फूलती है।”\nडॉक्टर ने पूछा, “लिफ्ट की जगह सीढ़ियाँ लेते हैं?”\nमरीज बोला, “जी, जब लिफ्ट के सामने लंबी कतार हो।”\nडॉक्टर ने सलाह दी, “कतार न हो तब भी सीढ़ियों का अभ्यास कीजिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “दवा समय पर लेते हैं?”\nमरीज बोला, “फोन में अलार्म लगाया है।”\nडॉक्टर ने कहा, “अच्छा।” मरीज बोला, “अब अलार्म को भी रोज़ याद दिलाना पड़ता है।”\nडॉक्टर ने कहा, “अलार्म बजते ही उठना भी उपचार का हिस्सा है।”"],
  ["doctor-patient", "मरीज ने पूछा, “क्या हँसना सेहत के लिए अच्छा है?”\nडॉक्टर बोले, “हाँ, मन हल्का हो सकता है।”\nमरीज बोला, “तो घर का बिजली बिल पढ़कर हँसने की कोशिश करूँ?”\nडॉक्टर बोले, “बिल बाद में पढ़िए, पहले मुस्कराना सीखिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आप पानी पीना भूल जाते हैं?”\nमरीज बोला, “जी, इसलिए बोतल मेज़ पर रखता हूँ।”\nडॉक्टर ने कहा, “फिर भी?” मरीज बोला, “मेज़ साफ़ करते हुए बोतल अलमारी में चली जाती है।”\nडॉक्टर ने कहा, “बोतल को ऐसी जगह रखिए जहाँ नज़र बार-बार जाए।”"],
  ["doctor-patient", "मरीज बोला, “रविवार को भी थकान रहती है।”\nडॉक्टर ने पूछा, “आराम करते हैं?”\nमरीज बोला, “जी, घर के कामों के बीच बैठने का समय खोजता हूँ।”\nडॉक्टर बोले, “आराम को कामों की सूची में सबसे ऊपर रखिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “खाने का समय नियमित है?”\nमरीज बोला, “जी, भूख लगने पर।”\nडॉक्टर ने कहा, “समय तय कीजिए।” मरीज बोला, “भूख को कैलेंडर भेज दूँ?”\nडॉक्टर ने कहा, “भूख के साथ घड़ी की भी सुनिए।”"],
  ["doctor-patient", "मरीज ने कहा, “मुझे मौसम बदलते ही छींक आती है।”\nडॉक्टर ने पूछा, “धूल से परेशानी होती है?”\nमरीज बोला, “जी, खासकर जब घर में सफ़ाई की घोषणा होती है।”\nडॉक्टर बोले, “सफ़ाई के समय मास्क और सावधानी रखिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आप व्यायाम कैसे शुरू करेंगे?”\nमरीज बोला, “पहले जूते निकालूँगा।”\nडॉक्टर ने कहा, “फिर?” मरीज बोला, “फिर जूतों को देखकर प्रेरणा लूँगा।”\nडॉक्टर ने कहा, “जूते पहनने के बाद बाहर निकलना भी योजना में जोड़िए।”"],
  ["doctor-patient", "मरीज बोला, “मुझे देर रात तक नींद नहीं आती।”\nडॉक्टर ने पूछा, “सोने से पहले क्या करते हैं?”\nमरीज बोला, “कल की चिंता को आज ही पूरा करने की कोशिश।”\nडॉक्टर बोले, “चिंता को कल पर मत टालिए, समाधान आज से शुरू करें।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “दर्द लगातार रहता है?”\nमरीज बोला, “नहीं, कभी-कभी छुट्टी भी लेता है।”\nडॉक्टर ने कहा, “अच्छा।” मरीज बोला, “पर लौटकर दोगुना काम देता है।”\nडॉक्टर ने कहा, “दर्द लौटे तो उसकी जानकारी ठीक से लिखिए।”"],
  ["doctor-patient", "मरीज ने कहा, “मुझे हर छोटी बात की चिंता होती है।”\nडॉक्टर बोले, “चिंताओं को लिखकर देखिए।”\nमरीज बोला, “लिख लिया है; अब सूची देखकर चिंता होती है।”\nडॉक्टर बोले, “सूची छोटी रखिए और एक-एक बात पर काम कीजिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आप फल खाते हैं?”\nमरीज बोला, “जी, जब घर में कटे हुए मिलते हैं।”\nडॉक्टर ने कहा, “खुद भी काटिए।” मरीज बोला, “फिर चाकू की सुरक्षा पर भी सलाह चाहिए।”\nडॉक्टर ने कहा, “फल काटने से पहले हाथ और चाकू साफ़ रखिए।”"],
  ["doctor-patient", "मरीज ने पूछा, “क्या देर तक बैठना ठीक है?”\nडॉक्टर बोले, “बीच-बीच में उठकर चलना बेहतर है।”\nमरीज बोला, “मैं हर मीटिंग में उठूँ तो लोग समझेंगे प्रस्तुति मेरी है।”\nडॉक्टर बोले, “मीटिंग में भी बीच-बीच में खड़े हो सकते हैं।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आपकी दिनचर्या कैसी है?”\nमरीज बोला, “सुबह अलार्म, फिर स्नूज़, फिर भाग-दौड़।”\nडॉक्टर ने कहा, “अलार्म से दोस्ती कीजिए।” मरीज बोला, “वह रोज़ मुझे जगाकर दुश्मनी करता है।”\nडॉक्टर ने कहा, “स्नूज़ कम और नींद पूरी करने पर ध्यान दीजिए।”"],
  ["doctor-patient", "मरीज बोला, “डॉक्टर साहब, पेट में गुड़गुड़ होती है।”\nडॉक्टर ने पूछा, “खाने के बाद?”\nमरीज बोला, “हाँ, जब बिल आता है तो पेट भी प्रतिक्रिया देता है।”\nडॉक्टर बोले, “लगातार परेशानी हो तो जाँच कराइए, अनुमान नहीं।”"],
  ["doctor-patient", "डॉक्टर ने कहा, “नमक थोड़ा कम कीजिए।”\nमरीज बोला, “घर में नमकदानी हटा दी।”\nडॉक्टर ने पूछा, “फिर?” मरीज बोला, “अब सब्ज़ी में अंदाज़ा लगाने की प्रतियोगिता होती है।”\nडॉक्टर ने कहा, “स्वाद के साथ सेहत का संतुलन भी रखिए।”"],
  ["doctor-patient", "मरीज ने पूछा, “क्या संगीत सुनने से मन शांत होता है?”\nडॉक्टर बोले, “कई लोगों को अच्छा लगता है।”\nमरीज बोला, “मेरे घर में तो गाना चुनने पर ही बहस शुरू हो जाती है।”\nडॉक्टर बोले, “घर में सबकी पसंद अलग हो तो हेडफ़ोन काम आएँगे।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आप बाहर कितना खाते हैं?”\nमरीज बोला, “कभी-कभी।”\nडॉक्टर ने कहा, “कितनी बार?” मरीज बोला, “जब घर में कोई पूछता है कि आज क्या बनेगा।”\nडॉक्टर ने कहा, “घर का खाना भी स्वादिष्ट और संतुलित हो सकता है।”"],
  ["doctor-patient", "मरीज बोला, “मेरी गर्दन अकड़ जाती है।”\nडॉक्टर ने पूछा, “लगातार नीचे देखते हैं?”\nमरीज बोला, “जी, फोन भी और पार्किंग में गिरी चाबी भी।”\nडॉक्टर बोले, “फोन को आँखों से उचित दूरी पर रखिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आपने आराम के लिए समय रखा?”\nमरीज बोला, “जी, डायरी में लिखा है।”\nडॉक्टर ने कहा, “फिर आराम क्यों नहीं?” मरीज बोला, “उस समय दूसरी मीटिंग रख दी।”\nडॉक्टर ने कहा, “काम के बीच तय समय पर उठना याद रखिए।”"],
  ["doctor-patient", "मरीज ने कहा, “मुझे सुबह टहलना शुरू करना है।”\nडॉक्टर बोले, “धीरे-धीरे शुरुआत कीजिए।”\nमरीज बोला, “पहले बालकनी तक, फिर गेट तक—योजना तैयार है।”\nडॉक्टर बोले, “छोटी शुरुआत को भी नियमित रखिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आपको कब सबसे अच्छी नींद आती है?”\nमरीज बोला, “जब छुट्टी के दिन कोई अलार्म नहीं होता।”\nडॉक्टर ने कहा, “तो नियमित नींद का समय रखिए।” मरीज बोला, “अलार्म को यह बात समझाइए।”\nडॉक्टर ने कहा, “छुट्टी के दिन भी सोने-जागने का समय बहुत न बदलें।”"],
  ["doctor-patient", "मरीज बोला, “मुझे स्क्रीन से आँखों में थकान होती है।”\nडॉक्टर ने कहा, “नियमित अंतराल पर दूर देखिए।”\nमरीज बोला, “खिड़की से बाहर देखता हूँ, वहाँ भी पड़ोसी का टीवी चल रहा होता है।”\nडॉक्टर बोले, “खिड़की से दूर हरियाली देखना भी अच्छा विराम है।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आप भोजन धीरे खाते हैं?”\nमरीज बोला, “घर पर हाँ।”\nडॉक्टर ने कहा, “और बाहर?” मरीज बोला, “दोस्त बिल बाँटने से पहले जल्दी कराते हैं।”\nडॉक्टर ने कहा, “खाने का समय दोस्तों की जल्दी पर मत छोड़िए।”"],
  ["doctor-patient", "मरीज ने पूछा, “क्या छोटी सैर भी फ़ायदेमंद है?”\nडॉक्टर बोले, “नियमित चलना अच्छी आदत है।”\nमरीज बोला, “तो आज से पार्क तक पैदल जाऊँगा, वापस आने के लिए रिक्शा रखूँगा।”\nडॉक्टर बोले, “वापसी की सैर भी योजना का हिस्सा बनाइए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आप दिन में कितनी बार तनाव महसूस करते हैं?”\nमरीज बोला, “गिनना शुरू किया था।”\nडॉक्टर ने पूछा, “फिर?” मरीज बोला, “गिनती पूरी होने से पहले नया तनाव आ गया।”\nडॉक्टर ने कहा, “तनाव गिनने से बेहतर है उसका कारण समझना।”"],
  ["doctor-patient", "मरीज बोला, “मुझे खाना बनाते समय छींक आती है।”\nडॉक्टर ने पूछा, “किस चीज़ से?”\nमरीज बोला, “प्याज़ से; परिवार कहता है खाना भावुक कर देता हूँ।”\nडॉक्टर बोले, “प्याज़ काटते समय हवा का रास्ता खुला रखिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आप नियमित जाँच कराते हैं?”\nमरीज बोला, “जी, कैलेंडर में तारीख लिखता हूँ।”\nडॉक्टर ने कहा, “बहुत अच्छा।” मरीज बोला, “अब कैलेंडर मुझे देखकर घबराता है।”\nडॉक्टर ने कहा, “जाँच की तारीख तय करें और उसे टालें नहीं।”"],
  ["doctor-patient", "मरीज ने कहा, “मुझे सुबह जल्दी उठना है।”\nडॉक्टर बोले, “रात को सोने का समय आगे कीजिए।”\nमरीज बोला, “ठीक है, मोबाइल को भी रात में घर भेज दूँगा।”\nडॉक्टर बोले, “नींद के समय फोन को सचमुच दूर रखिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आपको सबसे ज़्यादा खुशी किससे मिलती है?”\nमरीज बोला, “अच्छी रिपोर्ट से।”\nडॉक्टर मुस्कराए। मरीज बोला, “और रिपोर्ट के साथ छुट्टी मिल जाए तो बोनस।”\nडॉक्टर ने कहा, “अच्छी खबर का आनंद लीजिए, पर नियमित देखभाल जारी रखिए।”"],
  ["doctor-patient", "मरीज बोला, “मैंने रोज़ चलने का लक्ष्य रखा है।”\nडॉक्टर ने पूछा, “कितना पूरा हुआ?”\nमरीज बोला, “लक्ष्य फोन में है; फोन अभी सोफ़े पर है।”\nडॉक्टर ने मुस्कराकर कहा, “अब अगली मुलाक़ात में बहाने नहीं, प्रगति बताइए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आज किस परेशानी से आए हैं?”\nमरीज बोला, “घर में सब मुझे सलाह देते हैं।”\nडॉक्टर ने कहा, “यह तो आम बात है।”\nमरीज बोला, “सोचा, एक सलाह पेशेवर से भी ले लूँ।”"],
  ["doctor-patient", "मरीज ने कहा, “रिपोर्ट देखकर घर वाले डर गए।”\nडॉक्टर ने पूछा, “रिपोर्ट में क्या लिखा है?”\nमरीज बोला, “कुछ खास नहीं, बस सबने रंगीन हाइलाइटर चला दिया।”\nडॉक्टर ने रिपोर्ट से पहले हाइलाइटर ज़ब्त कर लिया।"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आराम कब मिलता है?”\nमरीज बोला, “जब फोन की बैटरी खत्म हो जाती है।”\nडॉक्टर ने पूछा, “फिर क्या करते हैं?”\nमरीज बोला, “चार्जर ढूँढ़ते हुए आराम भी खत्म हो जाता है।”"],
  ["doctor-patient", "मरीज बोला, “रोज़ टहलने का फैसला किया है।”\nडॉक्टर ने पूछा, “शुरुआत कहाँ से की?”\nमरीज बोला, “जूते दरवाज़े के पास रख दिए हैं।”\nडॉक्टर बोले, “अब जूतों को भी बाहर की दुनिया दिखाइए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “नींद कैसी आती है?”\nमरीज बोला, “बहुत अच्छी, बस आने में देर लगाती है।”\nडॉक्टर ने पूछा, “क्यों?”\nमरीज बोला, “दिमाग रात को दिनभर की मीटिंग के मिनट्स लिखता है।”"],
  ["doctor-patient", "मरीज ने कहा, “हर बात की सूची बनानी पड़ती है।”\nडॉक्टर बोले, “इससे काम व्यवस्थित रहता होगा।”\nमरीज बोला, “अब सूची बनाने की सूची भी बना ली है।”\nडॉक्टर ने कहा, “पहले उसी सूची को छुट्टी दीजिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “पानी पीना याद रखते हैं?”\nमरीज बोला, “बोतल सामने रखता हूँ।”\nडॉक्टर ने पूछा, “फिर भी भूल जाते हैं?”\nमरीज बोला, “अब बोतल पर मेरा नाम लिखना बाकी है।”"],
  ["doctor-patient", "मरीज बोला, “घर में सबको मेरी सेहत की चिंता है।”\nडॉक्टर बोले, “अच्छी बात है, वे ध्यान रखते हैं।”\nमरीज बोला, “पर हर कोई अलग डाइट चार्ट भेजता है।”\nडॉक्टर ने कहा, “पहले परिवार का साझा चार्ट बनाइए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “काम का तनाव घर लाते हैं?”\nमरीज बोला, “नहीं, घर का तनाव ऑफिस ले जाता हूँ।”\nडॉक्टर ने पूछा, “दोनों जगह काम करते हैं?”\nमरीज बोला, “जी, तनाव का पूरा नेटवर्क है।”"],
  ["doctor-patient", "मरीज ने पूछा, “हँसने से मन हल्का होता है?”\nडॉक्टर बोले, “कई लोगों को अच्छा महसूस होता है।”\nमरीज बोला, “तो घर का बजट खोलकर देखूँ?”\nडॉक्टर बोले, “पहले चाय पीजिए, फिर बजट देखिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आपको सबसे ज़्यादा थकाता क्या है?”\nमरीज बोला, “ऑनलाइन अपॉइंटमेंट लेना।”\nडॉक्टर ने पूछा, “इतना मुश्किल?”\nमरीज बोला, “बीमारी से पहले पासवर्ड याद करना पड़ता है।”"],
  ["doctor-patient", "मरीज बोला, “मोबाइल कम देखने का निश्चय किया है।”\nडॉक्टर ने पूछा, “कितना कम?”\nमरीज बोला, “अब हर घंटे स्क्रीन टाइम देखता हूँ।”\nडॉक्टर ने कहा, “यह निगरानी है, कमी नहीं।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “सुबह जल्दी उठ पाते हैं?”\nमरीज बोला, “अलार्म तो उठ जाता है।”\nडॉक्टर ने पूछा, “और आप?”\nमरीज बोला, “हम दोनों के बीच अभी भरोसा बन रहा है।”"],
  ["doctor-patient", "मरीज ने कहा, “छुट्टी के दिन भी काम याद आता है।”\nडॉक्टर बोले, “कुछ समय अपने लिए तय कीजिए।”\nमरीज बोला, “तय किया था, उसी समय रिश्तेदार आ गए।”\nडॉक्टर ने कहा, “अब रिश्तेदारों को भी अपॉइंटमेंट दीजिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “खाना समय पर खाते हैं?”\nमरीज बोला, “जब घर में सबकी राय एक हो जाए।”\nडॉक्टर ने पूछा, “इतनी देर क्यों?”\nमरीज बोला, “मेन्यू तय करने में आधा दिन निकल जाता है।”"],
  ["doctor-patient", "मरीज बोला, “जिम जाने की प्रेरणा चाहिए।”\nडॉक्टर ने पूछा, “फीस भर दी?”\nमरीज बोला, “जी, तीन महीने पहले।”\nडॉक्टर बोले, “अब जिम को भी आपकी शक्ल याद दिलाइए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “दिनचर्या में सैर है?”\nमरीज बोला, “बाज़ार में पार्किंग खोजते समय।”\nडॉक्टर ने कहा, “पार्क में भी चलिए।”\nमरीज बोला, “वहाँ पार्किंग खोजने का बहाना नहीं मिलेगा।”"],
  ["doctor-patient", "मरीज ने कहा, “नींद मोबाइल से प्रभावित होती है।”\nडॉक्टर ने पूछा, “सोने से पहले फोन दूर रखते हैं?”\nमरीज बोला, “जी, तकिए के दूसरी तरफ।”\nडॉक्टर ने कहा, “दूरी की परिभाषा फिर से पढ़िए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “तनाव कैसे सँभालते हैं?”\nमरीज बोला, “दोस्त को फोन करता हूँ।”\nडॉक्टर ने पूछा, “फिर तनाव कम होता है?”\nमरीज बोला, “नहीं, अब हम दोनों मिलकर चिंता करते हैं।”"],
  ["doctor-patient", "मरीज बोला, “घर वाले कहते हैं मैं धीरे खाता हूँ।”\nडॉक्टर ने पूछा, “जल्दी क्यों करनी चाहिए?”\nमरीज बोला, “मिठाई तक पहुँचने से पहले सब प्लेट साफ़ कर देते हैं।”\nडॉक्टर ने कहा, “खाने का आनंद भी ज़रूरी है।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “रिपोर्ट संभालकर रखी?”\nमरीज बोला, “जी, अलग फाइल में।”\nडॉक्टर ने पूछा, “फाइल कहाँ है?”\nमरीज बोला, “घर पर इतनी सुरक्षित है कि मुझे भी नहीं मिलती।”"],
  ["doctor-patient", "मरीज ने कहा, “इंटरनेट पर लक्षण पढ़कर घबरा जाता हूँ।”\nडॉक्टर बोले, “हर ऑनलाइन जानकारी निदान नहीं होती।”\nमरीज बोला, “अब सिर्फ़ शीर्षक पढ़ता हूँ।”\nडॉक्टर ने कहा, “शीर्षक भी पूरी कहानी नहीं बताते।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “दवा की पर्ची साथ लाए हैं?”\nमरीज बोला, “जी, फोटो भी खींची है।”\nडॉक्टर ने पूछा, “दिखाइए।”\nमरीज बोला, “फोन घर पर चार्ज हो रहा है।”"],
  ["doctor-patient", "मरीज बोला, “डॉक्टर के सामने सब याद रहता है।”\nडॉक्टर ने पूछा, “घर जाकर भूल जाते हैं?”\nमरीज बोला, “जी, सवालों की सूची घर पर रह जाती है।”\nडॉक्टर ने कहा, “अगली बार सूची की फोटो भी रखिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “पानी नियमित पीते हैं?”\nमरीज बोला, “जब कोई याद दिलाता है।”\nडॉक्टर ने कहा, “फोन में रिमाइंडर लगाइए।”\nमरीज बोला, “अब फोन मुझे पानी भी पिलाएगा क्या?”"],
  ["doctor-patient", "मरीज ने कहा, “सुबह उठते ही काम याद आ जाता है।”\nडॉक्टर बोले, “दिन की शुरुआत शांत तरीके से कीजिए।”\nमरीज बोला, “कोशिश की थी, दूधवाले ने घंटी बजा दी।”\nडॉक्टर ने कहा, “शांति के लिए दरवाज़े पर भी समय तय करें।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “कौन-सा व्यायाम पसंद है?”\nमरीज बोला, “जो घर बैठे हो जाए।”\nडॉक्टर ने कहा, “कुछ गतिविधियों में चलना भी शामिल होता है।”\nमरीज बोला, “इसीलिए मैं विकल्प तलाश रहा हूँ।”"],
  ["doctor-patient", "मरीज बोला, “हर समय घड़ी देखने की आदत है।”\nडॉक्टर ने पूछा, “कितनी बार देखते हैं?”\nमरीज बोला, “हर पाँच मिनट में।”\nडॉक्टर ने कहा, “फिर समय तो आपको अच्छी तरह जानता होगा।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “काम के बीच विराम लेते हैं?”\nमरीज बोला, “कंप्यूटर हैंग हो जाए तो।”\nडॉक्टर ने कहा, “अपने लिए भी विराम रखिए।”\nमरीज बोला, “कंप्यूटर को भी यही समझाइए।”"],
  ["doctor-patient", "मरीज ने कहा, “खाने के बाद मीठा चाहिए।”\nडॉक्टर ने पूछा, “हर बार?”\nमरीज बोला, “वरना खाना अधूरा लगता है।”\nडॉक्टर बोले, “आदत पर धीरे-धीरे काम करिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “सबसे अच्छी नींद कहाँ आती है?”\nमरीज बोला, “बस में।”\nडॉक्टर ने पूछा, “घर पर क्यों नहीं?”\nमरीज बोला, “बस में कोई काम की सूची लेकर नहीं आता।”"],
  ["doctor-patient", "मरीज बोला, “फोन देखने से गर्दन दुखती है।”\nडॉक्टर ने कहा, “फोन आँखों के स्तर पर रखिए और विराम लें।”\nमरीज बोला, “फिर फोन भी मुझे बराबरी से देखेगा।”\nडॉक्टर ने कहा, “कम से कम गर्दन को राहत मिलेगी।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “दिन में बाहर कितना रहते हैं?”\nमरीज बोला, “डिलीवरी लेने जितना।”\nडॉक्टर ने कहा, “थोड़ी खुली हवा में भी समय बिताइए।”\nमरीज बोला, “अब डिलीवरी वाले को टहलने बुलाऊँ?”"],
  ["doctor-patient", "मरीज ने कहा, “छोटी-छोटी बातों पर चिंता होती है।”\nडॉक्टर बोले, “हर बात का हल उसी समय ज़रूरी नहीं।”\nमरीज बोला, “यह बात नोट कर लूँ?”\nडॉक्टर ने कहा, “हाँ, पर नोटबुक को भी आराम दीजिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “पसंदीदा आराम क्या है?”\nमरीज बोला, “चुपचाप बैठना।”\nडॉक्टर ने पूछा, “घर में ऐसा हो पाता है?”\nमरीज बोला, “जब सब मुझसे रिमोट माँगना भूल जाते हैं।”"],
  ["doctor-patient", "मरीज बोला, “सुबह की सैर शुरू कर दी है।”\nडॉक्टर ने पूछा, “कितने दिन से?”\nमरीज बोला, “आज पहला दिन था।”\nडॉक्टर ने कहा, “कल भी यही अच्छी खबर दीजिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “भोजन के साथ क्या पीते हैं?”\nमरीज बोला, “कभी पानी, कभी छाछ।”\nडॉक्टर ने पूछा, “और मीठा पेय?”\nमरीज बोला, “वह मेहमान बनकर आता है और रुक जाता है।”"],
  ["doctor-patient", "मरीज ने कहा, “जाँच की तारीख याद नहीं रहती।”\nडॉक्टर ने पूछा, “कैलेंडर इस्तेमाल करते हैं?”\nमरीज बोला, “जी, पर उसमें बहुत तारीखें हैं।”\nडॉक्टर ने कहा, “अपनी जाँच को अलग से चिह्नित कीजिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “आराम के लिए कितना समय चाहिए?”\nमरीज बोला, “कम से कम आधा घंटा।”\nडॉक्टर ने पूछा, “मिलता है?”\nमरीज बोला, “हाँ, पर सब पूछते हैं कि खाली क्यों बैठे हो।”"],
  ["doctor-patient", "मरीज बोला, “मैंने चाय कम कर दी है।”\nडॉक्टर ने पूछा, “अब कितनी पीते हैं?”\nमरीज बोला, “पहले कप गिनता था, अब केतली गिनता हूँ।”\nडॉक्टर ने कहा, “गिनती की इकाई बदलने से आदत नहीं बदलती।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “सबसे ज़्यादा परेशान क्या करता है?”\nमरीज बोला, “लोगों का कहना कि चिंता मत करो।”\nडॉक्टर ने पूछा, “क्यों?”\nमरीज बोला, “फिर चिंता होती है कि चिंता कैसे रोकूँ।”"],
  ["doctor-patient", "मरीज ने कहा, “सेहत सुधारने का ऐप डाउनलोड किया है।”\nडॉक्टर ने पूछा, “उससे क्या मदद मिली?”\nमरीज बोला, “अब सात तरह के नोटिफिकेशन आते हैं।”\nडॉक्टर ने कहा, “एक आदत चुनिए, सात अलर्ट नहीं।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “सैर में क्या अच्छा लगता है?”\nमरीज बोला, “रास्ते की चाय की दुकान।”\nडॉक्टर ने कहा, “तो दूरी धीरे-धीरे बढ़ाइए।”\nमरीज बोला, “दुकान भी धीरे-धीरे दूर होनी चाहिए।”"],
  ["doctor-patient", "मरीज बोला, “रात को जल्दी सोने का नियम बनाया है।”\nडॉक्टर ने पूछा, “नियम निभा रहे हैं?”\nमरीज बोला, “जी, नियम रोज़ दस बजे सो जाता है।”\nडॉक्टर ने कहा, “और आप?” मरीज बोला, “उसे शुभरात्रि कहता हूँ।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “फोन सोते समय कहाँ रहता है?”\nमरीज बोला, “मेरे पास।”\nडॉक्टर ने कहा, “थोड़ा दूर रखिए।”\nमरीज बोला, “फिर सुबह अलार्म को कौन उठाएगा?”"],
  ["doctor-patient", "मरीज ने कहा, “हर बात पर गूगल करने की आदत है।”\nडॉक्टर ने पूछा, “अभी क्या खोज रहे थे?”\nमरीज बोला, “डॉक्टर से क्या पूछना चाहिए।”\nडॉक्टर ने कहा, “अब मुझसे ही पूछ लीजिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “काम से छुट्टी मिलती है?”\nमरीज बोला, “जी, ईमेल पढ़ने के लिए।”\nडॉक्टर ने कहा, “वह छुट्टी नहीं है।”\nमरीज बोला, “ऑफिस को भी यही समझाना पड़ेगा।”"],
  ["doctor-patient", "मरीज बोला, “सुबह की धूप पसंद है।”\nडॉक्टर ने पूछा, “कितनी देर लेते हैं?”\nमरीज बोला, “जब तक पड़ोसी पूछ न लें कि ऑफिस नहीं जाना?”\nडॉक्टर हँसे, “धूप के साथ समय भी तय कर लीजिए।”"],
  ["doctor-patient", "डॉक्टर ने पूछा, “सेहत का लक्ष्य क्या है?”\nमरीज बोला, “सीढ़ियाँ देखकर बहाना न बनाऊँ।”\nडॉक्टर ने कहा, “अच्छा लक्ष्य है, धीरे-धीरे बढ़िए।”\nमरीज बोला, “पहले सीढ़ियों से परिचय कराता हूँ।”"],
  ["doctor-patient", "मरीज ने कहा, “दवाओं की सूची बना ली है।”\nडॉक्टर ने पूछा, “साथ लाए?”\nमरीज बोला, “जी, पर सूची में लिखा है कि उसे घर पर रखना है।”\nडॉक्टर ने कहा, “अगली बार सूची को भी साथ लाइए।”"],
  ["doctor-patient", "क्लिनिक में मरीज की नई उलझन सुनकर डॉक्टर ने पूछा—जल्दी ठीक होने की गारंटी है।\nडॉक्टर ने पूछा, \"जल्दी ठीक होने की गारंटी है?\"\nमरीज ने जवाब दिया, \"गारंटी नहीं,\nसही जाँच और इलाज से बेहतर होने की संभावना बढ़ती है।\""],
  ["doctor-patient", "क्लिनिक में मरीज की नई उलझन सुनकर डॉक्टर ने पूछा—तीन दिन में दौड़ सकूँगा।\nडॉक्टर ने पूछा, \"तीन दिन में दौड़ सकूँगा?\"\nमरीज ने जवाब दिया, \"पहले आराम और उपचार;\nशरीर को कैलेंडर से बहस नहीं करनी चाहिए।\""],
  ["doctor-patient", "क्लिनिक में मरीज की नई उलझन सुनकर डॉक्टर ने पूछा—दवा लेते ही सब ठीक होगा।\nडॉक्टर ने पूछा, \"दवा लेते ही सब ठीक होगा?\"\nमरीज ने जवाब दिया, \"दवा के साथ निर्देश,\nआराम और फॉलो-अप भी ज़रूरी हैं।\""],
  ["doctor-patient", "क्लिनिक में मरीज की नई उलझन सुनकर डॉक्टर ने पूछा—क्या छुट्टी लेनी पड़ेगी।\nडॉक्टर ने पूछा, \"क्या छुट्टी लेनी पड़ेगी?\"\nमरीज ने जवाब दिया, \"आपकी हालत और काम पर निर्भर है;\nसेहत को समय देना समझदारी है।\""],
  ["doctor-patient", "क्लिनिक में मरीज की नई उलझन सुनकर डॉक्टर ने पूछा—मुझे इंजेक्शन से डर लगता है।\nडॉक्टर ने पूछा, \"मुझे इंजेक्शन से डर लगता है।\"\nमरीज ने जवाब दिया, \"डर बताइए;\nहम प्रक्रिया समझाकर आपकी मदद करेंगे।\""],
  ["doctor-patient", "क्लिनिक में मरीज की नई उलझन सुनकर डॉक्टर ने पूछा—फिर कब दिखाना है।\nडॉक्टर ने पूछा, \"फिर कब दिखाना है?\"\nमरीज ने जवाब दिया, \"जैसा आज तय करेंगे;\nलक्षण बिगड़ें तो पहले संपर्क करें।\""],
  ["doctor-patient", "क्लिनिक में मरीज की नई उलझन सुनकर डॉक्टर ने पूछा—क्या मैं सामान्य खाना खा सकता हूँ।\nडॉक्टर ने पूछा, \"क्या मैं सामान्य खाना खा सकता हूँ?\"\nमरीज ने जवाब दिया, \"आपकी स्थिति के अनुसार बताएँगे;\nहर मरीज का परहेज़ एक जैसा नहीं।\""],
  ["doctor-patient", "क्लिनिक में मरीज की नई उलझन सुनकर डॉक्टर ने पूछा—दर्द चला गया तो दवा रोक दूँ।\nडॉक्टर ने पूछा, \"दर्द चला गया तो दवा रोक दूँ?\"\nमरीज ने जवाब दिया, \"बिना सलाह दवा बंद न करें;\nउपचार का पूरा निर्देश समझें।\""],
  ["doctor-patient", "क्लिनिक में मरीज की नई उलझन सुनकर डॉक्टर ने पूछा—जल्दी ठीक होने का छोटा रास्ता।\nडॉक्टर ने पूछा, \"जल्दी ठीक होने का छोटा रास्ता?\"\nमरीज ने जवाब दिया, \"गलत शॉर्टकट छोड़कर सही,\nसलाह का पालन करना।\""],
  ["doctor-patient", "क्लिनिक में मरीज की नई उलझन सुनकर डॉक्टर ने पूछा—डॉक्टर साहब, फीस कब दूँ।\nडॉक्टर ने पूछा, \"डॉक्टर साहब, फीस कब दूँ?\"\nमरीज ने जवाब दिया, \"काउंटर पर;\nइलाज की तरह हिसाब भी साफ़ होना चाहिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—बगीचे में सबसे सुंदर फूल कौन-सा है।\nराजा ने पूछा, \"बगीचे में सबसे सुंदर फूल कौन-सा है?\"\nतेनालीराम ने उत्तर दिया, \"जो खिलकर खुशबू दे,\nन कि माली से अपना परिचय-पत्र माँगे।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—माली कहता है पानी कम है।\nराजा ने पूछा, \"माली कहता है पानी कम है।\"\nतेनालीराम ने उत्तर दिया, \"पहले नल ठीक कराइए;\nफूलों को भाषण से प्यास नहीं बुझती।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—पेड़ की छाया किसकी है।\nराजा ने पूछा, \"पेड़ की छाया किसकी है?\"\nतेनालीराम ने उत्तर दिया, \"जो धूप में खड़ा हो,\nछाया सबको देता है; यही बगीचे का न्याय है।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—राजा ने पूछा पौधे क्यों झुके हैं।\nराजा ने पूछा, \"राजा ने पूछा पौधे क्यों झुके हैं?\"\nतेनालीराम ने उत्तर दिया, \"फल से भरी डाल झुकती है,\nखाली डाल ही अकड़ दिखाती है।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—कौन-सा पौधा जल्दी बढ़ेगा।\nराजा ने पूछा, \"कौन-सा पौधा जल्दी बढ़ेगा?\"\nतेनालीराम ने उत्तर दिया, \"जिसे धूप,\nपानी और देखभाल मिले; केवल शाही आदेश नहीं।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—माली ने पुरस्कार माँगा।\nराजा ने पूछा, \"माली ने पुरस्कार माँगा।\"\nतेनालीराम ने उत्तर दिया, \"तेनाली ने कहा पहले बगीचे को दिखाइए;\nमेहनत का फल पेड़ पर भी दिखना चाहिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—फूलों की गिनती कैसे हो।\nराजा ने पूछा, \"फूलों की गिनती कैसे हो?\"\nतेनालीराम ने उत्तर दिया, \"खुशबू गिनना कठिन है;\nपौधों की देखभाल का हिसाब रखिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—एक पौधा मुरझा गया।\nराजा ने पूछा, \"एक पौधा मुरझा गया।\"\nतेनालीराम ने उत्तर दिया, \"उसे दोष मत दीजिए;\nपानी की जिम्मेदारी किसकी थी?\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—बगीचे का सबसे बड़ा रहस्य क्या।\nराजा ने पूछा, \"बगीचे का सबसे बड़ा रहस्य क्या?\"\nतेनालीराम ने उत्तर दिया, \"सुंदरता रोज़ की देखभाल से आती है,\nएक दिन के उत्सव से नहीं।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—राजा ने कहा बगीचा मेरा है।\nराजा ने पूछा, \"राजा ने कहा बगीचा मेरा है।\"\nतेनालीराम ने उत्तर दिया, \"तभी तो इसकी खुशबू जनता,\nतक भी पहुँचनी चाहिए।\""],
  ["tenali-ram", "राजा ने तेनालीराम से पूछा, \"दरबार में सबसे बड़ा ज्ञानी कौन है?\"\nतेनाली ने खाली कुर्सी की ओर इशारा किया।\nराजा ने पूछा, \"यह कुर्सी क्यों?\"\nतेनाली बोले, \"जो हर बात पर नहीं बोलता, उसकी भूलें भी कम सुनाई देती हैं।\""],
  ["tenali-ram", "एक व्यापारी ने दावा किया कि उसका रेशम कभी नहीं सिकुड़ता।\nतेनालीराम ने पूछा, \"तो इसे धोकर दिखाइए।\"\nव्यापारी बोला, \"पहले ग्राहक खरीद तो ले।\"\nतेनाली हँसे, \"दावा पानी से पहले ही सूख गया।\""],
  ["tenali-ram", "राजा ने कहा, \"मेरे लिए सबसे सस्ता महल बनाओ।\"\nतेनाली ने नक्शा दिया जिसमें सिर्फ़ दरवाज़ा बना था।\nराजा बोले, \"बाकी महल कहाँ है?\"\nतेनाली ने कहा, \"बजट खुलते ही बाकी दीवारें भी खड़ी हो जाएँगी।\""],
  ["tenali-ram", "राजा ने तेनाली से पूछा, \"दरबार में कौन सबसे अधिक मेहनत करता है?\"\nतेनाली ने कहा, \"वह सेवक जो सबकी शिकायतें सुनता है।\"\nराजा ने पूछा, \"वह इतना शांत कैसे रहता है?\"\nतेनाली बोले, \"उसे पता है कि शिकायत के बाद भी काम उसी को करना है।\""],
  ["tenali-ram", "एक दरबारी ने कहा कि उसकी सलाह हमेशा सही निकलती है।\nतेनाली ने पूछा, \"तो पिछली सलाह का परिणाम बताइए।\"\nदरबारी बोला, \"वह अभी लागू नहीं हुई।\"\nतेनाली हँसे, \"अधूरी सलाह को गलत होने का मौका भी नहीं मिलता।\""],
  ["tenali-ram", "राजा ने पूछा, \"खाली खजाना कैसे भरेगा?\"\nतेनाली बोले, \"पहले अनावश्यक खर्च बंद कीजिए।\"\nराजा ने कहा, \"और फिर?\"\nतेनाली ने उत्तर दिया, \"फिर बची हुई रकम को खर्च करने की नई योजना मत बनाइए।\""],
  [ "tenali-ram", "राजा ने तेनालीराम से पूछा, “दरबार में सबसे अधिक काम कौन करता है?”\nतेनाली बोले, “घड़ी।”\nराजा ने पूछा, “वह कैसे?”\nतेनाली ने कहा, “सब देर से आएँ, फिर भी वही समय पर चलती रहती है।”" ],
  [ "tenali-ram", "एक व्यापारी ने राजा से कहा कि उसकी दुकान में सब कुछ असली है।\nतेनालीराम ने पूछा, “तो नकली मुस्कान क्यों लगा रखी है?”\nव्यापारी चौंका और बोला, “ग्राहक को खुश रखने के लिए।”\nतेनाली बोले, “पहले सामान से खुश रखो, चेहरा अपने आप मुस्कराएगा।”" ],
  [ "tenali-ram", "राजा ने पूछा, “राजकोष का हिसाब इतना लंबा क्यों है?”\nतेनाली ने कहा, “हर खर्च का कारण लिखा है।”\nराजा बोले, “कुछ कारण तो बहुत छोटे होंगे।”\nतेनाली मुस्कराए, “जी, पर उन्हें लिखने वाले अधिकारी का मानदेय बड़ा है।”" ],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—व्यापारी ने छूट का दावा किया।\nराजा ने पूछा, \"व्यापारी ने छूट का दावा किया।\"\nतेनालीराम ने उत्तर दिया, \"पहले असली दाम बताओ;\nछूट की कहानी बाद में।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—संदूक में क्या रखा है।\nराजा ने पूछा, \"संदूक में क्या रखा है?\"\nतेनालीराम ने उत्तर दिया, \"पहले खोलिए;\nअनुमान से खजाना और डर दोनों बढ़ते हैं।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—संदूक भारी क्यों है।\nराजा ने पूछा, \"संदूक भारी क्यों है?\"\nतेनालीराम ने उत्तर दिया, \"राजा ने कहा सोना होगा;\nतेनाली बोले, शायद अधूरे वादे जमा हैं।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—चाबी किसके पास है।\nराजा ने पूछा, \"चाबी किसके पास है?\"\nतेनालीराम ने उत्तर दिया, \"जिसे भरोसा मिला है,\nपर हिसाब देने की जिम्मेदारी भी उसी की है।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—संदूक खाली निकला तो।\nराजा ने पूछा, \"संदूक खाली निकला तो?\"\nतेनालीराम ने उत्तर दिया, \"कम से कम अब कोई उसके,\nखाली होने का श्रेय नहीं लेगा।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—ताला बहुत मजबूत है।\nराजा ने पूछा, \"ताला बहुत मजबूत है।\"\nतेनालीराम ने उत्तर दिया, \"अच्छा है;\nअब देखिए चाबी सही हाथ में है या नहीं।\""],
  [ "tenali-ram", "राजा ने पूछा, “दरबार में सबसे ध्यान से कौन सुनता है?”\nतेनाली बोले, “दरवाज़े का पहरेदार।”\nराजा ने पूछा, “वह क्यों?”\nतेनाली ने कहा, “सब सुनता है, पर बिना बुलाए जवाब नहीं देता।”" ],
  [ "tenali-ram", "एक दरबारी ने बिना मेहनत धन कमाने का दावा किया।\nतेनाली ने उसे खाली खेत दिखाया और फसल उगाने को कहा।\nदरबारी बोला, “बिना मेहनत कैसे?”\nतेनाली बोले, “आपका दावा भी इसी खेत जैसा खाली है।”" ],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—मंत्री ने कहा चाबी खो गई।\nराजा ने पूछा, \"मंत्री ने कहा चाबी खो गई।\"\nतेनालीराम ने उत्तर दिया, \"चाबी खोना भूल है;\nजवाबदेही खोना आदत।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—संदूक पर धूल क्यों है।\nराजा ने पूछा, \"संदूक पर धूल क्यों है?\"\nतेनालीराम ने उत्तर दिया, \"शायद इसे खोलने से ज़्यादा,\nइसकी रखवाली का दावा हुआ।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—राजा ने कहा इसे सुरक्षित रखो।\nराजा ने पूछा, \"राजा ने कहा इसे सुरक्षित रखो।\"\nतेनालीराम ने उत्तर दिया, \"पहले इसकी सामग्री का,\nसार्वजनिक हिसाब रखिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—सब कुएँ बिल्कुल साफ़ हैं।\nमंत्री ने कहा, \"सब कुएँ बिल्कुल साफ़ हैं।\"\nतेनालीराम ने बाल्टी उठाकर पूछा, \"तो फिर पानी,\nभरने से पहले बदबू की शिकायत क्यों आती है?\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—मंत्री ने कहा सब खुश हैं।\nराजा ने पूछा, \"मंत्री ने कहा सब खुश हैं।\"\nतेनालीराम ने उत्तर दिया, \"तेनाली ने पूछा आपने आख़िरी बार,\nजनता से कब बात की?\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—सड़कें अच्छी हैं।\nराजा ने पूछा, \"सड़कें अच्छी हैं?\"\nतेनालीराम ने उत्तर दिया, \"नक्शे पर तो हैं;\nचलकर देखेंगे तो सच्चाई मिलेगी।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—किसान को पानी मिल रहा है।\nराजा ने पूछा, \"किसान को पानी मिल रहा है?\"\nतेनालीराम ने उत्तर दिया, \"मंत्री बोले रिपोर्ट में हाँ;\nकिसान ने खाली बाल्टी दिखा दी।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—दफ़्तर में काम समय पर होता है।\nराजा ने पूछा, \"दफ़्तर में काम समय पर होता है?\"\nतेनालीराम ने उत्तर दिया, \"घड़ी दीवार पर है;\nअब उसे फ़ाइलों तक पहुँचाइए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—शहर साफ़ है।\nराजा ने पूछा, \"शहर साफ़ है?\"\nतेनालीराम ने उत्तर दिया, \"मंत्री ने तस्वीर दिखाई;\nतेनाली ने तस्वीर के बाहर का रास्ता पूछा।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—कर कम हैं।\nराजा ने पूछा, \"कर कम हैं?\"\nतेनालीराम ने उत्तर दिया, \"कर का हिसाब जनता से पूछिए,\nसिर्फ़ खजाने से नहीं।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—न्याय तेज़ है।\nराजा ने पूछा, \"न्याय तेज़ है?\"\nतेनालीराम ने उत्तर दिया, \"तेनाली ने कहा,\nफैसला आने तक पीढ़ी बदल जाए तो गति पर सवाल होगा।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—क्या अब सब संतुष्ट हैं।\nराजा ने प्रसन्न होकर पूछा, \"क्या अब सब संतुष्ट हैं?\"\nतेनालीराम ने पेटी का ताला दिखाया, \"महाराज,\nसंतोष से पहले इसकी चाबी ढूँढ़िए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—राजा ने कहा सब ठीक करो।\nराजा ने पूछा, \"राजा ने कहा सब ठीक करो।\"\nतेनालीराम ने उत्तर दिया, \"पहले समस्या मानिए;\nइलाज वहीं से शुरू होता है।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—बाज़ार में सबसे बड़ा सौदा क्या मिला।\nराजा ने पूछा, \"बाज़ार में सबसे बड़ा सौदा क्या मिला?\"\nतेनालीराम ने उत्तर दिया, \"दुकानदार ने मुस्कान मुफ्त दी,\nऔर दाम में जोड़ दी।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—एक ग्राहक रास्ता भूल गया।\nराजा ने पूछा, \"एक ग्राहक रास्ता भूल गया।\"\nतेनालीराम ने उत्तर दिया, \"तेनाली ने कहा नक्शा देखो;\nदुकानदार ने कहा पहले मेरी दुकान देखो।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—सब्ज़ी ताज़ी कैसे पहचानें।\nराजा ने पूछा, \"सब्ज़ी ताज़ी कैसे पहचानें?\"\nतेनालीराम ने उत्तर दिया, \"सब्ज़ी से पूछने की ज़रूरत नहीं;\nउसकी हालत देखिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—दुकानदार ने कहा आज घाटा है।\nराजा ने पूछा, \"दुकानदार ने कहा आज घाटा है।\"\nतेनालीराम ने उत्तर दिया, \"कल का मुनाफ़ा भी दिखाइए;\nहिसाब पूरा होना चाहिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—बाज़ार में शोर बहुत था।\nराजा ने पूछा, \"बाज़ार में शोर बहुत था।\"\nतेनालीराम ने उत्तर दिया, \"जहाँ दाम साफ़ न हों वहाँ,\nआवाज़ें अक्सर ऊँची होती हैं।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—एक आदमी मुफ्त चीज़ ढूँढ़ रहा था।\nराजा ने पूछा, \"एक आदमी मुफ्त चीज़ ढूँढ़ रहा था।\"\nतेनालीराम ने उत्तर दिया, \"तेनाली ने उसे आईना दिया;\nकहा, पहले अपना समय मुफ्त मत बाँटो।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—सबसे अच्छा ग्राहक कौन।\nराजा ने पूछा, \"सबसे अच्छा ग्राहक कौन?\"\nतेनालीराम ने उत्तर दिया, \"जो सवाल पूछे,\nरसीद ले और सामान देखकर खरीदे।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—दुकानदार ने उधार दिया।\nराजा ने पूछा, \"दुकानदार ने उधार दिया।\"\nतेनालीराम ने उत्तर दिया, \"अच्छा है;\nअब तारीख भी लिखो ताकि दोस्ती बची रहे।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—मिठाई वाला बोला सब ताज़ा है।\nराजा ने पूछा, \"मिठाई वाला बोला सब ताज़ा है।\"\nतेनालीराम ने उत्तर दिया, \"तेनाली ने कहा,\nतो फिर पुरानी तारीख किसकी है?\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—बाज़ार का नियम क्या।\nराजा ने पूछा, \"बाज़ार का नियम क्या?\"\nतेनालीराम ने उत्तर दिया, \"मोलभाव हो सकता है,\nमगर नाप और सच में नहीं।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—मित्र संकट में साथ देगा कैसे।\nराजा ने पूछा, \"मित्र संकट में साथ देगा कैसे?\"\nतेनालीराम ने उत्तर दिया, \"जो मुश्किल में फोन उठाए,\nऔर काम में हाथ लगाए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—मित्र ने केवल प्रशंसा की।\nराजा ने पूछा, \"मित्र ने केवल प्रशंसा की।\"\nतेनालीराम ने उत्तर दिया, \"अच्छा मित्र गलती भी बताए,\nसिर्फ़ तालियाँ न बजाए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—कौन-सा दोस्त सच्चा है।\nराजा ने पूछा, \"कौन-सा दोस्त सच्चा है?\"\nतेनालीराम ने उत्तर दिया, \"जो लाभ न हो,\nतब भी हाल पूछे।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—मित्र ने उधार लौटाने का वादा किया।\nराजा ने पूछा, \"मित्र ने उधार लौटाने का वादा किया।\"\nतेनालीराम ने उत्तर दिया, \"तारीख लिख लो;\nदोस्ती को याददाश्त की परीक्षा मत बनाओ।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—दो मित्र झगड़ पड़े।\nराजा ने पूछा, \"दो मित्र झगड़ पड़े।\"\nतेनालीराम ने उत्तर दिया, \"तेनाली ने कहा पहले सुनो;\nआधी लड़ाई गलतफहमी से बनी थी।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—मित्र ने राज़ रखा।\nराजा ने पूछा, \"मित्र ने राज़ रखा।\"\nतेनालीराम ने उत्तर दिया, \"भरोसा वही है जो अनुपस्थिति,\nमें भी सुरक्षित रहे।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—किसके साथ यात्रा करें।\nराजा ने पूछा, \"किसके साथ यात्रा करें?\"\nतेनालीराम ने उत्तर दिया, \"जो रास्ता साझा करे,\nबोझ नहीं बढ़ाए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—मित्र ने कहा मैं हमेशा सही हूँ।\nराजा ने पूछा, \"मित्र ने कहा मैं हमेशा सही हूँ।\"\nतेनालीराम ने उत्तर दिया, \"तब तुम्हें मित्र नहीं,\nदर्पण चाहिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—पुराना मित्र मिला।\nराजा ने पूछा, \"पुराना मित्र मिला।\"\nतेनालीराम ने उत्तर दिया, \"समय बदला है;\nअपनापन अब भी पहचानता है।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—मित्रता का सबसे अच्छा उपहार।\nराजा ने पूछा, \"मित्रता का सबसे अच्छा उपहार?\"\nतेनालीराम ने उत्तर दिया, \"ईमानदार सलाह और बिना,\nहिसाब की मदद।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—चित्रकार ने कहा चित्र बिल्कुल जीवंत है।\nराजा ने पूछा, \"चित्रकार ने कहा चित्र बिल्कुल जीवंत है।\"\nतेनालीराम ने उत्तर दिया, \"अच्छा; अब चित्र में रंग भरने,\nवाले को भी श्रेय दीजिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—राजा का चित्र बहुत चमकीला था।\nराजा ने पूछा, \"राजा का चित्र बहुत चमकीला था।\"\nतेनालीराम ने उत्तर दिया, \"तेनाली ने कहा,\nरंग अच्छे हैं; अब चेहरे पर थोड़ा सच भी बनाइए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—चित्रकार ने अपनी फीस बढ़ाई।\nराजा ने पूछा, \"चित्रकार ने अपनी फीस बढ़ाई।\"\nतेनालीराम ने उत्तर दिया, \"पहले बताइए आपने कितने,\nचित्र पूरे किए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—चित्र में हाथ तीन क्यों हैं।\nराजा ने पूछा, \"चित्र में हाथ तीन क्यों हैं?\"\nतेनालीराम ने उत्तर दिया, \"चित्रकार बोला शैली है;\nतेनाली बोले, फिर काम में दो हाथ क्यों?\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—सबसे अच्छा चित्र कौन-सा।\nराजा ने पूछा, \"सबसे अच्छा चित्र कौन-सा?\"\nतेनालीराम ने उत्तर दिया, \"जो देखने वाले को सोचने दे,\nसिर्फ़ चित्रकार का नाम न पढ़ाए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—चित्रकार ने कहा मेरी कला अमूल्य है।\nराजा ने पूछा, \"चित्रकार ने कहा मेरी कला अमूल्य है।\"\nतेनालीराम ने उत्तर दिया, \"तो फिर मूल्य तय करने,\nसे पहले ग्राहक की सुनिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—रंग जल्दी उतर गए।\nराजा ने पूछा, \"रंग जल्दी उतर गए।\"\nतेनालीराम ने उत्तर दिया, \"तेनाली ने पूछा,\nरंग खरीदे थे या तारीफ़ का वादा?\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—राजा ने चित्र पसंद किया।\nराजा ने पूछा, \"राजा ने चित्र पसंद किया।\"\nतेनालीराम ने उत्तर दिया, \"अब जनता की तस्वीर भी बनाइए;\nराज्य सिर्फ़ महल नहीं।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—चित्रकार ने समय माँगा।\nराजा ने पूछा, \"चित्रकार ने समय माँगा।\"\nतेनालीराम ने उत्तर दिया, \"समय दीजिए;\nपर हर बार नई तारीख न लिखिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—कला का सम्मान कैसे हो।\nराजा ने पूछा, \"कला का सम्मान कैसे हो?\"\nतेनालीराम ने उत्तर दिया, \"कलाकार को उचित मेहनताना और,\nकाम को ईमानदार प्रतिक्रिया दीजिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—किसान की शिकायत क्या है।\nराजा ने पूछा, \"किसान की शिकायत क्या है?\"\nतेनालीराम ने उत्तर दिया, \"उसकी मेहनत का दाम रास्ते,\nमें कहीं अटक गया है।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—किसान ने कर कम करने को कहा।\nराजा ने पूछा, \"किसान ने कर कम करने को कहा।\"\nतेनालीराम ने उत्तर दिया, \"तेनाली ने पूछा फसल कैसी है;\nन्याय हालात देखकर होना चाहिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—पानी खेत तक क्यों नहीं पहुँचा।\nराजा ने पूछा, \"पानी खेत तक क्यों नहीं पहुँचा?\"\nतेनालीराम ने उत्तर दिया, \"किसान बोला नहर बनी है;\nतेनाली ने कहा कागज़ पर या ज़मीन पर?\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—बीज खराब निकले।\nराजा ने पूछा, \"बीज खराब निकले।\"\nतेनालीराम ने उत्तर दिया, \"पहले आपूर्तिकर्ता का हिसाब जाँचो,\nकिसान को दोष मत दो।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—मंडी में भाव गिर गया।\nराजा ने पूछा, \"मंडी में भाव गिर गया।\"\nतेनालीराम ने उत्तर दिया, \"तेनाली ने कहा किसान को जानकारी,\nऔर उचित बाज़ार तक पहुँच दो।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—किसान ने खाली टोकरी दिखाई।\nराजा ने पूछा, \"किसान ने खाली टोकरी दिखाई।\"\nतेनालीराम ने उत्तर दिया, \"खाली टोकरी से ज़्यादा खाली,\nवादों की जाँच होनी चाहिए।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—फसल का नुकसान किसका।\nराजा ने पूछा, \"फसल का नुकसान किसका?\"\nतेनालीराम ने उत्तर दिया, \"मौसम का हिस्सा अलग,\nव्यवस्था की लापरवाही अलग; दोनों का हिसाब रखो।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—किसान ने सहायता माँगी।\nराजा ने पूछा, \"किसान ने सहायता माँगी।\"\nतेनालीराम ने उत्तर दिया, \"सहायता दया नहीं,\nसमय पर मिलने वाला अधिकार है।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—सबसे अच्छा बीज कौन-सा।\nराजा ने पूछा, \"सबसे अच्छा बीज कौन-सा?\"\nतेनालीराम ने उत्तर दिया, \"जो जाँच में खरा हो और किसान,\nको सही जानकारी के साथ मिले।\""],
  ["tenali-ram", "राजा के दरबार में आज तेनालीराम के सामने सवाल आया—राजा ने किसान को सुना।\nराजा ने पूछा, \"राजा ने किसान को सुना।\"\nतेनालीराम ने उत्तर दिया, \"अब सुनवाई को काम में बदलिए;\nखेत इंतज़ार नहीं करता।\""],
  ["tenali-ram", "विजयनगर के बाज़ार में एक सुनार ने दावा किया कि उसकी तराज़ू कभी कम नहीं तौलती।\nतेनालीराम ने उसी तराज़ू पर दो बार एक ही सिक्का तौलने को कहा।\nदोनों बार अलग वज़न आया तो सुनार बोला, \"सिक्का बेचैन है।\"\nतेनाली हँसे, \"तो तराज़ू को स्थिर रहने की शिक्षा दीजिए।\""],
  ["tenali-ram", "राजा ने महल के चित्रकार से अपनी सबसे सुंदर तस्वीर बनवाई।\nचित्रकार ने मुकुट तो चमकदार बनाया, पर चेहरे पर चिंता भी उकेर दी।\nराजा नाराज़ हुए, \"मेरी चिंता किसने बताई?\"\nतेनाली बोले, \"आईना रोज़ दरबार आता है, महाराज।\""],
  ["tenali-ram", "एक मंत्री ने कहा कि राज्य का नया पुल रिकॉर्ड समय में बन गया है।\nतेनालीराम ने पूछा, \"क्या नदी पार करने वाले भी यही कहते हैं?\"\nमंत्री ने बताया कि पुल अभी उद्घाटन की प्रतीक्षा में बंद है।\nतेनाली बोले, \"फिर रिकॉर्ड निर्माण का नहीं, प्रतीक्षा का है।\""],
  ["tenali-ram", "दरबार में एक कवि ने अपनी कविता को सबसे लंबी रचना बताया।\nराजा ने पूछा, \"इसका सार क्या है?\"\nकवि ने कहा, \"महाराज, सार तो अंतिम पन्ने पर है।\"\nतेनाली बोले, \"तब तक श्रोता अपना सार लेकर घर जा चुके होंगे।\""],
  ["tenali-ram", "एक अधिकारी ने शिकायत की कि महल के कुएँ से पानी कम निकलता है।\nतेनाली ने देखा कि बाल्टी में बड़ा छेद था।\nअधिकारी बोला, \"कुएँ का निरीक्षण कराना होगा।\"\nतेनाली हँसे, \"पहले बाल्टी का दोष कुएँ पर मत डालिए।\""],
  ["tenali-ram", "राजा ने आदेश दिया कि महल में हर सूचना तुरंत पहुँचे।\nदूत ने एक संदेश तीन मुहरों और चार हस्ताक्षरों के बाद पहुँचाया।\nराजा ने पूछा, \"इतनी देर क्यों हुई?\"\nतेनाली बोले, \"सूचना दौड़ रही थी, मुहरें उसे पैदल चला रही थीं।\""],
  ["tenali-ram", "एक व्यापारी ने अपने गोदाम को पूरी तरह सुरक्षित बताया।\nतेनालीराम ने पूछा कि चूहे कहाँ से आते हैं।\nव्यापारी बोला, \"वे छोटे छेद से घुसते हैं, पर हिसाब में नहीं आते।\"\nतेनाली ने कहा, \"जिस छेद को आप नहीं गिनते, वही सबसे बड़ा खर्च है।\""],
  ["tenali-ram", "दरबार में ज्योतिषी ने कहा कि वर्षा केवल उसके शुभ दिन पर होगी।\nतेनाली ने किसानों से पूछा कि खेत कब पानी माँगते हैं।\nकिसानों ने बादलों और मिट्टी की दशा बताई।\nतेनाली बोले, \"आकाश का हाल खेत से पूछिए, कैलेंडर से नहीं।\""],
  ["tenali-ram", "राजा ने घोषणा की कि महल में अब कोई झूठ नहीं बोलेगा।\nअगले दिन मंत्री ने कहा कि सभी काम समय पर पूरे हो गए हैं।\nतेनाली ने अधूरी फ़ाइलों की ओर इशारा किया।\nमंत्री बोला, \"महाराज, झूठ पर रोक है; भविष्य की तारीख़ पर नहीं।\""],
  ["tenali-ram", "एक दरबारी ने दावा किया कि वह बिना देखे भी हर वस्तु पहचान सकता है।\nतेनाली ने उसे कपड़े में लिपटी वस्तु पकड़ाई।\nदरबारी ने गंभीरता से कहा, \"यह अवश्य कोई राजकीय खजाना है।\"\nकपड़ा खुला तो उसमें आलू निकला; तेनाली बोले, \"खजाना रसोई में सुरक्षित रहेगा।\""],
  ["tenali-ram", "राजा ने बगीचे के माली से पूछा कि सूखे पेड़ को हटाने में कितने दिन लगेंगे।\nमाली ने कहा, \"एक दिन, महाराज।\"\nतेनालीराम ने सूखी डाल पर झूला बाँध दिया और बच्चों को बुला लिया।\nराजा ने पूछा, \"यह क्या किया?\" तेनाली बोले, \"अब पेड़ हटाने से पहले जनता की अनुमति भी लेनी पड़ेगी।\""],
  ["tenali-ram", "दरबार में एक व्यापारी ने दावा किया कि उसकी घड़ी कभी गलत समय नहीं बताती।\nतेनालीराम ने घड़ी को महल की धूपघड़ी के पास रखवाया।\nदोनों में अंतर निकला तो व्यापारी बोला, \"धूपघड़ी धीमी है।\"\nतेनाली मुस्कराए, \"अच्छा, अब सूरज को भी आपकी दुकान पर मरम्मत के लिए भेज दें?\""],
  ["tenali-ram", "राजा ने घोषणा की कि जो सबसे भारी उपहार लाएगा, उसे इनाम मिलेगा।\nदरबारी सोने की थालियाँ और चाँदी के संदूक लेकर पहुँचे।\nतेनालीराम खाली हाथ आए और बोले, \"मैं आपके लिए प्रजा की एक सच्ची शिकायत लाया हूँ।\"\nराजा ने उसे सुना और कहा, \"यह उपहार बाकी सबकी चमक से भारी है।\""],
  ["tenali-ram", "एक दरबारी ने महल के दरवाज़े पर बड़ा-सा ताला लगवा दिया ताकि कोई बिना अनुमति न आए।\nतेनालीराम ने पूछा, \"चाबी किसके पास है?\"\nदरबारी बोला, \"मेरे पास, सुरक्षा पूरी है।\"\nतेनाली ने कहा, \"और आग लग जाए तो बाहर निकलने की अनुमति भी आपसे लेनी होगी?\""],
  ["tenali-ram", "राजा ने रसोइए से पूछा कि खीर में मिठास कम क्यों है।\nरसोइए ने चीनी की कमी बताई और खजाने से अतिरिक्त रकम माँगी।\nतेनालीराम ने पहले खीर चखी, फिर रसोइए से पूछा कि उसने चीनी कब डाली थी।\nरसोइया बोला, \"अभी डालनी थी।\" तेनाली बोले, \"तो कमी खजाने में नहीं, आपकी याददाश्त में है।\""],
  ["tenali-ram", "दरबार के कवि ने अपनी कविता को इतना लंबा बताया कि सुनने में पूरा दिन लगेगा।\nतेनालीराम ने कहा, \"महाराज, पहले इसका सार सुन लेते हैं।\"\nकवि ने एक घंटे तक भूमिका ही सुनाई।\nतेनाली ने घड़ी दिखाकर कहा, \"सार तो मिल गया—कविता अभी शुरू नहीं हुई।\""],
  ["tenali-ram", "राजा ने नदी पर बने पुल की मजबूती जाँचने का आदेश दिया।\nठेकेदार ने कहा कि पुल सौ हाथियों का भार सह सकता है।\nतेनालीराम ने पूछा, \"क्या आपने एक हाथी भी चढ़ाकर देखा?\"\nठेकेदार चुप हुआ तो तेनाली बोले, \"कागज़ पर हाथी हल्के होते हैं, महाराज।\""],
  ["tenali-ram", "एक ज्योतिषी ने दरबार में दावा किया कि वह बिना पूछे हर व्यक्ति की इच्छा बता सकता है।\nतेनालीराम ने उसे खाली थाली और चम्मच दिया।\nज्योतिषी ने कहा, \"आप भोजन चाहते हैं।\"\nतेनाली बोले, \"गलत—मैं देखना चाहता था कि आपकी विद्या भूख से तेज़ है या रसोई।\""],
  ["tenali-ram", "राजा ने आदेश दिया कि महल में पानी की एक बूँद भी व्यर्थ न जाए।\nअगले दिन दरबारी ने पानी बचाने के नाम पर हाथ धोना बंद कर दिया।\nतेनालीराम ने उसे पानी से भरा छोटा कटोरा दिया और कहा, \"इसे पी लीजिए।\"\nदरबारी घबराया तो तेनाली बोले, \"बचत का अर्थ सफ़ाई छोड़ना नहीं, समझदारी से उपयोग करना है।\""],
  ["tenali-ram", "एक सेनापति ने कहा कि उसकी सेना बिना नक्शे के भी रास्ता ढूँढ़ लेगी।\nतेनालीराम ने उसे महल के भंडार तक जाने का रास्ता पूछा।\nसेनापति तीन बार गलत गलियारे में मुड़ गया।\nतेनाली ने कहा, \"सीमा पर दुश्मन से पहले अपने नक्शे से मित्रता कर लीजिए।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—गृहकार्य पूरा क्यों नहीं है।\nअध्यापक ने पूछा, \"गृहकार्य पूरा क्यों नहीं है?\"\nछात्र ने जवाब दिया, \"कॉपी तैयार थी;\nपेंसिल ने आख़िरी समय पर आराम माँग लिया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—किसने सबसे पहले काम जमा किया।\nअध्यापक ने पूछा, \"किसने सबसे पहले काम जमा किया?\"\nछात्र ने जवाब दिया, \"जिसने सवाल पढ़ने से पहले नाम लिख दिया,\nसर।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कितने प्रश्न हल किए।\nअध्यापक ने पूछा, \"कितने प्रश्न हल किए?\"\nछात्र ने जवाब दिया, \"तीन पूरे और चौथे से,\nदोस्ती की कोशिश जारी है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कॉपियाँ खाली क्यों हैं।\nअध्यापक ने पूछा, \"कॉपियाँ खाली क्यों हैं?\"\nछात्र ने जवाब दिया, \"विचार बहुत थे;\nवे लाइन में लगते-लगते छुट्टी हो गई।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—गृहकार्य किसने समझाया।\nअध्यापक ने पूछा, \"गृहकार्य किसने समझाया?\"\nछात्र ने जवाब दिया, \"दोस्त ने समझाया,\nमैंने सुना; कॉपी ने दोनों की बात नहीं मानी।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—उत्तर में चित्र क्यों बनाया।\nअध्यापक ने पूछा, \"उत्तर में चित्र क्यों बनाया?\"\nछात्र ने जवाब दिया, \"शब्द कम पड़ गए तो,\nकल्पना को बुला लिया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—किताब घर भूल आए।\nअध्यापक ने पूछा, \"किताब घर भूल आए?\"\nछात्र ने जवाब दिया, \"सर; आज किताब को भी,\nघर पर पढ़ाई करने दी।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—काम देर से क्यों आया।\nअध्यापक ने पूछा, \"काम देर से क्यों आया?\"\nछात्र ने जवाब दिया, \"समय पर निकला था,\nरास्ते में बहाना मिल गया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—किसी से नकल की।\nअध्यापक ने पूछा, \"किसी से नकल की?\"\nछात्र ने जवाब दिया, \"नहीं सर,\nबस सवाल ने मेरे दोस्त का उत्तर देखकर प्रेरणा ली।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—अगली बार क्या करोगे।\nअध्यापक ने पूछा, \"अगली बार क्या करोगे?\"\nछात्र ने जवाब दिया, \"पहले पढ़ूँगा,\nफिर लिखूँगा; आज उल्टा प्रयोग सफल नहीं हुआ।\""],
  ["teacher-student", "शिक्षक ने पूछा, \"होमवर्क क्यों नहीं किया?\"\nछात्र बोला, \"सर, बिजली चली गई थी।\"\nशिक्षक ने कहा, \"तो दिन में कर लेते।\"\nछात्र बोला, \"सर, दिन में बिजली थी, पर मेरा मन छुट्टी पर था।\""],
  ["teacher-student", "मैडम ने पूछा, \"पृथ्वी गोल क्यों है?\"\nपप्पू बोला, \"ताकि कोई कोना पकड़कर उसे रोक न सके।\"\nमैडम ने कहा, \"विज्ञान में ऐसा नहीं लिखा।\"\nपप्पू बोला, \"इसीलिए तो मैंने अपनी तरफ़ से सुरक्षा उपाय बताया।\""],
  ["teacher-student", "सर ने कहा, \"कल परीक्षा है, सब तैयारी करके आना।\"\nछात्र ने पूछा, \"सर, प्रश्नपत्र आसान होगा?\"\nसर बोले, \"तुम्हारी तैयारी पर निर्भर है।\"\nछात्र बोला, \"तो प्रश्नपत्र को भी थोड़ा पढ़कर आने को कहिए।\""],
  ["teacher-student", "शिक्षक ने पूछा, \"इतिहास से हमें क्या सीख मिलती है?\"\nछात्र बोला, \"कि परीक्षा में तारीख़ें याद रखना ज़रूरी है।\"\nशिक्षक ने कहा, \"और जीवन में?\"\nछात्र बोला, \"गलती दोहराने से पहले पिछला अध्याय पढ़ लेना चाहिए।\""],
  ["teacher-student", "मैडम ने कहा, \"वाक्य में 'ईमानदारी' शब्द का प्रयोग करो।\"\nचिंटू बोला, \"मैंने होमवर्क ईमानदारी से नहीं किया।\"\nमैडम ने पूछा, \"यह कैसा उत्तर है?\"\nचिंटू बोला, \"कम-से-कम वाक्य में ईमानदारी तो है।\""],
  ["teacher-student", "सर ने पूछा, \"अगर तुम्हारे पास पाँच आम हों और दो दे दो तो कितने बचेंगे?\"\nछात्र बोला, \"पाँच।\"\nसर ने कहा, \"गणित समझाओ।\"\nछात्र बोला, \"आम मेरे हैं, सर; देने का फैसला अभी नहीं किया।\""],
  [ "teacher-student", "शिक्षक ने पूछा, “इतिहास पढ़ना क्यों ज़रूरी है?”\nविद्यार्थी बोला, “ताकि पुरानी गलतियाँ दोहराएँ नहीं।”\nशिक्षक ने कहा, “अच्छा, कल का गृहकार्य कहाँ है?”\nविद्यार्थी बोला, “उसी सिद्धांत पर आज नहीं दोहराया; कल की गलती सुधारूँगा।”" ],
  [ "teacher-student", "मैडम ने पूछा, “कक्षा में सबसे शांत कौन रहता है?”\nचिंटू बोला, “कंप्यूटर।”\nमैडम ने पूछा, “वह कैसे?”\nचिंटू बोला, “उसका माइक बंद है, फिर भी सब उसे स्मार्ट कहते हैं।”" ],
  [ "teacher-student", "शिक्षक ने बोर्ड पर कठिन सवाल लिखा।\nएक छात्र ने हाथ उठाकर कहा, “सर, सवाल बहुत अच्छा है।”\nशिक्षक खुश हुए और बोले, “हल बताओ।”\nछात्र बोला, “मैंने सिर्फ़ सवाल की तारीफ़ की थी, तैयारी की नहीं।”" ],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—गणित का अभ्यास कैसे बढ़े।\nअध्यापक ने पूछा, \"गणित का अभ्यास कैसे बढ़े?\"\nछात्र ने जवाब दिया, \"रोज़ थोड़ा करूँगा;\nएक रात में पूरी किताब से दोस्ती नहीं होगी।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—ज्वालामुखी का मॉडल कैसे बना।\nअध्यापक ने पूछा, \"ज्वालामुखी का मॉडल कैसे बना?\"\nछात्र ने जवाब दिया, \"आटे से पहाड़ बनाया और,\nगुस्से से लावा बहा दिया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—मॉडल में तार क्यों नहीं जुड़े।\nअध्यापक ने पूछा, \"मॉडल में तार क्यों नहीं जुड़े?\"\nछात्र ने जवाब दिया, \"बिजली से पहले हमने,\nकल्पना को जोड़ दिया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—सबसे अच्छा प्रयोग कौन-सा।\nअध्यापक ने पूछा, \"सबसे अच्छा प्रयोग कौन-सा?\"\nछात्र ने जवाब दिया, \"जो सुरक्षित हो,\nसमझ आए और घर में रसोई न उड़ा दे।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—पौधे की वृद्धि कैसे दिखाओगे।\nअध्यापक ने पूछा, \"पौधे की वृद्धि कैसे दिखाओगे?\"\nछात्र ने जवाब दिया, \"रोज़ फोटो लेंगे;\nपौधे को भी उपस्थिति लगानी होगी।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—सौर मंडल में ग्रह कितने हैं।\nअध्यापक ने पूछा, \"सौर मंडल में ग्रह कितने हैं?\"\nछात्र ने जवाब दिया, \"आठ, सर;\nमेरी टीम में भी आठ विचार थे, पर मॉडल में जगह कम पड़ी।\""],
  [ "teacher-student", "शिक्षक ने पूछा, “पुस्तकालय में शांति क्यों रखनी चाहिए?”\nछात्र बोला, “ताकि किताबें ध्यान से पढ़ सकें।”\nशिक्षक ने कहा, “बिल्कुल सही।”\nछात्र बोला, “और कोई यह न सुन ले कि मैं सिर्फ़ पन्ने पलट रहा हूँ।”" ],
  [ "teacher-student", "सर ने पूछा, “परियोजना में क्या नया सीखा?”\nविद्यार्थी बोला, “टीमवर्क।”\nसर ने उदाहरण माँगा।\nविद्यार्थी बोला, “चार लोगों ने मिलकर तय किया कि काम कल से शुरू होगा।”" ],
  [ "teacher-student", "मैडम ने कहा, “उत्तर के साथ उदाहरण भी देना।”\nछात्र ने लिखा, “उदाहरण घर पर उपलब्ध है।”\nमैडम ने पूछा, “कक्षा में क्यों नहीं लाए?”\nछात्र बोला, “उदाहरण बड़ा था; बस में जगह नहीं मिली।”" ],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—प्रयोग असफल हुआ।\nअध्यापक ने पूछा, \"प्रयोग असफल हुआ?\"\nछात्र ने जवाब दिया, \"नहीं सर,\nहमने एक तरीका खोज लिया जो काम नहीं करता।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—सबसे जरूरी नियम क्या।\nअध्यापक ने पूछा, \"सबसे जरूरी नियम क्या?\"\nछात्र ने जवाब दिया, \"सुरक्षा पहले;\nजिज्ञासा उसके बाद भी पूरी ताकत से।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—परीक्षा की तैयारी कैसी है।\nअध्यापक ने पूछा, \"परीक्षा की तैयारी कैसी है?\"\nछात्र ने जवाब दिया, \"योजना बहुत अच्छी है;\nअब पढ़ाई को भी उसमें शामिल करना है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कितने घंटे पढ़े।\nअध्यापक ने पूछा, \"कितने घंटे पढ़े?\"\nछात्र ने जवाब दिया, \"घड़ी के हिसाब से दो;\nध्यान के हिसाब से आधा।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कठिन विषय कब पढ़ोगे।\nअध्यापक ने पूछा, \"कठिन विषय कब पढ़ोगे?\"\nछात्र ने जवाब दिया, \"आज से, सर;\nकल तक उसे कठिन कहकर टालता रहा।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—नोट्स बनाए।\nअध्यापक ने पूछा, \"नोट्स बनाए?\"\nछात्र ने जवाब दिया, \"सर; रंगीन हैं,\nअब उनमें जानकारी भरनी है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—पुनरावृत्ति की।\nअध्यापक ने पूछा, \"पुनरावृत्ति की?\"\nछात्र ने जवाब दिया, \"सर; किताब खोली तो पुरानी,\nचिंता भी वापस आ गई।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—रात भर पढ़ोगे।\nअध्यापक ने पूछा, \"रात भर पढ़ोगे?\"\nछात्र ने जवाब दिया, \"नहीं सर,\nनींद भी याददाश्त की टीम में है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—समय कैसे बाँटोगे।\nअध्यापक ने पूछा, \"समय कैसे बाँटोगे?\"\nछात्र ने जवाब दिया, \"छोटे हिस्सों में;\nमोबाइल को भी अलग कमरे में रखूँगा।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कौन-सा प्रश्न पहले हल करोगे।\nअध्यापक ने पूछा, \"कौन-सा प्रश्न पहले हल करोगे?\"\nछात्र ने जवाब दिया, \"जो आता है,\nसर; आत्मविश्वास से शुरुआत करूँगा।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—गलती से क्या सीखोगे।\nअध्यापक ने पूछा, \"गलती से क्या सीखोगे?\"\nछात्र ने जवाब दिया, \"गलत उत्तर को समझूँगा,\nसिर्फ़ लाल निशान नहीं देखूँगा।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—अच्छी तैयारी का राज़।\nअध्यापक ने पूछा, \"अच्छी तैयारी का राज़?\"\nछात्र ने जवाब दिया, \"नियमित अभ्यास,\nपर्याप्त आराम और आख़िरी रात का कम नाटक।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—अशोक ने क्या किया था।\nअध्यापक ने पूछा, \"अशोक ने क्या किया था?\"\nछात्र ने जवाब दिया, \"बहुत कुछ;\nलेकिन परीक्षा में वही लिखूँगा जो आपने पढ़ाया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—इतिहास क्यों पढ़ते हैं।\nअध्यापक ने पूछा, \"इतिहास क्यों पढ़ते हैं?\"\nछात्र ने जवाब दिया, \"ताकि पुरानी गलतियों को नई,\nतारीख़ देकर दोहराएँ नहीं।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—राजा महान कैसे बनता है।\nअध्यापक ने पूछा, \"राजा महान कैसे बनता है?\"\nछात्र ने जवाब दिया, \"जनता का भला करे तो;\nसिर्फ़ बड़े महल से नहीं।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कौन-सी घटना याद है।\nअध्यापक ने पूछा, \"कौन-सी घटना याद है?\"\nछात्र ने जवाब दिया, \"वह जो किताब में भी है और सवाल,\nमें भी आने की उम्मीद है।\""],
  ["teacher-student", "इतिहास की किताब में एक पुराना नक्शा खुला पड़ा था।\nअध्यापक ने पूछा, \"तारीख़ें याद रखने का तरीका?\"\nछात्र बोला, \"उन्हें कैलेंडर में लिख दूँ?\"\nअध्यापक बोले, \"फिर परीक्षा में कैलेंडर भी साथ लाना पड़ेगा।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—पुराने समय में इंटरनेट था।\nअध्यापक ने पूछा, \"पुराने समय में इंटरनेट था?\"\nछात्र ने जवाब दिया, \"नहीं सर,\nइसलिए अफ़वाह फैलने में थोड़ा ज़्यादा समय लगता था।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कौन-सा स्रोत भरोसेमंद है।\nअध्यापक ने पूछा, \"कौन-सा स्रोत भरोसेमंद है?\"\nछात्र ने जवाब दिया, \"कई स्रोत मिलाकर जाँचूँगा;\nएक कहानी पूरी तस्वीर नहीं।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—इतिहास से क्या सीख मिली।\nअध्यापक ने पूछा, \"इतिहास से क्या सीख मिली?\"\nछात्र ने जवाब दिया, \"सत्ता बदलती है,\nलेकिन जिम्मेदारी का सवाल बना रहता है।\""],
  ["teacher-student", "विज्ञान की कक्षा में पंखे की आवाज़ अचानक तेज़ हो गई।\nअध्यापक ने पूछा, \"सबका ध्यान कहाँ है?\"\nछात्र बोला, \"सर, पंखे की गति पर।\"\nअध्यापक हँसे, \"कम से कम आज हवा में विज्ञान तो है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—सबसे अच्छा इतिहासकार कौन।\nअध्यापक ने पूछा, \"सबसे अच्छा इतिहासकार कौन?\"\nछात्र ने जवाब दिया, \"जो प्रमाण देखे और अपनी पसंद,\nको तथ्य न बना दे।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—देर से क्यों आए।\nअध्यापक ने पूछा, \"देर से क्यों आए?\"\nछात्र ने जवाब दिया, \"घड़ी समय पर थी;\nमैं उससे सहमत नहीं हो पाया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—बस छूट गई।\nअध्यापक ने पूछा, \"बस छूट गई?\"\nछात्र ने जवाब दिया, \"जी सर, बस गई और मेरी,\nदौड़ का अभ्यास हो गया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—अलार्म नहीं बजा।\nअध्यापक ने पूछा, \"अलार्म नहीं बजा?\"\nछात्र ने जवाब दिया, \"बजा था सर,\nमैंने उसे सपने में बंद कर दिया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—रास्ते में क्या हुआ।\nअध्यापक ने पूछा, \"रास्ते में क्या हुआ?\"\nछात्र ने जवाब दिया, \"ट्रैफ़िक ने आज मुझे नागरिक,\nशास्त्र का पाठ पढ़ाया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कल भी देर हुई थी।\nअध्यापक ने पूछा, \"कल भी देर हुई थी।\"\nछात्र ने जवाब दिया, \"कल अभ्यास था;\nआज प्रदर्शन थोड़ा बेहतर रहा।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कक्षा शुरू होने के बाद आए।\nअध्यापक ने पूछा, \"कक्षा शुरू होने के बाद आए?\"\nछात्र ने जवाब दिया, \"जी सर, ज्ञान तो समय पर मिला;\nशरीर थोड़ा देर से पहुँचा।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—समय की कीमत जानते हो।\nअध्यापक ने पूछा, \"समय की कीमत जानते हो?\"\nछात्र ने जवाब दिया, \"जी सर, इसलिए देर से आने,\nपर हर मिनट भारी लगता है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—क्या बहाना तैयार है।\nअध्यापक ने पूछा, \"क्या बहाना तैयार है?\"\nछात्र ने जवाब दिया, \"बहाना नहीं;\nअगली बार पहले निकलने का अलार्म तैयार है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कितने मिनट देर।\nअध्यापक ने पूछा, \"कितने मिनट देर?\"\nछात्र ने जवाब दिया, \"इतने कि उपस्थिति से पहले,\nमेरी सफ़ाई शुरू हो गई।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—अब क्या करोगे।\nअध्यापक ने पूछा, \"अब क्या करोगे?\"\nछात्र ने जवाब दिया, \"कल से नहीं;\nआज ही बैग रात में तैयार करूँगा।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कैमरा बंद क्यों है।\nअध्यापक ने पूछा, \"कैमरा बंद क्यों है?\"\nछात्र ने जवाब दिया, \"नेटवर्क बचाने के लिए;\nचेहरा तो पूरी तरह उपस्थित है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—ऑनलाइन कक्षा में ध्यान है।\nअध्यापक ने पूछा, \"ऑनलाइन कक्षा में ध्यान है?\"\nछात्र ने जवाब दिया, \"जी सर, टैब खुला है;\nध्यान को भी लिंक भेजा है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—माइक बंद क्यों रखा।\nअध्यापक ने पूछा, \"माइक बंद क्यों रखा?\"\nछात्र ने जवाब दिया, \"घर में प्रेशर कुकर भी चर्चा,\nमें भाग लेना चाहता था।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—उत्तर चैट में क्यों लिखा।\nअध्यापक ने पूछा, \"उत्तर चैट में क्यों लिखा?\"\nछात्र ने जवाब दिया, \"आवाज़ धीमी थी;\nउँगलियों ने जिम्मेदारी ले ली।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—स्क्रीन पर कौन-सी किताब है।\nअध्यापक ने पूछा, \"स्क्रीन पर कौन-सी किताब है?\"\nछात्र ने जवाब दिया, \"पाठ्यपुस्तक;\nबाकी टैब को मैंने छुट्टी पर भेजा है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कनेक्शन टूट गया।\nअध्यापक ने पूछा, \"कनेक्शन टूट गया?\"\nछात्र ने जवाब दिया, \"जी सर, मेरी समझ जुड़ रही थी,\nतभी नेटवर्क ने विराम ले लिया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—ऑनलाइन उपस्थिति कैसे।\nअध्यापक ने पूछा, \"ऑनलाइन उपस्थिति कैसे?\"\nछात्र ने जवाब दिया, \"नाम दिख रहा है;\nअब ज्ञान भी डाउनलोड कर रहा हूँ।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कक्षा रिकॉर्ड की।\nअध्यापक ने पूछा, \"कक्षा रिकॉर्ड की?\"\nछात्र ने जवाब दिया, \"जी सर, ताकि दोबारा सुन सकूँ;\nपहली बार नोटिफिकेशन सुनता रहा।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—वीडियो में कौन बोल रहा था।\nअध्यापक ने पूछा, \"वीडियो में कौन बोल रहा था?\"\nछात्र ने जवाब दिया, \"मैं ही था;\nबस इंटरनेट ने मेरी आवाज़ को धीमा कर दिया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—ऑनलाइन पढ़ाई का नियम।\nअध्यापक ने पूछा, \"ऑनलाइन पढ़ाई का नियम?\"\nछात्र ने जवाब दिया, \"कैमरा हो या न हो,\nसवाल और ध्यान दोनों चालू रहें।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—पुस्तकालय में सबसे अच्छी किताब कौन-सी।\nअध्यापक ने पूछा, \"पुस्तकालय में सबसे अच्छी किताब कौन-सी?\"\nछात्र ने जवाब दिया, \"जो लौटाने की तारीख़ से,\nपहले पढ़ ली जाए।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—किताब देर से लौटाई क्यों।\nअध्यापक ने पूछा, \"किताब देर से लौटाई क्यों?\"\nछात्र ने जवाब दिया, \"कहानी खत्म नहीं हुई थी;\nलाइब्रेरियन ने अगला अध्याय माँग लिया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कौन-सी किताब चुनोगे।\nअध्यापक ने पूछा, \"कौन-सी किताब चुनोगे?\"\nछात्र ने जवाब दिया, \"जो मेरी जिज्ञासा बढ़ाए,\nसिर्फ़ मोटी न हो।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—शांत क्यों रहना है।\nअध्यापक ने पूछा, \"शांत क्यों रहना है?\"\nछात्र ने जवाब दिया, \"ताकि किताब की आवाज़ सुन सकें;\nवह पन्नों में बोलती है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—किताब खो गई।\nअध्यापक ने पूछा, \"किताब खो गई?\"\nछात्र ने जवाब दिया, \"नहीं; वह मेरे बैग में ऐसी जगह,\nहै जहाँ नक्शा भी नहीं पहुँचता।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—पढ़ने का समय कब है।\nअध्यापक ने पूछा, \"पढ़ने का समय कब है?\"\nछात्र ने जवाब दिया, \"रोज़ थोड़ा;\nकिताब को परीक्षा का मेहमान नहीं बनाऊँगा।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—किताब का सबसे अच्छा दोस्त कौन।\nअध्यापक ने पूछा, \"किताब का सबसे अच्छा दोस्त कौन?\"\nछात्र ने जवाब दिया, \"पाठक, सर;\nअलमारी सिर्फ़ उसका पता है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—किताबों से क्या मिलता है।\nअध्यापक ने पूछा, \"किताबों से क्या मिलता है?\"\nछात्र ने जवाब दिया, \"दूसरे लोगों के अनुभव और,\nअपने सवालों के नए रास्ते।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—किताब वापस क्यों नहीं की।\nअध्यापक ने पूछा, \"किताब वापस क्यों नहीं की?\"\nछात्र ने जवाब दिया, \"समय पर लौटाना था;\nकहानी ने आख़िरी पन्ना रोक लिया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—पुस्तकालय का नियम क्या।\nअध्यापक ने पूछा, \"पुस्तकालय का नियम क्या?\"\nछात्र ने जवाब दिया, \"किताब सँभालो,\nसमय पर लौटाओ और ज्ञान आगे बाँटो।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—टीम में काम कौन करेगा।\nअध्यापक ने पूछा, \"टीम में काम कौन करेगा?\"\nछात्र ने जवाब दिया, \"सब करेंगे;\nबस काम की सूची में मेरा नाम भी लिख दीजिए।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—प्रोजेक्ट पूरा क्यों नहीं हुआ।\nअध्यापक ने पूछा, \"प्रोजेक्ट पूरा क्यों नहीं हुआ?\"\nछात्र ने जवाब दिया, \"सबने एक-दूसरे को जिम्मेदारी दी;\nकाम अकेला रह गया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—टीम लीडर कौन है।\nअध्यापक ने पूछा, \"टीम लीडर कौन है?\"\nछात्र ने जवाब दिया, \"जो काम बाँटे और,\nखुद भी करे।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—एक सदस्य काम नहीं कर रहा।\nअध्यापक ने पूछा, \"एक सदस्य काम नहीं कर रहा।\"\nछात्र ने जवाब दिया, \"पहले उससे बात करेंगे;\nनाम काटने से पहले कारण समझेंगे।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—प्रेज़ेंटेशन कौन देगा।\nअध्यापक ने पूछा, \"प्रेज़ेंटेशन कौन देगा?\"\nछात्र ने जवाब दिया, \"जिसे विषय समझ आया;\nमाइक से डरने वाले को भी मौका देंगे।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—टीम में बहस क्यों हुई।\nअध्यापक ने पूछा, \"टीम में बहस क्यों हुई?\"\nछात्र ने जवाब दिया, \"सबके विचार अलग थे;\nहमने मतदान से पहले सुनना सीख लिया।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—रिपोर्ट में गलती किसकी।\nअध्यापक ने पूछा, \"रिपोर्ट में गलती किसकी?\"\nछात्र ने जवाब दिया, \"टीम की;\nसुधार भी मिलकर करेंगे।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—काम समय पर कैसे होगा।\nअध्यापक ने पूछा, \"काम समय पर कैसे होगा?\"\nछात्र ने जवाब दिया, \"छोटे लक्ष्य,\nसाफ़ जिम्मेदारी और बीच में प्रगति की जाँच।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—सबसे अच्छा साथी कौन।\nअध्यापक ने पूछा, \"सबसे अच्छा साथी कौन?\"\nछात्र ने जवाब दिया, \"जो अपना हिस्सा पूरा करे और,\nदूसरे की मदद भी करे।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—टीम ने क्या सीखा।\nअध्यापक ने पूछा, \"टीम ने क्या सीखा?\"\nछात्र ने जवाब दिया, \"समूह में नाम ज़्यादा होते हैं;\nजिम्मेदारी भी बराबर होनी चाहिए।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—जीवन की सबसे बड़ी परीक्षा क्या है।\nअध्यापक ने पूछा, \"जीवन की सबसे बड़ी परीक्षा क्या है?\"\nछात्र ने जवाब दिया, \"सही समय पर,\nसही निर्णय लेना।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—असफलता से क्या सीखें।\nअध्यापक ने पूछा, \"असफलता से क्या सीखें?\"\nछात्र ने जवाब दिया, \"गलती कहाँ हुई,\nयह समझें; खुद को गलती न मान लें।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—सफलता का राज़ क्या है।\nअध्यापक ने पूछा, \"सफलता का राज़ क्या है?\"\nछात्र ने जवाब दिया, \"लगातार कोशिश और जरूरत,\nपड़ने पर तरीका बदलना।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—कौन-सा ज्ञान सबसे काम का है।\nअध्यापक ने पूछा, \"कौन-सा ज्ञान सबसे काम का है?\"\nछात्र ने जवाब दिया, \"जो दूसरों के साथ सम्मान,\nसे पेश आना सिखाए।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—समय क्यों कीमती है।\nअध्यापक ने पूछा, \"समय क्यों कीमती है?\"\nछात्र ने जवाब दिया, \"क्योंकि बीता हुआ पीरियड वापस नहीं आता,\nसर।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—अच्छा इंसान कैसे बनें।\nअध्यापक ने पूछा, \"अच्छा इंसान कैसे बनें?\"\nछात्र ने जवाब दिया, \"जब कोई देख न रहा हो,\nतब भी सही काम करके।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—डर लगे तो क्या करें।\nअध्यापक ने पूछा, \"डर लगे तो क्या करें?\"\nछात्र ने जवाब दिया, \"तैयारी करें,\nसवाल पूछें और मदद लेने में संकोच न करें।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—गलती छिपानी चाहिए।\nअध्यापक ने पूछा, \"गलती छिपानी चाहिए?\"\nछात्र ने जवाब दिया, \"नहीं सर,\nउसे मानकर सुधारना ही असली सीख है।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—सबसे बड़ा पुरस्कार क्या है।\nअध्यापक ने पूछा, \"सबसे बड़ा पुरस्कार क्या है?\"\nछात्र ने जवाब दिया, \"जब आपकी सीख किसी और,\nके काम आ जाए।\""],
  ["teacher-student", "कक्षा में मास्टर जी और बच्चों के बीच बात चली—आज का पाठ क्या याद रखोगे।\nअध्यापक ने पूछा, \"आज का पाठ क्या याद रखोगे?\"\nछात्र ने जवाब दिया, \"अंक ज़रूरी हैं,\nपर जिज्ञासा, ईमानदारी और दया भी उतनी ही ज़रूरी हैं।\""],
  ["pati-patni", "पति ने पूछा, “आज खाने में क्या नया है?”\nपत्नी बोली, “आज तुम्हारी पसंद का खाना है।”\nपति खुश होकर बैठ गया और बोला, “वाह!”\nपत्नी ने थाली रखी, “कल की पसंद आज फिर गरम की है।”"],
  ["pati-patni", "पत्नी ने पति से कहा, “घर का बजट बनाना सीखो।”\nपति ने कॉपी में आमदनी और खर्च लिखे।\nपत्नी ने पूछा, “बचत कहाँ है?”\nपति बोला, “वह अगले पन्ने पर है, अभी पन्ना खरीदने के पैसे नहीं बचे।”"],
  ["pati-patni", "पति ने नई घड़ी पहनकर पूछा, “कैसी लग रही है?”\nपत्नी बोली, “बहुत अच्छी, समय भी बताती है?”\nपति ने कहा, “बिल्कुल, हर घंटे मुझे याद दिलाती है कि मैं देर से हूँ।”\nपत्नी मुस्कराई, “तो आखिर घर में कोई तो सच बोलता है।”"],
  ["pati-patni", "पत्नी ने कहा, “आज से हम फिजूलखर्ची बंद करेंगे।”\nपति ने तुरंत टीवी का रिमोट रख दिया।\nपत्नी ने पूछा, “यह क्या कर रहे हो?”\nपति बोला, “पहले विज्ञापन देखना बंद, फिर खरीदारी अपने आप कम होगी।”"],
  ["pati-patni", "पति बाजार से दो किलो आम लेकर आया।\nपत्नी ने पूछा, “इतने महँगे आम क्यों खरीदे?”\nपति बोला, “दुकानदार ने कहा था ये खास हैं।”\nपत्नी ने एक आम काटकर कहा, “हाँ, खास तौर पर तुम्हारे बजट के खिलाफ हैं।”"],
  ["pati-patni", "पत्नी ने पति को पौधे में पानी डालने को कहा।\nपति ने पूरा मग खाली कर दिया।\nपत्नी बोली, “इतना पानी कौन डालता है?”\nपति ने जवाब दिया, “तुमने कहा था रिश्ते और पौधे, दोनों को भरपूर देखभाल चाहिए।”"],
  ["pati-patni", "पति ने पूछा, “मेरी शर्ट कहाँ रखी है?”\nपत्नी बोली, “अलमारी में, जहाँ रोज़ रखता हूँ।”\nपति ने कहा, “वहाँ तो दूसरी शर्ट है।”\nपत्नी बोली, “तुम्हारी याददाश्त भी अब कपड़ों की तरह बदलनी चाहिए।”"],
  ["pati-patni", "पत्नी ने ऑनलाइन किराने का सामान मँगाया।\nपति ने पूछा, “इतने सारे पैकेट किसलिए?”\nपत्नी बोली, “ऑफर में बचत हो रही थी।”\nपति ने बिल देखा और कहा, “बचत इतनी हुई कि अब महीने भर खर्च नहीं कर पाएँगे।”"],
  ["pati-patni", "पति ने कहा, “आज मैं तुम्हें बाहर खाना खिलाऊँगा।”\nपत्नी ने पूछा, “कहाँ चलेंगे?”\nपति बोला, “छत पर, मौसम अच्छा है।”\nपत्नी ने मुस्कराकर कहा, “ठीक है, पहले नीचे से रेस्टोरेंट का खाना मँगवा लो।”"],
  ["pati-patni", "पत्नी ने पति से पूछा, “तुम मेरी बात ध्यान से सुनते हो?”\nपति ने तुरंत कहा, “बिल्कुल, एक भी शब्द नहीं छोड़ता।”\nपत्नी बोली, “तो बताओ मैंने क्या कहा?”\nपति बोला, “मैंने कहा था कि तुम्हारी बात बहुत ध्यान से सुनता हूँ।”"],
  ["pati-patni", "पति ने घर में स्मार्ट स्पीकर लगाया।\nपत्नी ने कहा, “अब यह हमारी हर बात सुनेगा।”\nपति बोला, “कम से कम कोई तो मेरी भी सुनेगा।”\nस्पीकर ने जवाब दिया, “कृपया पहले अपना वॉल्यूम कम करें।”"],
  ["pati-patni", "पत्नी ने कहा, “आज रसोई की सफाई तुम्हारी जिम्मेदारी है।”\nपति ने झाड़ू उठाई और काम शुरू किया।\nथोड़ी देर बाद बोला, “काम पूरा हो गया।”\nपत्नी ने देखा, “तुमने सिर्फ झाड़ू की धूल साफ की है।”"],
  ["pati-patni", "पति ने पूछा, “तुम्हें सालगिरह पर क्या उपहार चाहिए?”\nपत्नी बोली, “कुछ ऐसा जो रोज़ काम आए।”\nपति ने खुशी से नया प्रेशर कुकर दिखाया।\nपत्नी ने कहा, “अगली बार ऐसा उपहार लेना जो रोज़ तुम्हें भी काम पर लगाए।”"],
  ["pati-patni", "पत्नी ने पति से कहा, “मेरे लिए चाय बना दो।”\nपति ने चाय बनाकर कप में रख दी।\nपत्नी ने एक घूँट लेकर पूछा, “चीनी कहाँ है?”\nपति बोला, “तुमने कहा था मीठी बातें कम करो, मैंने चाय से भी शुरुआत कर दी।”"],
  ["pati-patni", "पति ने मोबाइल पर फिटनेस ऐप खोला।\nपत्नी ने पूछा, “आज कितने कदम चले?”\nपति बोला, “ऐप ने दस हजार का लक्ष्य दिखाया है।”\nपत्नी ने कहा, “लक्ष्य दिखाना और पूरा करना, दोनों अलग-अलग व्यायाम हैं।”"],
  ["pati-patni", "पत्नी ने कहा, “इस बार छुट्टी में पहाड़ चलेंगे।”\nपति ने होटल और रास्ते की जानकारी निकाली।\nपत्नी ने पूछा, “टिकट बुक कर दिए?”\nपति बोला, “पहले ऑफिस से छुट्टी की मंजूरी आए, फिर कल्पना से बाहर निकलेंगे।”"],
  ["pati-patni", "पति ने फ्रिज खोलकर पूछा, “कुछ खाने को है?”\nपत्नी बोली, “कल की सब्ज़ी रखी है।”\nपति ने डिब्बा देखकर कहा, “यह तो खाली है।”\nपत्नी बोली, “तुमने ही कहा था घर में खाली डिब्बे मत छोड़ना, इसलिए धोकर रख दिया।”"],
  ["pati-patni", "पत्नी ने पति को नया तौलिया दिया।\nपति ने पूछा, “पुराना कहाँ गया?”\nपत्नी बोली, “वह अब सफाई का कपड़ा है।”\nपति ने कहा, “अच्छा हुआ, घर में मेरी पदोन्नति से पहले उसकी हो गई।”"],
  ["pati-patni", "पति ने पूछा, “आज तुम इतनी खुश क्यों हो?”\nपत्नी बोली, “आज मैंने सारे काम समय पर पूरे कर लिए।”\nपति ने कहा, “तो अब आराम करो।”\nपत्नी बोली, “पहले तुम्हें बताऊँ कि तुम्हारे हिस्से के काम कौन-से हैं।”"],
  ["pati-patni", "पत्नी ने कहा, “हम दोनों को थोड़ा कम मोबाइल चलाना चाहिए।”\nपति ने फोन उल्टा रख दिया।\nपत्नी ने पूछा, “बस इतना?”\nपति बोला, “हाँ, अब स्क्रीन नहीं दिखेगी, पर नोटिफिकेशन की आवाज़ से रिश्ता बना रहेगा।”"],
  ["pati-patni", "पति ने रसोई में जाकर पूछा, “कौन-सा डिब्बा नमक का है?”\nपत्नी ने कहा, “जिस पर नमक लिखा है।”\nपति ने डिब्बा उठाकर पढ़ा, “चीनी।”\nपत्नी बोली, “कम से कम आज तुम्हारी आँखों ने सही सवाल पूछा।”"],
  ["pati-patni", "पत्नी ने कहा, “आज घर में मेहमान आ रहे हैं, थोड़ा सज-सँवर जाओ।”\nपति ने नई कमीज़ पहन ली।\nपत्नी ने पूछा, “बाल क्यों नहीं बनाए?”\nपति बोला, “मेहमान घर देखने आ रहे हैं या मेरी पुरानी इमारत की मरम्मत?”"],
  ["pati-patni", "पति ने पूछा, “तुम्हें मेरी कौन-सी आदत सबसे अच्छी लगती है?”\nपत्नी ने कुछ देर सोचा।\nपति उत्सुक होकर पास आया।\nपत्नी बोली, “तुम्हारा सवाल पूछकर चुप हो जाना।”"],
  ["pati-patni", "पत्नी ने पति से कहा, “बिजली का बिल इस बार बहुत आया है।”\nपति ने पंखा बंद किया और खिड़की खोल दी।\nपत्नी बोली, “अब मच्छर आएँगे।”\nपति ने कहा, “बिल कम होगा तो मच्छरों के लिए कॉइल खरीद लेंगे।”"],
  ["pati-patni", "पति ने पूछा, “आज सब्ज़ी में स्वाद अलग क्यों है?”\nपत्नी बोली, “नई रेसिपी आज़माई है।”\nपति ने कहा, “कौन-सी?”\nपत्नी बोली, “जो सामान बचा था, उसे एक साथ मिला देने वाली।”"],
  ["pati-patni", "पत्नी ने पति को कहा, “मेरी तस्वीर अच्छी खींचना।”\nपति ने कैमरा सीधा किया और कई तस्वीरें लीं।\nपत्नी ने पूछा, “सबमें मैं कैसी लग रही हूँ?”\nपति बोला, “कैमरा तो ठीक है, अब तारीफ का फ़िल्टर लगाता हूँ।”"],
  ["pati-patni", "पति ने कहा, “मैंने आज घर के सारे बिल जमा कर दिए।”\nपत्नी ने पूछा, “पानी का बिल भी?”\nपति बोला, “हाँ, और रसीद भी संभाल ली।”\nपत्नी बोली, “शाबाश, अब बस पानी की टंकी भरवाना बाकी है।”"],
  ["pati-patni", "पत्नी ने पूछा, “तुम्हें घर में सबसे ज्यादा शांति कब मिलती है?”\nपति बोला, “जब सब सो जाते हैं।”\nपत्नी ने कहा, “और मुझे?”\nपति बोला, “जब तुम सोने से पहले कल की सूची नहीं बनातीं।”"],
  ["pati-patni", "पति ने नया वैक्यूम क्लीनर चलाया।\nपत्नी ने पूछा, “फर्श साफ हुआ?”\nपति बोला, “हाँ, धूल पूरी मशीन में चली गई।”\nपत्नी ने कहा, “अब मशीन साफ करो, फिर फर्श की बारी आएगी।”"],
  ["pati-patni", "पत्नी ने पति से कहा, “आज हम दोनों मिलकर खाना बनाएँगे।”\nपति ने पूछा, “मैं क्या करूँ?”\nपत्नी बोली, “तुम प्याज़ काटो।”\nपति ने चाकू उठाया और बोला, “लगता है आज भावनात्मक सहयोग भी देना पड़ेगा।”"],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—मैंने पूरा घर साफ़ कर दिया।\nएक ने पूछा, \"मैंने पूरा घर साफ़ कर दिया।\"\nदूसरे ने जवाब दिया, \"अच्छा, अब वह कमरा भी दिखाओ,\nजहाँ सब सामान छिपाया है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—झाड़ू कहाँ रखूँ।\nएक ने पूछा, \"झाड़ू कहाँ रखूँ?\"\nदूसरे ने जवाब दिया, \"वहीं जहाँ तुमने आख़िरी,\nबार जिम्मेदारी रखी थी।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—बर्तन भी धो दिए।\nएक ने पूछा, \"बर्तन भी धो दिए।\"\nदूसरे ने जवाब दिया, \"वाह, आज सिंक को,\nभी छुट्टी मिल गई।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—कपड़े तह कर दिए।\nएक ने पूछा, \"कपड़े तह कर दिए।\"\nदूसरे ने जवाब दिया, \"तह तो ठीक है,\nअब उन्हें अलमारी तक भी पहुँचा दो।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—धूल कहाँ से आती है।\nएक ने पूछा, \"धूल कहाँ से आती है?\"\nदूसरे ने जवाब दिया, \"तुम्हारे 'कल करूँगा' वाले,\nवादों के साथ।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—मैंने कूड़ा बाहर रख दिया।\nएक ने पूछा, \"मैंने कूड़ा बाहर रख दिया।\"\nदूसरे ने जवाब दिया, \"अच्छा, अब उसे बाहर,\nतक भी पहुँचा दो।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—सफ़ाई में कितना समय लगा।\nएक ने पूछा, \"सफ़ाई में कितना समय लगा?\"\nदूसरे ने जवाब दिया, \"तुम्हारी खोजी हुई चीज़ें ढूँढ़ने,\nमें आधा समय गया।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—मैंने सब व्यवस्थित कर दिया।\nएक ने पूछा, \"मैंने सब व्यवस्थित कर दिया।\"\nदूसरे ने जवाब दिया, \"हाँ, अब घर में चीज़ें,\nढूँढ़ने के लिए नक्शा चाहिए।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—क्या कुछ बाकी है।\nएक ने पूछा, \"क्या कुछ बाकी है?\"\nदूसरे ने जवाब दिया, \"बस रोज़ की तरह अपना,\nसामान अपनी जगह रखना।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—सफ़ाई का इनाम क्या है।\nएक ने पूछा, \"सफ़ाई का इनाम क्या है?\"\nदूसरे ने जवाब दिया, \"कल फिर से यही,\nकाम करने का अवसर।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—सालगिरह कब है।\nएक ने पूछा, \"सालगिरह कब है?\"\nदूसरे ने जवाब दिया, \"तुम्हारे कैलेंडर में है;\nमेरी याददाश्त पर भरोसा मत करो।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—इस बार क्या उपहार दूँ।\nएक ने पूछा, \"इस बार क्या उपहार दूँ?\"\nदूसरे ने जवाब दिया, \"ऐसा जो मुझे पसंद हो,\nऔर जिसकी रसीद तुम संभाल सको।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—मैं तारीख़ भूल गया था।\nएक ने पूछा, \"मैं तारीख़ भूल गया था।\"\nदूसरे ने जवाब दिया, \"कोई बात नहीं,\nअब हर साल याद दिलाने के लिए अलार्म है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—शादी के बाद सबसे बड़ा बदलाव।\nएक ने पूछा, \"शादी के बाद सबसे बड़ा बदलाव?\"\nदूसरे ने जवाब दिया, \"तुम्हारी घड़ी अब मेरे,\nकार्यक्रम से चलती है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—हम पहली बार कहाँ मिले थे।\nएक ने पूछा, \"हम पहली बार कहाँ मिले थे?\"\nदूसरे ने जवाब दिया, \"तुम्हें याद नहीं? अच्छा है,\nकहानी फिर से सुनाती हूँ।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—आज खास दिन है क्या।\nएक ने पूछा, \"आज खास दिन है क्या?\"\nदूसरे ने जवाब दिया, \"हाँ, आज तुमने बिना पूछे,\nसही तारीख़ याद रखी।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—उपहार पसंद आया।\nएक ने पूछा, \"उपहार पसंद आया?\"\nदूसरे ने जवाब दिया, \"बहुत, खासकर वह हिस्सा जिसमें,\nतुमने सोचने में समय लगाया।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—केक कौन लाएगा।\nएक ने पूछा, \"केक कौन लाएगा?\"\nदूसरे ने जवाब दिया, \"जो तारीख़ याद रखेगा,\nवही केक भी लाएगा।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—तस्वीरें देखोगे।\nएक ने पूछा, \"तस्वीरें देखोगे?\"\nदूसरे ने जवाब दिया, \"हाँ, पर पहले यह बताओ कि हर फोटो,\nमें मेरी आँखें बंद क्यों हैं।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—सालगिरह का वादा क्या है।\nएक ने पूछा, \"सालगिरह का वादा क्या है?\"\nदूसरे ने जवाब दिया, \"तारीख़ याद रखना और बाकी,\nदिनों में भी साथ निभाना।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—मेरी बात सुन रहे हो।\nएक ने पूछा, \"मेरी बात सुन रहे हो?\"\nदूसरे ने जवाब दिया, \"हाँ, फोन भी सुन रहा है;\nवह अभी नोटिफिकेशन बंद कर रहा है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—तुम्हारा ध्यान कहाँ है।\nएक ने पूछा, \"तुम्हारा ध्यान कहाँ है?\"\nदूसरे ने जवाब दिया, \"यहीं है,\nबस मोबाइल बीच में अपनी राय दे रहा है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—मैंने क्या कहा था।\nएक ने पूछा, \"मैंने क्या कहा था?\"\nदूसरे ने जवाब दिया, \"तुमने कहा था फोन रखो;\nअब मैं पूरी तरह उपस्थित हूँ।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—कितनी देर से स्क्रीन देख रहे हो।\nएक ने पूछा, \"कितनी देर से स्क्रीन देख रहे हो?\"\nदूसरे ने जवाब दिया, \"इतनी देर कि फोन ने भी,\nपूछा घर में कोई और है?\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—चलो साथ टहलने चलते हैं।\nएक ने पूछा, \"चलो साथ टहलने चलते हैं।\"\nदूसरे ने जवाब दिया, \"अच्छा विचार है;\nमोबाइल को भी घर पर टहलने दो।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—तुम्हें मेरी बात याद है।\nएक ने पूछा, \"तुम्हें मेरी बात याद है?\"\nदूसरे ने जवाब दिया, \"हाँ, इसलिए अब जवाब देने से,\nपहले फोन नीचे रख दिया।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—आज फोन कम चलाओगे।\nएक ने पूछा, \"आज फोन कम चलाओगे?\"\nदूसरे ने जवाब दिया, \"बिल्कुल,\nअब केवल समय देखने के लिए उठाऊँगा।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—तुम हँस क्यों रहे हो।\nएक ने पूछा, \"तुम हँस क्यों रहे हो?\"\nदूसरे ने जवाब दिया, \"तुम्हारा संदेश पढ़ा;\nफोन ने पहली बार उपयोगी काम किया।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—क्या सुन रहे हो।\nएक ने पूछा, \"क्या सुन रहे हो?\"\nदूसरे ने जवाब दिया, \"तुम्हारी बात;\nआज ईयरफ़ोन भी छुट्टी पर हैं।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—सबसे अच्छी बातचीत कब होती है।\nएक ने पूछा, \"सबसे अच्छी बातचीत कब होती है?\"\nदूसरे ने जवाब दिया, \"जब दोनों स्क्रीन से नहीं,\nएक-दूसरे से नज़र मिलाते हैं।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—रविवार को क्या योजना है।\nएक ने पूछा, \"रविवार को क्या योजना है?\"\nदूसरे ने जवाब दिया, \"आराम करूँगा;\nघर के कामों ने मेरी योजना पढ़ ली है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—नाश्ता बिस्तर पर चाहिए।\nएक ने पूछा, \"नाश्ता बिस्तर पर चाहिए?\"\nदूसरे ने जवाब दिया, \"हाँ, पर बिस्तर को,\nभी साफ़ रखना पड़ेगा।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—आज देर तक सोऊँगा।\nएक ने पूछा, \"आज देर तक सोऊँगा।\"\nदूसरे ने जवाब दिया, \"ठीक है,\nपर दूधवाला तुम्हारी अनुमति नहीं लेता।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—फिल्म देखेंगे।\nएक ने पूछा, \"फिल्म देखेंगे?\"\nदूसरे ने जवाब दिया, \"हाँ, बस तुम हर पाँच मिनट,\nमें कहानी का विश्लेषण मत करना।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—मैंने छुट्टी ली है।\nएक ने पूछा, \"मैंने छुट्टी ली है।\"\nदूसरे ने जवाब दिया, \"अच्छा, अब घर की सूची ने,\nभी तुम्हें छुट्टी पर नहीं माना।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—आज बाहर नहीं जाएँगे।\nएक ने पूछा, \"आज बाहर नहीं जाएँगे?\"\nदूसरे ने जवाब दिया, \"नहीं, आज घर ही,\nहमारा पर्यटन स्थल है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—आराम का मतलब क्या है।\nएक ने पूछा, \"आराम का मतलब क्या है?\"\nदूसरे ने जवाब दिया, \"काम बाँटना और,\nफिर सचमुच बैठना।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—मैंने अलार्म बंद कर दिया।\nएक ने पूछा, \"मैंने अलार्म बंद कर दिया।\"\nदूसरे ने जवाब दिया, \"बहुत बढ़िया,\nअब घर के बाकी अलार्म सुनो।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—दोपहर में क्या करेंगे।\nएक ने पूछा, \"दोपहर में क्या करेंगे?\"\nदूसरे ने जवाब दिया, \"जो सुबह तय किया था,\nउसे शाम तक टालेंगे।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—रविवार जल्दी क्यों खत्म होता है।\nएक ने पूछा, \"रविवार जल्दी क्यों खत्म होता है?\"\nदूसरे ने जवाब दिया, \"क्योंकि सोमवार कैलेंडर में पहले से,\nइंतज़ार कर रहा होता है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—पौधे को पानी दिया।\nएक ने पूछा, \"पौधे को पानी दिया?\"\nदूसरे ने जवाब दिया, \"हाँ, पर तुम्हारी तरह उसे भी,\nरोज़ याद दिलाना पड़ता है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—पौधा मुरझा क्यों रहा है।\nएक ने पूछा, \"पौधा मुरझा क्यों रहा है?\"\nदूसरे ने जवाब दिया, \"शायद उसे भी घर के,\nबजट की चिंता हो गई।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—नया गमला कैसा है।\nएक ने पूछा, \"नया गमला कैसा है?\"\nदूसरे ने जवाब दिया, \"सुंदर है,\nबस अब पौधे को उसमें रहने की अनुमति दो।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—कितने पौधे और लाएँ।\nएक ने पूछा, \"कितने पौधे और लाएँ?\"\nदूसरे ने जवाब दिया, \"पहले इनकी देखभाल की,\nजिम्मेदारी बाँट लें।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—पौधे से बात करते हो।\nएक ने पूछा, \"पौधे से बात करते हो?\"\nदूसरे ने जवाब दिया, \"हाँ, वह कम से कम मेरी,\nबात बीच में नहीं काटता।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—पत्ते पीले क्यों हैं।\nएक ने पूछा, \"पत्ते पीले क्यों हैं?\"\nदूसरे ने जवाब दिया, \"उन्हें धूप चाहिए;\nतुम्हारी तरह सिर्फ़ तारीफ़ नहीं।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—बालकनी सुंदर लग रही है।\nएक ने पूछा, \"बालकनी सुंदर लग रही है?\"\nदूसरे ने जवाब दिया, \"हाँ, अब वहाँ कपड़े सुखाने,\nकी जगह भी सोच लो।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—पौधा बड़ा होगा।\nएक ने पूछा, \"पौधा बड़ा होगा?\"\nदूसरे ने जवाब दिया, \"अगर पानी और धूप मिले;\nवादों से नहीं।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—कौन-सा पौधा पसंद है।\nएक ने पूछा, \"कौन-सा पौधा पसंद है?\"\nदूसरे ने जवाब दिया, \"जो जीवित रहे और तुम्हारे,\nशेड्यूल से तालमेल बिठा ले।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—घर में हरियाली कैसे बढ़े।\nएक ने पूछा, \"घर में हरियाली कैसे बढ़े?\"\nदूसरे ने जवाब दिया, \"पौधे लगाकर और जिम्मेदारी,\nको रोज़ पानी देकर।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—बाहर खाना कहाँ खाएँ।\nएक ने पूछा, \"बाहर खाना कहाँ खाएँ?\"\nदूसरे ने जवाब दिया, \"जहाँ खाना अच्छा हो और,\nबिल देखकर भूख न भागे।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—मेन्यू में क्या चुनोगे।\nएक ने पूछा, \"मेन्यू में क्या चुनोगे?\"\nदूसरे ने जवाब दिया, \"पहले तुम्हें चुनने दूँगी;\nफिर तुम्हारे विकल्पों पर चर्चा होगी।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—आज मिठाई भी लें।\nएक ने पूछा, \"आज मिठाई भी लें?\"\nदूसरे ने जवाब दिया, \"हाँ, पर बिल आने से,\nपहले उसे देख लेना।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—खाना कैसा है।\nएक ने पूछा, \"खाना कैसा है?\"\nदूसरे ने जवाब दिया, \"अच्छा है;\nतुम्हारे फोन से ज़्यादा गर्म है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—वेटर ने पूछा और कुछ चाहिए।\nएक ने पूछा, \"वेटर ने पूछा और कुछ चाहिए?\"\nदूसरे ने जवाब दिया, \"हाँ, घर लौटकर बर्तन,\nन धोने की गारंटी।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—तुमने मेरा ऑर्डर खा लिया।\nएक ने पूछा, \"तुमने मेरा ऑर्डर खा लिया?\"\nदूसरे ने जवाब दिया, \"सिर्फ़ स्वाद चखा;\nप्लेट ने बाकी कहानी बताई।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—कहाँ बैठें।\nएक ने पूछा, \"कहाँ बैठें?\"\nदूसरे ने जवाब दिया, \"जहाँ स्पीकर कम और,\nबातचीत ज़्यादा सुनाई दे।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—बिल बाँटें।\nएक ने पूछा, \"बिल बाँटें?\"\nदूसरे ने जवाब दिया, \"तुमने मिठाई चुनी थी,\nयाद है?\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—अगली बार घर पर खाना।\nएक ने पूछा, \"अगली बार घर पर खाना?\"\nदूसरे ने जवाब दिया, \"हाँ, लेकिन आज की,\nतरह बर्तन तुम धोना।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—डिनर की सबसे अच्छी बात।\nएक ने पूछा, \"डिनर की सबसे अच्छी बात?\"\nदूसरे ने जवाब दिया, \"साथ बैठना;\nमेन्यू तो हर जगह मिल जाता है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—मैं नाराज़ क्यों हूँ, बताओ।\nएक ने पूछा, \"मैं नाराज़ क्यों हूँ, बताओ।\"\nदूसरे ने जवाब दिया, \"अगर बता दिया तो सही जवाब देना पड़ेगा;\nपहले सुन लेता हूँ।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—तुम्हें कुछ समझ नहीं आता।\nएक ने पूछा, \"तुम्हें कुछ समझ नहीं आता?\"\nदूसरे ने जवाब दिया, \"आता है,\nबस कभी-कभी तुम्हारी चुप्पी का अनुवाद चाहिए।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—मैंने क्या गलत किया।\nएक ने पूछा, \"मैंने क्या गलत किया?\"\nदूसरे ने जवाब दिया, \"पहले यह मत मानो कि सवाल ही गलत है;\nबात पूरी सुनो।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—तुम हमेशा देर करते हो।\nएक ने पूछा, \"तुम हमेशा देर करते हो।\"\nदूसरे ने जवाब दिया, \"आज जल्दी आया हूँ;\nअब इस उपलब्धि को इतिहास में दर्ज करो।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—तुमने वादा किया था।\nएक ने पूछा, \"तुमने वादा किया था।\"\nदूसरे ने जवाब दिया, \"याद है;\nअब बहाना नहीं, काम करके दिखाऊँगा।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—मुझे थोड़ा समय चाहिए।\nएक ने पूछा, \"मुझे थोड़ा समय चाहिए।\"\nदूसरे ने जवाब दिया, \"ठीक है,\nमैं सुनूँगा; समाधान से पहले समझना ज़रूरी है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—क्या हम बात कर सकते हैं।\nएक ने पूछा, \"क्या हम बात कर सकते हैं?\"\nदूसरे ने जवाब दिया, \"हाँ, फोन रख दिया;\nअब पूरा ध्यान तुम्हारा है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—तुम्हें मेरी पसंद याद है।\nएक ने पूछा, \"तुम्हें मेरी पसंद याद है?\"\nदूसरे ने जवाब दिया, \"हाँ, और आज उसी हिसाब,\nसे चाय बनाई है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—अब नाराज़गी कम हुई।\nएक ने पूछा, \"अब नाराज़गी कम हुई?\"\nदूसरे ने जवाब दिया, \"थोड़ी; बाकी तुम्हारे अगले,\nकाम पर निर्भर है।\""],
  ["pati-patni", "घर में पति-पत्नी की बातचीत इसी बात पर अटक गई—झगड़ा कैसे खत्म हुआ।\nएक ने पूछा, \"झगड़ा कैसे खत्म हुआ?\"\nदूसरे ने जवाब दिया, \"दोनों ने सही साबित होने से,\nपहले एक-दूसरे को समझना चुना।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—पृथ्वी गोल क्यों है।\nएक ने पूछा, \"पृथ्वी गोल क्यों है?\"\nदूसरे ने जवाब दिया, \"ताकि कोई कोना पकड़कर होमवर्क से भाग न सके,\nसर।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—सूरज कहाँ से निकलता है।\nएक ने पूछा, \"सूरज कहाँ से निकलता है?\"\nदूसरे ने जवाब दिया, \"पूर्व से,\nसर; लेकिन मेरा होमवर्क हमेशा देर से निकलता है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—पानी का सूत्र क्या है।\nएक ने पूछा, \"पानी का सूत्र क्या है?\"\nदूसरे ने जवाब दिया, \"एच टू ओ,\nसर; और मेरी कॉपी में अभी भी 'ओह' लिखा है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—किताब क्यों पढ़नी चाहिए।\nएक ने पूछा, \"किताब क्यों पढ़नी चाहिए?\"\nदूसरे ने जवाब दिया, \"ताकि सवाल पूछे जाने पर चेहरा,\nकम और उत्तर ज़्यादा खुले।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—गुरुत्वाकर्षण क्या है।\nएक ने पूछा, \"गुरुत्वाकर्षण क्या है?\"\nदूसरे ने जवाब दिया, \"जो मेरी कॉपी को बैग में नीचे और मेरे,\nअंक को सूची में नीचे रखता है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—कक्षा में ध्यान क्यों नहीं था।\nएक ने पूछा, \"कक्षा में ध्यान क्यों नहीं था?\"\nदूसरे ने जवाब दिया, \"ध्यान आया था;\nघंटी सुनकर वापस चला गया।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—सबसे तेज़ चीज़ क्या है।\nएक ने पूछा, \"सबसे तेज़ चीज़ क्या है?\"\nदूसरे ने जवाब दिया, \"छुट्टी की घंटी,\nसर; उसके बाद पूरी कक्षा दौड़ती है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—कौन-सा ग्रह सबसे बड़ा है।\nएक ने पूछा, \"कौन-सा ग्रह सबसे बड़ा है?\"\nदूसरे ने जवाब दिया, \"बृहस्पति,\nसर; पर परीक्षा का सवाल उससे भी बड़ा लगा।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—पेड़ हमें क्या देते हैं।\nएक ने पूछा, \"पेड़ हमें क्या देते हैं?\"\nदूसरे ने जवाब दिया, \"छाया, फल और होमवर्क में लिखने,\nके लिए तीन अच्छे कारण।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—तुमने उत्तर क्यों नहीं लिखा।\nएक ने पूछा, \"तुमने उत्तर क्यों नहीं लिखा?\"\nदूसरे ने जवाब दिया, \"सवाल इतना अच्छा था कि मैं,\nउसे पढ़कर ही प्रभावित हो गया।\""],
  ["pappu-chintu", "पप्पू ने चिंटू से पूछा, \"तू परीक्षा में इतना शांत कैसे रहता है?\"\nचिंटू बोला, \"मैंने सवाल पढ़ना छोड़ दिया है।\"\nपप्पू घबरा गया, \"फिर जवाब कैसे लिखता है?\"\nचिंटू बोला, \"जो याद हो वही; कम-से-कम आत्मविश्वास तो पूरा रहता है।\""],
  ["pappu-chintu", "चिंटू ने पूछा, \"पप्पू, तेरी घड़ी पाँच मिनट आगे क्यों है?\"\nपप्पू बोला, \"ताकि देर होने पर लगे कि मैं समय से पहले हूँ।\"\nचिंटू ने कहा, \"कामयाब हुआ?\"\nपप्पू बोला, \"नहीं, अब घरवाले पाँच मिनट पहले डाँटते हैं।\""],
  ["pappu-chintu", "पप्पू बोला, \"मैंने आज से बचत शुरू कर दी।\"\nचिंटू ने पूछा, \"कितनी बचाई?\"\nपप्पू बोला, \"दुकान तक गया ही नहीं।\"\nचिंटू ने कहा, \"अच्छा है, अब उधार की सूची भी छोटी होगी।\""],
  ["pappu-chintu", "चिंटू ने पप्पू से पूछा, \"तूने अलार्म कितने बजे का लगाया?\"\nपप्पू बोला, \"सुबह छह बजे का।\"\nचिंटू ने पूछा, \"उठा?\"\nपप्पू बोला, \"हाँ, अलार्म बंद करने के लिए; फिर नींद को वापस बुला लिया।\""],
  ["pappu-chintu", "पप्पू ने कहा, \"मैंने पढ़ाई का टाइमटेबल बना लिया है।\"\nचिंटू ने पूछा, \"कब से शुरू करेगा?\"\nपप्पू बोला, \"पहले टाइमटेबल को सुंदर लिखूँगा।\"\nचिंटू ने कहा, \"तेरी तैयारी से ज़्यादा तो कागज़ तैयार है।\""],
  ["pappu-chintu", "चिंटू ने पूछा, \"पप्पू, तूने विज्ञान का प्रयोग किया?\"\nपप्पू बोला, \"हाँ, पानी में नमक डाला।\"\nचिंटू ने कहा, \"नतीजा क्या निकला?\"\nपप्पू बोला, \"माँ ने कहा, अब रसोई में प्रयोग बंद कर।\""],
  [ "pappu-chintu", "चिंटू ने पूछा, “पप्पू, परीक्षा में सबसे कठिन क्या था?”\nपप्पू बोला, “नाम लिखना।”\nचिंटू ने कहा, “वह तो आसान है।”\nपप्पू बोला, “रोल नंबर याद था, पर अपनी लिखावट पहचान नहीं पाया।”" ],
  [ "pappu-chintu", "पप्पू ने चिंटू से पूछा, “तूने विज्ञान का मॉडल बनाया?”\nचिंटू बोला, “हाँ, ज्वालामुखी।”\nपप्पू ने पूछा, “फटा?”\nचिंटू बोला, “नहीं, गोंद सूख गया; अब यह शांत पर्वत है।”" ],
  [ "pappu-chintu", "चिंटू ने कहा, “पप्पू, पढ़ाई का टाइमटेबल बना?”\nपप्पू बोला, “हाँ, सुबह गणित, दोपहर विज्ञान।”\nचिंटू ने पूछा, “शाम को?”\nपप्पू बोला, “शाम को टाइमटेबल देखकर अगली सुबह की तैयारी।”" ],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—तैयारी कैसी है।\nएक ने पूछा, \"तैयारी कैसी है?\"\nदूसरे ने जवाब दिया, \"चिंटू, तैयारी अच्छी है;\nअब बस पढ़ना शुरू करना है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—बस कब आएगी।\nएक ने पूछा, \"बस कब आएगी?\"\nदूसरे ने जवाब दिया, \"जब हम दूसरी बस,\nपकड़ने का फैसला करेंगे।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—टिकट लिया।\nएक ने पूछा, \"टिकट लिया?\"\nदूसरे ने जवाब दिया, \"हाँ, जेब में रखा;\nअब जेब से पूछ रहा हूँ कहाँ रखा।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—सीट मिलेगी।\nएक ने पूछा, \"सीट मिलेगी?\"\nदूसरे ने जवाब दिया, \"मिलेगी,\nअगर हम पहले बस में चढ़ने की योजना बना लें।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—बस इतनी भरी क्यों है।\nएक ने पूछा, \"बस इतनी भरी क्यों है?\"\nदूसरे ने जवाब दिया, \"सबको एक ही समय पर,\nघर जाने का विचार आया।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—कंडक्टर ने क्या कहा।\nएक ने पूछा, \"कंडक्टर ने क्या कहा?\"\nदूसरे ने जवाब दिया, \"कहा पीछे बढ़ो;\nपीछे वालों ने कहा हम पहले से पीछे हैं।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—रास्ता कितना दूर है।\nएक ने पूछा, \"रास्ता कितना दूर है?\"\nदूसरे ने जवाब दिया, \"इतना कि हमारी बातचीत में,\nदो नए विषय आ जाएँ।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—बस छूट गई तो।\nएक ने पूछा, \"बस छूट गई तो?\"\nदूसरे ने जवाब दिया, \"चलेंगे;\nआज कदमों की उपस्थिति भी लग जाएगी।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—खिड़की खुली है।\nएक ने पूछा, \"खिड़की खुली है?\"\nदूसरे ने जवाब दिया, \"हाँ, हवा आ रही है;\nअब बालों की अलग योजना बनेगी।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—किराया किसने दिया।\nएक ने पूछा, \"किराया किसने दिया?\"\nदूसरे ने जवाब दिया, \"मैंने; चिंटू ने कहा दोस्ती,\nमें हिसाब बराबर होना चाहिए।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—बस यात्रा का सबक।\nएक ने पूछा, \"बस यात्रा का सबक?\"\nदूसरे ने जवाब दिया, \"समय से निकलो और सीट को,\nअपना स्थायी पता मत समझो।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—मॉडल किस चीज़ का है।\nएक ने पूछा, \"मॉडल किस चीज़ का है?\"\nदूसरे ने जवाब दिया, \"सौर ऊर्जा का;\nधूप मिले तो चलेगा, वरना प्रस्तुति से।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—तार क्यों उलझे हैं।\nएक ने पूछा, \"तार क्यों उलझे हैं?\"\nदूसरे ने जवाब दिया, \"ऊर्जा का प्रवाह जटिल है,\nसर; मॉडल भी उसे समझ रहा है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—यह बल्ब क्यों नहीं जलता।\nएक ने पूछा, \"यह बल्ब क्यों नहीं जलता?\"\nदूसरे ने जवाब दिया, \"यह ऊर्जा बचा रहा है;\nपर्यावरण के प्रति जागरूक है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—प्रोजेक्ट किसने बनाया।\nएक ने पूछा, \"प्रोजेक्ट किसने बनाया?\"\nदूसरे ने जवाब दिया, \"चिंटू ने विचार दिया,\nमैंने गोंद लगाया; टीमवर्क बराबर है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—मॉडल गिर गया तो।\nएक ने पूछा, \"मॉडल गिर गया तो?\"\nदूसरे ने जवाब दिया, \"गुरुत्वाकर्षण का लाइव,\nप्रदर्शन हो जाएगा।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—बैटरी कहाँ है।\nएक ने पूछा, \"बैटरी कहाँ है?\"\nदूसरे ने जवाब दिया, \"घर पर चार्ज हो रही है;\nअभी कल्पना से चल रही है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—प्रदर्शनी में क्या दिखाओगे।\nएक ने पूछा, \"प्रदर्शनी में क्या दिखाओगे?\"\nदूसरे ने जवाब दिया, \"कि छोटा विचार भी बड़ा,\nसवाल पूछ सकता है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—कितना खर्च हुआ।\nएक ने पूछा, \"कितना खर्च हुआ?\"\nदूसरे ने जवाब दिया, \"इतना कि अब मॉडल को,\nघर में किराया देना होगा।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—प्रयोग सफल हुआ।\nएक ने पूछा, \"प्रयोग सफल हुआ?\"\nदूसरे ने जवाब दिया, \"कम से कम हमने,\nगलती को पहचान लिया।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—अगली बार क्या बदलोगे।\nएक ने पूछा, \"अगली बार क्या बदलोगे?\"\nदूसरे ने जवाब दिया, \"पहले निर्देश पढ़ूँगा,\nफिर मॉडल को सजाऊँगा।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—नई डिश कैसी है।\nएक ने पूछा, \"नई डिश कैसी है?\"\nदूसरे ने जवाब दिया, \"स्वाद अच्छा है;\nनाम पढ़ने में ही आधा भोजन ठंडा हो गया।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—पैसे कितने हैं।\nएक ने पूछा, \"पैसे कितने हैं?\"\nदूसरे ने जवाब दिया, \"इतने कि मेन्यू देख सकते हैं,\nपर ऑर्डर सोचकर देंगे।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—यह इतना तीखा क्यों है।\nएक ने पूछा, \"यह इतना तीखा क्यों है?\"\nदूसरे ने जवाब दिया, \"शायद मिर्च ने आज अपना,\nलक्ष्य तय कर लिया।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—चिंटू, थोड़ा चखोगे।\nएक ने पूछा, \"चिंटू, थोड़ा चखोगे?\"\nदूसरे ने जवाब दिया, \"हाँ, पर पहले पानी,\nका गिलास पास रखो।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—बिल किसका होगा।\nएक ने पूछा, \"बिल किसका होगा?\"\nदूसरे ने जवाब दिया, \"जिसने सबसे महँगी डिश चुनी;\nदोस्ती में भी बजट होता है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—ऑर्डर गलत आया।\nएक ने पूछा, \"ऑर्डर गलत आया।\"\nदूसरे ने जवाब दिया, \"कोई बात नहीं,\nनई डिश का शोध शुरू करते हैं।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—मिठाई लें।\nएक ने पूछा, \"मिठाई लें?\"\nदूसरे ने जवाब दिया, \"हाँ, पर आधी;\nबाकी अगली परीक्षा के बाद।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—खाना जल्दी क्यों खत्म हुआ।\nएक ने पूछा, \"खाना जल्दी क्यों खत्म हुआ?\"\nदूसरे ने जवाब दिया, \"क्योंकि बातचीत लंबी थी,\nऔर भूख उससे तेज़।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—वेटर ने पूछा सब ठीक।\nएक ने पूछा, \"वेटर ने पूछा सब ठीक?\"\nदूसरे ने जवाब दिया, \"हमने कहा हाँ,\nबस जेब को थोड़ा आराम चाहिए।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—कैंटीन का नियम क्या।\nएक ने पूछा, \"कैंटीन का नियम क्या?\"\nदूसरे ने जवाब दिया, \"पहले कीमत देखो,\nफिर स्वाद की कल्पना करो।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—समय सबसे कीमती क्यों है।\nएक ने पूछा, \"समय सबसे कीमती क्यों है?\"\nदूसरे ने जवाब दिया, \"क्योंकि देर से आने पर,\nअध्यापक उसे वापस नहीं करते।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—एक मिनट में क्या कर सकते हो।\nएक ने पूछा, \"एक मिनट में क्या कर सकते हो?\"\nदूसरे ने जवाब दिया, \"होमवर्क शुरू कर सकता हूँ;\nपूरा करने का वादा नहीं।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—घड़ी क्यों पहनते हो।\nएक ने पूछा, \"घड़ी क्यों पहनते हो?\"\nदूसरे ने जवाब दिया, \"ताकि देर होने का सही,\nसमय पता चल सके।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—कल का काम आज क्यों करें।\nएक ने पूछा, \"कल का काम आज क्यों करें?\"\nदूसरे ने जवाब दिया, \"ताकि आज का काम कल,\nपर डालने की जगह बचे।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—समय कैसे बचाओगे।\nएक ने पूछा, \"समय कैसे बचाओगे?\"\nदूसरे ने जवाब दिया, \"मोबाइल पर टाइम देखने के,\nबाद उसे बंद करके।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—तुम हमेशा देर से क्यों आते हो।\nएक ने पूछा, \"तुम हमेशा देर से क्यों आते हो?\"\nदूसरे ने जवाब दिया, \"मैं समय पर निकलता हूँ;\nरास्ते में समय मुझसे आगे निकल जाता है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—घंटी कब बजेगी।\nएक ने पूछा, \"घंटी कब बजेगी?\"\nदूसरे ने जवाब दिया, \"घड़ी देख रहा हूँ;\nघंटी को भी समय का महत्व समझना चाहिए।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—पढ़ाई का समय कब है।\nएक ने पूछा, \"पढ़ाई का समय कब है?\"\nदूसरे ने जवाब दिया, \"जब टाइमटेबल और मैं एक,\nही कमरे में हों।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—समय लौट सकता है।\nएक ने पूछा, \"समय लौट सकता है?\"\nदूसरे ने जवाब दिया, \"नहीं सर,\nइसलिए अब से देर नहीं करूँगा; कल से पक्का।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—सबसे अच्छा समय कौन-सा।\nएक ने पूछा, \"सबसे अच्छा समय कौन-सा?\"\nदूसरे ने जवाब दिया, \"जब काम पूरा हो और,\nछुट्टी की घंटी पास हो।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—ऐप क्या काम करता है।\nएक ने पूछा, \"ऐप क्या काम करता है?\"\nदूसरे ने जवाब दिया, \"काम याद दिलाता है;\nमैं उसे बाद में याद करने का वादा करता हूँ।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—पासवर्ड क्या रखा।\nएक ने पूछा, \"पासवर्ड क्या रखा?\"\nदूसरे ने जवाब दिया, \"ऐसा कि ऐप भी सोचता,\nरहे मैं कौन हूँ।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—फोन धीमा क्यों है।\nएक ने पूछा, \"फोन धीमा क्यों है?\"\nदूसरे ने जवाब दिया, \"मेरे सारे ऐप एक साथ,\nछुट्टी से लौट आए हैं।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—नोटिफिकेशन बंद किए।\nएक ने पूछा, \"नोटिफिकेशन बंद किए?\"\nदूसरे ने जवाब दिया, \"हाँ, अब सिर्फ़ चिंटू,\nकी आवाज़ आती है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—बैटरी कितनी बची है।\nएक ने पूछा, \"बैटरी कितनी बची है?\"\nदूसरे ने जवाब दिया, \"इतनी कि फोन को घर,\nपहुँचने की उम्मीद है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—ऐप अपडेट क्यों नहीं किया।\nएक ने पूछा, \"ऐप अपडेट क्यों नहीं किया?\"\nदूसरे ने जवाब दिया, \"पुराना संस्करण मुझे पहचानता है;\nनया अभी परिचय माँग रहा है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—डेटा कहाँ गया।\nएक ने पूछा, \"डेटा कहाँ गया?\"\nदूसरे ने जवाब दिया, \"वीडियो देखते-देखते;\nअब यादें ही बची हैं।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—फोन सुरक्षित है।\nएक ने पूछा, \"फोन सुरक्षित है?\"\nदूसरे ने जवाब दिया, \"हाँ, पासवर्ड रखा है;\nबस मुझे याद नहीं।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—ऑनलाइन पढ़ाई करोगे।\nएक ने पूछा, \"ऑनलाइन पढ़ाई करोगे?\"\nदूसरे ने जवाब दिया, \"लिंक खोलूँगा;\nध्यान भी साथ में जोड़ना पड़ेगा।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—सबसे उपयोगी ऐप कौन-सा।\nएक ने पूछा, \"सबसे उपयोगी ऐप कौन-सा?\"\nदूसरे ने जवाब दिया, \"वह जो मुझे फोन नीचे,\nरखने की याद दिलाए।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—छुट्टी में कहाँ चलें।\nएक ने पूछा, \"छुट्टी में कहाँ चलें?\"\nदूसरे ने जवाब दिया, \"जहाँ होमवर्क साथ न आए;\nलेकिन किताब को बुरा न लगे।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—पहाड़ या समुद्र।\nएक ने पूछा, \"पहाड़ या समुद्र?\"\nदूसरे ने जवाब दिया, \"पहाड़, चिंटू;\nवहाँ नेटवर्क कम होगा और बहाने भी।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—योजना किसने बनाई।\nएक ने पूछा, \"योजना किसने बनाई?\"\nदूसरे ने जवाब दिया, \"मैंने; बजट ने उसे,\nपढ़कर कुछ बदलाव सुझाए।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—टिकट बुक किया।\nएक ने पूछा, \"टिकट बुक किया?\"\nदूसरे ने जवाब दिया, \"हाँ, पहले तारीख़ तय की;\nअब छुट्टी मंज़ूर करवानी है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—बैग में क्या रखोगे।\nएक ने पूछा, \"बैग में क्या रखोगे?\"\nदूसरे ने जवाब दिया, \"ज़रूरी सामान;\nऔर तुम्हारे तीन अतिरिक्त चार्जर नहीं।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—कितने दिन की छुट्टी।\nएक ने पूछा, \"कितने दिन की छुट्टी?\"\nदूसरे ने जवाब दिया, \"जितने दिन स्कूल कैलेंडर और,\nघर वाले अनुमति दें।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—यात्रा में क्या देखोगे।\nएक ने पूछा, \"यात्रा में क्या देखोगे?\"\nदूसरे ने जवाब दिया, \"नज़ारे,\nस्थानीय खाना और वापसी का समय।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—खर्च कैसे बाँटेंगे।\nएक ने पूछा, \"खर्च कैसे बाँटेंगे?\"\nदूसरे ने जवाब दिया, \"जो ऑर्डर करेगा,\nवही बिल का हिसाब रखेगा।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—रास्ता भूल गए तो।\nएक ने पूछा, \"रास्ता भूल गए तो?\"\nदूसरे ने जवाब दिया, \"नक्शा देखेंगे;\nअनुमान से घूमना छुट्टी को लंबा कर देगा।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—यात्रा का सबसे अच्छा हिस्सा।\nएक ने पूछा, \"यात्रा का सबसे अच्छा हिस्सा?\"\nदूसरे ने जवाब दिया, \"दोस्त के साथ यादें बनाना,\nसिर्फ़ फोटो जमा करना नहीं।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—कप्तान कौन बनेगा।\nएक ने पूछा, \"कप्तान कौन बनेगा?\"\nदूसरे ने जवाब दिया, \"जो टीम को साथ रखे;\nसिर्फ़ टॉस जीतने वाला नहीं।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—टॉस हार गए तो।\nएक ने पूछा, \"टॉस हार गए तो?\"\nदूसरे ने जवाब दिया, \"खेल अभी बाकी है;\nसिक्का पूरी कहानी नहीं लिखता।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—गेंद कहाँ गई।\nएक ने पूछा, \"गेंद कहाँ गई?\"\nदूसरे ने जवाब दिया, \"सीमा के पार;\nमेरी नज़र भी उसके पीछे चली गई।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—टीम अभ्यास क्यों नहीं कर रही।\nएक ने पूछा, \"टीम अभ्यास क्यों नहीं कर रही?\"\nदूसरे ने जवाब दिया, \"सब रणनीति बना रहे हैं;\nगेंद अकेली अभ्यास कर रही है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—किसे पहले खिलाओगे।\nएक ने पूछा, \"किसे पहले खिलाओगे?\"\nदूसरे ने जवाब दिया, \"जो तैयार है और टीम,\nके लिए सही भूमिका निभाए।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—हार गए तो क्या करोगे।\nएक ने पूछा, \"हार गए तो क्या करोगे?\"\nदूसरे ने जवाब दिया, \"गलती समझेंगे;\nबहाना बनाकर स्कोर नहीं बदलता।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—जीत का श्रेय किसे।\nएक ने पूछा, \"जीत का श्रेय किसे?\"\nदूसरे ने जवाब दिया, \"पूरी टीम को;\nकप्तान अकेला मैदान नहीं भरता।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—अंपायर ने निर्णय दिया।\nएक ने पूछा, \"अंपायर ने निर्णय दिया।\"\nदूसरे ने जवाब दिया, \"हमने माना;\nनियम तभी काम करते हैं जब सब उनका सम्मान करें।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—पप्पू ने कैच छोड़ा।\nएक ने पूछा, \"पप्पू ने कैच छोड़ा।\"\nदूसरे ने जवाब दिया, \"उसने कहा गेंद हाथ से फिसली;\nचिंटू बोला अगली बार हाथ भी साथ रखना।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—खेल का असली मज़ा क्या।\nएक ने पूछा, \"खेल का असली मज़ा क्या?\"\nदूसरे ने जवाब दिया, \"ईमानदार खेल,\nसाथियों का भरोसा और अंत में हाथ मिलाना।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—दुकान का नाम क्या रखेंगे।\nएक ने पूछा, \"दुकान का नाम क्या रखेंगे?\"\nदूसरे ने जवाब दिया, \"पप्पू-चिंटू एंड कंपनी;\nग्राहक पहले नाम पढ़कर हँसेंगे।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—पहला ग्राहक कौन आया।\nएक ने पूछा, \"पहला ग्राहक कौन आया?\"\nदूसरे ने जवाब दिया, \"मेरा दोस्त;\nउसने उधार माँगकर उद्घाटन कर दिया।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—दाम कैसे तय करेंगे।\nएक ने पूछा, \"दाम कैसे तय करेंगे?\"\nदूसरे ने जवाब दिया, \"लागत देखकर;\nदोस्ती में भी दुकान का हिसाब ज़रूरी है।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—माल कम क्यों बचा।\nएक ने पूछा, \"माल कम क्यों बचा?\"\nदूसरे ने जवाब दिया, \"हमने नमूना दिखाते-दिखाते,\nआधा बेच दिया।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—दुकान देर से क्यों खुली।\nएक ने पूछा, \"दुकान देर से क्यों खुली?\"\nदूसरे ने जवाब दिया, \"चिंटू ने कहा शुभ मुहूर्त;\nघड़ी ने कहा ग्राहक जा चुके।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—हिसाब कौन रखेगा।\nएक ने पूछा, \"हिसाब कौन रखेगा?\"\nदूसरे ने जवाब दिया, \"जो गणित में अच्छा है;\nयानी ग्राहक से पूछेंगे।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—मुनाफ़ा कितना हुआ।\nएक ने पूछा, \"मुनाफ़ा कितना हुआ?\"\nदूसरे ने जवाब दिया, \"नकद कम,\nअनुभव ज़्यादा; अगली बार हिसाब पहले करेंगे।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—ग्राहक लौटकर आया।\nएक ने पूछा, \"ग्राहक लौटकर आया?\"\nदूसरे ने जवाब दिया, \"हाँ, सामान बदलने;\nहमने सेवा का नया अध्याय खोला।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—दुकान बंद कब करेंगे।\nएक ने पूछा, \"दुकान बंद कब करेंगे?\"\nदूसरे ने जवाब दिया, \"जब स्टॉक खत्म हो या हम,\nदोनों की बहस शुरू हो।\""],
  ["pappu-chintu", "पप्पू ने चिंटू के सामने आज यह सवाल रख दिया—व्यापार का सबक क्या मिला।\nएक ने पूछा, \"व्यापार का सबक क्या मिला?\"\nदूसरे ने जवाब दिया, \"मुस्कान अच्छी है,\nपर रसीद और हिसाब उससे भी ज़रूरी हैं।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—सबसे पहले कौन-सा काम करेंगे।\nनागरिक ने पूछा, \"सबसे पहले कौन-सा काम करेंगे?\"\nप्रतिनिधि ने जवाब दिया, \"पहले वही काम दिखाइए जो पिछली,\nबैठक में तय हुआ था।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—योजना की समय-सीमा क्या है।\nनागरिक ने पूछा, \"योजना की समय-सीमा क्या है?\"\nप्रतिनिधि ने जवाब दिया, \"कागज़ पर तारीख़ नहीं,\nज़मीन पर काम की प्रगति बताइए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—विकास किसे कहते हैं।\nनागरिक ने पूछा, \"विकास किसे कहते हैं?\"\nप्रतिनिधि ने जवाब दिया, \"जब सुविधा हर गली तक पहुँचे,\nसिर्फ़ मंच तक नहीं।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—बजट कहाँ खर्च होगा।\nनागरिक ने पूछा, \"बजट कहाँ खर्च होगा?\"\nप्रतिनिधि ने जवाब दिया, \"हर मद का हिसाब सार्वजनिक हो,\nतभी भरोसा बनेगा।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—सड़क कब बनेगी।\nनागरिक ने पूछा, \"सड़क कब बनेगी?\"\nप्रतिनिधि ने जवाब दिया, \"वादा सुन चुके;\nअब मशीन और मजदूर की तारीख़ बताइए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—जनता की प्राथमिकता क्या है।\nनागरिक ने पूछा, \"जनता की प्राथमिकता क्या है?\"\nप्रतिनिधि ने जवाब दिया, \"पानी, सफ़ाई, सुरक्षा और समय पर सेवा—\nबाकी बाद में।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—किसे श्रेय मिलेगा।\nनागरिक ने पूछा, \"किसे श्रेय मिलेगा?\"\nप्रतिनिधि ने जवाब दिया, \"जिसने काम किया;\nउद्घाटन की कैंची को नहीं।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—काम की समीक्षा कैसे होगी।\nनागरिक ने पूछा, \"काम की समीक्षा कैसे होगी?\"\nप्रतिनिधि ने जवाब दिया, \"नागरिकों के सामने लक्ष्य,\nऔर वास्तविक नतीजे रखकर।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—कौन-सी योजना सफल है।\nनागरिक ने पूछा, \"कौन-सी योजना सफल है?\"\nप्रतिनिधि ने जवाब दिया, \"जिसका लाभ कागज़ से,\nनिकलकर लोगों तक पहुँचे।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—सभा का निष्कर्ष क्या रहा।\nनागरिक ने पूछा, \"सभा का निष्कर्ष क्या रहा?\"\nप्रतिनिधि ने जवाब दिया, \"अगली बार भाषण छोटा और,\nकाम की रिपोर्ट लंबी होगी।\""],
  ["politics", "नेता ने सभा में कहा, \"हम हर गली में रोशनी पहुँचाएँगे।\"\nएक मतदाता बोला, \"हमारी गली में तो खंभा ही नहीं है।\"\nनेता ने तुरंत कहा, \"पहले खंभा ढूँढ़ेंगे, फिर रोशनी देंगे।\"\nमतदाता बोला, \"चुनाव बाद खंभा भी हमें ही ढूँढ़ना पड़ेगा क्या?\""],
  ["politics", "पत्रकार ने पूछा, \"आपकी सबसे बड़ी उपलब्धि क्या है?\"\nनेता बोले, \"हमने जनता की आवाज़ सुनी है।\"\nपत्रकार ने पूछा, \"फिर जवाब कब देंगे?\"\nनेता बोले, \"आवाज़ रिकॉर्ड हो गई है; जवाब अगली प्रेस कॉन्फ़्रेंस में चलाएँगे।\""],
  ["politics", "चुनावी पोस्टर पर लिखा था, \"हर समस्या का समाधान।\"\nनागरिक ने पूछा, \"पानी कब आएगा?\"\nकार्यकर्ता बोला, \"समाधान तैयार है।\"\nनागरिक ने कहा, \"तो नल खोलो।\" कार्यकर्ता बोला, \"पहले पोस्टर की फोटो तो ले लें।\""],
  ["politics", "सभा में नेता ने कहा, \"हम युवाओं को रोज़गार देंगे।\"\nएक युवक ने पूछा, \"कब तक?\"\nनेता बोले, \"बहुत जल्द।\"\nयुवक ने कहा, \"तारीख़ बता दीजिए, मैं तब तक बेरोज़गारी को छुट्टी पर भेज दूँ।\""],
  ["politics", "नगर निगम की बैठक में पार्षद ने कहा, \"हमने सफ़ाई अभियान शुरू किया है।\"\nनिवासी ने पूछा, \"कचरा कब उठेगा?\"\nपार्षद बोले, \"अभियान का उद्घाटन हो चुका है।\"\nनिवासी ने कहा, \"अब कचरे को भी कार्यक्रम का निमंत्रण भेजिए।\""],
  ["politics", "मतदाता ने पूछा, \"पिछले वादे का क्या हुआ?\"\nउम्मीदवार बोला, \"हमने उसे भुलाया नहीं है।\"\nमतदाता ने कहा, \"तो पूरा कब करेंगे?\"\nउम्मीदवार बोला, \"याद रखना और पूरा करना दो अलग-अलग विभाग हैं।\""],
  [ "politics", "सभा में नागरिक ने पूछा, “पिछले साल की सड़क का काम पूरा हुआ?”\nनेता बोले, “काम प्रगति पर है।”\nनागरिक ने कहा, “पर सड़क तो खोदी हुई है।”\nनेता बोले, “इसीलिए तो प्रगति दिखाई दे रही है।”" ],
  [ "politics", "पत्रकार ने पूछा, “आपका सबसे बड़ा चुनावी वादा क्या है?”\nउम्मीदवार बोला, “हर सवाल का जवाब देंगे।”\nपत्रकार ने पूछा, “कब?”\nउम्मीदवार मुस्कराया, “यह भी एक अच्छा सवाल है; अगली सभा में जवाब दूँगा।”" ],
  [ "politics", "मतदाता ने प्रतिनिधि से कहा, “इस बार काम का हिसाब चाहिए।”\nप्रतिनिधि बोला, “हमने बहुत बैठकें की हैं।”\nमतदाता ने पूछा, “उनसे क्या बदला?”\nप्रतिनिधि बोला, “अब बैठक का समय पहले से तय रहता है।”" ],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—मतदाता ने क्या कहा।\nनागरिक ने पूछा, \"मतदाता ने क्या कहा?\"\nप्रतिनिधि ने जवाब दिया, \"वोट भरोसे से मिलेगा,\nपोस्टर की चमक से नहीं।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—बजट में सबसे ज़रूरी मद क्या है।\nनागरिक ने पूछा, \"बजट में सबसे ज़रूरी मद क्या है?\"\nप्रतिनिधि ने जवाब दिया, \"वह जो नागरिक की रोज़मर्रा,\nकी समस्या हल करे।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—खर्च बढ़ गया तो क्या करेंगे।\nनागरिक ने पूछा, \"खर्च बढ़ गया तो क्या करेंगे?\"\nप्रतिनिधि ने जवाब दिया, \"पहले कारण बताएँगे;\nहर कमी का हल नया कर नहीं।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—कितना पैसा शिक्षा पर जाएगा।\nनागरिक ने पूछा, \"कितना पैसा शिक्षा पर जाएगा?\"\nप्रतिनिधि ने जवाब दिया, \"सिर्फ़ घोषणा नहीं,\nस्कूल तक पहुँची राशि दिखाइए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—बजट में पारदर्शिता कैसे आए।\nनागरिक ने पूछा, \"बजट में पारदर्शिता कैसे आए?\"\nप्रतिनिधि ने जवाब दिया, \"हर खर्च की जानकारी सरल,\nभाषा में सार्वजनिक करके।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—घाटा किससे पूरा होगा।\nनागरिक ने पूछा, \"घाटा किससे पूरा होगा?\"\nप्रतिनिधि ने जवाब दिया, \"बेकार खर्च घटाकर और,\nप्राथमिकताओं को स्पष्ट करके।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—योजना की सफलता कौन मापेगा।\nनागरिक ने पूछा, \"योजना की सफलता कौन मापेगा?\"\nप्रतिनिधि ने जवाब दिया, \"स्वतंत्र समीक्षा और जनता,\nकी प्रतिक्रिया दोनों।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—कागज़ पर बचत दिख रही है।\nनागरिक ने पूछा, \"कागज़ पर बचत दिख रही है।\"\nप्रतिनिधि ने जवाब दिया, \"सेवा में कटौती हुई तो,\nवह बचत किसके काम आई?\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—स्वास्थ्य पर खर्च क्यों बढ़ाएँ।\nनागरिक ने पूछा, \"स्वास्थ्य पर खर्च क्यों बढ़ाएँ?\"\nप्रतिनिधि ने जवाब दिया, \"क्योंकि समय पर इलाज,\nबाद की बड़ी परेशानी से बेहतर है।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—कौन-सा खर्च रोका जाए।\nनागरिक ने पूछा, \"कौन-सा खर्च रोका जाए?\"\nप्रतिनिधि ने जवाब दिया, \"जिसका लाभ जनता तक न पहुँचे,\nऔर जिसका हिसाब न मिले।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—बजट भाषण का सार क्या है।\nनागरिक ने पूछा, \"बजट भाषण का सार क्या है?\"\nप्रतिनिधि ने जवाब दिया, \"आँकड़े तभी अच्छे हैं जब,\nउनका असर जीवन में दिखे।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—पार्षद जी, गली में पानी क्यों भरा है।\nनागरिक ने पूछा, \"पार्षद जी, गली में पानी क्यों भरा है?\"\nप्रतिनिधि ने जवाब दिया, \"उन्होंने कहा निरीक्षण करूँगा;\nनागरिक बोला, अभी जूते उतारकर देखिए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—कूड़ा रोज़ क्यों जमा होता है।\nनागरिक ने पूछा, \"कूड़ा रोज़ क्यों जमा होता है?\"\nप्रतिनिधि ने जवाब दिया, \"क्योंकि गाड़ी का समय तय है,\nपर गली का इंतज़ार अनंत।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—स्ट्रीट लाइट कब ठीक होगी।\nनागरिक ने पूछा, \"स्ट्रीट लाइट कब ठीक होगी?\"\nप्रतिनिधि ने जवाब दिया, \"पार्षद ने कहा जल्द;\nअँधेरे ने कहा मुझे तारीख़ चाहिए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—पार्क की बेंच टूटी है।\nनागरिक ने पूछा, \"पार्क की बेंच टूटी है।\"\nप्रतिनिधि ने जवाब दिया, \"पार्षद बोला मरम्मत होगी;\nबुज़ुर्ग बोले तब तक खड़े रहेंगे?\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—नाली बंद क्यों है।\nनागरिक ने पूछा, \"नाली बंद क्यों है?\"\nप्रतिनिधि ने जवाब दिया, \"रिपोर्ट में खुली है;\nनागरिक ने पानी की तस्वीर दिखा दी।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—शिकायत कहाँ दर्ज करें।\nनागरिक ने पूछा, \"शिकायत कहाँ दर्ज करें?\"\nप्रतिनिधि ने जवाब दिया, \"पार्षद ने नंबर दिया;\nनागरिक ने पूछा जवाब की समय-सीमा भी?\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—क्षेत्र में काम किसका है।\nनागरिक ने पूछा, \"क्षेत्र में काम किसका है?\"\nप्रतिनिधि ने जवाब दिया, \"पार्षद बोला मेरा;\nनागरिक ने कहा फिर श्रेय से पहले जिम्मेदारी निभाइए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—बच्चों का मैदान कहाँ है।\nनागरिक ने पूछा, \"बच्चों का मैदान कहाँ है?\"\nप्रतिनिधि ने जवाब दिया, \"नक्शे पर;\nबच्चों ने कहा खेलने के लिए ज़मीन चाहिए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—सड़क की मरम्मत हुई।\nनागरिक ने पूछा, \"सड़क की मरम्मत हुई?\"\nप्रतिनिधि ने जवाब दिया, \"हाँ, गड्ढे के चारों ओर,\nरंग कर दिया गया।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—दौरे का नतीजा क्या।\nनागरिक ने पूछा, \"दौरे का नतीजा क्या?\"\nप्रतिनिधि ने जवाब दिया, \"पार्षद ने समस्या देखी;\nअब नागरिक काम होते देखना चाहते हैं।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—पोस्टर में चेहरा इतना बड़ा क्यों है।\nनागरिक ने पूछा, \"पोस्टर में चेहरा इतना बड़ा क्यों है?\"\nप्रतिनिधि ने जवाब दिया, \"काम की तस्वीर छोटी थी,\nइसलिए डिज़ाइनर ने चेहरा बढ़ा दिया।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—नारा कौन-सा रखें।\nनागरिक ने पूछा, \"नारा कौन-सा रखें?\"\nप्रतिनिधि ने जवाब दिया, \"ऐसा जो काम पूरा होने,\nके बाद भी सच रहे।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—पोस्टर कहाँ लगाएँ।\nनागरिक ने पूछा, \"पोस्टर कहाँ लगाएँ?\"\nप्रतिनिधि ने जवाब दिया, \"जहाँ अनुमति हो;\nदीवार भी नागरिक संपत्ति है।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—कितने पोस्टर छपेंगे।\nनागरिक ने पूछा, \"कितने पोस्टर छपेंगे?\"\nप्रतिनिधि ने जवाब दिया, \"उतने नहीं जितने वादे;\nखर्च का हिसाब भी रखना है।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—रंग चमकीला है।\nनागरिक ने पूछा, \"रंग चमकीला है?\"\nप्रतिनिधि ने जवाब दिया, \"हाँ, पर शहर की,\nसड़क उससे नहीं चमकेगी।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—पोस्टर में उपलब्धियाँ लिखें।\nनागरिक ने पूछा, \"पोस्टर में उपलब्धियाँ लिखें?\"\nप्रतिनिधि ने जवाब दिया, \"लिखें, साथ में तारीख़,\nऔर प्रमाण भी दें।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—किसकी तस्वीर सबसे आगे।\nनागरिक ने पूछा, \"किसकी तस्वीर सबसे आगे?\"\nप्रतिनिधि ने जवाब दिया, \"उस काम की तस्वीर जो लोगों,\nके जीवन में बदलाव लाए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—नारा छोटा कैसे हो।\nनागरिक ने पूछा, \"नारा छोटा कैसे हो?\"\nप्रतिनिधि ने जवाब दिया, \"कम शब्द,\nसाफ़ वादा और पूरा करने की जिम्मेदारी।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—पोस्टर उतरने के बाद क्या बचेगा।\nनागरिक ने पूछा, \"पोस्टर उतरने के बाद क्या बचेगा?\"\nप्रतिनिधि ने जवाब दिया, \"अगर काम हुआ तो परिणाम;\nनहीं तो सिर्फ़ गोंद।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—प्रचार का सबसे अच्छा माध्यम।\nनागरिक ने पूछा, \"प्रचार का सबसे अच्छा माध्यम?\"\nप्रतिनिधि ने जवाब दिया, \"जनता का भरोसा,\nजो सेवा से बनता है।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—बहस में सबसे पहले कौन बोले।\nनागरिक ने पूछा, \"बहस में सबसे पहले कौन बोले?\"\nप्रतिनिधि ने जवाब दिया, \"जो सबसे ज़्यादा सुनने,\nको तैयार हो।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—विपक्ष का सवाल कठिन है।\nनागरिक ने पूछा, \"विपक्ष का सवाल कठिन है।\"\nप्रतिनिधि ने जवाब दिया, \"अध्यक्ष बोला,\nजवाब दीजिए; सवाल पूछना लोकतंत्र का काम है।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—समय सीमा क्यों रखी।\nनागरिक ने पूछा, \"समय सीमा क्यों रखी?\"\nप्रतिनिधि ने जवाब दिया, \"ताकि हर आवाज़ को मौका मिले,\nऔर चर्चा मुद्दे पर रहे।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—एक-दूसरे की बात क्यों काटते हैं।\nनागरिक ने पूछा, \"एक-दूसरे की बात क्यों काटते हैं?\"\nप्रतिनिधि ने जवाब दिया, \"क्योंकि उत्तर तैयार है,\nसुनने की तैयारी कम है।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—बहस का विजेता कौन।\nनागरिक ने पूछा, \"बहस का विजेता कौन?\"\nप्रतिनिधि ने जवाब दिया, \"वह नागरिक जिसे मुद्दे,\nपर साफ़ जवाब मिला।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—आँकड़े अलग-अलग हैं।\nनागरिक ने पूछा, \"आँकड़े अलग-अलग हैं।\"\nप्रतिनिधि ने जवाब दिया, \"स्रोत सामने रखिए;\nबहस अनुमान से नहीं चलती।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—किसी ने गलती मानी।\nनागरिक ने पूछा, \"किसी ने गलती मानी?\"\nप्रतिनिधि ने जवाब दिया, \"हाँ, और उसी दिन चर्चा,\nपहली बार आगे बढ़ी।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—जनता के सवाल कितने थे।\nनागरिक ने पूछा, \"जनता के सवाल कितने थे?\"\nप्रतिनिधि ने जवाब दिया, \"बहुत; मंच पर समय कम,\nऔर मुद्दे ज़्यादा थे।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—बहस में शोर क्यों हुआ।\nनागरिक ने पूछा, \"बहस में शोर क्यों हुआ?\"\nप्रतिनिधि ने जवाब दिया, \"माइक तेज़ था,\nतर्क को अभी आवाज़ खोजनी थी।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—अच्छी बहस का नियम।\nनागरिक ने पूछा, \"अच्छी बहस का नियम?\"\nप्रतिनिधि ने जवाब दिया, \"तथ्य, सम्मान और जवाबदेही—\nतीनों साथ।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—आपने ऑनलाइन क्या उपलब्धि लिखी।\nनागरिक ने पूछा, \"आपने ऑनलाइन क्या उपलब्धि लिखी?\"\nप्रतिनिधि ने जवाब दिया, \"प्रतिनिधि बोला सड़क बनी;\nनागरिक ने पूछा कौन-सी गली?\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—तस्वीर में फीता काट रहे हैं।\nनागरिक ने पूछा, \"तस्वीर में फीता काट रहे हैं।\"\nप्रतिनिधि ने जवाब दिया, \"लोग बोले,\nफीता तो कट गया; काम कब पूरा होगा?\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—पोस्ट पर टिप्पणी बंद क्यों है।\nनागरिक ने पूछा, \"पोस्ट पर टिप्पणी बंद क्यों है?\"\nप्रतिनिधि ने जवाब दिया, \"प्रतिनिधि बोला संवाद खुला है;\nनागरिक ने कहा सिर्फ़ एक दिशा में।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—कितने लोगों ने पोस्ट देखा।\nनागरिक ने पूछा, \"कितने लोगों ने पोस्ट देखा?\"\nप्रतिनिधि ने जवाब दिया, \"बहुतों ने;\nपर सड़क पर चलने वालों ने अभी गड्ढे देखे।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—लाइव वीडियो क्यों बनाया।\nनागरिक ने पूछा, \"लाइव वीडियो क्यों बनाया?\"\nप्रतिनिधि ने जवाब दिया, \"ताकि जनता देखे;\nजनता ने कहा कैमरा घुमाकर समस्या भी दिखाओ।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—ऑनलाइन शिकायत आई।\nनागरिक ने पूछा, \"ऑनलाइन शिकायत आई।\"\nप्रतिनिधि ने जवाब दिया, \"टीम ने लिखा 'धन्यवाद';\nनागरिक ने पूछा समाधान की तारीख़?\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—उपलब्धि की सूची लंबी है।\nनागरिक ने पूछा, \"उपलब्धि की सूची लंबी है।\"\nप्रतिनिधि ने जवाब दिया, \"लोग बोले,\nअब अधूरे काम की सूची भी साथ रखिए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—टिप्पणी में सवाल आया।\nनागरिक ने पूछा, \"टिप्पणी में सवाल आया।\"\nप्रतिनिधि ने जवाब दिया, \"प्रतिनिधि ने जवाब दिया;\nपहली बार पोस्ट से ज़्यादा चर्चा हुई।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—सोशल मीडिया का फायदा क्या।\nनागरिक ने पूछा, \"सोशल मीडिया का फायदा क्या?\"\nप्रतिनिधि ने जवाब दिया, \"सूचना तेज़ पहुँचती है;\nसही जवाब भी उतनी ही तेज़ होना चाहिए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—सबसे अच्छा अपडेट कौन-सा।\nनागरिक ने पूछा, \"सबसे अच्छा अपडेट कौन-सा?\"\nप्रतिनिधि ने जवाब दिया, \"काम पूरा होने की सूचना,\nसाथ में जाँच और खर्च का विवरण।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—गड्ढे पर सवाल क्यों उठा रहे हैं।\nनागरिक ने पूछा, \"गड्ढे पर सवाल क्यों उठा रहे हैं?\"\nप्रतिनिधि ने जवाब दिया, \"क्योंकि रोज़ मेरी साइकिल,\nलोकतंत्र में गिरती है।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—सड़क पर पानी जमा है।\nनागरिक ने पूछा, \"सड़क पर पानी जमा है।\"\nप्रतिनिधि ने जवाब दिया, \"अधिकारी बोला बारिश हुई;\nनागरिक ने कहा नाली भी तो आपकी जिम्मेदारी है।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—मरम्मत का बोर्ड लगा है।\nनागरिक ने पूछा, \"मरम्मत का बोर्ड लगा है।\"\nप्रतिनिधि ने जवाब दिया, \"लोग बोले,\nबोर्ड खड़ा है; सड़क अभी लेटी हुई है।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—किसने निरीक्षण किया।\nनागरिक ने पूछा, \"किसने निरीक्षण किया?\"\nप्रतिनिधि ने जवाब दिया, \"सूची में नाम है;\nनागरिक ने पूछा क्या उन्होंने यहाँ चलकर देखा?\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—गली में रोशनी नहीं।\nनागरिक ने पूछा, \"गली में रोशनी नहीं।\"\nप्रतिनिधि ने जवाब दिया, \"प्रतिनिधि बोला आवेदन दें;\nनागरिक बोला अँधेरे में फ़ॉर्म कहाँ भरूँ?\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—कितने गड्ढे गिने।\nनागरिक ने पूछा, \"कितने गड्ढे गिने?\"\nप्रतिनिधि ने जवाब दिया, \"नागरिक बोला गिनते-गिनते घर पहुँच गया;\nरिपोर्ट में शून्य लिखा है।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—काम कब शुरू होगा।\nनागरिक ने पूछा, \"काम कब शुरू होगा?\"\nप्रतिनिधि ने जवाब दिया, \"ठेकेदार बोला कल;\nनागरिक ने कहा इस बार कैलेंडर की तारीख़ लिखिए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—समस्या की तस्वीर भेजी।\nनागरिक ने पूछा, \"समस्या की तस्वीर भेजी?\"\nप्रतिनिधि ने जवाब दिया, \"हाँ, अब जवाब में सिर्फ़,\nइमोजी नहीं, मरम्मत चाहिए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—सड़क का नाम विकास पथ है।\nनागरिक ने पूछा, \"सड़क का नाम विकास पथ है।\"\nप्रतिनिधि ने जवाब दिया, \"नागरिक बोला नाम अच्छा है,\nअब रास्ता भी वैसा बनाइए।\""],
  ["politics", "जनसभा में मतदाता ने मंच से यह सवाल दागा—दौरे का असर क्या हुआ।\nनागरिक ने पूछा, \"दौरे का असर क्या हुआ?\"\nप्रतिनिधि ने जवाब दिया, \"पहली बार गड्ढे पर लाल निशान नहीं,\nमरम्मत की तारीख़ लगी।\""],
  ["politics", "नगर निगम ने गड्ढे के पास उद्घाटन का पत्थर लगा दिया।\nअगले दिन पत्रकार ने पूछा, “सड़क कब बनेगी?”\nअधिकारी बोले, “पहले शिलापट्ट की सुरक्षा ज़रूरी है।”\nनागरिक ने कहा, “गड्ढा तो पत्थर से भी पुराना है।”\nअधिकारी मुस्कराए, “इसीलिए इसे विरासत स्थल घोषित करने का प्रस्ताव है।”"],
  ["politics", "चुनावी वादा छापने वाली मशीन अचानक बंद हो गई।\nकर्मचारी बोला, “कागज़ खत्म हो गया है।”\nनेता ने कहा, “कोई बात नहीं, वादे तो डिजिटल भी किए जा सकते हैं।”\nकर्मचारी ने पूछा, “फिर पूरे कैसे होंगे?”\nनेता बोले, “उसके लिए अलग विभाग और अगला बजट चाहिए।”"],
  ["politics", "मतदान के बाद एक बुज़ुर्ग ने उँगली की स्याही दिखाई।\nयुवा ने पूछा, “अब आपकी पसंद का काम कब होगा?”\nबुज़ुर्ग बोले, “पहले परिणाम आएगा, फिर प्रतिनिधि मिलेंगे।”\nयुवा ने कहा, “और अगर वे न मिले?”\nबुज़ुर्ग हँसे, “तब यही स्याही अगली शिकायत पर हस्ताक्षर करने में काम आएगी।”"],
  ["politics", "बजट बैठक में अधिकारी ने हर योजना के लिए नया शीर्षक सुझाया।\nलेखाकार ने पूछा, “राशि कहाँ से आएगी?”\nअधिकारी बोले, “शीर्षक आकर्षक होगा तो निवेश भी आकर्षित होगा।”\nलेखाकार ने खाली खाते की ओर इशारा किया।\nअधिकारी ने तुरंत कहा, “इसे वित्तीय सादगी का मॉडल लिख दीजिए।”"],
  ["politics", "मोहल्ले में पानी का टैंकर तीसरी बार देर से पहुँचा।\nपार्षद ने कहा, “हमने जल-प्रबंधन में पारदर्शिता लाई है।”\nनिवासी ने पूछा, “पानी कहाँ है?”\nपार्षद बोले, “टैंकर का रास्ता सबको पता है।”\nनिवासी ने जवाब दिया, “हाँ, क्योंकि हम रोज़ खाली बाल्टियाँ लेकर उसी रास्ते पर खड़े रहते हैं।”"],
  ["politics", "सरकारी वाई-फाई का उद्घाटन हुआ, मगर पासवर्ड किसी को नहीं मिला।\nअधिकारी ने कहा, “सेवा सबके लिए खुली है।”\nछात्र ने पूछा, “तो जुड़ें कैसे?”\nअधिकारी बोले, “पहले आवेदन पोर्टल पर पंजीकरण कीजिए।”\nछात्र हँसा, “पोर्टल चलाने के लिए इंटरनेट चाहिए; इंटरनेट पाने के लिए पोर्टल!”"],
  ["politics", "कार्यालय में उपस्थिति मशीन ने मंत्री की उँगली पहचानने से मना कर दिया।\nकर्मचारी बोला, “मशीन कहती है कि आप आज आए ही नहीं।”\nमंत्री ने कहा, “मैं निरीक्षण पर था।”\nकर्मचारी ने पूछा, “कहाँ?”\nमंत्री बोले, “उपस्थिति व्यवस्था की कमियों का निरीक्षण करने—और मशीन ने कमी पकड़ ली।”"],
  ["politics", "नई सड़क पर लगी स्ट्रीट लाइट दिन में भी जल रही थी।\nअधिकारी ने कहा, “देखिए, शहर कितना रोशन है!”\nनिवासी बोला, “रात में तो यह बंद रहती है।”\nअधिकारी ने फाइल पलटी, “बिजली बचाने की नीति है।”\nनिवासी ने कहा, “तो दिन में रोशनी और रात में अँधेरा—नीति बिल्कुल समय-सारिणी से चलती है।”"],
  ["politics", "कूड़ा उठाने का ठेका फिर से उसी कंपनी को मिला।\nपत्रकार ने पूछा, “पिछली बार सफ़ाई क्यों नहीं हुई?”\nअधिकारी बोले, “अनुभव को महत्व दिया गया है।”\nपत्रकार ने कहा, “कंपनी का अनुभव या कूड़े का?”\nअधिकारी ने फाइल बंद की, “आपके सवाल में स्वच्छता की भावना कम दिखाई देती है।”"],
  ["politics", "प्रेस वार्ता में प्रवक्ता ने कहा, “आज हर प्रश्न का उत्तर दिया जाएगा।”\nपत्रकार ने पूछा, “पिछले महीने घोषित पुल का काम कहाँ तक पहुँचा?”\nप्रवक्ता बोले, “हमने प्रश्नों के प्रति अपनी प्रतिबद्धता दोहराई है।”\nपत्रकार ने कहा, “मैंने पुल पूछा था।”\nप्रवक्ता मुस्कराए, “और हमने जवाबदेही का रास्ता खोल दिया—पुल का रास्ता अगली वार्ता में खुलेगा।”"],
  ["politics", "नगर निगम की बैठक में पार्षद ने कहा, \"हमने गड्ढों की गिनती पूरी कर ली है।\"\nनिवासी बोला, \"अब उन्हें भरने की तारीख भी गिन लीजिए।\"\nअधिकारी ने कैलेंडर खोला, \"काम सोमवार से शुरू होगा।\"\nनिवासी मुस्कराया, \"कौन-सा सोमवार—यह भी कार्यवृत्त में लिखिए।\""],
  ["politics", "टीवी बहस में प्रवक्ता बोले, \"हमारे पास हर सवाल का जवाब है।\"\nपत्रकार ने पूछा, \"तो पिछले सवाल का जवाब क्या था?\"\nप्रवक्ता ने पानी पिया और विषय बदल दिया।\nदर्शक ने रिमोट उठाया, \"मेरे पास हर बहस का समाधान है।\""],
  ["politics", "ग्राम सभा में किसान ने सिंचाई की नहर का मुद्दा उठाया।\nअधिकारी बोले, \"प्रस्ताव आगे भेज दिया गया है।\"\nकिसान ने पूछा, \"पानी किस रास्ते से आएगा?\"\nअधिकारी चुप हुए; किसान बोला, \"कागज़ की नहर से खेत नहीं सींचते।\""],
  ["politics", "नेता जी ने सोशल मीडिया पर लिखा, \"जनता की आवाज़ मेरी प्राथमिकता है।\"\nएक नागरिक ने बिजली कटौती की शिकायत भेजी।\nजवाब आया, \"आपकी प्रतिक्रिया हमारे लिए महत्वपूर्ण है।\"\nनागरिक बोला, \"बिजली भी महत्वपूर्ण है—उसे भी ऑनलाइन मत रखिए।\""],
  ["politics", "मोहल्ले के युवाओं ने उम्मीदवार से पूछा, \"खेल का मैदान कब बनेगा?\"\nउम्मीदवार बोले, \"योजना तैयार है।\"\nएक बच्चे ने पूछा, \"मैदान कागज़ पर है या ज़मीन पर?\"\nउम्मीदवार ने नक्शे के बजाय खाली प्लॉट देखने का वादा किया।"],
  ["politics", "विद्यालय के बच्चों ने स्थानीय प्रतिनिधि को पत्र लिखा।\nउन्होंने माँगा, \"पुस्तकालय में नई किताबें और साफ़ शौचालय।\"\nप्रतिनिधि ने जवाब दिया, \"बच्चों की माँगें बहुत छोटी हैं।\"\nप्रधानाचार्य बोले, \"इसीलिए इन्हें पूरा करना मुश्किल नहीं होना चाहिए।\""],
  ["politics", "नगरपालिका के दफ्तर में नागरिक ने पूछा, \"कूड़ा उठाने वाली गाड़ी किस दिन आएगी?\"\nकर्मचारी बोला, \"रूट तय हो रहा है।\"\nनागरिक ने गली का नक्शा सामने रख दिया।\nकर्मचारी बोला, \"अब हमें बस गाड़ी भेजनी है।\""],
  ["politics", "नेता जी ने कहा, \"हम पारदर्शिता में विश्वास रखते हैं।\"\nएक छात्र ने पूछा, \"खर्च की पूरी सूची वेबसाइट पर क्यों नहीं है?\"\nनेता बोले, \"तकनीकी टीम देख रही है।\"\nछात्र ने कहा, \"मैं कंप्यूटर विज्ञान पढ़ता हूँ; लिंक भेजिए, बहाना नहीं।\""],
  ["politics", "चुनाव अधिकारी ने मतदाता से कहा, \"पहचान पत्र दिखाइए।\"\nमतदाता ने कार्ड दिया और पूछा, \"अब मेरी पहचान भी दर्ज होगी?\"\nअधिकारी बोले, \"आपका वोट दर्ज होगा।\"\nमतदाता मुस्कराया, \"चुनाव के बाद मेरी समस्या भी पहचान लीजिए।\""],
  ["politics", "स्थानीय बहस में नागरिक ने पूछा, \"पार्क की बेंचें कब लगेंगी?\"\nअधिकारी बोले, \"टेंडर प्रक्रिया चल रही है।\"\nएक बुज़ुर्ग ने कहा, \"तब तक हम खड़े होकर ही आराम कर लेते हैं।\"\nअधिकारी हँसे, \"आपकी प्रतीक्षा-शक्ति का भी बजट बनाना पड़ेगा।\""],
  ["mulla-nasruddin", "गाँव के कुएँ पर मुल्ला ने रस्सी की जगह लंबी बेल बाँध दी।\nपड़ोसी ने पूछा, “यह पानी खींचने के काम आएगी?”\nमुल्ला बोले, “पहले दिन बाल्टी ऊपर आई, पानी नहीं।”\nपड़ोसी हँसा, “तो फिर?”\nमुल्ला बोले, “अब कुएँ को भी पता है कि मैं प्रयोग कर रहा हूँ।”"],
  ["mulla-nasruddin", "मुल्ला ने बाज़ार में अपनी दुकान के बाहर लिखा—“आज उधार बंद है।”\nएक ग्राहक ने पूछा, “कल उधार मिलेगा?”\nमुल्ला बोले, “कल का बोर्ड कल लिखूँगा।”\nग्राहक बोला, “आपको ग्राहक खोने का डर नहीं?”\nमुल्ला ने कहा, “उधार में ग्राहक नहीं, तारीख़ें बढ़ती हैं।”"],
  ["mulla-nasruddin", "एक चित्रकार ने मुल्ला का चित्र बनाया और बहुत ऊँची कीमत माँगी।\nमुल्ला ने चित्र को उलटकर देखा, फिर सीधा कर दिया।\nचित्रकार बोला, “कुछ कमी मिली?”\nमुल्ला ने कहा, “चेहरा तो ठीक है, बस जेब मेरी असली हालत से बड़ी बना दी।”\nचित्रकार मुस्कराया, “कला में कल्पना होती है।” मुल्ला बोले, “तो कीमत भी कल्पना में ही रखिए।”"],
  ["mulla-nasruddin", "मुल्ला ने घर के दरवाज़े पर घंटी लगवाई।\nपहले ही दिन घंटी बजती रही, पर बाहर कोई नहीं था।\nकारीगर बोला, “शायद तार में गड़बड़ी है।”\nमुल्ला ने कहा, “तार ठीक है, पड़ोसी बच्चे इसे संगीत समझकर बजा रहे हैं।”\nअगले दिन मुल्ला ने घंटी के नीचे लिखा—“प्रवेश से पहले अभ्यास बंद करें।”"],
  ["mulla-nasruddin", "नाई ने मुल्ला से पूछा, “बाल छोटे कर दूँ या बहुत छोटे?”\nमुल्ला ने कहा, “इतने छोटे कि कंघी का खर्च बच जाए।”\nनाई ने मशीन उठाई तो मुल्ला पीछे हटे।\nनाई बोला, “डर क्यों रहे हैं?”\nमुल्ला ने जवाब दिया, “बचत बालों की माँगी थी, पहचान की नहीं।”"],
  ["mulla-nasruddin", "मुल्ला ने अपनी पुरानी चप्पल मरम्मत के लिए दी।\nमोची ने कहा, “तलवा बदलना पड़ेगा, पट्टा भी नया लगेगा।”\nमुल्ला ने पूछा, “फिर पुरानी क्या बचेगी?”\nमोची बोला, “यादें।”\nमुल्ला ने चप्पल वापस ली, “यादें घर में बहुत हैं, चलने लायक चप्पल चाहिए।”"],
  ["mulla-nasruddin", "गाँव के मेले में मुल्ला ने निशानेबाज़ी का इनाम जीत लिया।\nआयोजक ने पूछा, “आपने इतना सटीक निशाना कैसे लगाया?”\nमुल्ला ने कहा, “पहले निशाना लगाया, फिर तीर चलाया।”\nआयोजक चौंका, “बाकी लोग भी यही करते हैं!”\nमुल्ला बोले, “हाँ, पर मैं तीर चलाने से पहले लक्ष्य चुनता हूँ।”"],
  ["mulla-nasruddin", "मुल्ला ने पड़ोसी से उसकी नई गाय की तारीफ़ की।\nपड़ोसी बोला, “यह रोज़ बहुत दूध देती है।”\nमुल्ला ने पूछा, “और चारा कितना खाती है?”\nपड़ोसी ने गर्व से कहा, “काफ़ी, मगर दूध भी खूब है।”\nमुल्ला बोले, “तो हिसाब गाय का नहीं, तुम्हारे धैर्य का अच्छा है।”"],
  ["mulla-nasruddin", "मुल्ला ने अपने घर के बाहर दो कुर्सियाँ रखीं।\nराहगीर ने पूछा, “एक कुर्सी खाली क्यों है?”\nमुल्ला बोले, “मेहमान के लिए।”\nराहगीर बैठ गया और बोला, “अब दूसरी किसके लिए?”\nमुल्ला ने कहा, “उस मेहमान के लिए जो बिना पूछे पहली कुर्सी पर बैठने की सलाह न दे।”"],
  ["mulla-nasruddin", "मुल्ला ने अनाज तौलते दुकानदार से कहा, “तराज़ू ज़रा बराबर रखिए।”\nदुकानदार बोला, “मेरा तराज़ू बिल्कुल सही है।”\nमुल्ला ने बाट बदलकर फिर तौलने को कहा; इस बार वजन अलग निकला।\nदुकानदार घबरा गया, “यह कैसे हुआ?”\nमुल्ला बोले, “तराज़ू सही होगा, मगर आपकी ईमानदारी हर बाट के साथ बदलती है।”"],
  ["mulla-nasruddin", "मुल्ला ने बाज़ार में एक घड़ी खरीदी जो कभी सही समय नहीं बताती थी।\nदोस्त ने पूछा, \"ऐसी घड़ी क्यों ली?\"\nमुल्ला बोले, \"अब देर होने पर घड़ी को दोष दे सकता हूँ।\"\nदोस्त ने कहा, \"और जल्दी पहुँच गए तो?\" मुल्ला बोले, \"तब भी घड़ी ही गलत होगी।\""],
  ["mulla-nasruddin", "एक पड़ोसी ने मुल्ला से पूछा, \"आपने अपने गधे को इतना समझदार कैसे बनाया?\"\nमुल्ला बोले, \"मैं रोज़ उसे सलाह देता हूँ।\"\nपड़ोसी ने पूछा, \"वह मानता है?\"\nमुल्ला बोले, \"नहीं, पर अब हम दोनों को पता है कि घर में सलाह कौन देता है।\""],
  ["mulla-nasruddin", "मुल्ला ने छाता लेकर धूप में निकलना शुरू किया।\nदोस्त ने पूछा, \"बारिश तो हो नहीं रही।\"\nमुल्ला बोले, \"छाता साथ हो तो बादल भी सोच-समझकर आते हैं।\"\nदोस्त हँसा, \"और धूप?\" मुल्ला बोले, \"उससे तो छाते की दोस्ती पुरानी है।\""],
  ["mulla-nasruddin", "मुल्ला ने बाज़ार में एक खाली थैला उठाकर चलना शुरू किया।\nदोस्त ने पूछा, \"इसमें क्या है?\"\nमुल्ला बोले, \"अभी कुछ नहीं, इसलिए चोरी का डर भी नहीं।\"\nदोस्त ने कहा, \"फिर थैला क्यों?\" मुल्ला बोले, \"लोग समझेंगे मैं सावधान आदमी हूँ।\""],
  ["mulla-nasruddin", "मुल्ला ने अपने गधे को रास्ते के किनारे बाँध दिया।\nराहगीर ने पूछा, \"इसे बीच रास्ते में क्यों नहीं बाँधा?\"\nमुल्ला बोले, \"ताकि लोग रास्ता खुला रखने की मेरी समझदारी देखें।\"\nगधा बोला नहीं, पर उसने घास वहीं से खाना शुरू किया।"],
  ["mulla-nasruddin", "दोस्त ने मुल्ला से पूछा, \"आप हर मुश्किल में मुस्कराते कैसे हैं?\"\nमुल्ला बोले, \"पहले देखता हूँ कि रोने से काम बनेगा या नहीं।\"\nदोस्त ने पूछा, \"और अगर न बने?\"\nमुल्ला बोले, \"तो कम-से-कम चेहरा तो काम का बना रहता है।\""],
  [ "mulla-nasruddin", "मुल्ला ने बाज़ार में एक घड़ी खरीदी और दुकानदार से पूछा, “यह समय सही बताती है?”\nदुकानदार बोला, “बिल्कुल, रोज़ दो बार तो सही होती ही है।”\nमुल्ला ने घड़ी वापस रख दी।\n“मुझे ऐसी चीज़ चाहिए जो दिन में दो बार से ज़्यादा काम करे।”" ],
  [ "mulla-nasruddin", "दोस्त ने मुल्ला से पूछा, “आपने छाता क्यों खरीदा, आज तो धूप है?”\nमुल्ला बोले, “मौसम विभाग ने बारिश कही है।”\nदोस्त ने पूछा, “अगर बारिश न हुई?”\nमुल्ला बोले, “तो छाते को धूप से बचाने के लिए इस्तेमाल करूँगा।”" ],
  [ "mulla-nasruddin", "मुल्ला ने पड़ोसी से कहा, “तुम्हारी मुर्गी रोज़ मेरे आँगन में आती है।”\nपड़ोसी बोला, “उसे रास्ता पसंद होगा।”\nमुल्ला ने कहा, “ठीक है, अब अंडे भी रास्ते में ही दे तो आधे मेरे।”\nपड़ोसी ने उसी दिन बाड़ ठीक कर दी।" ],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—दोस्ती और पैसा कैसे बचाएँ।\nदोस्त ने पूछा, \"दोस्ती और पैसा कैसे बचाएँ?\"\nमुल्ला ने जवाब दिया, \"मदद करो और,\nशर्तें साफ़ रखो।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—तुम सच बोलोगे।\nदोस्त ने पूछा, \"तुम सच बोलोगे?\"\nमुल्ला ने जवाब दिया, \"कोशिश करूँगा;\nसवाल भी पूरा पूछिए।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—तुमने घटना देखी।\nदोस्त ने पूछा, \"तुमने घटना देखी?\"\nमुल्ला ने जवाब दिया, \"आधी देखी;\nबाकी हिस्सा गवाहों ने जोड़ दिया।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—तुम्हें सब याद है।\nदोस्त ने पूछा, \"तुम्हें सब याद है?\"\nमुल्ला ने जवाब दिया, \"जो देखा वह याद है;\nजो सुना उसे जाँचने आया हूँ।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—तुम अदालत में देर से क्यों आए।\nदोस्त ने पूछा, \"तुम अदालत में देर से क्यों आए?\"\nमुल्ला ने जवाब दिया, \"न्याय का इंतज़ार सबको था;\nमैं भी कतार में था।\""],
  ["mulla-nasruddin", "मुल्ला ने बाज़ार में दो दुकानदारों को बहस करते देखा।\nएक ने पूछा, \"आप किसकी बात मानेंगे?\"\nमुल्ला बोले, \"पहले दोनों की रसीदें दिखाओ।\"\nदुकानदार बोला, \"मुल्ला जी, आप तो बहस को लेखा-परीक्षा बना देते हैं।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—क्या तुमने दस्तख़त किए।\nदोस्त ने पूछा, \"क्या तुमने दस्तख़त किए?\"\nमुल्ला ने जवाब दिया, \"किए थे;\nअब पढ़कर पता चला क्या लिखा था।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—तुम्हारी गवाही कितनी पक्की है।\nदोस्त ने पूछा, \"तुम्हारी गवाही कितनी पक्की है?\"\nमुल्ला ने जवाब दिया, \"जितनी मेरी याद;\nइसलिए जो नहीं जानता उसे नहीं कहूँगा।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—किसने झगड़ा शुरू किया।\nदोस्त ने पूछा, \"किसने झगड़ा शुरू किया?\"\nमुल्ला ने जवाब दिया, \"पहले आवाज़ किसने ऊँची की यह पता करें,\nफिर कहानी सुनें।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—तुम्हें कोई डर है।\nदोस्त ने पूछा, \"तुम्हें कोई डर है?\"\nमुल्ला ने जवाब दिया, \"झूठ बोलने से है;\nसच कहने में सावधानी चाहिए।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—न्याय कब होगा।\nदोस्त ने पूछा, \"न्याय कब होगा?\"\nमुल्ला ने जवाब दिया, \"जब सवाल से पहले,\nफैसला न लिखा जाए।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—घर छोटा क्यों लिया।\nदोस्त ने पूछा, \"घर छोटा क्यों लिया?\"\nमुल्ला ने जवाब दिया, \"किराया कम है;\nसपने बड़े रखने की जगह मन में है।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—छत टपकती है।\nदोस्त ने पूछा, \"छत टपकती है?\"\nमुल्ला ने जवाब दिया, \"बारिश में घर को भी आसमान,\nसे बातचीत करनी होती है।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—मकान मालिक कैसा है।\nदोस्त ने पूछा, \"मकान मालिक कैसा है?\"\nमुल्ला ने जवाब दिया, \"अच्छा है;\nकिराया समय पर याद दिलाता है।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—दरवाज़ा चरमराता है।\nदोस्त ने पूछा, \"दरवाज़ा चरमराता है।\"\nमुल्ला ने जवाब दिया, \"कम से कम घर आने की,\nसूचना पहले दे देता है।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—घर में खिड़की छोटी क्यों है।\nदोस्त ने पूछा, \"घर में खिड़की छोटी क्यों है?\"\nमुल्ला ने जवाब दिया, \"बाहर की दुनिया देखने को काफी है,\nभागने को नहीं।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—किराया बढ़ गया।\nदोस्त ने पूछा, \"किराया बढ़ गया?\"\nमुल्ला ने जवाब दिया, \"घर बड़ा नहीं हुआ;\nमकान मालिक की उम्मीदें बढ़ गईं।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—दीवार पर निशान किसके हैं।\nदोस्त ने पूछा, \"दीवार पर निशान किसके हैं?\"\nमुल्ला ने जवाब दिया, \"पुराने किरायेदार की यादें;\nमकान मालिक उन्हें रंगना भूल गया।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—घर में शांति है।\nदोस्त ने पूछा, \"घर में शांति है?\"\nमुल्ला ने जवाब दिया, \"हाँ, बस छत बारिश,\nमें तबला बजाती है।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—मकान बदलोगे।\nदोस्त ने पूछा, \"मकान बदलोगे?\"\nमुल्ला ने जवाब दिया, \"पहले इस घर को समझ लूँ;\nयह भी मुझे समझ रहा है।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—अच्छा घर किसे कहेंगे।\nदोस्त ने पूछा, \"अच्छा घर किसे कहेंगे?\"\nमुल्ला ने जवाब दिया, \"जहाँ किराया भी समझ,\nआए और पड़ोसी भी।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—चाय इतनी गरम क्यों है।\nदोस्त ने पूछा, \"चाय इतनी गरम क्यों है?\"\nमुल्ला ने जवाब दिया, \"ताकि बातचीत ठंडी,\nन पड़े।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—किसकी चाय सबसे अच्छी।\nदोस्त ने पूछा, \"किसकी चाय सबसे अच्छी?\"\nमुल्ला ने जवाब दिया, \"जिसकी कीमत पीने के बाद,\nभी याद न रहे।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—दोस्त ने कहा तुम बहुत बोलते हो।\nदोस्त ने पूछा, \"दोस्त ने कहा तुम बहुत बोलते हो।\"\nमुल्ला ने जवाब दिया, \"चाय खत्म होने तक मेरी,\nबात भी उबलती रहती है।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—चाय में चीनी कितनी।\nदोस्त ने पूछा, \"चाय में चीनी कितनी?\"\nमुल्ला ने जवाब दिया, \"जितनी दोस्ती में हो;\nज़्यादा हुई तो स्वाद छिप जाएगा।\""],
  ["mulla-nasruddin", "मुल्ला ने अँधेरे कमरे में लालटेन जलाई।\nपड़ोसी ने पूछा, \"रोशनी किसलिए?\"\nमुल्ला बोले, \"चाबी ढूँढ़ रहा हूँ।\"\nपड़ोसी ने कहा, \"चाबी तो बाहर गिरी थी!\" मुल्ला बोले, \"वहाँ अँधेरा था।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—चायखाने में बहस क्यों हुई।\nदोस्त ने पूछा, \"चायखाने में बहस क्यों हुई?\"\nमुल्ला ने जवाब दिया, \"सबको सही होना था;\nचाय को बस ठंडा होना था।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—किस बात पर हँस रहे हो।\nदोस्त ने पूछा, \"किस बात पर हँस रहे हो?\"\nमुल्ला ने जवाब दिया, \"अपनी पुरानी बात पर;\nनई बात अभी तैयार नहीं।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—चाय का दूसरा दौर।\nदोस्त ने पूछा, \"चाय का दूसरा दौर?\"\nमुल्ला ने जवाब दिया, \"पहले पहला दौर किसने दिया,\nथा उसका हिसाब करें।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—सबसे अच्छा साथी कौन।\nदोस्त ने पूछा, \"सबसे अच्छा साथी कौन?\"\nमुल्ला ने जवाब दिया, \"जो चाय बाँटे और,\nबात ध्यान से सुने।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—चायखाने का राज़ क्या है।\nदोस्त ने पूछा, \"चायखाने का राज़ क्या है?\"\nमुल्ला ने जवाब दिया, \"यहाँ हर कप में सलाह मुफ्त,\nऔर समाधान अलग से मिलता है।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—सिक्का किसका है।\nदोस्त ने पूछा, \"सिक्का किसका है?\"\nमुल्ला ने जवाब दिया, \"ज़मीन का;\nमालिक ढूँढ़ना हो तो आसपास पूछो।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—सिक्का चमक रहा है।\nदोस्त ने पूछा, \"सिक्का चमक रहा है।\"\nमुल्ला ने जवाब दिया, \"शायद किसी ने इसे गिराने,\nसे पहले पॉलिश किया था।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—तुम इसे रखोगे।\nदोस्त ने पूछा, \"तुम इसे रखोगे?\"\nमुल्ला ने जवाब दिया, \"मालिक न मिले तो जरूरतमंद को दूँगा;\nपहले पहचान करूँगा।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—सिक्का एक तरफ़ से घिसा है।\nदोस्त ने पूछा, \"सिक्का एक तरफ़ से घिसा है।\"\nमुल्ला ने जवाब दिया, \"शायद बहुत हाथ बदल चुका;\nअब ईमानदार हाथ देखेगा।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—कितना मूल्य है इसका।\nदोस्त ने पूछा, \"कितना मूल्य है इसका?\"\nमुल्ला ने जवाब दिया, \"सिक्के का कम;\nउसे लौटाने की नीयत का ज़्यादा।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—सिक्का उछालकर फैसला करोगे।\nदोस्त ने पूछा, \"सिक्का उछालकर फैसला करोगे?\"\nमुल्ला ने जवाब दिया, \"छोटे खेल में ठीक;\nबड़े फैसले में दिमाग लगाओ।\""],
  ["mulla-nasruddin", "गाँव के मेले में ज्योतिषी ने मुल्ला का हाथ देखा।\nज्योतिषी बोला, \"आपकी किस्मत बहुत तेज़ है।\"\nमुल्ला ने पूछा, \"तो फिर यह मेरे पीछे क्यों चलती है?\"\nज्योतिषी ने हाथ छोड़ दिया, \"आज फीस किस्मत से ले लेना।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—सिक्का जेब में क्यों रखा।\nदोस्त ने पूछा, \"सिक्का जेब में क्यों रखा?\"\nमुल्ला ने जवाब दिया, \"सुरक्षित रखा है;\nअब मालिक की तलाश भी जारी है।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—किसे इनाम दोगे।\nदोस्त ने पूछा, \"किसे इनाम दोगे?\"\nमुल्ला ने जवाब दिया, \"जिसने खोया है उसे;\nईमानदारी को इनाम की जरूरत नहीं।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—इस घटना से क्या सीखा।\nदोस्त ने पूछा, \"इस घटना से क्या सीखा?\"\nमुल्ला ने जवाब दिया, \"छोटी चीज़ भी सही मालिक तक,\nपहुँचे तो बड़ा काम है।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—शिष्य ने पूछा बुद्धिमान कैसे बनूँ।\nदोस्त ने पूछा, \"शिष्य ने पूछा बुद्धिमान कैसे बनूँ?\"\nमुल्ला ने जवाब दिया, \"पहले सवाल पूरा सुनो;\nजवाब देने की जल्दी कम करो।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—शिष्य ने कहा मैं सब जानता हूँ।\nदोस्त ने पूछा, \"शिष्य ने कहा मैं सब जानता हूँ।\"\nमुल्ला ने जवाब दिया, \"तब सीखने के लिए तुम्हारे पास,\nबहुत कम जगह बची है।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—गलती कैसे पहचानें।\nदोस्त ने पूछा, \"गलती कैसे पहचानें?\"\nमुल्ला ने जवाब दिया, \"परिणाम देखो और अपनी,\nभूमिका से भागो मत।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—शिष्य ने हर बात लिख ली।\nदोस्त ने पूछा, \"शिष्य ने हर बात लिख ली।\"\nमुल्ला ने जवाब दिया, \"अब एक बात,\nकरके भी दिखाओ।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—ज्ञान कहाँ मिलेगा।\nदोस्त ने पूछा, \"ज्ञान कहाँ मिलेगा?\"\nमुल्ला ने जवाब दिया, \"किताब से शुरुआत करो,\nऔर अनुभव से जाँचो।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—शिष्य ने पूछा मौन कब रखें।\nदोस्त ने पूछा, \"शिष्य ने पूछा मौन कब रखें?\"\nमुल्ला ने जवाब दिया, \"जब तुम्हारे शब्द किसी की,\nबात दबा रहे हों।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—सफलता का रहस्य क्या।\nदोस्त ने पूछा, \"सफलता का रहस्य क्या?\"\nमुल्ला ने जवाब दिया, \"तैयारी करो और मौका आए,\nतो बहाना मत बनाओ।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—शिष्य ने कहा गुरु जी मैं उलझ गया।\nदोस्त ने पूछा, \"शिष्य ने कहा गुरु जी मैं उलझ गया।\"\nमुल्ला ने जवाब दिया, \"अच्छा है;\nअब सही सवाल खोजने का समय है।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—सबसे कठिन पाठ कौन-सा।\nदोस्त ने पूछा, \"सबसे कठिन पाठ कौन-सा?\"\nमुल्ला ने जवाब दिया, \"अपनी गलती स्वीकार,\nकरना।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—शिष्य ने पूछा आख़िरी सलाह।\nदोस्त ने पूछा, \"शिष्य ने पूछा आख़िरी सलाह?\"\nमुल्ला ने जवाब दिया, \"हँसो ज़रूर,\nपर किसी की परेशानी पर नहीं।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—तुम अँधेरे में क्या खोज रहे हो।\nदोस्त ने पूछा, \"तुम अँधेरे में क्या खोज रहे हो?\"\nमुल्ला ने जवाब दिया, \"चाबी; रोशनी यहाँ है,\nचाबी शायद वहाँ गिरी।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—लालटेन यहीं क्यों रखी।\nदोस्त ने पूछा, \"लालटेन यहीं क्यों रखी?\"\nमुल्ला ने जवाब दिया, \"जहाँ रोशनी है वहीं खोज आसान है;\nपर चाबी की जगह भी देखनी होगी।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—चाबी मिली।\nदोस्त ने पूछा, \"चाबी मिली?\"\nमुल्ला ने जवाब दिया, \"नहीं; मगर खोजने का तरीका बदलने,\nकी जरूरत समझ आ गई।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—तुमने दिन में क्यों नहीं खोजा।\nदोस्त ने पूछा, \"तुमने दिन में क्यों नहीं खोजा?\"\nमुल्ला ने जवाब दिया, \"दिन में काम था;\nरात में समय मिला, अब गलती समझ आई।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—लोग मदद क्यों नहीं कर रहे।\nदोस्त ने पूछा, \"लोग मदद क्यों नहीं कर रहे?\"\nमुल्ला ने जवाब दिया, \"उन्हें पता नहीं चाबी कैसी है;\nपहले बताना चाहिए।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—लालटेन का तेल खत्म होगा।\nदोस्त ने पूछा, \"लालटेन का तेल खत्म होगा।\"\nमुल्ला ने जवाब दिया, \"तभी तो जल्दी खोजूँगा;\nसमय की भी सीमा है।\""],
  ["mulla-nasruddin", "घड़ीसाज़ ने मुल्ला की पुरानी घड़ी खोलकर रख दी।\nमुल्ला ने पूछा, \"यह रुक क्यों गई?\"\nघड़ीसाज़ बोला, \"अंदर का पुर्जा अटक गया है।\"\nमुल्ला हँसे, \"तो मेरी तरह इसे भी छुट्टी चाहिए।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—तुम्हें जगह याद नहीं।\nदोस्त ने पूछा, \"तुम्हें जगह याद नहीं?\"\nमुल्ला ने जवाब दिया, \"याद है;\nबस मेरी याददाश्त को नक्शा चाहिए।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—लालटेन बुझ गई।\nदोस्त ने पूछा, \"लालटेन बुझ गई।\"\nमुल्ला ने जवाब दिया, \"अब चाबी नहीं मिली तो कम से,\nकम रात का अंत मिल गया।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन के सामने आज एक नया सवाल आ खड़ा हुआ—कहानी का सबक क्या।\nदोस्त ने पूछा, \"कहानी का सबक क्या?\"\nमुल्ला ने जवाब दिया, \"जहाँ चीज़ खोई हो,\nवहीं खोजो; सुविधा की जगह पर नहीं।\""],
  ["mulla-nasruddin", "सुबह मुल्ला नसरुद्दीन अपने गधे को बाज़ार ले जा रहे थे।\nरास्ते में एक आदमी बोला, \"आप गधे पर क्यों नहीं बैठते?\"\nमुल्ला बैठ गए तो दूसरे राहगीर ने कहा, \"बेचारे गधे पर इतना बोझ!\"\nमुल्ला उतरकर बोले, \"इस शहर में गधे से ज़्यादा राय ढोना मुश्किल है।\""],
  ["mulla-nasruddin", "मुल्ला ने पड़ोसी से उधार ली हुई सीढ़ी वापस की।\nपड़ोसी ने पूछा, \"सीढ़ी इतनी साफ़ कैसे हो गई?\"\nमुल्ला बोले, \"उधार की चीज़ लौटाने से पहले साफ़ करनी चाहिए।\"\nपड़ोसी खुश हुआ, फिर मुल्ला ने जोड़ा, \"अब आपकी बारी है—मेरी उधार वाली बाल्टी भी धोकर लौटाइए।\""],
  ["mulla-nasruddin", "बाज़ार में मुल्ला ने दो तरबूज़ उठाकर दुकानदार से भाव पूछा।\nदुकानदार ने कहा, \"दोनों मीठे हैं, बिना काटे पहचान सकता हूँ।\"\nमुल्ला ने एक तरबूज़ कान से लगाया और सिर हिलाया।\nदुकानदार चौंका, \"क्या आवाज़ सुनी?\" मुल्ला बोले, \"अंदर से कह रहा है—मुझे घर ले चलो, यहाँ भरोसा नहीं।\""],
  ["mulla-nasruddin", "काज़ी ने मुल्ला से पूछा कि गवाही देते समय सच बोलने का भरोसा कैसे दिलाएँगे।\nमुल्ला ने कहा, \"मैं वही कहूँगा जो अपनी आँखों से देखा।\"\nकाज़ी ने पूछा, \"और जो नहीं देखा?\"\nमुल्ला बोले, \"उस पर चुप रहूँगा—इसीलिए मेरी कल्पना को गवाह मत बनाइए।\""],
  ["mulla-nasruddin", "मुल्ला ने घर की छत पर लालटेन जलाई और देर तक उसे देखते रहे।\nदोस्त ने पूछा, \"रात में इतनी रोशनी किसलिए?\"\nमुल्ला बोले, \"चाँद बादलों में छिपा है, रास्ता दिखाने को कुछ तो चाहिए।\"\nदोस्त ने कहा, \"पर तुम घर के अंदर हो!\" मुल्ला बोले, \"इसीलिए तो बाहर वालों को रास्ता दिखा रहा हूँ।\""],
  ["mulla-nasruddin", "एक यात्री ने मुल्ला से पूछा कि सराय तक पहुँचने का सबसे छोटा रास्ता कौन-सा है।\nमुल्ला ने दूर जाती पगडंडी की ओर इशारा किया।\nयात्री ने पूछा, \"क्या वह सचमुच छोटा है?\"\nमुल्ला बोले, \"मुझे दूरी नहीं मालूम; मगर रास्ता पूछते-पूछते आप आधा दिन बचा चुके हैं—अब चल भी पड़िए।\""],
  ["mulla-nasruddin", "मुल्ला ने दर्जी को नया कुरता सिलने के लिए कपड़ा दिया।\nदर्जी ने नाप लिया और बोला, \"कल तैयार मिलेगा।\"\nएक सप्ताह बाद मुल्ला लौटे तो कुरता अब भी अधूरा था।\nदर्जी ने कहा, \"धागा कम पड़ गया।\" मुल्ला बोले, \"कपड़ा मेरा था; इंतज़ार आपने अपने हिसाब से क्यों काटा?\""],
  ["mulla-nasruddin", "गाँव के कुएँ पर मुल्ला ने बाल्टी नीचे उतारी, मगर रस्सी छोटी निकली।\nलोग हँसे, \"इतनी छोटी रस्सी लेकर पानी भरने आए हो?\"\nमुल्ला ने कहा, \"रस्सी की लंबाई जाँचने आया था।\"\nएक बुज़ुर्ग ने पूछा, \"पानी नहीं चाहिए?\" मुल्ला बोले, \"चाहिए, पर आज पता चला कि कुआँ मेरी योजना से गहरा है।\""],
  ["mulla-nasruddin", "मुल्ला ने दोस्त को एक खाली डिब्बा भेंट किया।\nदोस्त ने ढक्कन खोलकर पूछा, \"इसमें है क्या?\"\nमुल्ला बोले, \"तुम्हारे लिए जगह रखी है।\"\nदोस्त हँसा, \"किस चीज़ की जगह?\" मुल्ला ने कहा, \"उस सलाह की, जो तुम हर मुलाक़ात में बिना माँगे दे जाते हो।\""],
  ["mulla-nasruddin", "एक किसान ने मुल्ला से पूछा कि बारिश कब होगी।\nमुल्ला ने आसमान देखा और कहा, \"जब बादल पानी लेकर आएँगे।\"\nकिसान बोला, \"यह तो हर कोई जानता है; कोई पक्का अनुमान दो।\"\nमुल्ला ने जवाब दिया, \"पक्का अनुमान चाहिए तो छाता साथ रखो—मौसम से बहस मत करो।\""],
  ["mulla-nasruddin", "मुल्ला नसरुद्दीन ने बाज़ार में अपना गधा बेचने की घोषणा की।\nखरीदार ने पूछा, \"यह इतना शांत क्यों खड़ा है?\"\nमुल्ला बोले, \"इसे बोलने की आदत नहीं,\nइसीलिए घर में इसकी सबसे ज़्यादा इज़्ज़त है।\""],
  ["mulla-nasruddin", "गाँव के मुखिया ने मुल्ला से पूछा, \"सबसे समझदार सलाहकार कौन होता है?\"\nमुल्ला ने खाली कुर्सी आगे खिसका दी।\nमुखिया बोले, \"यह तो खाली है!\"\nमुल्ला हँसे, \"जो हर बात पर नहीं बोलता, उसे सुनना आसान होता है।\""],
  ["mulla-nasruddin", "मुल्ला ने खेत में दो बीज बोए और दोनों पर अलग-अलग निशान लगाए।\nपड़ोसी ने पूछा, \"इतनी सावधानी क्यों?\"\nमुल्ला बोले, \"एक मेहनत का है, दूसरा उम्मीद का।\"\nपड़ोसी बोला, \"फसल किससे होगी?\" मुल्ला बोले, \"पानी दोनों को चाहिए।\""],
  ["mulla-nasruddin", "एक दुकानदार ने मुल्ला को उधार की लंबी सूची दिखाई।\nमुल्ला ने सूची के नीचे अपना नाम ढूँढ़ा।\nदुकानदार बोला, \"आपका नाम सबसे ऊपर है!\"\nमुल्ला बोले, \"तो कम से कम इस हिसाब में मेरी तरक्की तो हुई।\""],
  ["mulla-nasruddin", "मुल्ला ने पड़ोसी के दरवाज़े पर दस्तक देकर सीढ़ी माँगी।\nपड़ोसी ने पूछा, \"किस काम के लिए?\"\nमुल्ला बोले, \"छत पर चढ़कर मौसम देखना है।\"\nपड़ोसी ने कहा, \"खिड़की से देख लो!\" मुल्ला बोले, \"वहाँ से मौसम दिखता है, पड़ोसी नहीं।\""],
  ["mulla-nasruddin", "दरबार में मंत्री ने दावा किया कि गाँव की सड़क बिल्कुल सीधी है।\nमुल्ला ने नक्शा उल्टा पकड़कर ध्यान से देखा।\nमंत्री ने पूछा, \"क्या कमी मिली?\"\nमुल्ला बोले, \"रास्ता सीधा है, बस नक्शे को मंज़िल तक पहुँचने की जल्दी है।\""],
  ["mulla-nasruddin", "मुल्ला ने अपने गधे के गले में छोटी घंटी बाँध दी।\nराहगीर ने पूछा, \"इससे क्या फायदा होगा?\"\nमुल्ला बोले, \"रास्ते में वह दिखे न दिखे, उसकी खबर मिलती रहेगी।\"\nराहगीर बोला, \"और अगर घंटी वाला गधा ही रुक जाए?\" मुल्ला बोले, \"तब खबर भी आराम करेगी।\""],
  ["mulla-nasruddin", "गाँव के पुस्तकालय में मुल्ला ने मोटी किताब लौटाई।\nलाइब्रेरियन ने पूछा, \"पूरी पढ़ ली?\"\nमुल्ला बोले, \"शीर्षक से अंत तक देख ली।\"\nलाइब्रेरियन ने कहा, \"अंदर के पन्ने?\" मुल्ला बोले, \"उनसे अगली मुलाक़ात तय है।\""],
  ["mulla-nasruddin", "मुल्ला ने कुएँ के पास रस्सी की लंबाई नापी।\nकिसान ने पूछा, \"पानी कितना गहरा है?\"\nमुल्ला बोले, \"रस्सी पूरी नीचे गई, पर जवाब ऊपर नहीं आया।\"\nकिसान हँसा, \"तो बाल्टी डालो!\" मुल्ला बोले, \"यही तो अगला प्रयोग है।\""],
  ["mulla-nasruddin", "एक यात्री ने मुल्ला से पूछा, \"इस गाँव में सबसे छोटा रास्ता कौन-सा है?\"\nमुल्ला ने उसे चौपाल की ओर भेज दिया।\nयात्री लौटकर बोला, \"वहाँ तो सबने अलग रास्ता बताया!\"\nमुल्ला बोले, \"अब तुम्हें मंज़िल के साथ गाँव की राय भी मिल गई।\""],
  ["rajasthani","हाट में एक दुकानदार ऊँट की घंटी बेच रह्यो थो।\nग्राहक पूछ्यो, \"ई घंटी कितनी दूर सूं सुनाई देसी?\"\nदुकानदार बोल्यो, \"ऊँट नै तो पास सूं, पड़ोसी नै पूरी रात।\"\nग्राहक हँस पड़्यो, \"फेर घंटी कम, चेतावनी ज्यादा है।\""],
  ["rajasthani","धोरां में पधार्या मेहमान नै पानी मांग्यो।\nमेजबान ने छाछ अर पानी दोनों धर दिया।\nमेहमान पूछ्यो, \"पहले काई पीऊँ?\"\nमेजबान बोल्यो, \"जिको मन कहे, पण गिलास खाली करजो—रेगिस्तान में बूँद भी मेहमान है।\""],
  ["rajasthani","गाँव री पंचायत में सड़क रो नक्शो खुल्यो।\nएक बुजुर्ग पूछ्या, \"रास्तो सीधो क्यूँ नहीं?\"\nइंजीनियर बोल्यो, \"बीच में पुराणो कुओं आवे।\"\nबुजुर्ग हँसकै कह्या, \"कुएँ नै बचावो, पण सड़क नै पहेली मत बनावो।\""],
  ["rajasthani","एक सेठजी दुकान पर नया पंखो लगवायो।\nगर्मी में ग्राहक पूछ्यो, \"हवा कितणी तेज है?\"\nसेठजी बोल्या, \"इतणी कि बिल देखकै ठंडी पड़ जासी।\"\nग्राहक ने पंखे सूं ज्यादा हिसाब देख्यो।"],
  ["rajasthani","मेले में कठपुतली वाला राजा रो खेल दिखावै।\nबच्चो पूछ्यो, \"राजा खुद क्यूँ नहीं बोलै?\"\nकलाकार बोल्यो, \"डोर मेरे हाथ में है।\"\nपास बैठ्यो काका बोल्यो, \"फेर तो दरबार में भी ई कला काम आवे।\""],
  ["rajasthani","एक किसान मंडी में बाजरे रो भाव पूछण गयो।\nव्यापारी बोल्यो, \"आज भाव ऊपर है।\"\nकिसान पूछ्यो, \"फसल भी ऊपर उगाऊँ के?\"\nव्यापारी हँसकै बोल्यो, \"भाव ऊपर, किसान री उम्मीद जमीन पर।\""],
  ["rajasthani","बारात में घोड़ी सजाई गई अर ढोल बजण लाग्या।\nदूल्हे रो दोस्त नाचतो-नाचतो थक गयो।\nकिसी ने पूछ्यो, \"थक गयो के?\"\nवो बोल्यो, \"ना, बस घोड़ी सूं पहले मंजिल पर पहुँचना चाहूँ।\""],
  ["rajasthani","पगड़ी बांधता समय बालक ने दादाजी सूं पूछ्यो, \"ई इतनी लंबी क्यूँ?\"\nदादाजी बोल्या, \"मान-सम्मान री निशानी है।\"\nबालक कह्यो, \"फेर स्कूल में छोटी पगड़ी पहनूँ?\"\nदादाजी हँसकै बोल्या, \"पहले होमवर्क रो मान रख।\""],
  ["rajasthani","गाँव में पानी बचावण री बैठक बुलाई गई।\nसबने लंबा भाषण दियो अर घड़े खाली रह्या।\nएक दादी उठी अर नल बंद कर दियो।\nबोली, \"बातां बाद में, पहले टपकतो पानी रोक्यो।\""],
  ["rajasthani","ऊँट वाला सैलानी नै रेगिस्तान घुमावै ले गयो।\nसैलानी पूछ्यो, \"ऊँट तेज चलै है?\"\nऊँट वाले बोल्यो, \"जब मन होवे।\"\nसैलानी हँसकै कह्यो, \"फेर तो ई भी छुट्टी मंजूर करवावै बिना नहीं चलै।\""],
  ["rajasthani", "चौपाल पर काका पूछे, \"घणी गर्मी पड़ री है, छाँव किधर मिलसी?\"\nछोरो बोल्यो, \"पीपळ रे नीचे।\"\nकाका पहुँचा तो पेड़ कट्यो मिल्यो।\nछोरो कह्यो, \"अब छाँव यादां में मिलसी, काका।\""],
  ["rajasthani", "ऊँटवाले ने पूछा, \"म्हारो ऊँट आज चालै क्यूँ कोनी?\"\nसाथी बोल्यो, \"शायद रास्तो लंबो लाग रह्यो है।\"\nऊँटवाले ने कहा, \"रास्तो तो रोज़ इतनो ही है।\"\nसाथी हँस्यो, \"आज ऊँट ने भी छुट्टी माँग ली होगी।\""],
  ["rajasthani", "मेले में दुकानदार बोल्यो, \"आओ सा, सबसे सस्ती पगड़ी ले जाओ।\"\nग्राहक ने पूछा, \"रंग कितने दिन टिकसी?\"\nदुकानदार बोला, \"जब तक धूप में रहसी।\"\nग्राहक हँस्यो, \"तो पगड़ी नहीं, बादल भी साथ देजो।\""],
  ["rajasthani", "ढाणी में छोरे ने काका तै पूछ्यो, \"बिजली कब आवैगी?\"\nकाका बोल्यो, \"जब लाइन ठीक होसी।\"\nछोरो कह्यो, \"लाइन तो ठीक बताई थी।\"\nकाका हँस्यो, \"फेर खबर गलत होसी, तार नै पूछ ले।\""],
  ["rajasthani", "मेला में काकी ने दुकानदार तै पूछ्यो, \"ई मटकी कितनी मजबूत है?\"\nदुकानदार बोल्यो, \"घणी मजबूत, पानी भर लो।\"\nकाकी कहे, \"पहले तू नीचे धर, फेर भरोसो करूँ।\"\nदुकानदार बोला, \"सही बात, भरोसो भी धीरे-धीरे भरै।\""],
  ["rajasthani", "ऊँटवाले ने छोरे तै पूछ्यो, \"रास्तो याद है?\"\nछोरो बोल्यो, \"हाँ, पिछली बार भी इधर तै गया था।\"\nऊँटवाला हँस्यो, \"तब तो ऊँट नै भी याद होसी।\"\nऊँट बैठ गयो—उसे पिछली यात्रा का आराम याद आ गयो।"],
  [ "rajasthani", "चौपाल पर काकसा बोले, “आज ऊँट इतना धीरे क्यूँ चालै?”\nछोरो बोल्यो, “रास्तो लंबो है, आराम सूं जावै।”\nकाकसा हँस्या, “ऊँट नै भी छुट्टी चाहिए?”\nछोरो बोल्यो, “जी, थारो भाषण सुन कै तो सबने चाहिए।”" ],
  [ "rajasthani", "एक मेहमान ने पूछा, “यहाँ पानी इतना संभालकर क्यों रखते हैं?”\nगाँव के बुज़ुर्ग बोले, “रेगिस्तान में हर बूँद की कीमत समझ आती है।”\nमेहमान ने गिलास आधा छोड़ दिया।\nबुज़ुर्ग बोले, “अब बाकी आधा भी समझदारी से पीज्यो।”" ],
  [ "rajasthani", "ढाणी में छोरे ने नया मोबाइल दिखायो।\nदादा पूछ्या, “इसमें खेत दिखे है?”\nछोरो बोल्यो, “नक्शे में सब दिखे है।”\nदादा हँस्या, “तो बादल भी दिखा दे, पानी कब आवैला?”" ],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—ऊँट से क्या सीख मिली।\nएक ने पूछा, \"ऊँट से क्या सीख मिली?\"\nदूसरे ने जवाब दिया, \"बोझ उठावो पर अपनी,\nचाल मत भूलो।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—मेहमान कितने दिन रुकेंगे।\nएक ने पूछा, \"मेहमान कितने दिन रुकेंगे?\"\nदूसरे ने जवाब दिया, \"घरवाली बोली,\nपूछ मत; बस चाय और बिस्तर का हिसाब बढ़ा ले।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—मेहमान के लिए क्या बनावें।\nएक ने पूछा, \"मेहमान के लिए क्या बनावें?\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nजो घर में है वही; प्यार में मेन्यू की कमी ना पड़ै।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—इतनी मिठाई क्यूँ बनाई।\nएक ने पूछा, \"इतनी मिठाई क्यूँ बनाई?\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nमेहमान आवे तो थाली में खुशी भी परोसनी पड़ै।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—मेहमान कब पहुँचेंगे।\nएक ने पूछा, \"मेहमान कब पहुँचेंगे?\"\nदूसरे ने जवाब दिया, \"बेटा बोल्यो,\nरास्ते में हैं; राजस्थान में रास्ता भी कहानी सुनावै।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—बिस्तर कहाँ लगावें।\nएक ने पूछा, \"बिस्तर कहाँ लगावें?\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nजहाँ जगह मिले; मेहमान को अपनापन चाहिए, नक्शो नहीं।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—कौन चाय बनावैगा।\nएक ने पूछा, \"कौन चाय बनावैगा?\"\nदूसरे ने जवाब दिया, \"घरवाली बोली,\nजो पहले बोले मैं बना दूँ, वही बनावैगा।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—मेहमान ने कहा बस पानी चाहिए।\nएक ने पूछा, \"मेहमान ने कहा बस पानी चाहिए।\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nपानी के साथ थोड़ा नाश्ता भी आ जावै; रीति है सा।\""],
  ["rajasthani", "घर में त्योहार की तैयारी के लिए मिठाइयाँ सजाई गईं।\nपोते ने पूछा, \"इतनी मिठाई किसके लिए?\"\nदादी बोलीं, \"रिश्तेदारों के लिए भी और पड़ोसियों के लिए भी।\"\nपोता बोला, \"मेरे हिस्से की गिनती अलग से कर लेना।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—मेहमान जल्दी जा रहे हैं।\nएक ने पूछा, \"मेहमान जल्दी जा रहे हैं।\"\nदूसरे ने जवाब दिया, \"बेटा बोल्यो,\nचाय पीकर जावो; यहाँ विदाई भी धीरे-धीरे होवै।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—आतिथ्य का राज़ क्या।\nएक ने पूछा, \"आतिथ्य का राज़ क्या?\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nथाली से पहले मुस्कान परोस।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—आज बादल क्यूँ नहीं आए।\nएक ने पूछा, \"आज बादल क्यूँ नहीं आए?\"\nदूसरे ने जवाब दिया, \"शायद मौसम ने भी छुट्टी,\nका आवेदन दे राख्यो है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—बरखा कब होगी।\nएक ने पूछा, \"बरखा कब होगी?\"\nदूसरे ने जवाब दिया, \"चौपाल पर जवाब आयो,\nबादल से पूछो; किसान तो रोज़ तैयार बैठो है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—हवा तेज़ चलै है।\nएक ने पूछा, \"हवा तेज़ चलै है।\"\nदूसरे ने जवाब दिया, \"बुज़ुर्ग बोल्या,\nखिड़की बंद कर; मौसम को घर का रास्तो पता है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—गर्मी इतनी क्यूँ।\nएक ने पूछा, \"गर्मी इतनी क्यूँ?\"\nदूसरे ने जवाब दिया, \"एक बोल्यो,\nसूरज ने आज ओवरटाइम लिखवा लियो।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—मौसम का भरोसो है।\nएक ने पूछा, \"मौसम का भरोसो है?\"\nदूसरे ने जवाब दिया, \"किसान भरोसो रखै भी है और,\nबीज बचाकर भी रखै है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—बारिश आई तो खेत खुश होंगे।\nएक ने पूछा, \"बारिश आई तो खेत खुश होंगे?\"\nदूसरे ने जवाब दिया, \"खेत भी और किसान की,\nचिंता भी थोड़ी कम होगी।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—बादल गरजे पर बरसे नहीं।\nएक ने पूछा, \"बादल गरजे पर बरसे नहीं।\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nकुछ लोग भाषण ज़्यादा और काम कम करै हैं।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—सर्दी में ऊन कहाँ से लावें।\nएक ने पूछा, \"सर्दी में ऊन कहाँ से लावें?\"\nदूसरे ने जवाब दिया, \"चौपाल ने कहा,\nपहले स्वेटर निकाल; मौसम से बहस बाद में करियो।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—मौसम की खबर कौन सही दे।\nएक ने पूछा, \"मौसम की खबर कौन सही दे?\"\nदूसरे ने जवाब दिया, \"आसमान देखो और मौसम,\nविभाग भी सुनो।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—चौपाल का निष्कर्ष क्या।\nएक ने पूछा, \"चौपाल का निष्कर्ष क्या?\"\nदूसरे ने जवाब दिया, \"मौसम बदलै,\nपर तैयारी और पड़ोसी की मदद काम आवै।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—हवेली इतनी बड़ी क्यूँ है।\nएक ने पूछा, \"हवेली इतनी बड़ी क्यूँ है?\"\nदूसरे ने जवाब दिया, \"गाइड बोल्यो,\nपरिवार बड़ा था; अब फोटो खींचने वाले ज़्यादा हैं।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—दीवारों पर चित्र किसने बनाए।\nएक ने पूछा, \"दीवारों पर चित्र किसने बनाए?\"\nदूसरे ने जवाब दिया, \"गाइड बोल्यो,\nकारीगर ने; आज भी रंग उनकी मेहनत की कहानी कहै।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—यह झरोखा किस काम आवै।\nएक ने पूछा, \"यह झरोखा किस काम आवै?\"\nदूसरे ने जवाब दिया, \"गाइड बोल्यो,\nहवा और नज़ारे दोनों; पुरखों ने वेंटिलेशन भी कला से किया।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—हवेली में लिफ्ट है।\nएक ने पूछा, \"हवेली में लिफ्ट है?\"\nदूसरे ने जवाब दिया, \"गाइड हँस्यो,\nसीढ़ियाँ हैं; इतिहास को थोड़ा पैदल देखो।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—इतने कमरे किसके थे।\nएक ने पूछा, \"इतने कमरे किसके थे?\"\nदूसरे ने जवाब दिया, \"गाइड बोल्यो,\nपरिवार के; अब हर कमरा पर्यटक की जिज्ञासा का है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—दीवार पर दरार क्यूँ।\nएक ने पूछा, \"दीवार पर दरार क्यूँ?\"\nदूसरे ने जवाब दिया, \"गाइड बोल्यो,\nसमय का निशान है; मरम्मत से पहले इतिहास समझो।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—सबसे सुंदर हिस्सा कौन-सा।\nएक ने पूछा, \"सबसे सुंदर हिस्सा कौन-सा?\"\nदूसरे ने जवाब दिया, \"गाइड बोल्यो,\nवह जहाँ रोशनी आती है और कहानी ठहर जाती है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—यह दरवाज़ा इतना भारी क्यूँ।\nएक ने पूछा, \"यह दरवाज़ा इतना भारी क्यूँ?\"\nदूसरे ने जवाब दिया, \"गाइड बोल्यो,\nलकड़ी मजबूत है; पुराने समय में सुरक्षा भी शिल्प थी।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—हवेली का रखरखाव कौन करे।\nएक ने पूछा, \"हवेली का रखरखाव कौन करे?\"\nदूसरे ने जवाब दिया, \"गाइड बोल्यो,\nमालिक, कारीगर और हम सबकी जिम्मेदारी है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—पर्यटक ने क्या सीखा।\nएक ने पूछा, \"पर्यटक ने क्या सीखा?\"\nदूसरे ने जवाब दिया, \"कि विरासत सिर्फ़ देखने की चीज़ नहीं,\nसँभालने की जिम्मेदारी भी है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—बाटी इतनी सख्त क्यूँ है।\nएक ने पूछा, \"बाटी इतनी सख्त क्यूँ है?\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nधैर्य से तोड़; हर स्वाद जल्दी में नहीं खुलै।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—दाल में घी कितना डालें।\nएक ने पूछा, \"दाल में घी कितना डालें?\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nस्वाद जितना माँगे; पर थाली में संतुलन भी रख।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—चूरमा किसने बनाया।\nएक ने पूछा, \"चूरमा किसने बनाया?\"\nदूसरे ने जवाब दिया, \"बेटी बोली,\nमैंने; दादी बोली, मेहनत मीठी है और गुड़ भी।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—रसोई में धुआँ क्यूँ है।\nएक ने पूछा, \"रसोई में धुआँ क्यूँ है?\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nलकड़ी की आँच है; फोन की रेसिपी से ज़्यादा अनुभव काम आवै।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—बाटी कब तैयार होगी।\nएक ने पूछा, \"बाटी कब तैयार होगी?\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nजब बाहर से सुनहरी और भीतर से पकी हो।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—मेहमान ने और माँगा।\nएक ने पूछा, \"मेहमान ने और माँगा।\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nपहले पानी पी ले; फिर भूख का फैसला करियो।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—मिर्च तेज़ है।\nएक ने पूछा, \"मिर्च तेज़ है?\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nस्वाद में दम है; थोड़ा छाछ भी रख ले।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—कौन-सी थाली सही है।\nएक ने पूछा, \"कौन-सी थाली सही है?\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nजिसमें मेहनत का सम्मान और सबके लिए हिस्सा हो।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—खाना इतना स्वादिष्ट कैसे।\nएक ने पूछा, \"खाना इतना स्वादिष्ट कैसे?\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nनाप से सामग्री और मन से सेवा।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—सबसे अच्छा पकवान कौन।\nएक ने पूछा, \"सबसे अच्छा पकवान कौन?\"\nदूसरे ने जवाब दिया, \"दादी बोली,\nजो सबको साथ बैठाकर खिलाए।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—कठपुतली बोलती कैसे है।\nएक ने पूछा, \"कठपुतली बोलती कैसे है?\"\nदूसरे ने जवाब दिया, \"कलाकार बोल्यो,\nडोर मेरे हाथ में है; आवाज़ कहानी की है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—राजा वाली कठपुतली क्यों हँस रही।\nएक ने पूछा, \"राजा वाली कठपुतली क्यों हँस रही?\"\nदूसरे ने जवाब दिया, \"कलाकार बोल्यो,\nउसे पता है आज दरबार में सच बोलना सुरक्षित है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—कठपुतली गिर गई तो।\nएक ने पूछा, \"कठपुतली गिर गई तो?\"\nदूसरे ने जवाब दिया, \"कलाकार बोल्यो,\nउठा देंगे; कहानी में भी किरदार संभलते हैं।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—बच्चे सबसे ज़्यादा किस पर हँसे।\nएक ने पूछा, \"बच्चे सबसे ज़्यादा किस पर हँसे?\"\nदूसरे ने जवाब दिया, \"जो कठपुतली सवाल पूछे और जवाब,\nखुद से भी सुन ले।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—डोर कितनी लंबी है।\nएक ने पूछा, \"डोर कितनी लंबी है?\"\nदूसरे ने जवाब दिया, \"कलाकार बोल्यो,\nइतनी कि किरदार चले; इतनी नहीं कि कहानी भटके।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—खेल कब खत्म होगा।\nएक ने पूछा, \"खेल कब खत्म होगा?\"\nदूसरे ने जवाब दिया, \"कलाकार बोल्यो,\nजब तालियाँ रुकें; बच्चों की हँसी अभी बाकी है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—कठपुतली का कपड़ा किसने सिला।\nएक ने पूछा, \"कठपुतली का कपड़ा किसने सिला?\"\nदूसरे ने जवाब दिया, \"कारीगर ने;\nकलाकार बोला, मंच पर हर हाथ की मेहनत दिखती है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—राजा की कठपुतली ने क्या कहा।\nएक ने पूछा, \"राजा की कठपुतली ने क्या कहा?\"\nदूसरे ने जवाब दिया, \"कि सत्ता की डोर जनता के,\nभरोसे से बँधी रहती है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—सबसे कठिन किरदार कौन।\nएक ने पूछा, \"सबसे कठिन किरदार कौन?\"\nदूसरे ने जवाब दिया, \"वह जो हँसते हुए,\nसच बोल दे।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—मेले की सीख क्या।\nएक ने पूछा, \"मेले की सीख क्या?\"\nदूसरे ने जवाब दिया, \"कला छोटी डोर से भी,\nबड़ी बात कह सकती है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—फसल देखकर किसान खुश क्यूँ है।\nएक ने पूछा, \"फसल देखकर किसान खुश क्यूँ है?\"\nदूसरे ने जवाब दिया, \"क्योंकि मेहनत रंग लाई;\nअब सही दाम की बारी है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—खेत में पानी कितना चाहिए।\nएक ने पूछा, \"खेत में पानी कितना चाहिए?\"\nदूसरे ने जवाब दिया, \"जितना फसल माँगे;\nअंदाज़े से नहर नहीं चलती।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—बीज कहाँ से लिया।\nएक ने पूछा, \"बीज कहाँ से लिया?\"\nदूसरे ने जवाब दिया, \"जाँची हुई दुकान से;\nभरोसा भी प्रमाण देखकर किया।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—मंडी में भाव क्या है।\nएक ने पूछा, \"मंडी में भाव क्या है?\"\nदूसरे ने जवाब दिया, \"मेहनत का दाम सही मिले,\nतो हिसाब पूरा हो।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—खेत में पक्षी क्यों आए।\nएक ने पूछा, \"खेत में पक्षी क्यों आए?\"\nदूसरे ने जवाब दिया, \"फसल देख कर;\nकिसान ने कहा थोड़ा हिस्सा उनका भी है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—मिट्टी कैसी है।\nएक ने पूछा, \"मिट्टी कैसी है?\"\nदूसरे ने जवाब दिया, \"मेहनत माँगती है;\nपर सही देखभाल का जवाब देती है।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—फसल खराब हुई तो।\nएक ने पूछा, \"फसल खराब हुई तो?\"\nदूसरे ने जवाब दिया, \"बीमा, सलाह और समय पर मदद—\nतीनों का सहारा चाहिए।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—सबसे अच्छी खाद कौन-सी।\nएक ने पूछा, \"सबसे अच्छी खाद कौन-सी?\"\nदूसरे ने जवाब दिया, \"जो मिट्टी की ज़रूरत,\nसमझकर डाली जाए।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—किसान कब आराम करेगा।\nएक ने पूछा, \"किसान कब आराम करेगा?\"\nदूसरे ने जवाब दिया, \"जब उपज बिके और भुगतान,\nसमय पर घर पहुँचे।\""],
  ["rajasthani", "राजस्थान की चौपाल पर आज इस बात की चर्चा चली—खेती का गर्व क्या है।\nएक ने पूछा, \"खेती का गर्व क्या है?\"\nदूसरे ने जवाब दिया, \"धरती सँभालना और सबके,\nलिए अन्न उगाना।\""],
  ["rajasthani", "जैसलमेर के एक दुकानदार ने अपनी दुकान के बाहर लिखा—“यहाँ ठंडी हवा मिलती है।”\nपर्यटक ने पूछा, “कूलर कहाँ है?”\nदुकानदार बोला, “कूलर तो नहीं, पर दुकान की छाँव पक्की है।”\nपर्यटक ने कहा, “मुझे ठंडी हवा चाहिए थी।”\nदुकानदार मुस्कराया, “रेगिस्तान में उम्मीद भी छाँव देखकर करनी चाहिए।”"],
  ["rajasthani", "बीकानेर के हलवाई ने नई मिठाई का नाम रखा—“शाही बादल।”\nग्राहक ने पूछा, “इसमें खास क्या है?”\nहलवाई बोला, “नाम सुनते ही मुँह में मिठास आ जाती है।”\nग्राहक ने एक टुकड़ा चखा और बोला, “स्वाद तो अच्छा है, पर बादल कहाँ?”\nहलवाई ने कहा, “वह दाम देखकर आपकी आँखों में आ जाएगा।”"],
  ["rajasthani", "पुष्कर मेले में ऊँट सजाने की प्रतियोगिता चल रही थी।\nएक मालिक ने अपने ऊँट को इतने गहने पहनाए कि वह चलना भूल गया।\nनिर्णायक ने पूछा, “इतनी सजावट क्यों?”\nमालिक बोला, “इनाम जीतना है।”\nऊँट बैठ गया; मालिक बोला, “लगता है इसे भी मंच पर बैठकर भाषण देना है।”"],
  ["rajasthani", "जोधपुर में एक पर्यटक ने नीले घरों की तस्वीर लेते हुए पूछा, “सबने घर नीले क्यों रंगे?”\nगाइड बोला, “यहाँ रंग से पहचान बनती है।”\nपर्यटक ने कहा, “तो मेरा होटल कैसे पहचानूँ?”\nगाइड हँसा, “जिस घर के बाहर आपका बिल लगा है, वही आपका है।”"],
  ["rajasthani", "गाँव के मेले में कठपुतली कलाकार ने राजा और मंत्री का खेल दिखाया।\nबच्चे ने पूछा, “मंत्री हमेशा राजा की हाँ में हाँ क्यों मिलाता है?”\nकलाकार बोला, “कठपुतली की डोर ऊपर वाले के हाथ में होती है।”\nबच्चा बोला, “तो राजा की डोर किसके हाथ में?”\nकलाकार मुस्कराया, “यह सवाल बड़े लोग पूछते हैं, बेटा।”"],
  ["rajasthani", "एक किसान ने बाजरे की फसल देखकर राहत की साँस ली।\nशहर से आए रिश्तेदार ने पूछा, “यहाँ पिज़्ज़ा का आटा कहाँ मिलेगा?”\nकिसान ने मुट्ठी भर बाजरा दिखाया, “पहले इसे पहचानो।”\nरिश्तेदार बोला, “यह तो देसी अनाज है!”\nकिसान हँसा, “हाँ, और पेट भरने के बाद ही तुम्हारी विदेशी भूख जागेगी।”"],
  ["rajasthani", "उदयपुर की झील में नाविक ने पर्यटक को जीवन-जैकेट दी।\nपर्यटक बोला, “तस्वीर में यह अच्छा नहीं लगेगा।”\nनाविक ने कहा, “तस्वीर बाद में भी खिंच जाएगी।”\nपर्यटक ने पूछा, “इतनी सावधानी क्यों?”\nनाविक बोला, “झील खूबसूरत है, पर उसे आपकी सेल्फ़ी से कोई मतलब नहीं।”"],
  ["rajasthani", "गाँव के स्कूल में अध्यापक ने पूछा, “राजस्थान की सबसे बड़ी सीख क्या है?”\nएक छात्र बोला, “पानी बचाना।”\nदूसरा बोला, “मेहमान का आदर करना।”\nतीसरे ने कहा, “गर्मी में छाँव ढूँढ़ना।”\nअध्यापक ने सिर हिलाया; पीछे से आवाज़ आई, “और परीक्षा में नकल नहीं—क्योंकि पर्ची भी पसीने से भीग जाती है!”"],
  ["rajasthani", "एक कुम्हार ने नए घड़े पर लिखा—“ठंडा पानी, बिना बिजली।”\nग्राहक ने पूछा, “गारंटी कितने दिन की?”\nकुम्हार बोला, “जब तक घड़ा सलामत है।”\nग्राहक ने कहा, “अगर पानी ठंडा न हुआ?”\nकुम्हार ने जवाब दिया, “पहले उसे भरकर छाँव में रखो; घड़ा जादूगर नहीं, कारीगर की मेहनत है।”"],
  ["rajasthani", "नागौर के पशु मेले में एक व्यापारी ने अपने बैल की खूब तारीफ़ की।\nखरीदार ने पूछा, “यह कितना तेज़ चलता है?”\nव्यापारी बोला, “खेत में काम के समय सबसे आगे।”\nखरीदार ने कहा, “और घर लौटते समय?”\nव्यापारी हँसा, “तब इसे भी पता रहता है कि चारा घर पर मिलेगा।”"],
  ["rajasthani", "जैसलमेर में मेहमान ने पूछा, \"इतनी दूर से पानी कैसे लाते हैं?\"\nमेज़बान बोला, \"थोड़ी योजना और बहुत धीरज से, सा।\"\nमेहमान ने कहा, \"आपकी पानी-बचत की सीख तो कमाल है।\"\nमेज़बान हँसा, \"रेगिस्तान में नल खुला छोड़ना मज़ाक नहीं, भूल है।\""],
  ["rajasthani", "बीकानेर के हलवाई से ग्राहक ने पूछा, \"भुजिया इतनी मशहूर कैसे हुई?\"\nहलवाई बोला, \"मसाला सही, बेसन सही और हाथ में हुनर, सा।\"\nग्राहक ने एक पैकेट और माँगा।\nहलवाई मुस्कराया, \"अब राज़ समझ गए; अगला पैकेट भी स्वाद के नाम पर!\""],
  ["rajasthani", "गाँव में मेहमान ने पूछा, \"आप लोग हर बात पर पधारो सा क्यों कहते हैं?\"\nमेज़बान बोला, \"क्योंकि दरवाज़ा खुला रखना हमारी खुशी है।\"\nमेहमान ने कहा, \"तो मैं कल फिर आ जाऊँ?\"\nमेज़बान हँसा, \"आवजो सा, पर इस बार खाली डिब्बा मत लाना—मिठाई भरकर ले जाना।\""],
  ["rajasthani", "कुम्हार ने शहर से आए युवक को मिट्टी का घड़ा दिखाया।\nयुवक बोला, \"इसमें फ्रिज जैसी ठंडक कैसे आती है?\"\nकुम्हार ने समझाया, \"मिट्टी साँस लेती है, पानी धीरे-धीरे ठंडा होता है।\"\nयुवक ने कहा, \"वाह, बिना ऐप के स्मार्ट कूलर!\""],
  ["rajasthani", "मेले में दुकानदार ने आवाज़ लगाई, \"पधारो सा, हाथ की बनी कठपुतली देखो!\"\nबच्चे ने पूछा, \"ये बोलती क्यों नहीं?\"\nदुकानदार बोला, \"डोर मेरे हाथ में है, आवाज़ कहानी में।\"\nबच्चा हँसा, \"तो घर जाकर पापा को भी यही डोर दिखाऊँगा।\""],
  ["rajasthani", "ऊँट मेले में पर्यटक ने ऊँटवाले से पूछा, \"यह इतना आराम से कैसे चलता है?\"\nऊँटवाला बोला, \"रेत का रास्ता पहचानता है, जल्दी का शोर नहीं करता।\"\nपर्यटक ने कहा, \"मुझे भी ऐसी शांति चाहिए।\"\nऊँटवाला हँसा, \"पहले फोन की घंटी बंद करो सा, आधी शांति वहीं मिल जाएगी।\""],
  ["rajasthani", "जयपुर की दुकान में ग्राहक ने पूछा, \"बंधेज के रंग इतने चटख कैसे रहते हैं?\"\nकारीगर बोला, \"धागे की गाँठ और रंगाई में धीरज लगता है।\"\nग्राहक ने कहा, \"मशीन से जल्दी नहीं बन सकता?\"\nकारीगर मुस्कराया, \"जल्दी कपड़ा बना देगी; हर गाँठ की कहानी नहीं।\""],
  ["rajasthani", "दादी ने पोती से कहा, \"थारी रोटी गोल हो या न हो, मन से बनी होनी चाहिए।\"\nपोती बोली, \"दादी, मेरी रोटी तो राजस्थान का नक्शा बन गई।\"\nदादी ने ध्यान से देखा और कहा, \"घणी बढ़िया!\"\nपोती खुश हुई, \"आज खाने में भूगोल भी पास हो गया।\""],
  ["rajasthani", "किले के गाइड ने बताया, \"यह दीवार गर्मी में भी भीतर ठंडक रखती थी।\"\nपर्यटक ने पूछा, \"तब एयर कंडीशनर कहाँ था?\"\nगाइड बोला, \"मोटे पत्थर, हवा की दिशा और समझदार कारीगर।\"\nपर्यटक ने कहा, \"पुराने इंजीनियरों को तो आज भी नौकरी मिल जाए।\""],
  ["rajasthani", "चौपाल पर बुज़ुर्ग ने पूछा, \"थारे गाँव में सबसे बड़ा बदलाव क्या आया?\"\nयुवा बोला, \"अब खबर मोबाइल पर तुरंत मिल जाती है।\"\nबुज़ुर्ग ने कहा, \"और मदद माँगने पर पड़ोसी अब भी तुरंत आ जाता है?\"\nयुवा बोला, \"हाँ सा, नेटवर्क कमजोर हो तो वही सबसे मजबूत सिग्नल है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पार्किंग किसकी है।\nएक निवासी ने पूछा, \"पार्किंग किसकी है?\"\nदूसरे निवासी ने जवाब दिया, \"जिसकी गाड़ी खड़ी है उसकी;\nरास्ता सबका है, उसे बंद मत करो।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—मेहमान की गाड़ी कहाँ लगेगी।\nएक निवासी ने पूछा, \"मेहमान की गाड़ी कहाँ लगेगी?\"\nदूसरे निवासी ने जवाब दिया, \"जहाँ नियम अनुमति दें;\nफुटपाथ को निजी गैराज मत समझो।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—दो लोग एक जगह चाहते हैं।\nएक निवासी ने पूछा, \"दो लोग एक जगह चाहते हैं।\"\nदूसरे निवासी ने जवाब दिया, \"समिति बोली,\nपहले नियम पढ़ो; हॉर्न से जगह नहीं बनती।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पार्किंग का समाधान क्या है।\nएक निवासी ने पूछा, \"पार्किंग का समाधान क्या है?\"\nदूसरे निवासी ने जवाब दिया, \"स्पष्ट आवंटन,\nआगंतुकों की जगह और सबकी सहमति।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—गाड़ी तिरछी क्यों खड़ी है।\nएक निवासी ने पूछा, \"गाड़ी तिरछी क्यों खड़ी है?\"\nदूसरे निवासी ने जवाब दिया, \"मालिक बोला जल्दी थी;\nपड़ोसी ने कहा रास्ता भी जल्दी में है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—बच्चों की साइकिल कहाँ रखें।\nएक निवासी ने पूछा, \"बच्चों की साइकिल कहाँ रखें?\"\nदूसरे निवासी ने जवाब दिया, \"ऐसी जगह जहाँ गाड़ी भी,\nबचे और खेल भी।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—किसका नियम चलेगा।\nएक निवासी ने पूछा, \"किसका नियम चलेगा?\"\nदूसरे निवासी ने जवाब दिया, \"जो सबके लिए बराबर हो,\nसिर्फ़ सबसे ऊँची आवाज़ के लिए नहीं।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पार्किंग में झगड़ा कैसे रुके।\nएक निवासी ने पूछा, \"पार्किंग में झगड़ा कैसे रुके?\"\nदूसरे निवासी ने जवाब दिया, \"सीमा तय करो और बात सीधे करो;\nसंदेशों में आग मत लगाओ।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—गाड़ी हटाने को कहा तो।\nएक निवासी ने पूछा, \"गाड़ी हटाने को कहा तो?\"\nदूसरे निवासी ने जवाब दिया, \"निवासी बोला ठीक है;\nसाझा जगह साझा जिम्मेदारी है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—बैठक का फैसला क्या रहा।\nएक निवासी ने पूछा, \"बैठक का फैसला क्या रहा?\"\nदूसरे निवासी ने जवाब दिया, \"जगह कम थी,\nइसलिए नियम और विनम्रता दोनों बढ़ाए गए।\""],
  ["society", "मोहल्ले की बैठक में तय हुआ कि हर घर पौधा लगाएगा।\nअगली सुबह सबने पौधे दरवाज़े पर रख दिए।\nकिसी ने पानी नहीं डाला, क्योंकि सबको लगा यह सफ़ाई समिति का काम है।\nपौधों ने बैठक बुलाकर जिम्मेदारी बाँटने की माँग की।"],
  ["society", "पड़ोसी ने पूछा, \"आपकी गली इतनी साफ़ कैसे रहती है?\"\nदूसरे ने कहा, \"सब अपना कचरा डिब्बे में डालते हैं।\"\nपहले ने पूछा, \"डिब्बा कहाँ है?\"\nजवाब मिला, \"गली के मोड़ पर—बस लोग उसे पड़ोसी की संपत्ति समझते हैं।\""],
  ["society", "सोसायटी ने पार्क में शांति बनाए रखने का बोर्ड लगाया।\nबच्चों ने बोर्ड पढ़कर खेलना बंद कर दिया।\nबड़ों ने वहीं खड़े होकर आधे घंटे बहस की।\nगार्ड ने कहा, \"बोर्ड बच्चों के लिए था या बैठक के लिए?\""],
  ["society", "मोहल्ले में सबने तय किया कि रात को तेज़ हॉर्न नहीं बजाएँगे।\nअगले दिन एक निवासी ने गली में पटाखे चलाए।\nपड़ोसी ने पूछा, \"यह किस नियम में आता है?\"\nजवाब मिला, \"हॉर्न नहीं बजाया, इसलिए नियम पूरा हुआ।\""],
  ["society", "सोसायटी ने पानी बचाने की अपील जारी की।\nनिवासी ने पूछा, \"टंकी का रिसाव कब ठीक होगा?\"\nसमिति बोली, \"पहले जागरूकता फैलाएँगे।\"\nनिवासी ने कहा, \"पानी तो अभी जागकर बह रहा है।\""],
  ["society", "पड़ोसियों ने मिलकर गली में पुस्तकालय बनाया।\nपहले दिन किताबें आईं, दूसरे दिन कुर्सियाँ आईं।\nतीसरे दिन बैठक हुई कि कौन पढ़ेगा।\nबच्चों ने कहा, \"आप तय करते रहिए, हम किताबें शुरू करते हैं।\""],
  [ "society", "मोहल्ले ने साझा बगीचे के लिए बैठक बुलाई।\nएक निवासी पौधे लाया, दूसरा पानी की बाल्टी।\nतीसरे ने पूछा, “कौन देखभाल करेगा?”\nबच्चों ने कहा, “पहले पौधे लगाइए, फिर बड़ों की ड्यूटी तय करिए।”" ],
  [ "society", "पड़ोसियों ने गली में कूड़ेदान रखने का फैसला किया।\nपहले दिन सबने उसकी तस्वीर खींची।\nदूसरे दिन कूड़ा फिर सड़क पर मिला।\nबुज़ुर्ग बोले, “कूड़ेदान सजावट नहीं, इस्तेमाल की चीज़ है।”" ],
  [ "society", "समाज भवन में पुस्तक दान अभियान शुरू हुआ।\nलोग किताबें लेकर आए, पर अलमारी की चाबी किसी के पास नहीं थी।\nबच्चे बोले, “किताबें तो मिल गईं, अब पढ़ने का रास्ता खोलिए।”\nअगली बैठक में चाबी सबसे पहले एजेंडे पर थी।" ],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—समूह ने क्या सीखा।\nएक निवासी ने पूछा, \"समूह ने क्या सीखा?\"\nदूसरे निवासी ने जवाब दिया, \"साझा जगह का सम्मान करना,\nभी पड़ोस की शिष्टता है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—आप रोज़ यहीं मिलते हैं।\nएक निवासी ने पूछा, \"आप रोज़ यहीं मिलते हैं?\"\nदूसरे निवासी ने जवाब दिया, \"एक ने कहा,\nलिफ्ट समय पर आती है; बातचीत मुफ्त मिलती है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—कौन-सी मंज़िल।\nएक निवासी ने पूछा, \"कौन-सी मंज़िल?\"\nदूसरे निवासी ने जवाब दिया, \"दूसरे ने कहा,\nपाँचवीं; लिफ्ट ने कहा पहले सबको अंदर आने दो।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—लिफ्ट इतनी धीमी क्यों है।\nएक निवासी ने पूछा, \"लिफ्ट इतनी धीमी क्यों है?\"\nदूसरे निवासी ने जवाब दिया, \"बुज़ुर्ग बोले,\nजल्दी किस बात की; मंज़िल भागी नहीं जा रही।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—किसी ने नमस्ते नहीं की।\nएक निवासी ने पूछा, \"किसी ने नमस्ते नहीं की।\"\nदूसरे निवासी ने जवाब दिया, \"लिफ्ट बोली,\nदरवाज़ा बंद हुआ; शिष्टाचार अभी खुलना बाकी है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—कौन पहले उतरेगा।\nएक निवासी ने पूछा, \"कौन पहले उतरेगा?\"\nदूसरे निवासी ने जवाब दिया, \"जो दरवाज़े के पास है;\nबाकी लोग धक्का नहीं, धैर्य रखें।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—लिफ्ट में फोन पर तेज़ बात क्यों।\nएक निवासी ने पूछा, \"लिफ्ट में फोन पर तेज़ बात क्यों?\"\nदूसरे निवासी ने जवाब दिया, \"पड़ोसी ने कहा,\nनेटवर्क कम है; आवाज़ बढ़ाने से गोपनीयता नहीं बढ़ती।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—बिजली चली गई तो।\nएक निवासी ने पूछा, \"बिजली चली गई तो?\"\nदूसरे निवासी ने जवाब दिया, \"सबने एक-दूसरे का हाल पूछा;\nलिफ्ट ने पहली बार सबको रुककर मिलाया।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—लिफ्ट में कितने लोग आएँ।\nएक निवासी ने पूछा, \"लिफ्ट में कितने लोग आएँ?\"\nदूसरे निवासी ने जवाब दिया, \"जितनी क्षमता लिखी है;\nदोस्ती में वजन सीमा नहीं बदलती।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—आपका नाम क्या है।\nएक निवासी ने पूछा, \"आपका नाम क्या है?\"\nदूसरे निवासी ने जवाब दिया, \"दोनों हँसे,\nबोले रोज़ मिलते हैं; आज परिचय भी कर लेते हैं।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—लिफ्ट का सबक क्या है।\nएक निवासी ने पूछा, \"लिफ्ट का सबक क्या है?\"\nदूसरे निवासी ने जवाब दिया, \"ऊपर जाने से पहले दूसरों,\nको जगह देना सीखो।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—समूह में संदेश किसने भेजा।\nएक निवासी ने पूछा, \"समूह में संदेश किसने भेजा?\"\nदूसरे निवासी ने जवाब दिया, \"जिसने खबर पढ़ी नहीं,\nउसने सबसे पहले आगे भेज दी।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—संदेश सच है।\nएक निवासी ने पूछा, \"संदेश सच है?\"\nदूसरे निवासी ने जवाब दिया, \"एडमिन बोला,\nस्रोत देखो; फ़ॉरवर्ड की संख्या प्रमाण नहीं।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—हर सुबह शुभकामना क्यों आती है।\nएक निवासी ने पूछा, \"हर सुबह शुभकामना क्यों आती है?\"\nदूसरे निवासी ने जवाब दिया, \"एक निवासी बोला,\nसूरज उगता है; समूह भी जाग जाता है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—बहस क्यों बढ़ गई।\nएक निवासी ने पूछा, \"बहस क्यों बढ़ गई?\"\nदूसरे निवासी ने जवाब दिया, \"क्योंकि दो लोगों ने इमोजी,\nको पूरा तर्क समझ लिया।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—नियम किसने बदला।\nएक निवासी ने पूछा, \"नियम किसने बदला?\"\nदूसरे निवासी ने जवाब दिया, \"समिति ने बैठक में;\nव्हाट्सऐप पर सिर्फ़ सूचना दी।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—फोटो किसकी है।\nएक निवासी ने पूछा, \"फोटो किसकी है?\"\nदूसरे निवासी ने जवाब दिया, \"पहले अनुमति पूछो;\nहर तस्वीर साझा करने के लिए नहीं होती।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—संदेश देर रात आया।\nएक निवासी ने पूछा, \"संदेश देर रात आया।\"\nदूसरे निवासी ने जवाब दिया, \"एडमिन ने कहा,\nकल बात करेंगे; नोटिफिकेशन को भी आराम चाहिए।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—समूह का उद्देश्य क्या है।\nएक निवासी ने पूछा, \"समूह का उद्देश्य क्या है?\"\nदूसरे निवासी ने जवाब दिया, \"ज़रूरी सूचना,\nसहयोग और सम्मान; हर अफ़वाह का मंच नहीं।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—गलत खबर फैल गई।\nएक निवासी ने पूछा, \"गलत खबर फैल गई।\"\nदूसरे निवासी ने जवाब दिया, \"भेजने वाले ने माफ़ी माँगी और,\nसही स्रोत भी साझा किया।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—सबसे अच्छा संदेश कौन-सा।\nएक निवासी ने पूछा, \"सबसे अच्छा संदेश कौन-सा?\"\nदूसरे निवासी ने जवाब दिया, \"जो मदद करे,\nजाँच पर खरा उतरे और अनावश्यक शोर न करे।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पार्क में जगह किसकी है।\nएक निवासी ने पूछा, \"पार्क में जगह किसकी है?\"\nदूसरे निवासी ने जवाब दिया, \"बच्चों की दौड़ और बुज़ुर्गों की बेंच,\nदोनों की।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—बच्चे तेज़ खेल रहे हैं।\nएक निवासी ने पूछा, \"बच्चे तेज़ खेल रहे हैं।\"\nदूसरे निवासी ने जवाब दिया, \"बुज़ुर्ग बोले,\nखेलने दो; बस रास्ता सबके लिए खुला रखो।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—किसे पहले झूला मिलेगा।\nएक निवासी ने पूछा, \"किसे पहले झूला मिलेगा?\"\nदूसरे निवासी ने जवाब दिया, \"जो पहले आया;\nलेकिन बारी बदलना भी सीखो।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पार्क साफ़ क्यों है।\nएक निवासी ने पूछा, \"पार्क साफ़ क्यों है?\"\nदूसरे निवासी ने जवाब दिया, \"क्योंकि आज सबने कचरा डिब्बे में डाला,\nमाली अकेला नहीं था।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—बुज़ुर्ग क्या सिखा रहे हैं।\nएक निवासी ने पूछा, \"बुज़ुर्ग क्या सिखा रहे हैं?\"\nदूसरे निवासी ने जवाब दिया, \"कि अनुभव रास्ता दिखाता है और,\nबच्चे नई दिशा पूछते हैं।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—मोबाइल पार्क में भी।\nएक निवासी ने पूछा, \"मोबाइल पार्क में भी?\"\nदूसरे निवासी ने जवाब दिया, \"एक दादा बोले,\nथोड़ी देर फोन रखो; पेड़ भी लाइव हैं।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—बेंच पर जगह कम है।\nएक निवासी ने पूछा, \"बेंच पर जगह कम है।\"\nदूसरे निवासी ने जवाब दिया, \"लोग बोले,\nथोड़ा सरकिए; बातचीत में जगह बढ़ जाती है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—कौन-सा खेल अच्छा है।\nएक निवासी ने पूछा, \"कौन-सा खेल अच्छा है?\"\nदूसरे निवासी ने जवाब दिया, \"जो सबको शामिल करे और,\nकिसी को बाहर न छोड़े।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पार्क का नियम क्या है।\nएक निवासी ने पूछा, \"पार्क का नियम क्या है?\"\nदूसरे निवासी ने जवाब दिया, \"खेलो, हँसो और साझा,\nजगह को साफ़ छोड़ो।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पार्क की सबसे बड़ी खुशी।\nएक निवासी ने पूछा, \"पार्क की सबसे बड़ी खुशी?\"\nदूसरे निवासी ने जवाब दिया, \"जब पीढ़ियाँ साथ बैठें,\nऔर एक-दूसरे से सीखें।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—किताबें कौन देगा।\nएक निवासी ने पूछा, \"किताबें कौन देगा?\"\nदूसरे निवासी ने जवाब दिया, \"निवासी बोले,\nहर घर एक किताब दे; ज्ञान मिलकर बढ़ेगा।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—लाइब्रेरी कहाँ बनेगी।\nएक निवासी ने पूछा, \"लाइब्रेरी कहाँ बनेगी?\"\nदूसरे निवासी ने जवाब दिया, \"समिति ने कहा,\nखाली कमरे में; पहले उसे सामान से खाली करें।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—कौन-सी किताब पहले रखें।\nएक निवासी ने पूछा, \"कौन-सी किताब पहले रखें?\"\nदूसरे निवासी ने जवाब दिया, \"बच्चों की कहानी,\nउपयोगी जानकारी और सबकी पसंद की किताबें।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—किताब वापस नहीं आई।\nएक निवासी ने पूछा, \"किताब वापस नहीं आई।\"\nदूसरे निवासी ने जवाब दिया, \"समूह ने कहा,\nयाद दिलाएँगे; पुस्तकालय भरोसे से चलता है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—शांत रहना जरूरी है।\nएक निवासी ने पूछा, \"शांत रहना जरूरी है?\"\nदूसरे निवासी ने जवाब दिया, \"हाँ, ताकि पाठक किताब सुन सके,\nऔर पड़ोसी आराम कर सके।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—लाइब्रेरियन कौन बनेगा।\nएक निवासी ने पूछा, \"लाइब्रेरियन कौन बनेगा?\"\nदूसरे निवासी ने जवाब दिया, \"जिसे किताबें पसंद हों और,\nरजिस्टर संभालना आता हो।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—किताब पुरानी है।\nएक निवासी ने पूछा, \"किताब पुरानी है।\"\nदूसरे निवासी ने जवाब दिया, \"निवासी बोला,\nकहानी पुरानी हो सकती है; सीख नई रहती है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—कितने सदस्य हैं।\nएक निवासी ने पूछा, \"कितने सदस्य हैं?\"\nदूसरे निवासी ने जवाब दिया, \"पहले दिन दस;\nअगले हफ़्ते किताबों ने और दोस्त बुला लिए।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पुस्तकालय का खर्च कैसे चलेगा।\nएक निवासी ने पूछा, \"पुस्तकालय का खर्च कैसे चलेगा?\"\nदूसरे निवासी ने जवाब दिया, \"छोटे योगदान और,\nपारदर्शी हिसाब से।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—सबसे अच्छा पाठक कौन।\nएक निवासी ने पूछा, \"सबसे अच्छा पाठक कौन?\"\nदूसरे निवासी ने जवाब दिया, \"जो पढ़कर किताब लौटाए,\nऔर विचार साझा करे।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पानी किस समय आएगा।\nएक निवासी ने पूछा, \"पानी किस समय आएगा?\"\nदूसरे निवासी ने जवाब दिया, \"समिति बोली,\nसमय-सारणी सबको देंगे; अफ़वाह से टंकी नहीं भरती।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—टंकी खाली क्यों है।\nएक निवासी ने पूछा, \"टंकी खाली क्यों है?\"\nदूसरे निवासी ने जवाब दिया, \"रिपोर्ट में भरी थी;\nनल ने अलग कहानी सुनाई।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पानी बचाने का तरीका।\nएक निवासी ने पूछा, \"पानी बचाने का तरीका?\"\nदूसरे निवासी ने जवाब दिया, \"लीकेज ठीक करो और,\nजरूरत भर उपयोग करो।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—किस घर को पहले मिलेगा।\nएक निवासी ने पूछा, \"किस घर को पहले मिलेगा?\"\nदूसरे निवासी ने जवाब दिया, \"नियम के अनुसार सबको;\nऊँची आवाज़ से पानी नहीं बढ़ता।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—टैंकर कब बुलाएँ।\nएक निवासी ने पूछा, \"टैंकर कब बुलाएँ?\"\nदूसरे निवासी ने जवाब दिया, \"जब माप और जरूरत इसकी पुष्टि करें;\nअनुमान से खर्च न बढ़ाएँ।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—नल खुला छोड़ दिया।\nएक निवासी ने पूछा, \"नल खुला छोड़ दिया।\"\nदूसरे निवासी ने जवाब दिया, \"पड़ोसी ने बंद किया और दरवाज़े,\nपर विनम्र सूचना लगा दी।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पानी की शिकायत कहाँ करें।\nएक निवासी ने पूछा, \"पानी की शिकायत कहाँ करें?\"\nदूसरे निवासी ने जवाब दिया, \"समिति को समय और विवरण दें;\nसमाधान की स्थिति भी पूछें।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—कौन जिम्मेदार है।\nएक निवासी ने पूछा, \"कौन जिम्मेदार है?\"\nदूसरे निवासी ने जवाब दिया, \"प्रबंधन और निवासी दोनों;\nसाझा संसाधन साझा जिम्मेदारी है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पानी कम है तो क्या करें।\nएक निवासी ने पूछा, \"पानी कम है तो क्या करें?\"\nदूसरे निवासी ने जवाब दिया, \"पीने और जरूरी काम को प्राथमिकता दें;\nबर्बादी रोकें।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—बैठक का फैसला क्या।\nएक निवासी ने पूछा, \"बैठक का फैसला क्या?\"\nदूसरे निवासी ने जवाब दिया, \"खपत का हिसाब,\nलीकेज की मरम्मत और सबके लिए स्पष्ट समय।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—त्योहार में सजावट कौन करेगा।\nएक निवासी ने पूछा, \"त्योहार में सजावट कौन करेगा?\"\nदूसरे निवासी ने जवाब दिया, \"हर मंज़िल से दो लोग;\nरोशनी भी बाँटेंगे और जिम्मेदारी भी।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—लाउडस्पीकर कितनी देर बजेगा।\nएक निवासी ने पूछा, \"लाउडस्पीकर कितनी देर बजेगा?\"\nदूसरे निवासी ने जवाब दिया, \"नियम और पड़ोसियों की सुविधा देखकर;\nउत्सव में सम्मान भी जरूरी है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—बच्चों का कार्यक्रम कौन चलाएगा।\nएक निवासी ने पूछा, \"बच्चों का कार्यक्रम कौन चलाएगा?\"\nदूसरे निवासी ने जवाब दिया, \"बच्चे खुद;\nबड़े बस मंच और सुरक्षा सँभालेंगे।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—खर्च कितना होगा।\nएक निवासी ने पूछा, \"खर्च कितना होगा?\"\nदूसरे निवासी ने जवाब दिया, \"पहले बजट तय;\nत्योहार के बाद हिसाब भी साझा होगा।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—प्रसाद कहाँ बाँटेंगे।\nएक निवासी ने पूछा, \"प्रसाद कहाँ बाँटेंगे?\"\nदूसरे निवासी ने जवाब दिया, \"साफ़ जगह पर,\nसबको बराबर और बिना भीड़ के।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—किसे आमंत्रित करें।\nएक निवासी ने पूछा, \"किसे आमंत्रित करें?\"\nदूसरे निवासी ने जवाब दिया, \"पूरे पड़ोस को;\nउत्सव का अर्थ साथ होना है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—सजावट उतरने के बाद।\nएक निवासी ने पूछा, \"सजावट उतरने के बाद?\"\nदूसरे निवासी ने जवाब दिया, \"सामान संभालेंगे और,\nपरिसर साफ़ करेंगे।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—कार्यक्रम में देरी हुई।\nएक निवासी ने पूछा, \"कार्यक्रम में देरी हुई।\"\nदूसरे निवासी ने जवाब दिया, \"संचालक बोला,\nअगली बार समय-सारणी और जिम्मेदारी पहले तय करेंगे।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—किसका योगदान सबसे बड़ा।\nएक निवासी ने पूछा, \"किसका योगदान सबसे बड़ा?\"\nदूसरे निवासी ने जवाब दिया, \"हर छोटे योगदान का;\nआयोजन अकेले किसी एक का नहीं।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—त्योहार की सीख क्या।\nएक निवासी ने पूछा, \"त्योहार की सीख क्या?\"\nदूसरे निवासी ने जवाब दिया, \"खुशी तभी पूरी है जब सबकी,\nसुविधा और सुरक्षा साथ रहे।\""],
  ["society", "लिफ्ट में एक साहब हर मंज़िल पर रुकने का बटन दबा रहे थे।\nपड़ोसी ने पूछा, \"इतनी मंज़िलों पर जाना है?\"\nसाहब बोले, \"नहीं, बस लिफ्ट को व्यस्त रखना है।\"\nपड़ोसी हँसा, \"फिर तो आप सोसायटी के सबसे बड़े नेटवर्किंग मैनेजर हैं।\""],
  ["society", "अपार्टमेंट के पार्किंग बोर्ड पर लिखा था—अपनी गाड़ी सही जगह लगाएँ।\nएक निवासी ने कार दो लाइनों के बीच खड़ी कर दी।\nगार्ड ने टोका तो बोले, \"मैंने दोनों स्लॉट का आधा-आधा इस्तेमाल किया है।\"\nगार्ड बोला, \"साहब, यह पार्किंग है; बुफे नहीं कि थोड़ा-थोड़ा सब ले लें।\""],
  ["society", "कूड़ा अलग-अलग देने की नई व्यवस्था शुरू हुई।\nएक निवासी ने गीला और सूखा कचरा एक ही थैले में दे दिया।\nसफाईकर्मी ने कहा, \"दो डिब्बे रखे हैं, फिर भी यह मिश्रित पैकेज क्यों?\"\nनिवासी बोला, \"घर में सब साथ रहते हैं, कचरे में भेदभाव अच्छा नहीं लगता।\""],
  ["society", "सोसायटी के बगीचे में एक निवासी रोज़ पौधों को पानी देते थे।\nमाली ने कहा, \"आपकी मेहनत से पौधे खूब बढ़ रहे हैं।\"\nनिवासी बोले, \"मैं इन्हें अपने बच्चों जैसा मानता हूँ।\"\nमाली मुस्कराया, \"तभी तो हर पौधे की फोटो है, पर पानी देने का समय याद नहीं रहता।\""],
  ["society", "डिलीवरी वाला तीसरी बार गलत फ्लैट की घंटी बजा गया।\nदरवाज़ा खोलकर निवासी ने कहा, \"मेरा कोई पार्सल नहीं है।\"\nडिलीवरी वाला बोला, \"ऐप में लिखा है—घर पर कोई मौजूद है।\"\nनिवासी ने जवाब दिया, \"हाँ, मैं मौजूद हूँ; बस आपका ग्राहक नहीं हूँ।\""],
  ["society", "पानी का टैंकर आते ही पूरी इमारत में हलचल मच गई।\nएक निवासी बाल्टियाँ लेकर सबसे पहले नीचे पहुँचे।\nगार्ड ने पूछा, \"आपको खबर इतनी जल्दी कैसे मिली?\"\nवे बोले, \"सोसायटी का अलार्म बंद हो सकता है, पानी की सूचना कभी नहीं।\""],
  ["society", "सोसायटी के व्हाट्सऐप समूह में किसी ने लिखा, \"कृपया केवल ज़रूरी संदेश भेजें।\"\nअगले ही मिनट उसी सदस्य ने सुप्रभात के साथ सात फूल भेज दिए।\nपड़ोसी ने पूछा, \"यह ज़रूरी संदेश है?\"\nजवाब आया, \"बिल्कुल, फूल देखकर सबका दिन अच्छा होगा—अब बहस मत कीजिए।\""],
  ["society", "त्योहार पर गलियारे में रंगोली बनाने की जगह तय हुई।\nएक निवासी ने दरवाज़े से लिफ्ट तक पूरी राह रंग दी।\nसमिति ने कहा, \"इतनी लंबी रंगोली किसलिए?\"\nवे बोले, \"ताकि मेहमान रास्ता न भूलें; अब बस लिफ्ट तक टिकट लगाना बाकी है।\""],
  ["society", "एक निवासी अपने कुत्ते को रोज़ सुबह टहलाने ले जाते थे।\nपड़ोसी ने कहा, \"आपका कुत्ता सबको पहचानने लगा है।\"\nमालिक बोले, \"हाँ, यह बहुत सामाजिक है।\"\nपड़ोसी ने हँसकर कहा, \"तभी तो हर सुबह आपसे पहले मेरी घंटी पर दस्तक देता है।\""],
  ["society", "लॉबी में एक निवासी अपना खोया हुआ पार्सल ढूँढ़ रहे थे।\nगार्ड ने रजिस्टर दिखाकर कहा, \"आपके नाम का कोई पैकेट दर्ज नहीं है।\"\nनिवासी बोले, \"लेकिन ऐप कहता है कि सुरक्षित पहुँचा दिया गया।\"\nगार्ड ने मुस्कराकर पूछा, \"ऐप में सुरक्षित है या आपके घर में—यह भी देख लीजिए।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—नए पड़ोसी को कैसे स्वागत करें।\nएक निवासी ने पूछा, \"नए पड़ोसी को कैसे स्वागत करें?\"\nदूसरे निवासी ने जवाब दिया, \"दरवाज़े पर नमस्ते और जरूरत,\nहो तो मदद की पेशकश।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—उनका नाम क्या है।\nएक निवासी ने पूछा, \"उनका नाम क्या है?\"\nदूसरे निवासी ने जवाब दिया, \"पहले पूछ लो;\nअनुमान से रिश्ते नहीं बनते।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—नए परिवार को नियम पता हैं।\nएक निवासी ने पूछा, \"नए परिवार को नियम पता हैं?\"\nदूसरे निवासी ने जवाब दिया, \"समिति ने सरल पुस्तिका दी;\nनियम समझाना भी स्वागत का हिस्सा है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—बच्चे किस स्कूल में जाएँगे।\nएक निवासी ने पूछा, \"बच्चे किस स्कूल में जाएँगे?\"\nदूसरे निवासी ने जवाब दिया, \"पड़ोसी ने कहा,\nपहले उन्हें इलाके से परिचित कराते हैं।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—किसने मिठाई भेजी।\nएक निवासी ने पूछा, \"किसने मिठाई भेजी?\"\nदूसरे निवासी ने जवाब दिया, \"पुराने पड़ोसी ने;\nनए घर में अपनापन भी पहुँचा।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—गाड़ी कहाँ रखेंगे।\nएक निवासी ने पूछा, \"गाड़ी कहाँ रखेंगे?\"\nदूसरे निवासी ने जवाब दिया, \"नियम के अनुसार;\nनई शुरुआत में साझा जगह का सम्मान जरूरी है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—उन्हें मदद चाहिए।\nएक निवासी ने पूछा, \"उन्हें मदद चाहिए?\"\nदूसरे निवासी ने जवाब दिया, \"पूछकर जानेंगे;\nमदद थोपना नहीं, उपलब्ध रहना है।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—पहली बैठक में क्या कहेंगे।\nएक निवासी ने पूछा, \"पहली बैठक में क्या कहेंगे?\"\nदूसरे निवासी ने जवाब दिया, \"अपना परिचय देंगे और,\nपड़ोस की बात सुनेंगे।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—किसी को भाषा नहीं आती।\nएक निवासी ने पूछा, \"किसी को भाषा नहीं आती।\"\nदूसरे निवासी ने जवाब दिया, \"धीरे बोलेंगे,\nसंकेत और मुस्कान भी संवाद बनाते हैं।\""],
  ["society", "मोहल्ले की बैठक में पड़ोसियों ने यह मुद्दा उठाया—अच्छा पड़ोस कैसे बनता है।\nएक निवासी ने पूछा, \"अच्छा पड़ोस कैसे बनता है?\"\nदूसरे निवासी ने जवाब दिया, \"नमस्ते,\nभरोसा, सीमाओं का सम्मान और समय पर मदद से।\""],
  ["saas-bahu", "सास ने पूछा, “आज रसोई में इतनी शांति क्यों है?”\nबहू बोली, “मिक्सर चलाने से पहले ढक्कन ठीक से लगा दिया।”\nसास ने राहत की साँस ली।\nकुकर बोला, “मेरी आवाज़ अभी बाकी है।”"],
  ["saas-bahu", "बहू ने कहा, “आज आपके बताए तरीके से अचार बनाया है।”\nसास ने चखकर पूछा, “नमक थोड़ा कम नहीं?”\nबहू बोली, “आपकी सलाह पूरी डाली है, नमक अगली किश्त में आएगा।”\nसास हँस पड़ीं, “बातों में पूरा स्वाद है।”"],
  ["saas-bahu", "सास ने पूछा, “मेहमानों के लिए कितनी रोटियाँ बनेंगी?”\nबहू बोली, “जितने मेहमान आएँगे, उतनी।”\nसास ने कहा, “और कोई दो बार ले तो?”\nबहू बोली, “आपकी तारीफ सुनकर तीसरी भी बन जाएगी।”"],
  ["saas-bahu", "बहू ने अलमारी व्यवस्थित कर दी।\nसास ने पूछा, “मेरी पुरानी चाबियाँ कहाँ हैं?”\nबहू बोली, “नाम लिखकर अलग डिब्बे में रखी हैं।”\nसास ने कहा, “अब ताला भी अपनी पहचान से खुलेगा।”"],
  ["saas-bahu", "सास ने बहू को पौधों में पानी डालते देखा।\nउन्होंने कहा, “पहले मिट्टी देख लिया करो।”\nबहू बोली, “आज मिट्टी सूखी थी।”\nसास ने कप दिखाया, “और मेरी चाय?”\nबहू मुस्कराई, “वह भी अभी भर देती हूँ।”"],
  ["saas-bahu", "बहू ने पूछा, “माँजी, सब्ज़ी में कौन-सा मसाला डालूँ?”\nसास बोलीं, “जो स्वाद बढ़ाए।”\nबहू ने पूछा, “तारीफ वाला मसाला कहाँ मिलेगा?”\nसास बोलीं, “पहले खाना परोस, समीक्षा बाद में होगी।”"],
  ["saas-bahu", "सास ने कहा, “मेहमान आने वाले हैं, बैठक सजा देना।”\nबहू ने कुशन और मेज़ ठीक कर दी।\nसास ने पूछा, “फूल कहाँ हैं?”\nबहू बोली, “आपकी मुस्कान के बाद लगाऊँगी, वही सुंदर सजावट है।”"],
  ["saas-bahu", "बहू ने मोबाइल पर सास को वीडियो दिखाया।\nसास ने पूछा, “इसे रोकना कैसे है?”\nबहू ने विराम का निशान दिखाया।\nसास बोलीं, “घर के कामों में भी ऐसा बटन होना चाहिए।”"],
  ["saas-bahu", "सास ने पूछा, “आज इतना समय किस काम में लगाया?”\nबहू बोली, “रसोई, कपड़े और सफाई में।”\nसास ने पूछा, “आराम कब किया?”\nबहू बोली, “जब आपने आराम के बारे में पूछा।”"],
  ["saas-bahu", "बहू ने सास के लिए चाय बनाई।\nसास ने घूँट लेकर कहा, “अदरक अच्छी है।”\nबहू खुश होकर बोली, “धन्यवाद माँजी।”\nसास ने कप रखा, “अब चाय को बता दो, ठंडी हो रही है।”"],
  ["saas-bahu", "सास ने कहा, “पुराने बर्तन अलग रख देना।”\nबहू ने उन्हें साफ़ करके शेल्फ़ में सजा दिया।\nसास ने पूछा, “इतने चमक क्यों रहे हैं?”\nबहू बोली, “पुरानी चीज़ें भी नई शिकायत न करें।”"],
  ["saas-bahu", "बहू ने पूछा, “आज बाजार से क्या लाना है?”\nसास ने लंबी सूची थमा दी।\nबहू ने पूछा, “कुछ भूल गई तो?”\nसास बोलीं, “अगली बार याद रखने के लिए एक और सूची मिलेगी।”"],
  ["saas-bahu", "सास ने कहा, “घर में सबकी पसंद का ध्यान रखना चाहिए।”\nबहू ने पूछा, “तो आज सबकी पसंद का खाना बनाऊँ?”\nसास बोलीं, “हाँ, पहले पता करो कि सबकी पसंद एक जैसी है या नहीं।”\nबहू ने कहा, “तब तक मैं सब्ज़ियाँ काट लेती हूँ।”"],
  ["saas-bahu", "बहू ने नया कुकर दिखाया।\nसास ने पूछा, “इसमें कितनी सीटी लगती हैं?”\nबहू बोली, “दाल के हिसाब से।”\nसास ने कहा, “अब घर में सीटी भी नियम से बजेगी।”"],
  ["saas-bahu", "सास ने पूछा, “फ्रिज के डिब्बों पर तारीख क्यों लिखी है?”\nबहू बोली, “पता रहे सब्ज़ी कब बनी थी।”\nसास बोलीं, “हम सूँघकर बता देते थे।”\nबहू ने कहा, “तकनीक ने नाक को छुट्टी दे दी।”"],
  ["saas-bahu", "बहू ने कहा, “आज ऑनलाइन सब्ज़ी मँगाई है।”\nसास ने पूछा, “ताज़ी आएगी न?”\nबहू बोली, “रेटिंग अच्छी है।”\nसास ने कहा, “तो धनिया भी अच्छी रेटिंग वाला मँगवाना।”"],
  ["saas-bahu", "सास ने पूछा, “घर की चाबी कहाँ रखी है?”\nबहू बोली, “दरवाज़े के पास हुक पर।”\nसास ने देखा, “वहाँ तो कुछ नहीं।”\nबहू बोली, “लगता है चाबी भी आज बाहर घूमने गई है।”"],
  ["saas-bahu", "बहू ने पुराने नुस्खे से हलवा बनाया।\nसास ने चखकर पूछा, “घी थोड़ा कम है?”\nबहू बोली, “डॉक्टर ने मात्रा कम रखने को कहा है।”\nसास बोलीं, “अगली बार डॉक्टर को भी कटोरी भेजेंगे।”"],
  ["saas-bahu", "सास ने पूछा, “खिड़की क्यों खोली?”\nबहू बोली, “ताज़ी हवा आएगी।”\nसास ने कहा, “धूल भी आएगी।”\nबहू बोली, “तो झाड़ू को भी आज खुली हवा मिलेगी।”"],
  ["saas-bahu", "बहू ने घर के खर्च का हिसाब बनाया।\nसास ने पूछा, “बचत कितनी हुई?”\nबहू बोली, “हिसाब देखकर सबको बचत की ज़रूरत समझ आ गई।”\nसास ने कहा, “बिना भाषण के बड़ा काम हुआ।”"],
  ["saas-bahu", "सास ने बहू को नई साड़ी में देखा।\nउन्होंने पूछा, “यह कब खरीदी?”\nबहू बोली, “पिछले महीने सेल में।”\nसास मुस्कराईं, “आज सेल की जीत मनाई जा रही है।”"],
  ["saas-bahu", "बहू ने पूछा, “आज टीवी पर क्या देखें?”\nसास बोलीं, “समाचार लगा दो।”\nचैनल पर विज्ञापन आ गया।\nसास बोलीं, “खबरों से पहले धैर्य का कार्यक्रम आता है।”"],
  ["saas-bahu", "सास ने कहा, “आज जल्दी सो जाना।”\nबहू बोली, “बस रसोई समेट दूँ।”\nसास ने घड़ी देखी।\nबहू बोली, “काम जल्दी होगा तो नींद भी जल्दी आएगी।”"],
  ["saas-bahu", "बहू ने पूछा, “आपकी पसंदीदा मिठाई कौन-सी है?”\nसास बोलीं, “जो सबके साथ बाँटी जाए।”\nबहू ने डिब्बा खोला।\nसास ने कहा, “पहले तुम्हारा टुकड़ा, फिर बाकी का हिसाब।”"],
  ["saas-bahu", "सास ने कहा, “कपड़े धूप में डाल देना।”\nबहू ने मौसम का ऐप देखा, “बारिश की संभावना है।”\nसास बोलीं, “हम बादल देखकर काम करते थे।”\nबहू ने कहा, “अब बादल भी मोबाइल पर सूचना भेजते हैं।”"],
  ["saas-bahu", "बहू ने डिब्बों पर लेबल लगाए।\nसास ने पढ़ा, “दाल, चावल, मसाले।”\nउन्होंने खाली डिब्बा दिखाया, “यह किसका है?”\nबहू बोली, “आपकी अगली सलाह के लिए जगह रखी है।”"],
  ["saas-bahu", "सास ने पूछा, “सब्ज़ी इतनी रंगीन कैसे है?”\nबहू बोली, “अलग-अलग सब्ज़ियाँ मिलाई हैं।”\nसास ने कहा, “स्वाद भी ऐसा ही मेलजोल वाला हो।”\nबहू बोली, “पहले चखिए, फिर गठबंधन घोषित करेंगे।”"],
  ["saas-bahu", "बहू ने सास को योग करते देखा।\nउसने पूछा, “आज कौन-सा आसन है?”\nसास बोलीं, “शांति आसन।”\nबहू ने कहा, “मैं भी रसोई में पाँच मिनट यही अभ्यास करूँगी।”"],
  ["saas-bahu", "सास ने कहा, “बैठक की घड़ी ठीक कर देना।”\nबहू ने बैटरी बदल दी।\nसास ने पूछा, “अब सही समय दिखा रही है?”\nबहू बोली, “अब घड़ी देर से आने का बहाना नहीं बनाएगी।”"],
  ["saas-bahu", "बहू ने पुरानी तस्वीरें डिजिटल कर दीं।\nसास ने पूछा, “अब एल्बम कहाँ रहेगा?”\nबहू बोली, “मोबाइल में।”\nसास मुस्कराईं, “अब यादों को भी चार्ज करना पड़ेगा।”"],
  ["saas-bahu", "बहू ने सुबह सास से कहा, “आज नाश्ते में आपकी पसंद का उपमा बनाया है।”\nसास ने चखकर पूछा, “इसमें मूँगफली कहाँ है?”\nबहू बोली, “डिब्बे पर लिखा था—मूँगफली से दूर रखें।”\nसास हँसीं, “तुमने निर्देशों का पालन बहुत गंभीरता से किया है!”"],
  ["saas-bahu", "सास ने बहू से पूछा, “मेरी चाबी फिर कहाँ रख दी?”\nबहू ने कहा, “जहाँ आपने सुरक्षित रखी थी।”\nसास बोलीं, “मुझे याद क्यों नहीं?”\nबहू मुस्कराई, “क्योंकि सुरक्षा इतनी कड़ी थी कि मालिक भी प्रवेश नहीं कर पा रहा।”"],
  ["saas-bahu", "बहू ने घर के खर्च की सूची सास को दिखाई।\nसास ने पूछा, “इतनी सब्ज़ियाँ एक हफ्ते में?”\nबहू बोली, “ऑनलाइन दाम देखकर खरीदी हैं।”\nसास ने चश्मा उतारा, “अच्छा, अब सब्ज़ी भी स्क्रीन पर देखकर ही सस्ती लगती है!”"],
  ["saas-bahu", "सास ने कहा, “हमारे ज़माने में बहुएँ सूरज निकलने से पहले उठती थीं।”\nबहू बोली, “आपके ज़माने में अलार्म भी मुर्गा बजाता था।”\nसास हँस पड़ीं, “और अब?”\n“अब मुर्गा भी मोबाइल में है, बस उसे साइलेंट मत करना!”"],
  ["saas-bahu", "रविवार को सास ने पूछा, “आज घर इतना व्यवस्थित कैसे है?”\nबहू ने कहा, “मैंने सब चीज़ें उनकी जगह रख दीं।”\nसास ने चारों ओर देखा, “और मेरा चश्मा?”\nबहू बोली, “वह भी अपनी जगह है—आपके सिर पर।”"],
  ["saas-bahu", "सास ने बहू से कहा, “चाय में अदरक ज़रा कम डालना।”\nबहू ने पूछा, “कितनी कम?”\nसास बोलीं, “बस स्वाद रहे, गला न जाग जाए।”\nबहू ने कप दिया, “लीजिए, आज अदरक को भी छुट्टी दे दी है।”"],
  ["saas-bahu", "बहू ने सास से पूछा, “मेहमानों के सामने कौन-सी मिठाई रखें?”\nसास बोलीं, “जो घर में सबसे अच्छी हो।”\nबहू ने फल की प्लेट रख दी।\nसास ने पूछा, “मिठाई कहाँ है?”\nबहू बोली, “चीनी कम करने का आपका संकल्प सबसे मीठा है।”"],
  ["saas-bahu", "आँगन में तुलसी के झुके पत्ते देखकर सास ने बहू से पूछा।\nउन्होंने कहा, “तुलसी को रोज़ पानी देना चाहिए।”\nबहू बोली, “देती हूँ, माँजी।”\nसास ने पूछा, “फिर पत्ते झुके क्यों हैं?”\nबहू ने जवाब दिया, “शायद आपकी रोज़ की निरीक्षण बैठक से घबरा गए हैं।”"],
  ["saas-bahu", "बहू ने सास से पूछा, “आज बाज़ार से क्या लाना है?”\nसास बोलीं, “कुछ खास नहीं, बस ज़रूरत का सामान।”\nबहू लौटी तो सास ने थैले देखे।\nबहू बोली, “आपकी सूची में ‘कुछ खास नहीं’ सबसे महँगा निकला!”"],
  ["saas-bahu", "सास ने कहा, “रसोई में काम करते समय मोबाइल मत देखा करो।”\nबहू ने फोन रख दिया।\nथोड़ी देर बाद सास बोलीं, “रेसिपी वाला वीडियो कहाँ गया?”\nबहू ने कहा, “आपके आदेश से वह भी ध्यान लगाकर बैठा है।”"],
  ["saas-bahu", "बहू ने सास से पूछा, “आज दोपहर क्या पकाएँ?”\nसास बोलीं, “जो कल बचा है, वही खत्म करो।”\nबहू ने फ्रिज खोला और बोली, “कल का खाना तो खत्म है।”\nसास ने कहा, “तो कल की बचत का विचार ही पका लो!”"],
  ["saas-bahu", "सास ने बहू से कहा, “तुम्हारी रोटियाँ गोल होने लगी हैं।”\nबहू खुश होकर बोली, “सच में?”\nसास ने कहा, “हाँ, अब बस उन्हें बेलन से पहले समझाना बंद करो।”\nबहू बोली, “रोटी सुनती नहीं, पर आपकी समीक्षा ज़रूर सुनती है।”"],
  ["saas-bahu", "बहू ने घर में नया कैलेंडर लगाया।\nसास ने पूछा, “पुराना क्यों हटाया?”\nबहू बोली, “उसमें पिछले महीने की तारीखें थीं।”\nसास ने कहा, “मुझे पता है, मैं बस देख रही थी कि तुम ध्यान देती हो या नहीं।”\nबहू ने मुस्कराकर कहा, “घर में तारीख़ भी परीक्षा देकर बदलती है!”"],
  ["saas-bahu", "सास ने पूछा, “मेरी पसंद का धारावाहिक शुरू हुआ?”\nबहू ने रिमोट देते हुए कहा, “हाँ, चैनल लगा दिया है।”\nसास बोलीं, “आवाज़ कहाँ है?”\nबहू ने टीवी की ओर इशारा किया, “वह भी आपकी पसंद का इंतज़ार कर रही थी।”"],
  ["saas-bahu", "बहू ने सास को नया कुशन दिखाया।\nसास बोलीं, “इतना चमकीला क्यों?”\nबहू ने कहा, “ताकि सोफ़े पर बैठते ही सबका मूड उजला हो।”\nसास ने कुशन रखा, “पहले धूल तो देख लें, चमक बाद में करेंगे।”"],
  ["saas-bahu", "सास ने बहू से पूछा, “आज तुमने आराम किया?”\nबहू बोली, “हाँ, पूरे दस मिनट।”\nसास ने कहा, “बस?”\nबहू ने जवाब दिया, “बाकी आराम का समय घर के कामों ने पहले से बुक कर रखा था।”"],
  ["saas-bahu", "बहू ने सास से कहा, “माँजी, आपके पसंद के बिस्कुट रखे हैं।”\nसास ने डिब्बा खोला, “खाली क्यों?”\nबहू बोली, “आपने मेहमानों के लिए बचाने को कहा था।”\nसास ने हँसकर कहा, “तो आज हम ही मेहमान बनकर खा लेते हैं!”"],
  ["saas-bahu", "सास ने कहा, “घर में सबकी बात सुनी जानी चाहिए।”\nबहू ने सिर हिलाया।\nफिर सास ने पूछा, “तुम चुप क्यों हो?”\nबहू बोली, “मैं सुनने की बारी निभा रही हूँ, माँजी; अब आपकी बारी पूरी होने दीजिए।”"],
  ["saas-bahu", "बहू ने सास से कहा, “आज मैंने बिना रेसिपी देखे दाल बनाई।”\nसास ने चखकर पूछा, “नमक ठीक है?”\nबहू बोली, “आपकी सलाह याद थी—पहले कम, फिर स्वाद के हिसाब से।”\nसास ने कहा, “लगता है आज मेरी ट्रेनिंग काम आई!”"],
  ["saas-bahu", "सास ने पूछा, “कपड़े धूप में डाले?”\nबहू बोली, “जी, मौसम साफ़ था।”\nसास ने खिड़की से बादल देखे।\nबहू ने कहा, “मौसम ऐप भी धूप दिखा रहा था, माँजी—बादलों ने अपडेट देर से भेजा।”"],
  ["saas-bahu", "बहू ने सास को चाय दी और पूछा, “चीनी कितनी ठीक है?”\nसास बोलीं, “डॉक्टर ने कम कहा है।”\nबहू ने कप आगे किया, “तो आज चाय में मिठास आपकी तारीफ से पूरी कर दी।”\nसास मुस्कराईं, “यह नुस्खा डॉक्टर को मत बताना!”"],
  ["saas-bahu", "सास ने कहा, “घर में चीज़ें अपनी जगह पर होनी चाहिए।”\nबहू ने पूछा, “और लोग?”\nसास कुछ पल रुकीं।\nबहू बोली, “लोगों को भी अपनी पसंद की जगह मिले, तो चीज़ें खुद व्यवस्थित हो जाएँगी।”"],
  ["saas-bahu", "बहू ने सास से पूछा, “आपकी पुरानी रेसिपी वाली डायरी कहाँ है?”\nसास ने कहा, “अलमारी में, संभालकर रखी है।”\nबहू ने डायरी खोली तो हर पन्ने पर अलग निशान थे।\nसास बोलीं, “वही तो मेरा सर्च इंजन है—बस इसमें विज्ञापन नहीं आते!”"],
  ["saas-bahu", "सास ने बहू से कहा, “आज पड़ोस में सबने तुम्हारी तारीफ की।”\nबहू ने पूछा, “किस बात की?”\nसास बोलीं, “तुमने सबकी मदद की।”\nबहू ने कहा, “आपने भी तो मुझे पड़ोसियों के नाम और चाय की पसंद याद करवाई थी।”"],
  ["saas-bahu", "बहू ने कहा, “माँजी, मैंने रसोई का सामान ऑनलाइन मँगाया है।”\nसास ने पूछा, “दुकान पर जाकर देख क्यों नहीं लिया?”\nबहू बोली, “वहाँ भीड़ थी।”\nसास ने पैकेट देखकर कहा, “अच्छा है, अब दुकानदार भी घर आकर सामान दिखाने लगा!”"],
  ["saas-bahu", "सास ने पूछा, “तुमने मेरी सिलाई वाली टोकरी देखी?”\nबहू बोली, “जी, सोफ़े के पास रखी है।”\nसास ने कहा, “वहाँ तो अख़बार है।”\nबहू ने जवाब दिया, “टोकरी अख़बार के नीचे है—आपकी चीज़ें भी अब परतों में सुरक्षित रहती हैं।”"],
  ["saas-bahu", "बहू ने सास से कहा, “आज घर में सबने मिलकर सफ़ाई की।”\nसास ने पूछा, “किसने क्या किया?”\nबहू ने बताया, “आपने काम बाँटे, मैंने सूची बनाई, सबने काम किया।”\nसास बोलीं, “और तुम्हारे पति?”\nबहू ने कहा, “उन्होंने पहले और बाद की तस्वीरें लीं—इतिहास सुरक्षित है!”"],
  ["saas-bahu", "सास ने कहा, “त्योहार पर घर में रौनक होनी चाहिए।”\nबहू ने रंगोली बनाई और दीये सजाए।\nसास ने देखकर कहा, “बहुत सुंदर, बस बीच में जगह खाली है।”\nबहू बोली, “वहाँ सबकी मुस्कान रखनी है, माँजी।”"],
  ["saas-bahu", "बहू ने पूछा, “माँजी, मेहमानों को घर का रास्ता कैसे समझाऊँ?”\nसास बोलीं, “मंदिर से बाएँ मुड़ना, फिर नीम का पेड़ आएगा।”\nबहू ने कहा, “अब तो वहाँ पार्किंग बन गई है।”\nसास ने हँसकर कहा, “तो मेहमानों को लोकेशन भेजो, मेरी याददाश्त को नहीं!”"],
  ["saas-bahu", "सास ने कहा, “तुम दोनों मिलकर घर का बजट बनाओ।”\nबहू ने खर्च और बचत लिखकर दिखाए।\nसास ने पूछा, “मनोरंजन का खर्च कहाँ है?”\nबहू बोली, “आपके साथ बैठकर हँसने का समय उसमें मुफ़्त रखा है।”\nसास ने कहा, “यह मद सबसे पहले भरना!”"],
  ["saas-bahu", "बहू ने सास से पूछा, “आज आप बाहर टहलने चलेंगी?”\nसास बोलीं, “घुटनों में हल्का दर्द है।”\nबहू ने कहा, “धीरे चलेंगे, जितना आराम हो उतना।”\nसास मुस्कराईं, “ठीक है, पर लौटते समय सब्ज़ी भी लेते आएँगे—टहलना उपयोगी होना चाहिए!”"],
  ["saas-bahu", "सास ने पूछा, “तुमने पुराने डिब्बे क्यों नहीं फेंके?”\nबहू बोली, “कुछ में दाल रखी है, कुछ में मसाले।”\nसास ने एक डिब्बा उठाया, “इसमें क्या है?”\nबहू ने कहा, “आपकी बचाकर रखने की आदत का संग्रहालय।”"],
  ["saas-bahu", "बहू ने सास को वीडियो कॉल पर मायके से बात करते देखा।\nसास ने फोन रखकर कहा, “आज सब बहुत खुश थे।”\nबहू बोली, “आपकी आवाज़ सुनकर उन्हें अच्छा लगा होगा।”\nसास ने कहा, “और तुम्हारे भेजे पकवान की तस्वीर ने सबको भूखा कर दिया!”"],
  ["saas-bahu", "सास ने कहा, “मेरे पौधे को रोज़ थोड़ी धूप चाहिए।”\nबहू ने गमला खिड़की के पास रख दिया।\nसास ने पूछा, “इतना पास क्यों?”\nबहू बोली, “ताकि पौधा भी परिवार की बातचीत सुन सके।”\nसास हँसीं, “बस उसे हमारी बहसों से दूर रखना!”"],
  ["saas-bahu", "बहू ने सास से कहा, “मैंने आज काम की सूची छोटी कर दी है।”\nसास ने पूछा, “क्यों?”\nबहू बोली, “कुछ काम कल भी हो सकते हैं।”\nसास ने मुस्कराकर कहा, “अच्छा निर्णय है; घर कोई भागती ट्रेन नहीं।”"],
  ["saas-bahu", "सास ने पूछा, “तुमने मेरी पसंद का गाना चलाया?”\nबहू ने कहा, “जी, प्लेलिस्ट बना दी है।”\nसास ने पहला गाना सुना और बोलीं, “यह तो नया रीमिक्स है!”\nबहू ने जवाब दिया, “पुरानी पसंद, नया पैकेज—पीढ़ियों का साझा प्रोजेक्ट।”"],
  ["saas-bahu", "बहू ने कहा, “माँजी, आज खाना थोड़ा देर से बनेगा।”\nसास ने पूछा, “क्यों?”\nबहू बोली, “मैं पहले आपका ब्लड प्रेशर चेक कर दूँगी, फिर रसोई संभालूँगी।”\nसास ने कहा, “ठीक है, स्वास्थ्य पहले; रोटी थोड़ी देर इंतज़ार कर सकती है।”"],
  ["saas-bahu", "सास ने बहू से पूछा, “तुमने मेरी पसंद की साड़ी कहाँ रखी?”\nबहू ने अलमारी का खाना दिखाया।\nसास बोलीं, “यहाँ तो दूसरी साड़ी है।”\nबहू ने कहा, “वह भी आपकी पसंद की है—आपकी पसंद का दायरा बहुत बड़ा है!”"],
  ["saas-bahu", "बहू ने सास से कहा, “आज मैंने घर के सब काम बाँट दिए हैं।”\nसास ने पूछा, “किसे क्या मिला?”\nबहू बोली, “किसी को बर्तन, किसी को झाड़ू, किसी को कपड़े।”\nसास ने पूछा, “और तुम्हें?”\nबहू ने कहा, “सबको याद दिलाने का विभाग—वह सबसे व्यस्त निकला!”"],
  ["saas-bahu", "सास ने पूछा, “आज तुम इतनी खुश क्यों हो?”\nबहू बोली, “आज हमने बिना बहस के रसोई का काम पूरा किया।”\nसास ने कहा, “यह तो बड़ी उपलब्धि है।”\nबहू ने जवाब दिया, “हाँ, अब इसे हर महीने की पारिवारिक छुट्टी घोषित कर दें!”"],
  ["saas-bahu", "बहू ने सास से कहा, “मैंने आपके लिए नया चश्मा मँगाया है।”\nसास ने पहनकर पूछा, “अब कैसी दिख रही हूँ?”\nबहू बोली, “एकदम साफ़।”\nसास ने मुस्कराकर कहा, “तो अब तुम्हारी छोटी-छोटी शरारतें भी साफ़ दिखेंगी!”"],
  ["saas-bahu", "सास ने बहू से कहा, “घर में हर किसी को अपनी बात कहने का मौका मिलना चाहिए।”\nबहू ने कहा, “बिल्कुल, और जवाब देने का भी।”\nसास ने सिर हिलाया, “ठीक है, आज से नियम बराबर।”\nबहू बोली, “वाह, घर में लोकतंत्र की नई शुरुआत!”"],
  ["saas-bahu", "सास ने बहू से पूछा, “मेरी बनाई खीर कैसी बनी?”\nबहू ने कटोरी चखकर कहा, “बहुत अच्छी, बस चीनी थोड़ी कम है।”\nसास बोलीं, “तुम्हें कैसे पता?”\nबहू मुस्कराई, “आपकी तारीफ़ में मिठास पूरी है, खीर में थोड़ी बच गई!”"],
  ["saas-bahu", "बहू ने सास से कहा, “आज मैंने घर की सारी अलमारियाँ व्यवस्थित कर दीं।”\nसास ने पूछा, “मेरी पुरानी रेसिपी वाली डायरी कहाँ रखी?”\nबहू बोली, “रसोई की सबसे सुरक्षित जगह पर।”\nसास ने देखा, डायरी मसालों के डिब्बे में थी—अब हर सब्ज़ी में इतिहास का स्वाद आएगा!"],
  ["saas-bahu", "सास ने बहू से कहा, “मेरे ज़माने में हम बिना मशीन के कपड़े धोते थे।”\nबहू बोली, “आपकी मेहनत को सलाम है।”\nसास ने गर्व से पूछा, “तो आज मशीन क्यों चलाई?”\nबहू बोली, “आपकी कहानी सुनने के लिए समय बचाना था!”"],
  ["saas-bahu", "बहू ने नया पौधा लाकर बालकनी में रखा।\nसास ने पूछा, “इसे रोज़ पानी कौन देगा?”\nबहू बोली, “हम दोनों बारी-बारी से।”\nसास हँसीं, “ठीक है, पर पौधा मुरझाया तो दोष मौसम को देंगे, एक-दूसरे को नहीं।”"],
  ["saas-bahu", "सास ने बहू से पूछा, “आज मेहमानों के लिए क्या बनाया है?”\nबहू बोली, “आपकी पसंद की कचौड़ी और मेरी पसंद की चटनी।”\nसास ने कहा, “मेरी पसंद तो तुम्हें पता है।”\nबहू मुस्कराई, “इसीलिए चटनी तीखी रखी है—आपकी राय भी तीखी आती है!”"],
  ["saas-bahu", "बहू ने सास से कहा, “मैंने आज से सुबह की सैर शुरू कर दी है।”\nसास बोलीं, “बहुत बढ़िया, मैं भी साथ चलूँगी।”\nअगली सुबह बहू तैयार खड़ी थी, सास चाय लेकर बैठीं।\n“चलें?” बहू ने पूछा। सास बोलीं, “पहले चाय की सैर पेट तक तो पहुँचने दो!”"],
  ["saas-bahu", "सास ने बहू से कहा, “तुम्हारे फोन में मेरी तस्वीर बहुत अच्छी आई है।”\nबहू बोली, “क्योंकि आपने पहली बार कैमरे को देखकर मुस्कराया।”\nसास ने पूछा, “बाकी तस्वीरों में क्या करती थी?”\nबहू बोली, “आप हर बार कैमरे को ऐसे देखती थीं जैसे वह घर का हिसाब माँगने आया हो!”"],
  ["saas-bahu", "बहू ने रसोई में नया टाइमर लगाया।\nसास ने पूछा, “यह किस काम आएगा?”\nबहू बोली, “दाल समय पर पक जाएगी।”\nसास ने टाइमर बजते ही कहा, “अच्छा है, अब दाल के साथ तुम्हारी बातें भी समय पर खत्म होंगी!”"],
  ["saas-bahu", "सास ने बहू से कहा, “आज घर में शांति बहुत है।”\nबहू बोली, “बच्चे नानी के घर गए हैं और टीवी बंद है।”\nसास ने चैन की साँस ली, “वाह, ऐसा रोज़ हो तो कितना अच्छा!”\nबहू ने पूछा, “तो कल भी भेज दूँ?” सास बोलीं, “नहीं, कल से मुझे उनकी याद आने लगेगी।”"],
  ["saas-bahu", "बहू ने सास से पूछा, “आपको जन्मदिन पर क्या उपहार चाहिए?”\nसास बोलीं, “कुछ ऐसा जो रोज़ काम आए।”\nबहू ने उन्हें आरामदायक चप्पलें दीं।\nसास ने पहनकर कहा, “बहुत अच्छी हैं—अब मैं तुम्हारे पीछे रसोई तक तेज़ी से पहुँच पाऊँगी!”"],
  ["saas-bahu", "घर के आँगन में सास-बहू की नोकझोंक इस बात पर शुरू हुई—खाना बाहर से मँगाएँ।\nसास ने पूछा, \"खाना बाहर से मँगाएँ?\"\nबहू ने जवाब दिया, \"आज हाँ;\nरोज़ का समाधान नहीं, आज का आराम है।\""],
  ["saas-bahu", "घर के आँगन में सास-बहू की नोकझोंक इस बात पर शुरू हुई—घर की सूची लंबी है।\nसास ने पूछा, \"घर की सूची लंबी है।\"\nबहू ने जवाब दिया, \"काम छोटे हिस्सों में बाँटेंगे;\nएक साथ देखकर डरेंगे नहीं।\""],
  ["saas-bahu", "घर के आँगन में सास-बहू की नोकझोंक इस बात पर शुरू हुई—कौन पहले आराम करेगा।\nसास ने पूछा, \"कौन पहले आराम करेगा?\"\nबहू ने जवाब दिया, \"जो थका है;\nघर का काम दौड़ नहीं है।\""],
  ["saas-bahu", "घर के आँगन में सास-बहू की नोकझोंक इस बात पर शुरू हुई—साफ़-सफ़ाई कितनी करनी है।\nसास ने पूछा, \"साफ़-सफ़ाई कितनी करनी है?\"\nबहू ने जवाब दिया, \"ज़रूरत भर;\nमेहमानों के लिए घर को संग्रहालय नहीं बनाना।\""],
  ["saas-bahu", "घर के आँगन में सास-बहू की नोकझोंक इस बात पर शुरू हुई—बर्तन किसकी बारी।\nसास ने पूछा, \"बर्तन किसकी बारी?\"\nबहू ने जवाब दिया, \"आज मेरी;\nकल तुम्हारी; नियम साफ़ रखेंगे।\""],
  ["saas-bahu", "घर के आँगन में सास-बहू की नोकझोंक इस बात पर शुरू हुई—काम जल्दी कैसे होगा।\nसास ने पूछा, \"काम जल्दी कैसे होगा?\"\nबहू ने जवाब दिया, \"साथ करें तो;\nआदेश देने से काम नहीं घटता।\""],
  ["saas-bahu", "घर के आँगन में सास-बहू की नोकझोंक इस बात पर शुरू हुई—रविवार का सबसे अच्छा पल।\nसास ने पूछा, \"रविवार का सबसे अच्छा पल?\"\nबहू ने जवाब दिया, \"जब दोनों काम पूरा,\nकर बैठकर चाय पिएँ।\""],
  ["saas-bahu", "घर के आँगन में सास-बहू की नोकझोंक इस बात पर शुरू हुई—छुट्टी का मतलब।\nसास ने पूछा, \"छुट्टी का मतलब?\"\nबहू ने जवाब दिया, \"जिम्मेदारी बाँटना और खुद,\nको भी समय देना।\""],
  ["saas-bahu", "रविवार की रसोई में सास ने दो डिब्बे देखकर बहू से पूछा, “इनमें क्या है?”\nबहू बोली, “एक में चीनी है और दूसरे में नमक।”\nसास ने चखकर कहा, “अच्छा किया, पिछली बार दोनों की पहचान उलझ गई थी।”\nबहू हँसी, “तभी तो अब हर डिब्बे पर नाम भी लिख दिया है!”"],
  ["saas-bahu", "किराने की ऐप पर बहू ने सास को खरीदारी की सूची दिखाई।\nसास ने पूछा, “इतनी सारी चीज़ें किसने चुनीं?”\nबहू बोली, “आपकी पसंद और मेरी ज़रूरतें मिलाकर।”\nसास मुस्कराईं, “तो बिल भी आधा-आधा बाँट लेते हैं!”"],
  ["saas-bahu", "पड़ोस से लौटकर सास ने बहू से कहा, “आज सबने तुम्हारी तारीफ़ की।”\nबहू ने पूछा, “किस बात की?”\nसास बोलीं, “तुमने मेरी बनाई रेसिपी सबको बताई।”\nबहू हँसी, “नाम आपका बताया, राज़ अपना रखा—नमक कितना डालना है!”"],
  ["saas-bahu", "बालकनी के पौधों पर नाम की पट्टियाँ देखकर सास ने बहू से पूछा, “ये किसने लगाईं?”\nबहू बोली, “तुलसी, मनी प्लांट और गुलाब की पहचान आसान रहेगी।”\nसास ने आख़िरी गमला देखा, “इस पर पानी देना मत भूलना लिखा है!”\nबहू बोली, “वो आपके पसंदीदा पौधे के लिए है, जिसे आप रोज़ भूल जाती हैं।”"],
  ["saas-bahu", "दरवाज़े के पास खड़ी सास ने बहू से पूछा, “मेरी चाबी कहाँ रखी है?”\nबहू बोली, “जहाँ आपने कल रखी थी, वहीं।”\nसास ने कहा, “मुझे याद नहीं।”\nबहू मुस्कराई, “इसीलिए मैंने चाबी के साथ जगह की तस्वीर भी खींच रखी है!”"],
  ["saas-bahu", "पुरानी साड़ी के नए परदे देखकर सास ने बहू से कहा, “रंग तो बहुत सुंदर है।”\nबहू बोली, “कपड़ा भी आपका आशीर्वाद लेकर आया है।”\nसास हँसीं, “अगली बार मेरी अलमारी से आशीर्वाद लेने से पहले पूछ लेना!”\nबहू बोली, “अब अगला डिज़ाइन आपकी मंज़ूरी के बाद ही बनेगा।”"],
  ["saas-bahu", "सुबह-सुबह रसोई में बहू को गुनगुनाते सुनकर सास ने पूछा, “आज इतनी खुशी किस बात की है?”\nबहू बोली, “आज खाना दोनों मिलकर बना रहे हैं।”\nसास ने कहा, “तो संगीत बंद मत करना।”\nबहू हँसी, “वरना आप फिर काम बाँटने लगेंगी और मेरी धुन बिगड़ जाएगी!”"],
  ["saas-bahu", "महीने का हिसाब देखते हुए बहू ने सास से कहा, “हर खर्च अलग लिख दिया है।”\nसास ने पूछा, “मेरी चाय और तुम्हारी कॉफी कहाँ लिखी है?”\nबहू बोली, “अलग-अलग पंक्तियों में।”\nसास मुस्कराईं, “बहुत खूब, अब बहस भी बजट के अंदर होगी!”"],
  ["saas-bahu", "टीवी का नया रिकॉर्डिंग विकल्प देखकर सास ने बहू से पूछा, “मेरा धारावाहिक रिकॉर्ड किया?”\nबहू बोली, “हाँ, पूरा एपिसोड।”\nसास ने कहा, “और विज्ञापन?”\nबहू हँसी, “वो भी रखे हैं—आपको उनके बीच में ही तो चाय बनाने का समय मिलता है!”"],
  ["saas-bahu", "पुरानी तस्वीरों का एल्बम निकालकर बहू ने सास से कहा, “आज साथ बैठकर इन्हें देखते हैं।”\nसास ने पूछा, “पहले घर का काम?”\nबहू बोली, “सूची बाँट दी है, सबकी जिम्मेदारी तय है।”\nसास ने एल्बम खोला, “तो आज यादें भी मिलकर सँभालेंगे!”"],
  ["haryanvi", "चौपाल में बिजली बचाने की बैठक हुई।\nताऊ ने पूछा, \"बत्ती बंद करने से बिल घटेगा के?\"\nअधिकारी बोला, \"बिलकुल घटेगा।\"\nताऊ हँसा, \"फेर पहले दफ्तर की बत्ती बंद कर, सलाह वहीं से शुरू कर।\""],
  ["haryanvi", "खेत में छोरे ने मौसम ऐप खोला।\nताऊ ने पूछा, \"बारिश कब आवैगी?\"\nछोरा बोला, \"ऐप कहै शाम तक।\"\nताऊ हँसा, \"बादल नै भी फोन कर दे, टाइम पै आ जावै।\""],
  ["haryanvi", "गांव की दुकान पर नया तराजू आया।\nताऊ ने बाट रखकर वजन देखा।\nदुकानदार बोला, \"अब मशीन गलती ना करै।\"\nताऊ हँसा, \"फेर उधार का हिसाब भी इसी पै तौल दे।\""],
  ["haryanvi", "बस में कंडक्टर ने टिकट मांगा।\nताऊ बोला, \"पैसे घर रह गए।\"\nकंडक्टर ने पूछा, \"फेर चढ़ा क्यूँ?\"\nताऊ हँसा, \"बस आई तो पुरानी दोस्ती याद आ गई।\""],
  ["haryanvi", "चौपाल पर पोते ने दादा को वीडियो दिखाया।\nदादा ने पूछा, \"इसमें आदमी बोल क्यूँ ना रह्या?\"\nपोता बोला, \"दादा, ये मूक वीडियो सै।\"\nदादा हँसा, \"अच्छा, आजकल चुप रहना भी रिकॉर्ड होवै सै।\""],
  ["haryanvi", "खेत में किसान ने नई मशीन मंगवाई।\nताऊ ने पूछा, \"कितने आदमी का काम करेगी?\"\nकिसान बोला, \"चार का।\"\nताऊ हँसा, \"फेर चार आदमी नै चाय पिलाण का काम बच गया।\""],
  ["haryanvi", "गांव के स्कूल में स्मार्ट बोर्ड लगा।\nमास्टर जी ने पूछा, \"सब समझ में आया?\"\nछोरा बोला, \"बोर्ड तो समझदार सै।\"\nमास्टर जी हँसे, \"अब तू भी पाठ पढ़कै उसका साथी बन जा।\""],
  ["haryanvi", "ताऊ ने बैंक में पासबुक अपडेट करवाई।\nकर्मचारी बोला, \"अब सब ऑनलाइन दिखेगा।\"\nताऊ पूछै, \"ब्याज भी ऑनलाइन बढ़ेगा के?\"\nकर्मचारी मुस्कराया, \"वो नियम से बढ़ेगा।\""],
  ["haryanvi", "चौपाल में खेती पर चर्चा चल रही थी।\nएक ताऊ बोला, \"इस बार फसल बढ़िया होगी।\"\nदूजा पूछै, \"इतना भरोसा कैसे?\"\nपहला हँसा, \"बीज अच्छा सै, अब बादल की बारी सै।\""],
  ["haryanvi", "गांव के मेले में फोटो खिंचवाने की मशीन लगी।\nताऊ ने पूछा, \"फोटो कितनी देर में मिलेगी?\"\nलड़का बोला, \"फोन में तुरंत।\"\nताऊ हँसा, \"एक कागज पै भी दे, याद जेब में रखूँगा।\""],
  ["haryanvi", "दूध की डेयरी पर ताऊ ने मशीन देखी।\nकर्मचारी बोला, \"अब नाप बिल्कुल सही होगा।\"\nताऊ पूछै, \"मलाई का हिसाब कौन करेगा?\"\nकर्मचारी हँसा, \"उसका हिसाब घर जाकर कर लेना।\""],
  ["haryanvi", "एक छोरा जिम की फीस भर आया।\nताऊ ने पूछा, \"कसरत शुरू कर दी?\"\nछोरा बोला, \"कल से पक्का।\"\nताऊ हँसा, \"तेरी फीस ने आज ही वजन उठा लिया।\""],
  ["haryanvi", "गांव में नई सड़क बनी।\nताऊ ने बाइक रोककर सड़क देखी।\nपोता पूछै, \"दादा, चल क्यूँ ना रहे?\"\nताऊ बोला, \"इतनी चिकनी सड़क देख कै पुरानी आदत भरोसा ना करै।\""],
  ["haryanvi", "पंचायत में पानी की टंकी का उद्घाटन हुआ।\nताऊ ने नल खोला तो पानी ना आया।\nअधिकारी बोला, \"लाइन कल चालू होगी।\"\nताऊ हँसा, \"फेर आज फीता पानी के भरोसे काटा सै के?\""],
  ["haryanvi", "दुकानदार ने डिजिटल भुगतान का बोर्ड लगाया।\nताऊ ने पूछा, \"नकद बंद कर दिया के?\"\nदुकानदार बोला, \"ना, दोनों चलेंगे।\"\nताऊ हँसा, \"ठीक सै, तकनीक नई रख पर ग्राहक पुराना मत खो।\""],
  ["haryanvi", "खेत में ड्रोन उड़ता देख ताऊ रुक गया।\nउसने पूछा, \"ये चिड़िया इतनी महंगी क्यूँ सै?\"\nपोता बोला, \"ये फसल की फोटो लेती है।\"\nताऊ हँसा, \"फेर इसे चिड़ियों से बचाकर रखियो।\""],
  ["haryanvi", "मास्टर जी ने पूछा, \"होमवर्क पूरा क्यूँ ना हुआ?\"\nछोरा बोला, \"कल इंटरनेट बंद था।\"\nमास्टर जी बोले, \"किताब तो घर में थी।\"\nछोरा हँसा, \"जी, पर किताब का पासवर्ड याद ना था।\""],
  ["haryanvi", "ताऊ ने नया स्मार्ट टीवी खरीदा।\nपोता बोला, \"आवाज से चैनल बदल जाएगा।\"\nताऊ ने टीवी से कहा, \"बिजली का बिल कम कर दे।\"\nटीवी चुप रहा, ताऊ बोला, \"लगै सै अभी अपडेट चाहिए।\""],
  ["haryanvi", "मंडी में किसान ने भाव पूछा।\nव्यापारी बोला, \"आज दाम नीचे हैं।\"\nकिसान ने कहा, \"मेहनत तो पूरी ऊपर गई।\"\nव्यापारी हँसा, \"मेहनत का भाव मेरी सूची में नहीं आवै।\""],
  ["haryanvi", "गांव की लाइब्रेरी में ताऊ पहुंचा।\nलाइब्रेरियन ने पूछा, \"किस विषय की किताब चाहिए?\"\nताऊ बोला, \"ऐसी जो खेती का खर्च घटा दे।\"\nलाइब्रेरियन हँसा, \"किताब पढ़नी पड़ेगी, खेत खुद नहीं पढ़ेगा।\""],
  ["haryanvi", "सुबह की चौपाल पर ताऊ ने अखबार खोला।\nपोते ने पूछा, \"मोबाइल पर खबर क्यों नहीं पढ़ते?\"\nताऊ बोले, \"कागज़ में खबर के साथ पड़ोसी की राय भी मिलती सै।\"\nपोता बोला, \"वो तो हर जगह मिल जाती सै!\""],
  ["haryanvi", "मंडी जाते समय किसान ने बेटे को हिसाब की कॉपी दी।\nबेटा बोला, \"मोबाइल में लिख लूँ?\"\nकिसान बोला, \"लिख ले, पर पर्ची भी संभाल।\"\nबेटा बोला, \"अब दोनों जगह हिसाब रखूँगा।\""],
  ["haryanvi", "नाई ने छोरे से पूछा, \"बाल कितने छोटे करूँ?\"\nछोरा बोला, \"ऐसे कि स्कूल में पहचान ना हो।\"\nनाई हँसा, \"फिर फीस भी नई पहचान से भरवाइयो!\"\nछोरा बोला, \"इतना छोटा भी मत करियो!\""],
  ["haryanvi", "खेत के रास्ते पर पोते ने ताऊ से पूछा, \"यह पगडंडी कहाँ जाती है?\"\nताऊ बोले, \"सीधे कुएँ तक।\"\nपोता बोला, \"नक्शे में तो दूसरा रास्ता दिखा रहा है।\"\nताऊ बोले, \"नक्शा देख, पर जमीन की चाल भी समझ।\""],
  ["haryanvi", "ढाबे पर ग्राहक ने कहा, \"चाय में चीनी कम रखना।\"\nमालिक बोला, \"ठीक सै।\"\nपहला घूँट लेकर ग्राहक बोला, \"अब तो फीकी है।\"\nमालिक हँसा, \"हुक्म भी मान लिया, शिकायत भी सुन ली!\""],
  ["haryanvi", "दंगल से पहले पहलवान ने गुरु के पैर छुए।\nगुरु बोले, \"आज ताकत से ज्यादा धीरज रखना।\"\nपहलवान बोला, \"अगर सामने वाला तेज निकला?\"\nगुरु बोले, \"तो दिमाग को उससे तेज चलाना।\""],
  ["haryanvi", "बस अड्डे पर छोरे ने पूछा, \"दिल्ली वाली बस कब आएगी?\"\nचायवाला बोला, \"घोषणा सुन ले।\"\nछोरा बोला, \"घोषणा तो हो गई।\"\nचायवाला हँसा, \"फिर बस को भी खबर मिलते ही आना चाहिए!\""],
  ["haryanvi", "पंचायत में एक युवक ने पानी बचाने का सुझाव दिया।\nबुजुर्ग बोले, \"पहले टपकता नल ठीक करवा।\"\nयुवक बोला, \"पोस्टर भी लगवाएँगे।\"\nबुजुर्ग हँसे, \"पोस्टर बाद में, पानी पहले बचा।\""],
  ["haryanvi", "ताऊ ने पुराने ट्रैक्टर की आवाज़ सुनी।\nपोते ने कहा, \"नई मशीन ले लो।\"\nताऊ बोले, \"पहले खराबी समझूँगा।\"\nपोता बोला, \"ठीक सै, हर आवाज़ पर नया सामान नहीं खरीदेंगे।\""],
  ["haryanvi", "गाँव के स्कूल में मास्टर ने पूछा, \"अनुशासन का मतलब?\"\nछोरा बोला, \"काम समय पर करना।\"\nमास्टर खुश हुए।\nछोरा बोला, \"और छुट्टी की घंटी पर सबसे पहले बाहर आना!\""],
  ["haryanvi", "दूधवाले ने ग्राहक से पूछा, \"थैली ठीक से बंद है?\"\nग्राहक बोला, \"हाँ, पर थोड़ा दूध बाहर लग गया।\"\nदूधवाला बोला, \"रास्ते में साइकिल का झटका लगा होगा।\"\nग्राहक हँसा, \"दूध घर पहुँचा, आधा रास्ते ने चख लिया!\""],
  ["haryanvi", "मेले में खिलौने वाले ने छोरे को लकड़ी की सीटी दिखाई।\nछोरा बोला, \"इसकी आवाज़ कितनी तेज है?\"\nदुकानदार बोला, \"बजा के देख।\"\nछोरे ने बजाई, तो पास की भैंस भी मुड़कर देखने लगी!"],
  ["haryanvi", "एक किसान ने पड़ोसी से पूछा, \"इस बार कौन सा बीज लिया?\"\nपड़ोसी बोला, \"पहले मिट्टी की जाँच करवाई।\"\nकिसान ने कहा, \"अच्छा किया, अंदाज़े से खर्च बढ़ता है।\"\nदोनों ने रिपोर्ट देखकर आगे की योजना बनाई।"],
  ["haryanvi", "चौपाल पर रेडियो में मौसम की खबर आई।\nएक बुजुर्ग बोले, \"आज हवा बदलेगी।\"\nपोता बोला, \"ऐप भी बारिश बता रहा है।\"\nबुजुर्ग हँसे, \"फिर छतरी रख ले, बहस बाद में कर लेंगे।\""],
  ["haryanvi", "ढाबे वाले ने पूछा, \"बाजरे की रोटी के साथ क्या दूँ?\"\nग्राहक बोला, \"लहसुन की चटनी।\"\nमालिक बोला, \"तीखी चलेगी?\"\nग्राहक हँसा, \"इतनी कि नींद खुले, दोस्ती ना टूटे!\""],
  ["haryanvi", "अखाड़े में लड़के ने कहा, \"आज मैं नया दाँव सीखूँगा।\"\nगुरु बोले, \"पहले पुराना दाँव सही कर।\"\nलड़का बोला, \"वो तो आता है।\"\nगुरु बोले, \"फिर अभ्यास में गलती क्यों दोहराता सै?\""],
  ["haryanvi", "गाँव की दुकान पर पोते ने ऑनलाइन भुगतान किया।\nदुकानदार ने पूछा, \"पैसे आए?\"\nपोता बोला, \"फोन पर सफल दिखा रहा है।\"\nदुकानदार बोला, \"मेरे खाते में भी दिख जाएँ, तब सौदा पूरा मानूँगा!\""],
  ["haryanvi", "ताऊ ने घर के बाहर नीम का पौधा लगाया।\nपोते ने पूछा, \"इसकी देखभाल कौन करेगा?\"\nताऊ बोले, \"जिसे छाँव चाहिए, वो पानी भी देगा।\"\nपोता बोला, \"फिर आज से मेरी बारी तय।\""],
  ["haryanvi", "किसान ने बेटे को औजार साफ़ करने को कहा।\nबेटा बोला, \"काम खत्म होने पर करूँगा।\"\nकिसान बोला, \"साफ़ औजार अगली बार समय बचावै सैं।\"\nबेटा बोला, \"आज ही रखरखाव का नियम बना दूँगा।\""],
  ["haryanvi", "बस में चढ़ते ही ताऊ ने खिड़की वाली सीट चुनी।\nपोता बोला, \"आपको वही सीट क्यों चाहिए?\"\nताऊ बोले, \"रास्ता देखना अच्छा लागै सै।\"\nपोता बोला, \"और मुझे फोन चलाना; सफर में दोनों का काम चल जाएगा!\""],
  ["haryanvi", "ताऊ ने नया चश्मा बनवाया और दुकान से बाहर आ गया।\nछोरे ने पूछा, “ताऊ, अब सब साफ दिखै सै?”\nताऊ बोला, “हाँ, पर बिल देख कै फिर धुंध छा गई।”\nदुकानदार दूर तै आवाज़ दे गया, “फ्रेम मजबूत सै, हिसाब भी संभाल लेगा!”"],
  ["haryanvi", "खेत में पोते ने दादा नै ड्रोन उड़ाता दिखाया।\nदादा बोले, “यो ऊपर जाके करैगा के?”\nपोता कह्या, “फसल की तस्वीर लेगा।”\nदादा हँसकै बोले, “पहले इसने बता दे, नीचे खाद किसने डाली सै।”"],
  ["haryanvi", "ताऊ बैंक में नया खाता खुलवाण पहुँचा।\nक्लर्क ने पूछा, “नाम बताइए।”\nताऊ बोला, “नाम तो पुराना सै, बस जमा नया शुरू करूँगा।”\nक्लर्क कह्या, “फेर पासबुक में उम्र ना, रकम बढ़ाइए।”"],
  ["haryanvi", "चौपाल पै दो दोस्त मोबाइल में मौसम देख रहे थे।\nएक बोला, “ऐप कहै सै आज बारिश होगी।”\nदूसरा बोला, “फेर छतरी ले चल।”\nपहला हँसकै कह्या, “छतरी घर पै सै, बारिश नै लोकेशन भेज दे।”"],
  ["haryanvi", "ताऊ ने ऑनलाइन दूध मँगवाया।\nडिलीवरी वाला बोला, “आपका पैकेट दरवाजे पै रख दिया।”\nताऊ बाहर आया तो थैली खाली थी।\nबोला, “दूध तो आया ना, बस बिल की मलाई रह गई।”"],
  ["haryanvi", "गाँव के स्कूल में मास्टर जी ने पूछा, “सबसे जरूरी चीज़ के सै?”\nछोरे ने कहा, “ज्ञान।”\nमास्टर जी खुश हो गए।\nछोरा बोला, “अर छुट्टी की घंटी, ताकि ज्ञान घर ले जा सकूँ।”"],
  ["haryanvi", "ताऊ ने फिटनेस ऐप में अपना लक्ष्य दस हजार कदम रखा।\nशाम तक खेत, दुकान और चौपाल के चक्कर लग गए।\nफोन ने बधाई दी तो ताऊ बोला, “अब इसने बता, आराम कितने कदम दूर सै?”\nपोता कह्या, “दादा, आराम का लक्ष्य कल रख लियो।”"],
  ["haryanvi", "पंचायत में सौर लाइट लगवाण की बात चली।\nसरपंच बोला, “अब गली रात नै भी चमकैगी।”\nएक ताऊ कह्या, “बढ़िया, पर बिल किसका घटेगा?”\nसरपंच बोला, “बिजली का।” ताऊ बोला, “फेर चाय मेरी तरफ तै।”"],
  ["haryanvi", "ताऊ की भैंस रोज़ एक ही जगह बैठ जाती थी।\nपोते ने पूछा, “दादा, इसने नई जगह क्यूँ ना पसंद?”\nताऊ बोला, “यो अपनी सीट बुक करकै बैठै सै।”\nपोता कह्या, “फेर टिकट कलेक्टर नै भी बता दे।”"],
  ["haryanvi", "मंडी में किसान ने भाव सुनकर माथा पकड़ लिया।\nव्यापारी बोला, “ताऊ, आज बाजार कमजोर सै।”\nकिसान कह्या, “मेरी फसल तो खेत में मजबूत खड़ी सै।”\nव्यापारी हँसकै बोला, “भाव नै भी खाद-पानी देणा पड़ेगा।”"],
  ["haryanvi", "ताऊ ने स्मार्ट टीवी खरीद लिया।\nपोती ने पूछा, “दादा, इसमें इंटरनेट चलैगा?”\nताऊ बोला, “हाँ, पर रिमोट पहले मेरे हाथ में रहैगा।”\nपोती कह्या, “फेर टीवी स्मार्ट सै, घर का नियम पुराना।”"],
  ["haryanvi", "गाँव की दुकान पर छोरे ने डिजिटल भुगतान किया।\nदुकानदार ने फोन देखकर कहा, “पैसे अभी आए ना।”\nछोरा बोला, “स्क्रीन पै सफल लिखा सै।”\nदुकानदार कह्या, “मेरे खाते में भी सफलता दिखा दे।”"],
  ["haryanvi", "ताऊ ने नई घड़ी में अलार्म लगाया।\nसुबह घड़ी बजती रही और ताऊ सोता रहा।\nपोते ने पूछा, “दादा, उठे क्यूँ ना?”\nताऊ बोला, “घड़ी नै जगाण की नौकरी दी थी, उठाण की ना।”"],
  ["haryanvi", "खेत में नलकूप बंद हो गया तो ताऊ मैकेनिक बुला लाया।\nमैकेनिक ने तार जाँचे और स्विच ठीक कर दिया।\nताऊ बोला, “इतना छोटा काम?”\nमैकेनिक कह्या, “काम छोटा था, बुलावा पूरे गाँव में घूम आया।”"],
  ["haryanvi", "ताऊ ने पोते से अंग्रेजी में रास्ता पूछना सीखा।\nपोते ने सिखाया, “गो स्ट्रेट।”\nअगले दिन ताऊ चौक पर सबको यही बताता रहा।\nएक राहगीर बोला, “किधर?” ताऊ कह्या, “पहले सीधा जा, फिर पूछ लियो।”"],
  ["haryanvi", "गाँव में कूड़ा उठाण वाली गाड़ी देर से आई।\nएक ताऊ ने चालक से पूछा, “आज इतनी देर क्यूँ?”\nचालक बोला, “रास्ते में जाम था।”\nताऊ कह्या, “कचरा भी अब शहर की तरह ट्रैफिक में फँसै सै।”"],
  ["haryanvi", "पोती ने दादा को वीडियो कॉल करना सिखाया।\nदादा ने फोन कान पर लगाया और कैमरे में छत दिखती रही।\nपोती बोली, “दादा, चेहरा दिखाओ।”\nदादा कह्या, “पहले फोन नै नीचे झुकना सीखण दे।”"],
  ["haryanvi", "ताऊ ने बाजार से छाता खरीद्या।\nदुकानदार बोला, “मजबूत है, तेज हवा में भी टिकेगा।”\nताऊ ने पूछा, “बारिश में?”\nदुकानदार कह्या, “वो तो पानी पर निर्भर सै।”"],
  ["haryanvi", "चौपाल पर ताऊ ने कहा कि अब खर्च लिखकर रखेगा।\nपोते ने पूछा, “दादा, सबसे बड़ा खर्च कौन-सा?”\nताऊ बोला, “तेरी ऑनलाइन पढ़ाई।”\nपोता कह्या, “फेर फीस के साथ वाई-फाई का भी ज्ञान ले लो।”"],
  ["haryanvi", "ताऊ ने गाँव के मेले में डिजिटल टिकट खरीदा।\nदरवाजे पर कर्मचारी ने स्क्रीन स्कैन करी।\nताऊ बोला, “कागज बच गया, बढ़िया काम सै।”\nफिर जेब टटोलकै कह्या, “पर टिकट संभालण की आदत अभी बाकी सै।”"],
  ["haryanvi", "ताऊ ने गाँव में नया सीसीटीवी कैमरा लगवाया।\nपोते ने पूछा, “दादा, अब सब दिखेगा?”\nताऊ बोला, “हाँ, पर पहले कैमरे नै चौपाल का रास्ता समझा दे।”\nपोता हँसकै कह्या, “दादा, कैमरा सै, सरपंच ना।”"],
  ["haryanvi", "खेत में ताऊ ने मिट्टी की जाँच करवाई।\nअधिकारी ने रिपोर्ट देकर खाद की सलाह दी।\nताऊ बोला, “रिपोर्ट तो ठीक सै, अब फसल नै भी पढ़वा दे।”\nअधिकारी कह्या, “फसल पढ़ेगी ना, बढ़ेगी।”"],
  ["haryanvi", "पोते ने दादा नै ऑनलाइन नक्शे पर गाँव दिखाया।\nदादा ने पूछा, “यो नीली लाइन के सै?”\nपोता बोला, “नहर का रास्ता।”\nदादा कह्या, “फेर ऐप नै बता, पानी कब आवैगा?”"],
  ["haryanvi", "ताऊ ने नया हेलमेट खरीद्या और खेत की सड़क पर निकल पड़ा।\nपोते ने कहा, “दादा, पट्टा बाँध लो।”\nताऊ बोला, “बाँध दिया, अब हवा भी चालान ना काटे।”\nपोता कह्या, “हवा ना, पुलिस देखेगी।”"],
  ["haryanvi", "गाँव की दुकान पर ताऊ ने यूपीआई से भुगतान किया।\nदुकानदार ने आवाज़ सुनकर कहा, “पैसे आ गए।”\nताऊ बोला, “अब रसीद भी भेज दे।”\nदुकानदार हँसकै कह्या, “ताऊ, दुकान सै, दफ्तर ना।”"],
  ["haryanvi", "चौपाल पर दो ताऊ खेती की मशीनों की बात कर रहे थे।\nएक बोला, “नई मशीन आधा काम कर दे सै।”\nदूसरा कह्या, “बाकी आधा कौन करैगा?”\nपहला बोला, “मालिक, जो किस्त भरैगा।”"],
  ["haryanvi", "ताऊ ने पोते को साइकिल चलाना सिखाया।\nपोता बोला, “दादा, हाथ छोड़ दूँ?”\nताऊ कह्या, “पहले संतुलन सीख।”\nपोता बोला, “आप भी तो बिना चश्मे के संतुलन खो देते हो।”"],
  ["haryanvi", "गाँव में नया एटीएम लगा तो ताऊ देखने पहुँच गया।\nगार्ड ने पूछा, “पैसे निकालने हैं?”\nताऊ बोला, “पहले मशीन का मिज़ाज देखूँगा।”\nगार्ड कह्या, “मशीन चुप सै, बस कार्ड सही डालो।”"],
  ["haryanvi", "ताऊ ने खेत में मौसम स्टेशन लगवाया।\nपोते ने पूछा, “अब बारिश पहले पता चल जाएगी?”\nताऊ बोला, “हाँ, पर बादल नै भी सूचना भेजणी पड़ेगी।”\nपोता कह्या, “दादा, बादल नेटवर्क से बाहर सै।”"],
  ["haryanvi", "पंचायत ने सड़क पर स्पीड ब्रेकर बनवाया।\nताऊ ने बाइक धीमी करी और बोला, “अच्छा काम सै।”\nछोरे ने पूछा, “क्यूँ ताऊ?”\nताऊ कह्या, “अब गड्ढे भी आराम तै मिलेंगे।”"],
  ["haryanvi", "ताऊ ने नया ट्रैक्टर लेने से पहले टेस्ट ड्राइव माँगी।\nडीलर बोला, “किस खेत में चलाएँ?”\nताऊ कह्या, “पहले कच्चे रास्ते पै, असली परीक्षा वहीं सै।”\nडीलर बोला, “ताऊ, आपने मशीन नहीं, उम्मीदवार चुनना सै।”"],
  ["haryanvi", "पोती ने दादा को ऑनलाइन बिल भरना सिखाया।\nदादा ने पूछा, “पैसा गया कहाँ?”\nपोती बोली, “सीधे विभाग में।”\nदादा कह्या, “फेर रसीद ऐसी दे कि विभाग भी मान ले।”"],
  ["haryanvi", "चौपाल में ताऊ ने कहा कि अब वह रोज़ योग करेगा।\nदोस्त ने पूछा, “कौन-सा आसन?”\nताऊ बोला, “पहले सुबह उठने वाला आसन सीखूँगा।”\nदोस्त कह्या, “उसमें अलार्म सबसे बड़ा गुरु सै।”"],
  ["haryanvi", "गाँव के मेले में ताऊ ने डिजिटल फोटो खिंचवाई।\nफोटोग्राफर बोला, “थोड़ा मुस्कुराइए।”\nताऊ कह्या, “पहले फोटो का दाम बता।”\nफोटोग्राफर बोला, “मुस्कान मुफ्त सै, प्रिंट का हिसाब अलग।”"],
  ["haryanvi", "ताऊ ने घर में सोलर पैनल लगवाए।\nपोते ने पूछा, “अब बिजली का बिल कम आएगा?”\nताऊ बोला, “हाँ, पर पहले छत पर धूप की जगह खाली करणी पड़ी।”\nपोता कह्या, “दादा, कबूतरों का किराया भी जोड़ लो।”"],
  ["haryanvi", "किसान ने मंडी जाने से पहले फसल तौल ली।\nताऊ ने कहा, “आज हिसाब पक्का रखूँगा।”\nव्यापारी बोला, “काँटा सही सै।”\nताऊ कह्या, “फेर भाव भी सीधा रख, बात बराबर हो जागी।”"],
  ["haryanvi", "ताऊ ने गाँव की लाइब्रेरी में किताब लौटाई।\nलाइब्रेरियन ने कहा, “दो दिन देर हो गई।”\nताऊ बोला, “किताब में ज्ञान ज्यादा था, समय कम पड़ गया।”\nलाइब्रेरियन हँसकै कह्या, “अगली बार तारीख़ भी पढ़ लियो।”"],
  ["haryanvi", "पोते ने दादा को स्मार्ट स्पीकर चलाना सिखाया।\nदादा बोले, “इससे गाना बजवा सकते हैं?”\nपोता बोला, “हाँ, बस नाम बोलो।”\nदादा कह्या, “पहले इसने बता, मेरी आवाज़ पहचानैगा के?”"],
  ["haryanvi", "ताऊ ने खेत की मेड़ पर पौधे लगाए।\nपोते ने पूछा, “दादा, इतने सारे क्यूँ?”\nताऊ बोला, “छाँव भी मिलेगी अर मिट्टी भी बचेगी।”\nपोता कह्या, “फेर सेल्फी की जगह भी तय हो गई।”"],
  ["haryanvi", "गाँव में बस का नया टाइम-टेबल लगा।\nताऊ ने उसे ध्यान से पढ़ा और घड़ी मिलाई।\nकंडक्टर बोला, “अब बस समय पर मिलेगी।”\nताऊ कह्या, “फेर मैं भी पहली बार समय पर पहुँचूँगा।”"],
  ["haryanvi", "खेत की मिट्टी जाँचवाने ताऊ लैब पहुँचा।\nकर्मचारी ने पूछा, “रिपोर्ट किस नाम से बनाऊँ?”\nताऊ बोला, “मिट्टी के नाम से, मेहनत तो इसी की सै।”\nकिसान मित्र हँसा, “नाम सही, अब खाद भी सही डालिए।”"],
  ["haryanvi", "ताऊ ने बिजली का बिल हाथ में लेकर चौपाल पर बात छेड़ी।\nएक किसान बोला, “इस बार मेरा बिल कम आया सै।”\nदूसरे ने पूछा, “कितना कम?”\nवह बोला, “इतना कि घरवाली ने बिल देख कै मेरी शक्ल देखी।”"],
  ["haryanvi", "पोते ने खेत की पगडंडी पर नई साइकिल दौड़ाई।\nदादा ने पूछा, “हाथ छोड़ कै चला लेगा?”\nपोता बोला, “पहले आप पीछे तै पकड़ कै रखो।”\nदादा हँसे, “साइकिल ते ज्यादा भरोसा तन्नै मेरी कमर पै सै।”"],
  ["haryanvi", "गाँव के मेले में ताऊ ने डिजिटल टिकट खरीदी।\nकर्मचारी ने कहा, “फोन पर टिकट दिखाओ।”\nताऊ ने स्क्रीन आगे कर दी, “टिकट भी यहीं सै, फोटो भी यहीं।”\nकर्मचारी हँसा, “बस मौसम का ऐप मत खोल दियो।”"],
  ["haryanvi", "मास्टर जी ने पूछा, “पानी बचाने का तरीका बताओ।”\nछोरे ने कहा, “नल खुला छोड़ण वाले नै समझाओ।”\nमास्टर जी बोले, “वो ना समझे तो?”\nछोरा बोला, “फेर ताऊ की तरह बिल दिखा दो।”"],
  ["haryanvi", "ताऊ ने घर के बाहर वर्षा जल का ड्रम रखा।\nपड़ोसी ने पूछा, “कितना पानी जमा होग्या?”\nताऊ बोला, “अभी बादलां की मीटिंग चल री सै।”\nपड़ोसी हँसा, “ड्रम तैयार रख, फैसला ऊपर तै आवेगा।”"],
  ["haryanvi", "किसान ने नई किस्म का बीज खरीदा।\nदुकानदार बोला, “उपज अच्छी होगी।”\nकिसान बोला, “बीज अच्छा हो, मेहनत मेरी हो, मौसम साथ दे।”\nदुकानदार ने पूछा, “गारंटी किस बात की?”\nकिसान बोला, “तेरी बात याद रखण की!”"],
  ["haryanvi", "ताऊ ने मोबाइल में कदम गिनने वाला ऐप लगाया।\nपोते ने पूछा, “आज कितने कदम चले?”\nताऊ बोला, “ऐप कहै पाँच हजार।”\nपोता बोला, “खेत का चक्कर?”\nताऊ हँसा, “वो जूते में दर्ज सै।”"],
  ["haryanvi", "चाय की दुकान पर दो दोस्त महँगाई पर बोले।\nएक ने कहा, “पहले चाय के साथ बिस्कुट भी मिलते थे।”\nदूसरा बोला, “अब बिस्कुट अलग पैसे के सैं।”\nताऊ ने कप उठाया, “चाय की गर्मी अभी भी मुफ्त सलाह देती सै।”"],
  ["haryanvi", "सरपंच ने कूड़ा अलग-अलग जमा करने की बात कही।\nताऊ ने पूछा, “गीला और सूखा अलग क्यों?”\nसरपंच बोला, “ताकि सही निपटान हो।”\nताऊ ने कहा, “ठीक सै, अब बहस भी अलग-अलग घरां में करियो।”"],
  ["haryanvi", "छोरे ने ताऊ से पूछा, “गाँव में सबसे तेज़ इंटरनेट कहाँ चलता है?”\nताऊ बोले, “चौपाल पर, वहाँ खबर बिना रिचार्ज के फैलती है।”\nछोरा बोला, “फिर पासवर्ड क्या है?”\nताऊ हँसे, “पहले खुद आ, फिर सब बता देंगे।”"],
  ["haryanvi", "सरपंच ने ताऊ से पूछा, “बैठक में देर क्यूँ हो गई?”\nताऊ बोले, “रास्ते में दो लोग बहस कर रहे थे।”\n“तो आपने सुलझाई?”\n“ना, मैं भी बैठ गया; अब तीनों की देर हो री सै।”"],
  ["haryanvi", "छोरी ने दादा से पूछा, “आप रोज़ सुबह खेत क्यूँ जाते हो?”\nदादा बोले, “फसल का हाल देखण।”\nछोरी बोली, “मोबाइल में फोटो देख लो।”\nदादा हँसे, “फोटो में मिट्टी की खुशबू कहाँ सूंघेगी?”"],
  ["haryanvi", "ताऊ ने नया स्मार्टवॉच पहना और सबको समय बताने लगे।\nपोते ने पूछा, “ताऊ, कदम भी गिनता है?”\nताऊ बोले, “हाँ, पर घरवाली के सामने मत बताइयो।”\n“क्यूँ?”\n“वो कहेगी, खेत तक पैदल जा, गाड़ी काहे माँगे सै!”"],
  ["haryanvi", "चौधरी ने दुकान वाले से पूछा, “भाई, दूध शुद्ध सै ना?”\nदुकानदार बोला, “बिलकुल, एकदम असली।”\nचौधरी ने कहा, “फिर चाय में रंग क्यूँ ना आया?”\nदुकानदार बोला, “चौधरी साहब, दूध शुद्ध सै, आपकी चाय की पत्ती छुट्टी पर सै।”"],
  ["haryanvi", "पोते ने ताऊ से कहा, “आज स्कूल में पर्यावरण पर भाषण दिया।”\nताऊ खुश होकर बोले, “के बताया?”\n“पेड़ लगाओ, पानी बचाओ।”\nताऊ बोले, “बढ़िया, अब भाषण छोड़ और आँगन का नल बंद कर।”"],
  ["haryanvi", "ताऊ ने ऑनलाइन टिकट बुक कराई और प्रिंटआउट संभाल लिया।\nपोते ने पूछा, “मोबाइल में टिकट है, कागज़ क्यूँ?”\nताऊ बोले, “बिजली गई तो?”\nपोता बोला, “ट्रेन भी बिजली से चलती है, ताऊ!”"],
  ["haryanvi", "गाँव के मेले में उद्घोषक बोला, “जो जीतेगा उसे इनाम मिलेगा।”\nताऊ ने पूछा, “इनाम में के सै?”\nउद्घोषक बोला, “एक शानदार ट्रॉफी।”\nताऊ बोले, “फिर तो हारने वाले का फायदा, घर में जगह बची रहेगी।”"],
  ["haryanvi", "छोरे ने ताऊ से पूछा, “आपने गुस्सा कम कैसे कर लिया?”\nताऊ बोले, “अब मैं दस तक गिनता हूँ।”\nछोरा बोला, “पहले क्या करते थे?”\nताऊ बोले, “सीधे जवाब देता था, इसलिए गाँव में दस दुश्मन बढ़ गए।”"],
  ["haryanvi", "दादी ने ताऊ से कहा, “आज सब्ज़ी मंडी से धनिया ले आना।”\nताऊ लौटे तो थैले में पूरा पौधा था।\nदादी बोली, “इतना सारा क्यूँ?”\nताऊ बोले, “भाव रोज़ बढ़ते हैं, मैंने भविष्य की खेती कर ली।”"],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—जीजा जी, दावत में सबसे पहले क्या खाएँगे।\nसाली ने पूछा, \"जीजा जी, दावत में सबसे पहले क्या खाएँगे?\"\nजीजा ने जवाब दिया, \"पहले सलाद;\nताकि बाकी पकवान के लिए जगह की योजना बन सके।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—खाना कैसा लगा।\nसाली ने पूछा, \"खाना कैसा लगा?\"\nजीजा ने जवाब दिया, \"स्वाद बढ़िया है;\nअब रसोई वाले को भी धन्यवाद देना चाहिए।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—इतनी मिठाई क्यों ली।\nसाली ने पूछा, \"इतनी मिठाई क्यों ली?\"\nजीजा ने जवाब दिया, \"परिवार बड़ा है;\nडिब्बा भी सामाजिक जिम्मेदारी निभा रहा है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—आपको कौन-सी डिश पसंद है।\nसाली ने पूछा, \"आपको कौन-सी डिश पसंद है?\"\nजीजा ने जवाब दिया, \"जो सबके साथ बाँटी जाए;\nअकेले खाने में मज़ा कम है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—जीजा जी, प्लेट खाली क्यों है।\nसाली ने पूछा, \"जीजा जी, प्लेट खाली क्यों है?\"\nजीजा ने जवाब दिया, \"खाना अच्छा था;\nप्लेट ने भी तारीफ़ करके जवाब दिया।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—दावत कब खत्म होगी।\nसाली ने पूछा, \"दावत कब खत्म होगी?\"\nजीजा ने जवाब दिया, \"जब आख़िरी मेहमान कहे पेट भर गया,\nफोटो नहीं।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—आपने नमक चखा।\nसाली ने पूछा, \"आपने नमक चखा?\"\nजीजा ने जवाब दिया, \"हाँ; स्वाद सही है,\nअब बातचीत में भी मिठास रखो।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—मिठाई कौन बाँटेगा।\nसाली ने पूछा, \"मिठाई कौन बाँटेगा?\"\nजीजा ने जवाब दिया, \"जो सबसे पहले हाथ बढ़ाए;\nबराबरी से बाँटना।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—आप इतना धीरे क्यों खा रहे।\nसाली ने पूछा, \"आप इतना धीरे क्यों खा रहे?\"\nजीजा ने जवाब दिया, \"स्वाद का सम्मान कर रहा हूँ;\nजल्दी में पकवान भी नाराज़ होगा।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—दावत की सबसे अच्छी बात।\nसाली ने पूछा, \"दावत की सबसे अच्छी बात?\"\nजीजा ने जवाब दिया, \"साथ बैठना;\nपकवान तो अगली बार भी बनेंगे।\""],
  ["jija-sali", "साली ने जीजा से पूछा, \"आप हर फोटो में चश्मा क्यों पहनते हैं?\"\nजीजा बोले, \"ताकि दुनिया मुझे स्मार्ट समझे।\"\nसाली ने कहा, \"फिर चश्मा उतारकर भी देखिए।\"\nजीजा बोले, \"वही तो दुनिया से छिपाकर रखता हूँ।\""],
  ["jija-sali", "साली ने पूछा, \"जीजाजी, घर में आपकी चलती है?\"\nजीजा बोले, \"बिल्कुल, मैं रोज़ सुबह टहलने जाता हूँ।\"\nसाली हँसी, \"मैंने घर के अंदर की बात पूछी थी।\"\nजीजा बोले, \"वहाँ तो मेरी चप्पल भी अनुमति लेकर चलती है।\""],
  ["jija-sali", "जीजा ने कहा, \"आज मैंने खाना बनाया है।\"\nसाली ने प्लेट देखकर पूछा, \"रेसिपी कहाँ से सीखी?\"\nजीजा बोले, \"वीडियो देखकर।\"\nसाली बोली, \"और स्वाद?\" जीजा बोले, \"वीडियो में तो बहुत अच्छा लग रहा था।\""],
  ["jija-sali", "साली ने जीजा से पूछा, \"आप हर काम कल पर क्यों छोड़ते हैं?\"\nजीजा बोले, \"कल में बहुत संभावनाएँ हैं।\"\nसाली ने कहा, \"आज में भी एक मौका है।\"\nजीजा बोले, \"आज को इतना दबाव मत दो, कल को भी काम चाहिए।\""],
  ["jija-sali", "जीजा ने कहा, \"मैंने घर में नई अलमारी लगवाई है।\"\nसाली ने पूछा, \"कितनी बड़ी है?\"\nजीजा बोले, \"इतनी कि सारे राज़ समा जाएँ।\"\nसाली बोली, \"तो फिर आपकी पुरानी बातें कहाँ रखें?\""],
  ["jija-sali", "साली ने पूछा, \"जीजाजी, आप खाना बनाते समय गाना क्यों गाते हैं?\"\nजीजा बोले, \"ताकि रसोई में माहौल अच्छा रहे।\"\nसाली ने चखकर कहा, \"और स्वाद?\"\nजीजा बोले, \"वह संगीत की तरह समझने वालों के लिए है।\""],
  [ "jija-sali", "साली ने जीजाजी से पूछा, “आप घर में सबसे ज़्यादा किसकी सुनते हैं?”\nजीजा बोले, “जो आख़िरी बार बोलता है।”\nसाली ने पूछा, “वह कौन?”\nजीजा बोले, “प्रेशर कुकर की सीटी; उसके बाद सब चुप हो जाते हैं।”" ],
  [ "jija-sali", "साली ने पूछा, “जीजाजी, आप हर फोटो में मुस्कराते क्यों हैं?”\nजीजा बोले, “ताकि तस्वीर अच्छी आए।”\nसाली ने कहा, “पर आँखें बंद हैं।”\nजीजा बोले, “कैमरा खुला था, मेरी किस्मत नहीं।”" ],
  [ "jija-sali", "साली ने जीजाजी से कहा, “आज चाय आप बनाएँगे।”\nजीजा ने बड़े ध्यान से अदरक कूटी और दूध उबाला।\nसाली ने पूछा, “चीनी कितनी?”\nजीजा बोले, “जितनी तारीफ़ मिलेगी, उतनी अगली बार कम कर दूँगा।”" ],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—समय की सबसे अच्छी सलाह।\nसाली ने पूछा, \"समय की सबसे अच्छी सलाह?\"\nजीजा ने जवाब दिया, \"लोगों को समय दो;\nघड़ी खुद रास्ता बता देगी।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कितना सामान खरीदेंगे।\nसाली ने पूछा, \"कितना सामान खरीदेंगे?\"\nजीजा ने जवाब दिया, \"सूची जितना;\nसाली ने कहा सूची में अभी इच्छा बाकी है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—भाव कम करवाओगे।\nसाली ने पूछा, \"भाव कम करवाओगे?\"\nजीजा ने जवाब दिया, \"कोशिश करूँगा;\nदुकानदार से मुस्कान भी साथ लेनी होगी।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—यह बैग कैसा है।\nसाली ने पूछा, \"यह बैग कैसा है?\"\nजीजा ने जवाब दिया, \"अच्छा है;\nबस घर में बैग रखने की जगह भी खरीदनी पड़ेगी।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—ऑफ़र असली है।\nसाली ने पूछा, \"ऑफ़र असली है?\"\nजीजा ने जवाब दिया, \"पहले तुलना करेंगे;\nछूट का बोर्ड सबूत नहीं होता।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—आपने रसीद रखी।\nसाली ने पूछा, \"आपने रसीद रखी?\"\nजीजा ने जवाब दिया, \"हाँ; खरीदारी के बाद याददाश्त,\nपर निर्भर नहीं रहना चाहिए।\""],
  [ "jija-sali", "साली ने पूछा, “जीजाजी, आप हर काम की सूची क्यों बनाते हैं?”\nजीजा बोले, “ताकि कुछ भूल न जाऊँ।”\nसाली ने पूछा, “आराम भी लिखा है?”\nजीजा बोले, “हाँ, पर आगे ‘यदि समय मिला’ लिखा है।”" ],
  [ "jija-sali", "साली ने पूछा, “आपको घर का रास्ता याद है?”\nजीजा बोले, “बिल्कुल।”\nसाली ने कहा, “फिर हर बार मैप क्यों देखते हैं?”\nजीजा बोले, “रास्ता याद है, घर पहुँचने का समय परिवार तय करता है।”" ],
  [ "jija-sali", "साली ने कहा, “आज खाना बनाने में मदद कीजिए।”\nजीजा ने सब्ज़ियाँ काटीं और मसाले निकाले।\nसाली ने पूछा, “अब क्या करें?”\nजीजा बोले, “पहले तारीफ़ कर दो, फिर अगला निर्देश सुनने की ताकत आएगी।”" ],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—खरीदारी पूरी हुई।\nसाली ने पूछा, \"खरीदारी पूरी हुई?\"\nजीजा ने जवाब दिया, \"हाँ; अब घर जाकर,\nसूची से मिलान करेंगे।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—सबसे अच्छा सौदा।\nसाली ने पूछा, \"सबसे अच्छा सौदा?\"\nजीजा ने जवाब दिया, \"जरूरत की चीज़ सही दाम पर,\nमिले और पछतावा न हो।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—यह फ़िल्टर मुझे कैसा दिखाता है।\nसाली ने पूछा, \"यह फ़िल्टर मुझे कैसा दिखाता है?\"\nजीजा ने जवाब दिया, \"मज़ेदार;\nअसली मुस्कान तो बिना फ़िल्टर के भी अच्छी है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—फोटो में आँखें बड़ी क्यों हैं।\nसाली ने पूछा, \"फोटो में आँखें बड़ी क्यों हैं?\"\nजीजा ने जवाब दिया, \"फ़िल्टर ने उत्साह बढ़ा दिया;\nअब कैमरा भी हैरान है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—वीडियो कहाँ पोस्ट करूँ।\nसाली ने पूछा, \"वीडियो कहाँ पोस्ट करूँ?\"\nजीजा ने जवाब दिया, \"पहले परिवार से पूछ लो;\nहर पल सार्वजनिक नहीं होता।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—यह फ़िल्टर सुरक्षित है।\nसाली ने पूछा, \"यह फ़िल्टर सुरक्षित है?\"\nजीजा ने जवाब दिया, \"ऐप की अनुमति जाँचो;\nकैमरा हर समय खुला न रहे।\""],
  ["jija-sali", "परिवार की फोटो खिंचने से पहले सबने अपनी जगह बदली।\nसाली ने पूछा, \"कैमरे में सब ठीक दिख रहे हैं?\"\nजीजा बोले, \"हाँ, बस मुस्कान असली रखो।\"\nसाली ने कहा, \"और फोटो भेजने से पहले सबकी इजाज़त भी।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कितने फ़िल्टर हैं।\nसाली ने पूछा, \"कितने फ़िल्टर हैं?\"\nजीजा ने जवाब दिया, \"बहुत; पर सबसे अच्छा,\nफ़िल्टर अच्छी रोशनी है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—वीडियो क्यों अटक गया।\nसाली ने पूछा, \"वीडियो क्यों अटक गया?\"\nजीजा ने जवाब दिया, \"नेटवर्क धीमा है;\nफ़िल्टर भी इंतज़ार कर रहा है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—आप भी फ़िल्टर लगाएँगे।\nसाली ने पूछा, \"आप भी फ़िल्टर लगाएँगे?\"\nजीजा ने जवाब दिया, \"पहले कैमरा ढूँढ़ लूँ;\nफिर तकनीक से दोस्ती करूँगा।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—फोटो में कौन अच्छा लग रहा।\nसाली ने पूछा, \"फोटो में कौन अच्छा लग रहा?\"\nजीजा ने जवाब दिया, \"सब; परिवार की तस्वीर,\nमें तुलना नहीं होती।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—डिजिटल तस्वीर का नियम।\nसाली ने पूछा, \"डिजिटल तस्वीर का नियम?\"\nजीजा ने जवाब दिया, \"मज़ा लो,\nगोपनीयता रखो और साझा करने से पहले पूछो।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—ऐसी कौन-सी चीज़ है जो बाँटने से बढ़ती है।\nसाली ने पूछा, \"ऐसी कौन-सी चीज़ है जो बाँटने से बढ़ती है?\"\nजीजा ने जवाब दिया, \"खुशी; साली बोली,\nमिठाई भी बाँटो तो खुशी दिखेगी।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कौन बिना पैर के चलता है।\nसाली ने पूछा, \"कौन बिना पैर के चलता है?\"\nजीजा ने जवाब दिया, \"समय; साली ने कहा,\nऔर आपकी बातें भी।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कौन-सी चाबी ताला नहीं खोलती।\nसाली ने पूछा, \"कौन-सी चाबी ताला नहीं खोलती?\"\nजीजा ने जवाब दिया, \"कीबोर्ड की चाबी;\nसाली बोली, अब जवाब अपडेटेड है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कौन-सी चीज़ सबके पास है पर दिखती नहीं।\nसाली ने पूछा, \"कौन-सी चीज़ सबके पास है पर दिखती नहीं?\"\nजीजा ने जवाब दिया, \"विचार; साली बोली,\nकुछ लोगों के विचार बहुत ज़ोर से दिखते हैं।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—किसका सिर है पर दिमाग नहीं।\nसाली ने पूछा, \"किसका सिर है पर दिमाग नहीं?\"\nजीजा ने जवाब दिया, \"कील का;\nसाली बोली, कुछ बहानों का भी।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कौन-सा घर बिना दरवाज़े का है।\nसाली ने पूछा, \"कौन-सा घर बिना दरवाज़े का है?\"\nजीजा ने जवाब दिया, \"घोंसला;\nसाली बोली, पर मेहमानों को बुलाना मत।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कौन-सा फल पढ़ाई में मदद करे।\nसाली ने पूछा, \"कौन-सा फल पढ़ाई में मदद करे?\"\nजीजा ने जवाब दिया, \"ज्ञान का फल;\nसाली बोली, पहले किताब का पेड़ लगाइए।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—किसकी आवाज़ नहीं पर जवाब है।\nसाली ने पूछा, \"किसकी आवाज़ नहीं पर जवाब है?\"\nजीजा ने जवाब दिया, \"आईना; साली बोली,\nवह भी आपकी हेयरस्टाइल पर टिप्पणी करता है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कौन-सा काम बैठकर भी दौड़ता है।\nसाली ने पूछा, \"कौन-सा काम बैठकर भी दौड़ता है?\"\nजीजा ने जवाब दिया, \"दिमाग; साली बोली,\nखासकर परीक्षा से एक रात पहले।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—पहेली का सबसे अच्छा हिस्सा।\nसाली ने पूछा, \"पहेली का सबसे अच्छा हिस्सा?\"\nजीजा ने जवाब दिया, \"जवाब; साली बोली,\nऔर जवाब के बाद आपकी शक्ल।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—रास्ता किस ओर है।\nसाली ने पूछा, \"रास्ता किस ओर है?\"\nजीजा ने जवाब दिया, \"नक्शा देख लेते हैं;\nअनुमान से छुट्टी लंबी हो जाएगी।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कितनी दूर बाकी है।\nसाली ने पूछा, \"कितनी दूर बाकी है?\"\nजीजा ने जवाब दिया, \"जीपीएस बता रहा है;\nजीजा बोले, वह भी हमसे ज़्यादा धैर्यवान है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—पहाड़ दिख रहे हैं।\nसाली ने पूछा, \"पहाड़ दिख रहे हैं?\"\nजीजा ने जवाब दिया, \"हाँ; कैमरे से पहले,\nआँखों से देखो।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—गाड़ी में संगीत कौन चुनेगा।\nसाली ने पूछा, \"गाड़ी में संगीत कौन चुनेगा?\"\nजीजा ने जवाब दिया, \"बारी-बारी से;\nजीजा बोले, यही लोकतांत्रिक यात्रा है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—रास्ते में भूख लगी।\nसाली ने पूछा, \"रास्ते में भूख लगी?\"\nजीजा ने जवाब दिया, \"ढाबे पर रुकेंगे;\nसफर में पानी और आराम भी जरूरी है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—नक्शा उल्टा क्यों दिख रहा।\nसाली ने पूछा, \"नक्शा उल्टा क्यों दिख रहा?\"\nजीजा ने जवाब दिया, \"फोन घुमाइए;\nजीजा बोले, अब रास्ता भी घूम गया।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कौन गाड़ी चलाएगा।\nसाली ने पूछा, \"कौन गाड़ी चलाएगा?\"\nजीजा ने जवाब दिया, \"जो आराम में हो,\nऔर नियम मानता हो।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—यात्रा का बजट कितना है।\nसाली ने पूछा, \"यात्रा का बजट कितना है?\"\nजीजा ने जवाब दिया, \"पहले योजना;\nजीजा बोले, फिर खर्च का हिसाब।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—फोटो कहाँ लें।\nसाली ने पूछा, \"फोटो कहाँ लें?\"\nजीजा ने जवाब दिया, \"सुरक्षित जगह पर;\nसड़क के बीच नहीं।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—यात्रा की सीख।\nसाली ने पूछा, \"यात्रा की सीख?\"\nजीजा ने जवाब दिया, \"साथ चलना मंज़िल से,\nभी अच्छा है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—चाय कौन बनाएगा।\nसाली ने पूछा, \"चाय कौन बनाएगा?\"\nजीजा ने जवाब दिया, \"मैं; साली बोली,\nपहले गैस और पानी का सही हिसाब कर लें।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—चीनी कितनी डालूँ।\nसाली ने पूछा, \"चीनी कितनी डालूँ?\"\nजीजा ने जवाब दिया, \"जितनी जरूरत;\nजीजा बोले, रिश्ते में मिठास अलग से है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—चाय कड़क है।\nसाली ने पूछा, \"चाय कड़क है?\"\nजीजा ने जवाब दिया, \"इतनी कि कप ने भी,\nसीधा बैठना सीख लिया।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—बिस्कुट कहाँ हैं।\nसाली ने पूछा, \"बिस्कुट कहाँ हैं?\"\nजीजा ने जवाब दिया, \"डिब्बे में;\nजीजा बोले, डिब्बा खाली है, अब सच भी परोस दो।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—चाय में अदरक डाली।\nसाली ने पूछा, \"चाय में अदरक डाली?\"\nजीजा ने जवाब दिया, \"हाँ; साली बोली,\nअब चाय की खुशबू से घर जागेगा।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कप कौन धोएगा।\nसाली ने पूछा, \"कप कौन धोएगा?\"\nजीजा ने जवाब दिया, \"जिसने चाय बनाई;\nसाली बोली, नियम लिखित में चाहिए।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—चाय ठंडी क्यों है।\nसाली ने पूछा, \"चाय ठंडी क्यों है?\"\nजीजा ने जवाब दिया, \"बातचीत लंबी हो गई;\nअगली बार कप भी साथ बैठेंगे।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—दूसरा कप चाहिए।\nसाली ने पूछा, \"दूसरा कप चाहिए?\"\nजीजा ने जवाब दिया, \"पहले पहला खत्म करें;\nचाय भी आराम चाहती है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—चाय कैसी बनी।\nसाली ने पूछा, \"चाय कैसी बनी?\"\nजीजा ने जवाब दिया, \"ठीक; अब अभ्यास,\nजारी रखिए।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—चाय का असली स्वाद।\nसाली ने पूछा, \"चाय का असली स्वाद?\"\nजीजा ने जवाब दिया, \"साथ बैठकर पीने में;\nरेसिपी बाद में।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—खेल में कौन जीतेगा।\nसाली ने पूछा, \"खेल में कौन जीतेगा?\"\nजीजा ने जवाब दिया, \"जो नियम समझे;\nसाली बोली, और स्कोर लिखना न भूले।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—टीम कैसे बनाएँ।\nसाली ने पूछा, \"टीम कैसे बनाएँ?\"\nजीजा ने जवाब दिया, \"सबको मौका दें;\nजीजा बोले, यही सही कप्तानी है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—मैं हार गया तो।\nसाली ने पूछा, \"मैं हार गया तो?\"\nजीजा ने जवाब दिया, \"फिर सीखेंगे;\nखेल में बहाना नहीं चलता।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—नियम किसने बदले।\nसाली ने पूछा, \"नियम किसने बदले?\"\nजीजा ने जवाब दिया, \"किसी ने नहीं;\nआपने पढ़े ही नहीं।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—स्कोर बराबर है।\nसाली ने पूछा, \"स्कोर बराबर है।\"\nजीजा ने जवाब दिया, \"अच्छा मुकाबला है;\nअब आख़िरी दौर में ध्यान रखो।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कौन रेफरी बनेगा।\nसाली ने पूछा, \"कौन रेफरी बनेगा?\"\nजीजा ने जवाब दिया, \"जो निष्पक्ष रहे;\nरिश्तेदारी से नियम नहीं बदलेंगे।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—खेल में झगड़ा क्यों हुआ।\nसाली ने पूछा, \"खेल में झगड़ा क्यों हुआ?\"\nजीजा ने जवाब दिया, \"जीत जरूरी लगी;\nसम्मान उससे भी जरूरी है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—अगला खेल कौन-सा।\nसाली ने पूछा, \"अगला खेल कौन-सा?\"\nजीजा ने जवाब दिया, \"ऐसा जिसमें सब,\nशामिल हों।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—पुरस्कार क्या होगा।\nसाली ने पूछा, \"पुरस्कार क्या होगा?\"\nजीजा ने जवाब दिया, \"सबको चाय;\nविजेता को अतिरिक्त बिस्कुट।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—खेल का नतीजा।\nसाली ने पूछा, \"खेल का नतीजा?\"\nजीजा ने जवाब दिया, \"हँसी सबकी हुई;\nयही असली जीत है।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—फोटो कौन खींचेगा।\nसाली ने पूछा, \"फोटो कौन खींचेगा?\"\nजीजा ने जवाब दिया, \"मैं; साली बोली,\nपहले लेंस साफ़ करिए।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—सबकी आँखें खुली हैं।\nसाली ने पूछा, \"सबकी आँखें खुली हैं?\"\nजीजा ने जवाब दिया, \"लगभग; एक और फोटो लेते हैं,\nधैर्य रखो।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कैमरा कहाँ रखें।\nसाली ने पूछा, \"कैमरा कहाँ रखें?\"\nजीजा ने जवाब दिया, \"सुरक्षित जगह;\nफोन गिरा तो यादें धुँधली हो जाएँगी।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—फोटो अच्छी आई।\nसाली ने पूछा, \"फोटो अच्छी आई?\"\nजीजा ने जवाब दिया, \"हाँ; पर साझा करने से,\nपहले सबकी अनुमति लें।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—सेल्फी में कौन आगे।\nसाली ने पूछा, \"सेल्फी में कौन आगे?\"\nजीजा ने जवाब दिया, \"जो कैमरा पकड़े;\nजीजा बोले, जिम्मेदारी भी उसी की।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—पृष्ठभूमि कैसी है।\nसाली ने पूछा, \"पृष्ठभूमि कैसी है?\"\nजीजा ने जवाब दिया, \"सुंदर; बस पीछे का कूड़ेदान,\nफ्रेम से बाहर कर दो।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कितनी तस्वीरें लें।\nसाली ने पूछा, \"कितनी तस्वीरें लें?\"\nजीजा ने जवाब दिया, \"कुछ अच्छी;\nहजार धुँधली नहीं।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—फोटो धुँधली क्यों।\nसाली ने पूछा, \"फोटो धुँधली क्यों?\"\nजीजा ने जवाब दिया, \"हाथ हिला;\nअगली बार दोनों पैर जमीन पर रखूँगा।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—कौन-सा फ़िल्टर चुनें।\nसाली ने पूछा, \"कौन-सा फ़िल्टर चुनें?\"\nजीजा ने जवाब दिया, \"प्राकृतिक;\nरोशनी सही हो तो फ़िल्टर की जरूरत कम।\""],
  ["jija-sali", "जीजा-साली की हँसी-मज़ाक में यह सवाल आ गया—तस्वीर की याद क्या है।\nसाली ने पूछा, \"तस्वीर की याद क्या है?\"\nजीजा ने जवाब दिया, \"साथ का पल;\nफोन में बस उसकी एक प्रति है।\""],
  ["jija-sali", "शादी के बाद जीजा ने साली से पूछा, “तुम्हें घर की सबसे मुश्किल जिम्मेदारी कौन-सी लगती है?”\nसाली बोली, “रिमोट किसके पास रहेगा, यह तय करना।”\nजीजा ने कहा, “इसका आसान हल है—टीवी बंद कर दो।”\nसाली हँसी, “तभी तो दीदी ने आपको घर का सबसे समझदार मेहमान कहा है!”"],
  ["jija-sali", "राखी के दिन साली ने जीजा से कहा, “इस बार उपहार सोच-समझकर लेना।”\nजीजा बोले, “पिछली बार क्या कमी रह गई थी?”\nसाली ने सूची दिखाई, “कुछ नहीं, बस इस बार बिल भी साथ लाना।”\nजीजा ने कहा, “लगता है उपहार से पहले मेरा बजट राखी बँधवाएगा!”"],
  ["jija-sali", "साली ने जीजा से पूछा, “आप हर फोटो में आँखें बंद क्यों रखते हैं?”\nजीजा बोले, “कैमरे की फ्लैश से बचता हूँ।”\nसाली ने कहा, “तो अगली बार फोटो खिंचवाने से पहले आँखें खोल लेना।”\nजीजा मुस्कराए, “और तुम मज़ाक शुरू करने से पहले कैमरा बंद कर देना!”"],
  ["jija-sali", "जीजा ने साली को नई साइकिल चलाते देखा और पूछा, “सीखने में डर नहीं लगा?”\nसाली बोली, “थोड़ा लगा, पर अभ्यास करती रही।”\nजीजा ने कहा, “गिरने पर क्या किया?”\nसाली बोली, “पहले साइकिल उठाई, फिर आपकी सलाह सुनने से बचने के लिए तेज़ चल दी!”"],
  ["jija-sali", "साली ने जीजा से पूछा, “आपने रसोई में चाय क्यों बनाई?”\nजीजा बोले, “आज दीदी को आराम देना था।”\nसाली ने कप चखकर कहा, “चीनी कुछ ज़्यादा है।”\nजीजा मुस्कराए, “घर में मीठी बातों की कमी न रहे, इसलिए चाय से शुरुआत की!”"],
  ["jija-sali", "जीजा ने साली से कहा, “मैंने घर का वाई-फाई पासवर्ड बदल दिया है।”\nसाली ने पूछा, “क्या रखा?”\nजीजा बोले, “पहले पुराना पासवर्ड बताओ।”\nसाली हँसी, “आपने सुरक्षा बढ़ाई है या मेरी याददाश्त का टेस्ट शुरू किया है?”"],
  ["jija-sali", "साली ने जीजा से पूछा, “आपने पौधों को पानी दिया?”\nजीजा बोले, “हाँ, हर गमले को बराबर।”\nसाली ने देखा कि कैक्टस भी पानी से लबालब था।\nवह बोली, “बराबरी अच्छी है, पर पौधों की ज़रूरत पूछ लेना भी ज़रूरी है!”"],
  ["jija-sali", "जीजा ने साली से कहा, “आज मैंने ऑनलाइन खाना मँगाने की जगह खुद बनाया।”\nसाली ने प्लेट देखकर पूछा, “रेसिपी कहाँ से सीखी?”\nजीजा बोले, “वीडियो से।”\nसाली हँसी, “अच्छा, अब रसोई में भी विज्ञापन के बाद ही अगला कदम उठेगा!”"],
  ["jija-sali", "साली ने जीजा से पूछा, “आप हर काम की सूची क्यों बनाते हैं?”\nजीजा बोले, “ताकि कुछ भूल न जाऊँ।”\nसाली ने सूची देखी और कहा, “इसमें आराम करना भी लिखा है?”\nजीजा बोले, “वो तो दीदी की तरफ़ से स्वतः स्वीकृत काम है!”"],
  ["jija-sali", "जीजा ने साली को पुरानी किताबें देते हुए कहा, “इनसे तुम्हारी पढ़ाई में मदद मिलेगी।”\nसाली ने पूछा, “आपने इन्हें पढ़ा है?”\nजीजा बोले, “हाँ, कई बार।”\nसाली मुस्कराई, “तभी तो हर पन्ने पर आपकी नींद के निशान बने हैं!”"],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—मेरा मामला कितना मजबूत है।\nमुवक्किल ने पूछा, \"मेरा मामला कितना मजबूत है?\"\nवकील ने जवाब दिया, \"पहले तथ्य और दस्तावेज़ देखेंगे;\nउम्मीद से फैसला नहीं लिखते।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या आप जीत की गारंटी देंगे।\nमुवक्किल ने पूछा, \"क्या आप जीत की गारंटी देंगे?\"\nवकील ने जवाब दिया, \"अदालत में गारंटी नहीं;\nईमानदार सलाह और तैयारी दे सकता हूँ।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—पहले क्या बताऊँ।\nमुवक्किल ने पूछा, \"पहले क्या बताऊँ?\"\nवकील ने जवाब दिया, \"पूरी बात बताइए;\nसुविधाजनक हिस्सा छिपाने से सलाह कमजोर होगी।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—कितना समय लगेगा।\nमुवक्किल ने पूछा, \"कितना समय लगेगा?\"\nवकील ने जवाब दिया, \"प्रक्रिया और अदालत की सूची पर निर्भर है;\nतारीख़ों का अनुमान सावधानी से देंगे।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या मैं खुद बोल सकता हूँ।\nमुवक्किल ने पूछा, \"क्या मैं खुद बोल सकता हूँ?\"\nवकील ने जवाब दिया, \"आपके तथ्य महत्वपूर्ण हैं;\nरणनीति और प्रक्रिया हम समझेंगे।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या फीस अभी तय होगी।\nमुवक्किल ने पूछा, \"क्या फीस अभी तय होगी?\"\nवकील ने जवाब दिया, \"काम का दायरा और खर्च,\nलिखित में स्पष्ट करेंगे।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—किससे बात करूँ।\nमुवक्किल ने पूछा, \"किससे बात करूँ?\"\nवकील ने जवाब दिया, \"एक संपर्क व्यक्ति तय करें;\nसंदेशों की उलझन कम होगी।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—मामले का अंत कैसा होगा।\nमुवक्किल ने पूछा, \"मामले का अंत कैसा होगा?\"\nवकील ने जवाब दिया, \"परिणाम प्रमाण और कानून पर निर्भर है;\nपहले तैयारी करें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या सब कुछ बताना जरूरी है।\nमुवक्किल ने पूछा, \"क्या सब कुछ बताना जरूरी है?\"\nवकील ने जवाब दिया, \"हाँ; गोपनीय सलाह तभी उपयोगी,\nहै जब तथ्य पूरे हों।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—पहली बैठक का निष्कर्ष।\nमुवक्किल ने पूछा, \"पहली बैठक का निष्कर्ष?\"\nवकील ने जवाब दिया, \"मुवक्किल बोला,\nअब मुझे प्रक्रिया समझ आई; डर की जगह तैयारी है।\""],
  ["lawyer-client", "मुवक्किल ने पूछा, \"क्या मेरी बात अदालत में पूरी सुनी जाएगी?\"\nवकील बोले, \"ज़रूर, पहले तथ्य क्रम से बताइए।\"\nमुवक्किल ने कहा, \"कहानी लंबी है।\"\nवकील बोले, \"इसीलिए तारीख़वार दस्तावेज़ लाएँ; अदालत को धारावाहिक नहीं चाहिए।\""],
  ["lawyer-client", "मुवक्किल बोला, \"मेरे पास गवाह नहीं, पर मुझे सच पता है।\"\nवकील ने कहा, \"सच महत्वपूर्ण है, पर उसे साबित करने के लिए प्रमाण चाहिए।\"\nमुवक्किल ने पूछा, \"तो मेरी याददाश्त चलेगी?\"\nवकील बोले, \"शुरुआत के लिए; बाकी रिकॉर्ड ढूँढ़ते हैं।\""],
  ["lawyer-client", "ग्राहक ने पूछा, \"मामला जल्दी निपट जाएगा?\"\nवकील ने कहा, \"यह दस्तावेज़ों और अदालत की प्रक्रिया पर निर्भर है।\"\nग्राहक बोला, \"मैं सब कागज़ आज ही दे दूँगा।\"\nवकील मुस्कराए, \"तो कम-से-कम हमारी तरफ़ से देरी का बहाना कम होगा।\""],
  ["lawyer-client", "मुवक्किल ने पूछा, \"क्या मौखिक वादा भी प्रमाण बन सकता है?\"\nवकील ने कहा, \"परिस्थिति और उपलब्ध साक्ष्य देखना पड़ता है।\"\nमुवक्किल बोला, \"गवाह मेरा दोस्त है।\"\nवकील ने पूछा, \"क्या वह अदालत में भी उतना ही दोस्त रहेगा?\""],
  ["lawyer-client", "क्लाइंट ने पूछा, \"क्या मैं अपनी तरफ़ से अदालत को पत्र लिख दूँ?\"\nवकील बोले, \"पहले मसौदा दिखाइए, भाषा और तथ्य जाँच लेंगे।\"\nक्लाइंट ने कहा, \"मैंने गुस्से में लिखा है।\"\nवकील बोले, \"तो पहले गुस्से को संपादित करते हैं, फिर पत्र को।\""],
  ["lawyer-client", "मुवक्किल ने पूछा, \"मेरे दस्तावेज़ों की कितनी प्रतियाँ बनवाऊँ?\"\nवकील ने कहा, \"ज़रूरत के अनुसार साफ़ और पढ़ने योग्य प्रतियाँ रखें।\"\nमुवक्किल बोला, \"मैंने सबकी फोटो खींच ली है।\"\nवकील बोले, \"अच्छा है; अब मूल कागज़ भी सुरक्षित रखिए।\""],
  [ "lawyer-client", "मुवक्किल ने पूछा, “क्या हर संदेश अदालत में सबूत बन सकता है?”\nवकील ने कहा, “संदर्भ, प्रामाणिकता और नियम देखे जाते हैं।”\nमुवक्किल बोला, “तो मेरा ‘ठीक है’ भी समझना पड़ेगा?”\nवकील मुस्कराए, “पहले यह पता करें कि आपने किस बात पर ठीक कहा था।”" ],
  [ "lawyer-client", "मुवक्किल बोला, “दूसरे पक्ष ने फोन पर वादा किया था।”\nवकील ने पूछा, “क्या तारीख़ और बातचीत का कोई रिकॉर्ड है?”\nमुवक्किल बोला, “मुझे सब याद है।”\nवकील ने कहा, “याददाश्त अच्छी है; अब उसे दस्तावेज़ों से मिलाते हैं।”" ],
  [ "lawyer-client", "मुवक्किल ने पूछा, “क्या मैं हर कागज़ पर हस्ताक्षर कर दूँ?”\nवकील ने कहा, “पहले पढ़ें, शर्तें समझें और प्रति रखें।”\nमुवक्किल बोला, “इतना समय लगेगा?”\nवकील ने कहा, “पढ़ने में लगा समय, विवाद में लगने वाले समय से कम है।”" ],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—दस्तावेज़ कैसे सुरक्षित रखें।\nमुवक्किल ने पूछा, \"दस्तावेज़ कैसे सुरक्षित रखें?\"\nवकील ने जवाब दिया, \"बैकअप बनाएं और निजी जानकारी अनावश्यक,\nलोगों से साझा न करें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—फैसला कब आएगा।\nमुवक्किल ने पूछा, \"फैसला कब आएगा?\"\nवकील ने जवाब दिया, \"तारीख़ बताई जा सकती है;\nफैसला अदालत के समय पर निर्भर है।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—मामला जल्दी खत्म हो सकता है।\nमुवक्किल ने पूछा, \"मामला जल्दी खत्म हो सकता है?\"\nवकील ने जवाब दिया, \"समझौता संभव हो तो विकल्प देखेंगे;\nदबाव में निर्णय नहीं।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—हर सुनवाई में आना होगा।\nमुवक्किल ने पूछा, \"हर सुनवाई में आना होगा?\"\nवकील ने जवाब दिया, \"आपकी उपस्थिति कब जरूरी है,\nपहले से बताएँगे।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—तारीख़ बदल गई तो।\nमुवक्किल ने पूछा, \"तारीख़ बदल गई तो?\"\nवकील ने जवाब दिया, \"आधिकारिक सूचना देखें;\nअफ़वाह से अदालत नहीं चलती।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—इतनी तारीख़ें क्यों हैं।\nमुवक्किल ने पूछा, \"इतनी तारीख़ें क्यों हैं?\"\nवकील ने जवाब दिया, \"हर चरण का उद्देश्य है;\nहम अगला कदम स्पष्ट रखेंगे।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या समय सीमा निकल गई।\nमुवक्किल ने पूछा, \"क्या समय सीमा निकल गई?\"\nवकील ने जवाब दिया, \"दस्तावेज़ देखकर गणना करेंगे;\nतुरंत सलाह लेना जरूरी है।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—मुझे इंतज़ार करना पड़ेगा।\nमुवक्किल ने पूछा, \"मुझे इंतज़ार करना पड़ेगा?\"\nवकील ने जवाब दिया, \"हाँ; पर तैयारी और रिकॉर्ड,\nव्यवस्थित रख सकते हैं।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—कितनी पेशियाँ होंगी।\nमुवक्किल ने पूछा, \"कितनी पेशियाँ होंगी?\"\nवकील ने जवाब दिया, \"अभी निश्चित संख्या,\nकहना संभव नहीं।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—सुनवाई की तैयारी कब।\nमुवक्किल ने पूछा, \"सुनवाई की तैयारी कब?\"\nवकील ने जवाब दिया, \"तारीख़ से पहले;\nआख़िरी रात दस्तावेज़ खोजने का समय नहीं।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—समय का सबसे अच्छा उपयोग।\nमुवक्किल ने पूछा, \"समय का सबसे अच्छा उपयोग?\"\nवकील ने जवाब दिया, \"मुवक्किल बोला,\nअब हर तारीख़ और कागज़ व्यवस्थित रखूँगा।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—अदालत में क्या पहनना है।\nमुवक्किल ने पूछा, \"अदालत में क्या पहनना है?\"\nवकील ने जवाब दिया, \"साफ़-सुथरे और सम्मानजनक कपड़े;\nनियमों का पालन करें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—मुझे कहाँ बैठना होगा।\nमुवक्किल ने पूछा, \"मुझे कहाँ बैठना होगा?\"\nवकील ने जवाब दिया, \"मैं बता दूँगा;\nअदालत में शांति और क्रम रखें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—जज सवाल पूछें तो।\nमुवक्किल ने पूछा, \"जज सवाल पूछें तो?\"\nवकील ने जवाब दिया, \"सच और संक्षेप में जवाब दें;\nअनुमान न लगाएँ।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—फोन साथ ले जा सकता हूँ।\nमुवक्किल ने पूछा, \"फोन साथ ले जा सकता हूँ?\"\nवकील ने जवाब दिया, \"अदालत के निर्देश देखें;\nफोन शांत या बंद रखें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या मुझे बोलना होगा।\nमुवक्किल ने पूछा, \"क्या मुझे बोलना होगा?\"\nवकील ने जवाब दिया, \"जब आपकी बात जरूरी होगी,\nआपको तैयार करेंगे।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—अगर सवाल समझ न आए।\nमुवक्किल ने पूछा, \"अगर सवाल समझ न आए?\"\nवकील ने जवाब दिया, \"विनम्रता से दोहराने को कहें;\nअंदाज़ा लगाकर उत्तर न दें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—किसे पहले संबोधित करूँ।\nमुवक्किल ने पूछा, \"किसे पहले संबोधित करूँ?\"\nवकील ने जवाब दिया, \"अदालत की निर्धारित प्रक्रिया,\nका पालन करें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या मैं बीच में बोल सकता हूँ।\nमुवक्किल ने पूछा, \"क्या मैं बीच में बोल सकता हूँ?\"\nवकील ने जवाब दिया, \"अनुमति के बिना नहीं;\nक्रम का सम्मान करें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—अदालत में घबराहट होगी।\nमुवक्किल ने पूछा, \"अदालत में घबराहट होगी।\"\nवकील ने जवाब दिया, \"तैयारी करें और तथ्य याद रखें;\nनाटक की जरूरत नहीं।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—सबसे जरूरी बात।\nमुवक्किल ने पूछा, \"सबसे जरूरी बात?\"\nवकील ने जवाब दिया, \"सच बोलें,\nशांत रहें और निर्देश समझकर चलें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—कुल खर्च कितना होगा।\nमुवक्किल ने पूछा, \"कुल खर्च कितना होगा?\"\nवकील ने जवाब दिया, \"फीस, कोर्ट फीस और अन्य,\nसंभावित खर्च अलग-अलग बताएँगे।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या फीस किस्तों में दे सकता हूँ।\nमुवक्किल ने पूछा, \"क्या फीस किस्तों में दे सकता हूँ?\"\nवकील ने जवाब दिया, \"व्यवस्था पहले लिखित में,\nतय कर लेते हैं।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—बीच में खर्च बढ़ेगा।\nमुवक्किल ने पूछा, \"बीच में खर्च बढ़ेगा?\"\nवकील ने जवाब दिया, \"अतिरिक्त काम हो तो पहले,\nकारण और अनुमान साझा करेंगे।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—रसीद मिलेगी।\nमुवक्किल ने पूछा, \"रसीद मिलेगी?\"\nवकील ने जवाब दिया, \"हर भुगतान की रसीद,\nऔर विवरण मिलेगा।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—कम फीस वाला वकील चुनूँ।\nमुवक्किल ने पूछा, \"कम फीस वाला वकील चुनूँ?\"\nवकील ने जवाब दिया, \"अनुभव, काम का दायरा और स्पष्ट,\nसंवाद भी तुलना में रखें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—सफलता पर अतिरिक्त फीस।\nमुवक्किल ने पूछा, \"सफलता पर अतिरिक्त फीस?\"\nवकील ने जवाब दिया, \"लागू नियम और लिखित शर्तें,\nसमझकर ही तय करें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—कितना अग्रिम देना है।\nमुवक्किल ने पूछा, \"कितना अग्रिम देना है?\"\nवकील ने जवाब दिया, \"काम शुरू करने से,\nपहले सहमति के अनुसार।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—मुझे खर्च समझ नहीं आया।\nमुवक्किल ने पूछा, \"मुझे खर्च समझ नहीं आया।\"\nवकील ने जवाब दिया, \"पूछिए; फीस का हिसाब,\nसाफ़ होना चाहिए।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या छिपा हुआ खर्च होगा।\nमुवक्किल ने पूछा, \"क्या छिपा हुआ खर्च होगा?\"\nवकील ने जवाब दिया, \"अनुमानित मदें पहले बताएँगे;\nअनिश्चितता भी स्पष्ट करेंगे।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—फीस पर भरोसा कैसे हो।\nमुवक्किल ने पूछा, \"फीस पर भरोसा कैसे हो?\"\nवकील ने जवाब दिया, \"मुवक्किल बोला,\nलिखित समझौता और रसीद से।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—मकान मालिक मौखिक वादा कर रहा है।\nउसने पूछा, \"मकान मालिक मौखिक वादा कर रहा है।\"\nवकील ने कहा, \"जो बात ज़रूरी है उसे लिखवाइए,\nयाददाश्त से बेहतर दस्तावेज़ होता है।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—यह छोटा अक्षर क्यों है।\nमुवक्किल ने पूछा, \"यह छोटा अक्षर क्यों है?\"\nवकील ने जवाब दिया, \"आकार छोटा है पर असर,\nबड़ा हो सकता है।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—मौखिक वादा भी मान्य है।\nमुवक्किल ने पूछा, \"मौखिक वादा भी मान्य है?\"\nवकील ने जवाब दिया, \"परिस्थितियों पर निर्भर;\nलिखित प्रमाण सुरक्षित रखना बेहतर है।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्लॉज़ समझ नहीं आया।\nमुवक्किल ने पूछा, \"क्लॉज़ समझ नहीं आया।\"\nवकील ने जवाब दिया, \"सरल भाषा में समझेंगे;\nबिना समझे सहमति न दें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—खाली जगह पर हस्ताक्षर करूँ।\nमुवक्किल ने पूछा, \"खाली जगह पर हस्ताक्षर करूँ?\"\nवकील ने जवाब दिया, \"कभी नहीं;\nपूरा दस्तावेज़ जाँचें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—दूसरा पक्ष जल्दी कर रहा है।\nमुवक्किल ने पूछा, \"दूसरा पक्ष जल्दी कर रहा है।\"\nवकील ने जवाब दिया, \"दबाव में हस्ताक्षर न करें;\nसमीक्षा का समय माँगें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—लाभ बराबर बाँटेंगे, नुकसान का क्या।\nउसने पूछा, \"लाभ बराबर बाँटेंगे, नुकसान का क्या?\"\nवकील ने कहा, \"दोनों की शर्तें पहले तय हों,\nवरना दोस्ती भी हिसाब में उलझेगी।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या प्रति रखूँ।\nमुवक्किल ने पूछा, \"क्या प्रति रखूँ?\"\nवकील ने जवाब दिया, \"पूरी हस्ताक्षरित प्रति अपने,\nरिकॉर्ड में रखें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—शर्त बदल सकती है।\nमुवक्किल ने पूछा, \"शर्त बदल सकती है?\"\nवकील ने जवाब दिया, \"दोनों पक्ष सहमत हों तो,\nउचित संशोधन लिखित करें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या हर पन्ना पढ़ना ज़रूरी है।\nउसने पूछा, \"क्या हर पन्ना पढ़ना ज़रूरी है?\"\nवकील ने कहा, \"खासकर वही पन्ना,\nजिसे कोई जल्दी में पलटने को कहे।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—पोस्ट में मेरा नाम लिखा है।\nमुवक्किल ने पूछा, \"पोस्ट में मेरा नाम लिखा है।\"\nवकील ने जवाब दिया, \"स्क्रीनशॉट और लिंक सुरक्षित रखें;\nपहले पूरा संदर्भ देखेंगे।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या तुरंत जवाब दूँ।\nमुवक्किल ने पूछा, \"क्या तुरंत जवाब दूँ?\"\nवकील ने जवाब दिया, \"गुस्से में पोस्ट न करें;\nप्रमाण सुरक्षित करके सलाह लें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—पोस्ट हट गई तो।\nमुवक्किल ने पूछा, \"पोस्ट हट गई तो?\"\nवकील ने जवाब दिया, \"आपके पास जो वैध रिकॉर्ड है उसे सुरक्षित रखें;\nछेड़छाड़ न करें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—किसी ने निजी फोटो साझा की।\nमुवक्किल ने पूछा, \"किसी ने निजी फोटो साझा की।\"\nवकील ने जवाब दिया, \"प्लेटफ़ॉर्म पर रिपोर्ट करें और,\nउचित कानूनी सहायता लें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या हर आलोचना मानहानि है।\nमुवक्किल ने पूछा, \"क्या हर आलोचना मानहानि है?\"\nवकील ने जवाब दिया, \"नहीं; तथ्य,\nराय और संदर्भ अलग-अलग होते हैं।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—कमेंट में धमकी मिली।\nमुवक्किल ने पूछा, \"कमेंट में धमकी मिली।\"\nवकील ने जवाब दिया, \"जवाबी धमकी न दें;\nरिकॉर्ड सुरक्षित रखें और सुरक्षा सहायता लें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—फर्जी अकाउंट बना है।\nमुवक्किल ने पूछा, \"फर्जी अकाउंट बना है।\"\nवकील ने जवाब दिया, \"प्लेटफ़ॉर्म को रिपोर्ट करें;\nपहचान का अनुमान सार्वजनिक न करें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—पोस्ट किसने लिखी, पता चलेगा।\nमुवक्किल ने पूछा, \"पोस्ट किसने लिखी, पता चलेगा?\"\nवकील ने जवाब दिया, \"यह कानूनी प्रक्रिया और उपलब्ध,\nप्रमाण पर निर्भर है।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या मैं स्क्रीनशॉट एडिट करूँ।\nमुवक्किल ने पूछा, \"क्या मैं स्क्रीनशॉट एडिट करूँ?\"\nवकील ने जवाब दिया, \"मूल रिकॉर्ड रखें;\nसंपादन प्रमाण की विश्वसनीयता घटा सकता है।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—ऑनलाइन व्यवहार का नियम।\nमुवक्किल ने पूछा, \"ऑनलाइन व्यवहार का नियम?\"\nवकील ने जवाब दिया, \"सोचकर लिखें और निजी,\nजानकारी सुरक्षित रखें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—गवाह को क्या बताना है।\nमुवक्किल ने पूछा, \"गवाह को क्या बताना है?\"\nवकील ने जवाब दिया, \"जो सच में देखा या सुना वही;\nकहानी याद मत कराएँ।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—गवाह घबरा रहा है।\nमुवक्किल ने पूछा, \"गवाह घबरा रहा है।\"\nवकील ने जवाब दिया, \"प्रक्रिया समझाएँ;\nझूठा उत्तर सिखाना गलत है।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—गवाह की याद बदल सकती है।\nमुवक्किल ने पूछा, \"गवाह की याद बदल सकती है?\"\nवकील ने जवाब दिया, \"इसलिए तारीख़ और मूल,\nरिकॉर्ड सुरक्षित रखें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—क्या गवाह से बात करूँ।\nमुवक्किल ने पूछा, \"क्या गवाह से बात करूँ?\"\nवकील ने जवाब दिया, \"उचित सीमा में;\nकिसी पर दबाव न डालें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—गवाह ने अलग बात कही।\nमुवक्किल ने पूछा, \"गवाह ने अलग बात कही।\"\nवकील ने जवाब दिया, \"अंतर समझेंगे;\nतथ्य छिपाने से मामला कमजोर होगा।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—गवाही में गलती हो गई तो।\nमुवक्किल ने पूछा, \"गवाही में गलती हो गई तो?\"\nवकील ने जवाब दिया, \"सच स्पष्ट करें;\nगलती सुधारना छिपाने से बेहतर है।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—कितने गवाह चाहिए।\nमुवक्किल ने पूछा, \"कितने गवाह चाहिए?\"\nवकील ने जवाब दिया, \"संख्या से अधिक प्रासंगिक और,\nविश्वसनीय प्रमाण महत्वपूर्ण है।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—गवाह को इनाम दें।\nमुवक्किल ने पूछा, \"गवाह को इनाम दें?\"\nवकील ने जवाब दिया, \"गवाही प्रभावित करने का,\nप्रयास न करें।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—गवाह देर से पहुँचा।\nमुवक्किल ने पूछा, \"गवाह देर से पहुँचा।\"\nवकील ने जवाब दिया, \"समय और सूचना की पुष्टि करें;\nअनुमान न लगाएँ।\""],
  ["lawyer-client", "वकील के चैंबर में मुवक्किल ने यह कानूनी सवाल उठाया—अच्छी गवाही क्या है।\nमुवक्किल ने पूछा, \"अच्छी गवाही क्या है?\"\nवकील ने जवाब दिया, \"स्पष्ट,\nसत्य और अपने अनुभव पर आधारित।\""],
  ["lawyer-client", "मकान-मालिक ने किरायेदार को नया समझौता थमाया।\nकिरायेदार ने पूछा, \"जमा राशि लौटाने की तारीख़ कहाँ लिखी है?\"\nवकील ने कहा, \"राशि, कटौती और वापसी की शर्त साफ़ लिखवाइए।\"\nकिरायेदार बोला, \"अब चाबी के साथ कैलेंडर भी मिलेगा।\""],
  ["lawyer-client", "दुकानदार ने ग्राहक को हाथ से लिखी उधारी-पर्ची दिखाई।\nग्राहक ने पूछा, \"इसमें तारीख़ और भुगतान का हिसाब अधूरा है।\"\nवकील ने समझाया, \"दोनों पक्षों से सही विवरण की पुष्टि कराइए।\"\nदुकानदार बोला, \"मेरी याददाश्त को भी अब गवाह चाहिए।\""],
  ["lawyer-client", "एक कर्मचारी को नौकरी छोड़ने के बाद अनुभव-पत्र नहीं मिला।\nउसने पूछा, \"क्या मैं कंपनी का लैपटॉप रोक लूँ?\"\nवकील ने कहा, \"संपत्ति लौटाने और पत्र माँगने की प्रक्रिया अलग रखें।\"\nकर्मचारी बोला, \"यानी इस्तीफ़े के साथ लैपटॉप की विदाई भी तय है।\""],
  ["lawyer-client", "पड़ोसी की दीवार पर पेड़ की शाखाएँ फैल गईं।\nमुवक्किल ने पूछा, \"क्या मैं रात में चुपचाप काट दूँ?\"\nवकील ने कहा, \"पहले स्थानीय नियम और पड़ोसी से सहमति जाँचें।\"\nमुवक्किल बोला, \"कानून ने कुल्हाड़ी को भी बातचीत सिखा दी।\""],
  ["lawyer-client", "ऑनलाइन खरीदी वस्तु खराब निकली और विक्रेता जवाब नहीं दे रहा था।\nग्राहक ने पूछा, \"शिकायत के लिए क्या-क्या संभालूँ?\"\nवकील ने कहा, \"ऑर्डर, भुगतान, तस्वीरें और बातचीत का रिकॉर्ड रखें।\"\nग्राहक बोला, \"डिब्बा फेंकने से पहले अब उसकी भी गवाही लूँगा।\""],
  ["lawyer-client", "एक परिवार को संपत्ति के पुराने काग़ज़ों में अलग-अलग नाम मिले।\nमुवक्किल ने पूछा, \"क्या एक नाम काटकर दूसरा लिख दें?\"\nवकील ने कहा, \"मूल दस्तावेज़ न बदलें; आधिकारिक रिकॉर्ड से सुधार कराएँ।\"\nमुवक्किल बोला, \"काग़ज़ पर सुधार भी अब बाकायदा रास्ता माँगता है।\""],
  ["lawyer-client", "समिति की बैठक में अध्यक्ष ने सबकी सहमति दर्ज कर दी।\nएक सदस्य ने पूछा, \"मैं तो बैठक में आया ही नहीं था।\"\nवकील ने कहा, \"कार्यवाही की प्रति माँगें और अपनी आपत्ति लिखित दें।\"\nअध्यक्ष बोला, \"अगली बार अनुपस्थिति की भी हाज़िरी लगेगी क्या?\""],
  ["lawyer-client", "एक फोटोग्राफ़र की तस्वीर बिना अनुमति विज्ञापन में छप गई।\nउसने पूछा, \"क्या स्क्रीनशॉट ही पर्याप्त रहेगा?\"\nवकील ने कहा, \"प्रकाशन का स्रोत, तारीख़ और मूल फ़ाइल सुरक्षित रखें।\"\nफोटोग्राफ़र बोला, \"अब मेरी तस्वीर से पहले उसका परिचय-पत्र बनेगा।\""],
  ["lawyer-client", "किसान को फसल बीमा का दावा अस्वीकार होने का संदेश मिला।\nउसने पूछा, \"किससे बात करूँ और कितने दिन में?\"\nवकील ने कहा, \"कारण पढ़ें, समय-सीमा जाँचें और लिखित अपील का रिकॉर्ड रखें।\"\nकिसान बोला, \"इस बार बादल नहीं, काग़ज़ों की चाल समझूँगा।\""],
  ["lawyer-client", "एक छोटे व्यवसायी ने साझेदार के साथ मौखिक हिसाब रखा था।\nउसने पूछा, \"अब मुनाफ़ा अलग-अलग बताया जा रहा है।\"\nवकील ने कहा, \"लेन-देन के प्रमाण जुटाएँ और आगे की शर्तें लिखित करें।\"\nव्यवसायी बोला, \"दोस्ती अपनी जगह, हिसाब की कॉपी अपनी जगह।\""],
  ["lawyer-client", "मुवक्किल ने किरायानामा पढ़े बिना हर पन्ने पर हस्ताक्षर कर दिए।\nवकील ने पूछा, \"शर्तें समझ ली थीं?\"\nवह बोला, \"मकान मालिक ने कहा था, बस औपचारिकता है।\"\nवकील ने चश्मा उतारा, \"अब यह औपचारिकता आपको हर महीने किराया याद दिलाएगी।\""],
  ["lawyer-client", "एक दुकानदार अपना ट्रेडमार्क दर्ज कराने वकील के पास पहुँचा।\nउसने कहा, \"नाम ऐसा चाहिए जिसे कोई चुरा न सके।\"\nवकील ने पूछा, \"नाम क्या है?\"\nदुकानदार बोला, \"अभी तय नहीं किया; पहले सुरक्षा पक्की करवा दीजिए।\""],
  ["lawyer-client", "मुवक्किल ने वसीयत की फाइल मेज़ पर रखी और फुसफुसाया, \"परिवार को कुछ पता नहीं चलना चाहिए।\"\nवकील ने पूछा, \"कागज़ पर गवाहों के हस्ताक्षर हैं?\"\nवह बोला, \"नहीं, सबको सरप्राइज़ देना है।\"\nवकील ने कहा, \"सरप्राइज़ जन्मदिन पर अच्छा लगता है, कानूनी दस्तावेज़ में नहीं।\""],
  ["lawyer-client", "सोसाइटी के सचिव ने पार्किंग विवाद का नक्शा वकील को दिखाया।\nहर निवासी ने अपनी गाड़ी के लिए अलग सीमा खींच रखी थी।\nवकील ने पूछा, \"कॉमन एरिया कहाँ बचा है?\"\nसचिव बोले, \"वही तो अब अदालत से ढूँढ़वाना है।\""],
  ["lawyer-client", "एक लेखक ने वकील से पूछा, \"क्या मेरे उपन्यास का किरदार मानहानि का दावा कर सकता है?\"\nवकील ने पांडुलिपि पलटी और पूछा, \"किरदार असली व्यक्ति पर आधारित है?\"\nलेखक बोला, \"नहीं, लेकिन उसका पड़ोसी खुद को पहचान गया।\"\nवकील मुस्कराए, \"कहानी काल्पनिक है; पड़ोसी की कल्पना बहुत सक्रिय है।\""],
  ["lawyer-client", "मुवक्किल अदालत में अपना मोबाइल सबूत के तौर पर जमा करना चाहता था।\nवकील ने पूछा, \"संदेशों का बैकअप और मूल रिकॉर्ड सुरक्षित हैं?\"\nवह बोला, \"हाँ, पर मैंने गुस्से में चैट का नाम 'सबूत मिटाओ' रख दिया।\"\nवकील ने कहा, \"सबूत से पहले अपनी संपर्क-सूची का नाम बदलवाइए।\""],
  ["lawyer-client", "एक उद्यमी ने साझेदारी का मसौदा दिखाकर कहा, \"हम दोनों बराबर के मालिक हैं।\"\nवकील ने हिस्सेदारी देखी—एक के पास निन्यानवे प्रतिशत था।\nउन्होंने पूछा, \"बराबरी कहाँ है?\"\nउद्यमी बोला, \"दूसरे साथी को कंपनी के नाम में बराबर जगह दी है।\""],
  ["lawyer-client", "मुवक्किल ने नोटिस का जवाब भेजने से पहले वकील से आखिरी सलाह माँगी।\nवकील ने कहा, \"पहले तारीख और प्राप्ति का प्रमाण जाँच लें।\"\nवह बोला, \"मैंने जवाब तो भेज दिया, पर लिफाफे पर पता नहीं लिखा।\"\nवकील ने सिर हिलाया, \"आपका जवाब अभी भी खुद से बातचीत कर रहा होगा।\""],
  ["lawyer-client", "एक ग्राहक ने ऑनलाइन खरीदी की रसीद दिखाकर उपभोक्ता शिकायत पूछी।\nवकील ने कहा, \"विक्रेता से हुई बातचीत और डिलीवरी का रिकॉर्ड भी रखिए।\"\nग्राहक बोला, \"मैंने पैकेट खोलते ही वीडियो बनाया था।\"\nवकील ने पूछा, \"अच्छा—तो शिकायत के साथ अनबॉक्सिंग का पूरा सिनेमा भी है?\""],
  ["lawyer-client", "मुवक्किल ने पूछा, \"क्या अदालत में देर से पहुँचना भी कोई बहाना बन सकता है?\"\nवकील ने घड़ी देखी और कहा, \"कारण असली हो तो समझाया जा सकता है।\"\nवह बोला, \"मैं समय पर निकला था, रास्ते में बहाने सोचता रहा।\"\nवकील ने कहा, \"कम-से-कम आपकी देरी की तैयारी समय से शुरू हो गई थी।\""]
);
